// Nastavit Secure + HttpOnly na session cookie okamžitě při načtení pluginu
// — musí být před jakýmkoliv session_start(), tedy i před WP hooky
if (session_status() === PHP_SESSION_NONE && !headers_sent()) {
    session_set_cookie_params([
        'lifetime' => 0,
        'path'     => '/',
        'domain'   => '',
        'secure'   => true,
        'httponly' => true,
        'samesite' => 'Lax',
    ]);
}

