function rd_get_color_themes() {
    return [
        'auto'     => ['name' => '🔄 Automaticky podle dne', 'from' => '#7c3aed', 'to' => '#db2777', 'a1' => '#a78bfa', 'a2' => '#f472b6', 'hue' => '220deg'],
        'aurora'   => ['name' => '🌌 Aurora',    'from' => '#7c3aed', 'to' => '#db2777', 'a1' => '#a78bfa', 'a2' => '#f472b6'],
        'ocean'    => ['name' => '🌊 Ocean',     'from' => '#0ea5e9', 'to' => '#7c3aed', 'a1' => '#38bdf8', 'a2' => '#a78bfa'],
        'sunset'   => ['name' => '🌅 Sunset',    'from' => '#f97316', 'to' => '#db2777', 'a1' => '#fb923c', 'a2' => '#f472b6'],
        'forest'   => ['name' => '🌿 Forest',    'from' => '#16a34a', 'to' => '#0ea5e9', 'a1' => '#4ade80', 'a2' => '#38bdf8'],
        'midnight' => ['name' => '🌃 Midnight',  'from' => '#1e40af', 'to' => '#7c3aed', 'a1' => '#818cf8', 'a2' => '#a78bfa'],
        'rosegold' => ['name' => '🌹 Rose Gold', 'from' => '#e11d48', 'to' => '#f59e0b', 'a1' => '#fb7185', 'a2' => '#fbbf24'],
    ];
}

add_action('wp_head', function() {
    $themes = rd_get_color_themes();
    $key = get_theme_mod('rd_color_theme', get_option('rd_color_theme', 'aurora'));
    if ($key === 'auto') {
        $auto_map = [0 => 'rosegold', 1 => 'aurora', 2 => 'ocean', 3 => 'sunset', 4 => 'forest', 5 => 'midnight', 6 => 'rosegold'];
        $key = $auto_map[date('w')] ?? 'aurora';
    }
    $t = $themes[$key] ?? $themes['aurora'];
    echo '<style>:root{'
        . '--rd-grad-from:' . esc_attr($t['from']) . ';'
        . '--rd-grad-to:'   . esc_attr($t['to'])   . ';'
        . '--rd-grad:linear-gradient(135deg,' . esc_attr($t['from']) . ',' . esc_attr($t['to']) . ');'
        . '--rd-accent-1:'  . esc_attr($t['a1'])   . ';'
        . '--rd-accent-2:'  . esc_attr($t['a2'])   . ';'
        . '--au-violet:' . esc_attr($t['from']) . ';'
        . '--au-violet-l:' . esc_attr($t['a1']) . ';'
        . '--au-pink:' . esc_attr($t['to']) . ';'
        . '--au-pink-l:' . esc_attr($t['a2']) . ';'
        . '--au-grad:linear-gradient(135deg,' . esc_attr($t['from']) . ',' . esc_attr($t['to']) . ');'
        . '--au-grad-soft:linear-gradient(135deg,' . esc_attr($t['from']) . '22,' . esc_attr($t['to']) . '11);'
        . '}</style>' . PHP_EOL;
}, 20);



