// Přesměrování přihlášeného řidiče — priorita 0, před vším

// Nastavit základní hodnoty webu při aktivaci pluginu
register_activation_hook(__FILE__, function() {
    // Vytvořit roli refdrive_admin
    add_role('refdrive_admin', 'RefDrive Admin', [
        'read' => true,
        'refdrive_access' => true,
    ]);
    // Přidat refdrive_access capability hlavnímu adminovi
    $admin_role = get_role('administrator');
    if ($admin_role) $admin_role->add_cap('refdrive_access');
    update_option('blogname',        'RefDrive.pro');
    update_option('blogdescription', 'Školení řidičů referentů');
    update_option('admin_email',     'admin@refdrive.pro');

    // Jednorázová aktualizace textu FAQ "Co je RefDrive.pro?" — zdůraznění
    // zprostředkovatelské role platformy mezi firmou a autoškolou.
    global $wpdb;
    $wpdb->update(
        "{$wpdb->prefix}rd_faq",
        ['odpoved' => 'RefDrive.pro propojuje firmy s autoškolami pro školení referentských řidičů dle nařízení vlády č. 168/2002 Sb. Vy jako firma vyberete autoškolu a objednáte kódy, my zajišťujeme celý průběh e-learningu a vydání certifikátů. Bez dojíždění, bez papírování.'],
        ['otazka' => 'Co je RefDrive.pro?']
    );

    // Jednorázová aktualizace textu FAQ o počtu otázek a prahu úspěšnosti testu
    $wpdb->update(
        "{$wpdb->prefix}rd_faq",
        ['odpoved' => 'Test má 15 otázek, minimální úspěšnost je 80 %.'],
        ['otazka' => 'Kolik otázek má test a jaká je minimální úspěšnost?']
    );
    // Registrovat rewrite rules pro portal
    add_rewrite_rule('^portal/?$',           'index.php?rd_portal=dashboard', 'top');
    add_rewrite_rule('^portal/firmy/?$',     'index.php?rd_portal=firmy',     'top');
    add_rewrite_rule('^portal/absolventi/?$','index.php?rd_portal=absolventi','top');
    add_rewrite_rule('^portal/objednavky/?$','index.php?rd_portal=objednavky','top');
    add_rewrite_rule('^portal/balicky/?$',   'index.php?rd_portal=balicky',   'top');
    add_rewrite_rule('^portal/nastaveni/?$', 'index.php?rd_portal=nastaveni', 'top');
    flush_rewrite_rules();
});
add_filter('query_vars', function($vars) {
    $vars[] = 'rd_portal';
    return $vars;
});
add_action('init', function() {
    // Jednorázová oprava uloženého JSON v rd_txt_kroky (homepage "Jak to funguje"),
    // pokud admin tyto texty dříve uložil přes formulář — uložená hodnota by jinak
    // navždy přebíjela opravený $default v rd_get_kroky() a zobrazovala starý
    // text "10 otázek, minimální úspěšnost 70 %".
    $saved_kroky = get_option('rd_txt_kroky', '');
    if (!$saved_kroky) return;
    if (strpos($saved_kroky, '10 otázek') === false) return;
    $parsed_kroky = json_decode($saved_kroky, true);
    if (!is_array($parsed_kroky)) return;
    foreach ($parsed_kroky as &$krok) {
        if (isset($krok['p']) && strpos($krok['p'], '10 otázek') !== false) {
            $krok['p'] = str_replace(
                ['10 otázek', '70 %', '70%'],
                ['15 otázek', '80 %', '80%'],
                $krok['p']
            );
        }
    }
    unset($krok);
    update_option('rd_txt_kroky', wp_json_encode($parsed_kroky));
});

add_action('init', function() {
    // Vypnout automatický lazy-loading obrázků WordPressu (od WP 5.5+).
    // Na některých Android prohlížečích způsobuje, že se obrázky (ikony,
    // QR kódy, loga) nenačtou, dokud uživatel nescrolluje / nevyčistí cache.
    add_filter('wp_lazy_loading_enabled', '__return_false');
}, 5);

add_action('init', function() {
    if (defined('DOING_AJAX') && DOING_AJAX) return;
    if (defined('DOING_CRON') && DOING_CRON) return;
    if (is_admin()) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    // Obnovit session řidiče z cookie pokud chybí (musí být zde, před redirect logikou)
    if (empty($_SESSION['rd_kod']) && !empty($_COOKIE['rd_ridic'])) {
        global $wpdb;
        $kod_c = sanitize_text_field($_COOKIE['rd_ridic']);
        $kr_c = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod_c));
        if ($kr_c) {
            $_SESSION['rd_kod']         = $kod_c;
            $_SESSION['rd_jmeno']       = $kr_c->ridic_jmeno ?? '';
            $_SESSION['rd_token']       = $kr_c->token ?? '';
            $_SESSION['rd_firma_email'] = $kr_c->firma_email ?? '';
            $_SESSION['rd_firma_nazev'] = $kr_c->firma_nazev ?? '';
        }
    }
    if (!isset($_SESSION['rd_kod'])) return;
    // Firma nebo lektor — nepřesměrovávat
    if (isset($_SESSION['rd_firma_id']) || isset($_SESSION['rd_lektor'])) return;
    $uri = $_SERVER['REQUEST_URI'] ?? '';
    // Přesměrovat jen ze stránky přihlášení
    if (strpos($uri, 'prihlaseni') === false) return;
    // Test nechme projít — kvíz shortcode sám přesměruje na certifikát pokud splnil
    // No-cache
    header('Cache-Control: no-store, no-cache, must-revalidate');
    header('Pragma: no-cache');
    global $wpdb;
    $abs = (int)$wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1",
        $_SESSION['rd_kod']
    ));
    if ($abs > 0) {
        wp_redirect(home_url('/certifikat/'), 302); exit;
    }
    wp_redirect(home_url('/kurz/'), 302); exit;
}, 0);

