// Firma přihlášena — zablokovat prihlaseni a objednavka
add_action('init', function() {
    if (defined('DOING_AJAX') && DOING_AJAX) return;
    if (is_admin()) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    if (empty($_SESSION['rd_firma_id'])) return;
    $uri = $_SERVER['REQUEST_URI'] ?? '';
    if (strpos($uri, 'prihlaseni') !== false) {
        wp_redirect(home_url('/firma-portal/'));
        exit;
    }
    if (strpos($uri, 'objednavka') !== false && empty($_GET['firma_portal']) && empty($_GET['ref'])) {
        wp_redirect(home_url('/firma-portal/'));
        exit;
    }
}, 2);

// Jednorázová aktualizace balíčků – Starter + nové ceny
add_action('init', function() {
    if (get_option('rd_tiers_updated_v2') === '1') return;
    global $wpdb;
    $tbl = defined('RD_TABLE_AS_TIERY') ? RD_TABLE_AS_TIERY : $wpdb->prefix . 'rd_as_tiery';
    // Aktualizuj stávající ceny
    $wpdb->update($tbl, ['cena_mesic' => 1490, 'poradi' => 2], ['nazev' => 'Základní']);
    $wpdb->update($tbl, ['cena_mesic' => 2990, 'poradi' => 3], ['nazev' => 'Standard']);
    $wpdb->update($tbl, ['cena_mesic' => 5490, 'poradi' => 4], ['nazev' => 'Pro']);
    $wpdb->update($tbl, ['cena_mesic' => 9490, 'poradi' => 5], ['nazev' => 'Neomezený']);
    // Přidej Starter pokud neexistuje
    $exists = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $tbl WHERE nazev=%s", 'Starter'));
    if (!$exists) {
        $wpdb->insert($tbl, ['nazev' => 'Starter', 'popis' => 'Pro vyzkoušení platformy', 'limit_kodu' => 5, 'cena_mesic' => 190, 'poradi' => 1, 'aktivni' => 1]);
    }
    update_option('rd_tiers_updated_v2', '1');
}, 5);
