// Přidat cert_uuid do existující DB pokud chybí
add_action('init', function() {
    global $wpdb;
    $cols = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_RIDICI . " LIKE 'cert_uuid'");
    if (empty($cols)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_RIDICI . " ADD COLUMN cert_uuid VARCHAR(64) DEFAULT NULL, ADD COLUMN trvani_min INT DEFAULT 0");
    }
}, 5);

// Přidat vyrizeno do rd_as_platby pokud chybí
add_action('init', function() {
    global $wpdb;
    $cols = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_AS_PLATBY . " LIKE 'vyrizeno'");
    if (empty($cols)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_AS_PLATBY . " ADD COLUMN vyrizeno DATETIME DEFAULT NULL AFTER platnost_do");
    }
}, 5);

add_action('init', function() {
    if (defined('DOING_AJAX') && DOING_AJAX) return;
    if (is_admin()) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();

    // Odhlášení lektora — funguje z libovolné stránky
    if (isset($_GET['odhlasit_lektora'])) {
        unset($_SESSION['rd_lektor']);
        setcookie('rd_lektor_login', '', time() - 3600, '/', '', is_ssl(), true);
        wp_redirect(home_url('/')); exit;
    }

    // Ukončení náhledu lektora — smaže session náhledu a zobrazí stránku pro zavření okna
    if (isset($_GET['rd_nahled_konec'])) {
        unset($_SESSION['rd_lektor_preview'], $_SESSION['rd_lektor_zkusebni'],
              $_SESSION['rd_kod'], $_SESSION['rd_jmeno'], $_SESSION['rd_token'],
              $_SESSION['rd_firma_email'], $_SESSION['rd_firma_nazev'],
              $_SESSION['rd_lekce_done'], $_SESSION['rd_kurz_done']);
        // Zobrazit stránku která se sama zavře
        nocache_headers();
        echo '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Zavírám náhled...</title></head><body style="font-family:sans-serif;text-align:center;padding:60px 20px;color:#6b7280"><p>Náhled lektora ukončen.</p><script>window.close();setTimeout(function(){window.location.href=' . json_encode(home_url('/lektor/')) . ';},300);</script></body></html>';
        exit;
    }

    // Odhlášení firmy — funguje z libovolné stránky
    if (isset($_GET['odhlasit_firmu'])) {
        // Smazat všechny cert access transients — tokeny nesmí zůstat platné po odhlášení
        global $wpdb;
        $wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_rd_cert_access_%' OR option_name LIKE '_transient_timeout_rd_cert_access_%'");
        unset($_SESSION['rd_firma_id'], $_SESSION['rd_firma_email'], $_SESSION['rd_firma_nazev'], $_SESSION['rd_login_email']);
        setcookie('rd_firma_login', '', time() - 3600, '/', '', is_ssl(), true);
        wp_redirect(home_url('/')); exit;
    }

    // Odhlášení řidiče — funguje z libovolné stránky
    if (isset($_GET['odhlasit']) && $_GET['odhlasit'] == '1') {
        $rid_kod = $_SESSION['rd_kod'] ?? (isset($_COOKIE['rd_ridic']) ? sanitize_text_field($_COOKIE['rd_ridic']) : '');
        // Smazat všechny cert access transients pro tohoto řidiče
        if ($rid_kod) {
            global $wpdb;
            $wpdb->query($wpdb->prepare(
                "DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",
                '_transient_rd_cert_access_%'
            ));
        }
        foreach (['rd_kod','rd_jmeno','rd_firma_email','rd_firma_nazev','rd_token',
                  'rd_cert_jmeno','rd_cert_datum','rd_cert_firma','rd_cert_score',
                  'rd_cert_token','rd_cert_uuid','rd_cert_kod'] as $k) {
            unset($_SESSION[$k]);
        }
        setcookie('rd_ridic', '', time() - 3600, '/', '', is_ssl(), true);
        wp_redirect(home_url('/')); exit;
    }

    // Obnovit session firmy z cookie
    if (empty($_SESSION['rd_firma_id']) && !empty($_COOKIE['rd_firma_login'])) {
        global $wpdb;
        $firma_id = intval(base64_decode($_COOKIE['rd_firma_login']));
        if ($firma_id > 0) {
            $firma = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rd_firmy WHERE id=%d LIMIT 1", $firma_id));
            if ($firma) {
                $_SESSION['rd_firma_id']    = $firma->id;
                $_SESSION['rd_firma_email'] = $firma->email;
                $_SESSION['rd_firma_nazev'] = $firma->nazev;
            }
        }
    }

    // Obnovit session lektora z cookie
    if (empty($_SESSION['rd_lektor']) && !empty($_COOKIE['rd_lektor_login'])) {
        global $wpdb;
        $lektor_id = intval(base64_decode($_COOKIE['rd_lektor_login']));
        if ($lektor_id > 0) {
            $lektor = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rd_lektor WHERE id=%d LIMIT 1", $lektor_id));
            if ($lektor) {
                $_SESSION['rd_lektor'] = $lektor->id;
            }
        }
    }

    // Obnovit session řidiče z cookie
    if (empty($_SESSION['rd_kod']) && !empty($_COOKIE['rd_ridic'])) {
        global $wpdb;
        $kod = sanitize_text_field($_COOKIE['rd_ridic']);
        $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
        if ($kr) {
            $_SESSION['rd_kod']         = $kod;
            $_SESSION['rd_jmeno']       = $kr->ridic_jmeno ?? '';
            $_SESSION['rd_firma_email'] = $kr->firma_email ?? '';
            $_SESSION['rd_firma_nazev'] = $kr->firma_nazev ?? '';
            $_SESSION['rd_token']       = $kr->token ?? '';
            $splnil = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $kod
            ));
            if ($splnil) {
                $_SESSION['rd_cert_jmeno'] = $splnil->jmeno;
                $_SESSION['rd_cert_datum'] = date('d.m.Y', strtotime($splnil->datum_skoleni));
                $_SESSION['rd_cert_firma'] = $kr->firma_nazev ?? '';
                $_SESSION['rd_cert_score'] = $splnil->score;
                $_SESSION['rd_cert_uuid']  = $splnil->cert_uuid;
                $_SESSION['rd_cert_kod']   = $kod;
                $_SESSION['rd_cert_token'] = $kr->token ?? '';
            }
        }
    }
}, 1);

add_action('init', function() {
    // Použít cookie i session pro detekci přihlášeného řidiče
    $kod = null;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    if (isset($_SESSION['rd_kod'])) {
        $kod = $_SESSION['rd_kod'];
    } elseif (isset($_COOKIE['rd_ridic']) && !empty($_COOKIE['rd_ridic'])) {
        // Cookie jen obnoví session pokud session je prázdná (ne po odhlášení)
        $kod = sanitize_text_field($_COOKIE['rd_ridic']);
        // Obnovit session z cookie
        global $wpdb;
        $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
        if ($kr) {
            $_SESSION['rd_kod']         = $kod;
            $_SESSION['rd_jmeno']       = $kr->ridic_jmeno ?? '';
            $_SESSION['rd_firma_email'] = $kr->firma_email ?? '';
            $_SESSION['rd_firma_nazev'] = $kr->firma_nazev ?? '';
            $_SESSION['rd_token']       = $kr->token ?? '';
            // Doplnit cert data pokud kurz splnil
            $splnil = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $kod
            ));
            if ($splnil) {
                $_SESSION['rd_cert_jmeno'] = $splnil->jmeno;
                $_SESSION['rd_cert_datum'] = date('d.m.Y', strtotime($splnil->datum_skoleni));
                $_SESSION['rd_cert_firma'] = $kr->firma_nazev ?? '';
                $_SESSION['rd_cert_score'] = $splnil->score;
                $_SESSION['rd_cert_uuid']  = $splnil->cert_uuid;
                $_SESSION['rd_cert_kod']   = $kod;
                $_SESSION['rd_cert_token'] = $kr->token ?? '';
            }
        }
    }
    if (!$kod) return;
    if (headers_sent()) return;
    // Firma nebo lektor — nepřesměrovávat
    if (isset($_SESSION['rd_firma_id']) || isset($_SESSION['rd_lektor'])) return;
    $uri = isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : '';
    // Volně přístupné stránky — nepřesměrovávat
    $volne = ['prihlaseni', 'kurz', 'zaverecny-test', 'certifikat'];
    $je_volna = false;
    foreach ($volne as $v) { if (strpos($uri, $v) !== false) { $je_volna = true; break; } }
    // Homepage a ostatní stránky — nepřesměrovávat
    $je_homepage = ($uri === '/' || $uri === home_url('/') || (isset($_SERVER['REQUEST_URI']) && rtrim(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), '/') === ''));
    if (!$je_volna) return;
    if (strpos($uri, 'prihlaseni') === false) return;
    global $wpdb;
    $abs = (int)$wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1",
        $kod
    ));
    if ($abs > 0) {
        wp_redirect(home_url('/certifikat/')); exit;
    }
    wp_redirect(home_url('/kurz/')); exit;
}, 1);

