// Cron job – upozornění na expiraci kódů 30 dní předem
add_action('rd_kody_expirace_check', 'rd_kody_expirace_notify');
function rd_kody_expirace_notify() {
    global $wpdb;
    $cil_datum = date('Y-m-d', strtotime('+30 days'));
    $kody = $wpdb->get_results($wpdb->prepare(
        "SELECT k.*, a.nazev as as_nazev FROM " . RD_TABLE_KODY . " k
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=k.autoskola_id
         WHERE k.pouzit=0 AND k.expiruje=%s AND k.firma_email!=''
         ORDER BY k.firma_email",
        $cil_datum
    ));
    if (!$kody) return;
    // Seskupit po firmách
    $firmy = [];
    foreach ($kody as $k) $firmy[$k->firma_email][] = $k;
    foreach ($firmy as $femail => $seznam) {
        $pocet    = count($seznam);
        $firma_n  = $seznam[0]->firma_nazev ?? $femail;
        $subj     = "Připomínka: {$pocet} nevyužitých kódů expiruje za 30 dní";
        $seznam_html = '';
        foreach ($seznam as $k) $seznam_html .= '<tr><td style="padding:4px 8px;font-family:monospace">' . esc_html($k->kod) . '</td><td style="padding:4px 8px;color:#6b7280">' . date('d.m.Y', strtotime($k->expiruje)) . '</td></tr>';
        $body = rd_email_wrap($subj,
            '<p>Dobrý den,</p>'
            . "<p>připomínáme, že máte <strong>{$pocet} nevyužitých přístupových kódů</strong>, jejichž platnost vyprší za 30 dní (dne " . date('d.m.Y', strtotime($cil_datum)) . ").</p>"
            . '<table style="width:100%;border-collapse:collapse;font-size:13px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><thead><tr style="background:#f9fafb"><th style="padding:8px;text-align:left">Kód</th><th style="padding:8px;text-align:left">Expiruje</th></tr></thead><tbody>' . $seznam_html . '</tbody></table>'
            . '<p>Zajistěte prosím, aby vaši zaměstnanci školení absolvovali včas.</p>'
            . rd_email_btn('Firemní portál →', home_url('/firma-portal/'))
        );
        wp_mail($femail, $subj, $body, ['Content-Type: text/html; charset=UTF-8']);
    }
}

add_action('rd_predplatne_check', 'rd_predplatne_check_run');

/**
 * RETENCE ZÁZNAMŮ O ABSOLVENTECH — 2 LETÉ UCHOVÁNÍ
 *
 * Záznamy v rd_ridici (jméno řidiče, výsledek, certifikát) jsou na platformě
 * uchovávány 2 roky od data absolvování (datum_skoleni). Běží denně:
 *
 * - 30 dní před uplynutím 2 let: odešle se e-mail na firma_email s upozorněním,
 *   ať si firma stáhne certifikát/export, protože za 30 dní bude záznam smazán.
 * - Po uplynutí přesně 2 let: záznam se trvale smaže z databáze (cert_uuid tím
 *   přestane být ověřitelný na /overit/).
 */
add_action('rd_ridici_retence_check', 'rd_ridici_retence_check_run');
function rd_ridici_retence_check_run() {
    global $wpdb;
    $dnes = date('Y-m-d');

    // 1) Upozornění 30 dní před smazáním (záznamy staré 1 rok 11 měsíců = 2 roky - 30 dní)
    $hranice_varovani = date('Y-m-d', strtotime('-' . ((2 * 365) - 30) . ' days'));
    $k_varovani = $wpdb->get_results($wpdb->prepare(
        "SELECT firma_email, firma_nazev, COUNT(*) as pocet, MIN(datum_skoleni) as nejstarsi
         FROM " . RD_TABLE_RIDICI . "
         WHERE retence_email_30d = 0
         AND datum_skoleni <= %s
         GROUP BY firma_email, firma_nazev",
        $hranice_varovani
    ));

    foreach ($k_varovani as $f) {
        if (!$f->firma_email) continue;
        rd_ridici_mail_retence_30d($f);
    }
    // Označit jako odeslané (samostatný update, ať se neopakuje)
    if ($k_varovani) {
        $wpdb->query($wpdb->prepare(
            "UPDATE " . RD_TABLE_RIDICI . " SET retence_email_30d = 1
             WHERE retence_email_30d = 0 AND datum_skoleni <= %s",
            $hranice_varovani
        ));
    }

    // 2) Trvalé smazání záznamů starších 2 let
    $hranice_smazani = date('Y-m-d', strtotime('-' . (2 * 365) . ' days'));
    $wpdb->query($wpdb->prepare(
        "DELETE FROM " . RD_TABLE_RIDICI . " WHERE datum_skoleni <= %s",
        $hranice_smazani
    ));
}

function rd_ridici_mail_retence_30d($f) {
    $email  = (string) $f->firma_email;
    $nazev  = esc_html($f->firma_nazev);
    $pocet  = intval($f->pocet);
    $subj   = 'RefDrive: Za 30 dní budou smazány záznamy o ' . $pocet . ' absolventovi/absolventech';
    $body   = rd_email_wrap($subj,
        '<p>Dobrý den,</p>'
        . '<p>v souladu se zásadami platformy RefDrive.pro jsou záznamy o absolvovaných školeních uchovávány <strong>2 roky</strong> od data absolvování.</p>'
        . '<p>Pro firmu <strong>' . $nazev . '</strong> se blíží konec této lhůty u <strong>' . $pocet . '</strong> záznam(ů) — za 30 dní budou tyto záznamy a certifikáty trvale a nevratně smazány.</p>'
        . '<p><strong>Důležité:</strong> stáhněte si je <strong>co nejdříve</strong> (Export absolventů CSV / Certifikáty ZIP ve firemním portálu) a archivujte je ve vlastním systému — 2letá lhůta uchování na platformě je poskytována jako součást služby a není zárukou ani garancí. Zákonnou povinnost archivovat doklady o proškolení zaměstnanců má vždy <strong>zaměstnavatel</strong>, nikoli RefDrive.pro — obvykle po dobu trvání pracovního poměru, doporučeně i několik let po jeho skončení.</p>'
    );
    wp_mail($email, $subj, $body, array('Content-Type: text/html; charset=UTF-8'));
}

function rd_predplatne_check_run() {
    global $wpdb;
    $dnes = date('Y-m-d');
    $rows = $wpdb->get_results(
        "SELECT a.id, a.nazev, a.email, a.stav, a.predplatne_expiruje, a.expir_grace_od,
                a.expir_email_7d, a.expir_email_0d, a.expir_email_7po, a.expir_email_arch, a.anonymizovano
         FROM " . RD_TABLE_AUTOSKOLY . " a
         WHERE a.predplatne_expiruje IS NOT NULL
         AND a.stav IN ('aktivni', 'predplatne_expirovano')
         AND a.anonymizovano = 0"
    );
    if (!$rows) {
        return;
    }
    foreach ($rows as $as) {
        $exp  = $as->predplatne_expiruje;
        $grac = $as->expir_grace_od;
        $d2e  = (int) round((strtotime($exp) - strtotime($dnes)) / 86400);
        $dpe  = $grac ? (int) round((strtotime($dnes) - strtotime($grac)) / 86400) : 0;

        if ($d2e === 7 && !$as->expir_email_7d) {
            rd_predplatne_mail_7d($as);
            $wpdb->update(RD_TABLE_AUTOSKOLY, array('expir_email_7d' => 1), array('id' => $as->id));
        }
        if ($d2e <= 0 && !$as->expir_email_0d) {
            $wpdb->update(RD_TABLE_AUTOSKOLY, array(
                'expir_grace_od'   => $dnes,
                'expir_email_0d'   => 1,
            ), array('id' => $as->id));
            rd_predplatne_mail_0d($as);
            rd_predplatne_mail_admin($as, 'expirovano');
        }
        if ($grac && $dpe >= 7 && !$as->expir_email_7po) {
            $wpdb->update(RD_TABLE_AUTOSKOLY, array(
                'stav'            => 'predplatne_expirovano',
                'expir_email_7po' => 1,
            ), array('id' => $as->id));
            rd_predplatne_mail_zmizelo($as);
            rd_predplatne_mail_admin($as, 'zmizelo');
        }

        // 150 dní po expiraci (30 dní před anonymizací) — výzva ke stažení certifikátů/exportu
        if ($grac && $dpe >= 150 && !$as->expir_email_arch) {
            $wpdb->update(RD_TABLE_AUTOSKOLY, array(
                'expir_email_arch' => 1,
            ), array('id' => $as->id));
            rd_predplatne_mail_archivace($as);
            rd_predplatne_mail_admin($as, 'archivace_30');
        }

        // 180 dní po expiraci — anonymizace profilu
        if ($grac && $dpe >= 180) {
            rd_predplatne_anonymizovat_autoskolu($as->id);
            rd_predplatne_mail_admin($as, 'anonymizovano');
        }
    }
}

/**
 * Anonymizuje profil autoškoly 6 měsíců po expiraci předplatného.
 * Zachovává agregovanou historii (počty absolventů, certifikáty řidičů)
 * pro účely archivace zaměstnavatelů, ale odstraňuje identifikační
 * a kontaktní údaje autoškoly a napojených firem.
 */
function rd_predplatne_anonymizovat_autoskolu($as_id) {
    global $wpdb;
    $as_id = intval($as_id);

    $wpdb->update(RD_TABLE_AUTOSKOLY, [
        'nazev'   => 'Anonymizovaná autoškola #' . $as_id,
        'email'   => 'anonymizovano+' . $as_id . '@refdrive.pro',
        'telefon' => null,
        'ico'     => null,
        'dic'     => null,
        'ulice'   => null,
        'mesto'   => null,
        'psc'     => null,
        'kraj'    => null,
        'stav'    => 'anonymizovano',
        'anonymizovano' => 1,
    ], ['id' => $as_id]);

    // Napojené firmy odpojit (data řidičů/certifikátů v rd_ridici zůstávají
    // zachována pro archivační účely zaměstnavatelů)
    $wpdb->update($wpdb->prefix . 'rd_firma_autoskola', ['do' => current_time('mysql')], ['autoskola_id' => $as_id, 'do' => null]);
}

