// Automatický převod českého čísla účtu na IBAN
function rd_cislo_uctu_to_iban($cislo_uctu) {
    $cislo_uctu = trim(preg_replace('/\s+/', '', $cislo_uctu));
    if (!preg_match('/^(?:(\d{1,6})-)?(\d{1,10})\/(\d{4})$/', $cislo_uctu, $m)) {
        return '';
    }
    $predcisli = str_pad($m[1] ?: '0', 6, '0', STR_PAD_LEFT);
    $cislo     = str_pad($m[2], 10, '0', STR_PAD_LEFT);
    $banka     = $m[3];
    $basic     = $banka . $predcisli . $cislo; // 20 číslic
    $rearranged = $basic . '123500'; // CZ=12,35 + 00 placeholder
    // Mod 97 pro velká čísla
    $remainder = bcmod($rearranged, '97');
    $check     = str_pad((string)(98 - (int)$remainder), 2, '0', STR_PAD_LEFT);
    $iban      = 'CZ' . $check . $basic;
    // Formátovat do skupin po 4
    return implode(' ', str_split($iban, 4));
}

// Získat IBAN — z nastavení nebo automaticky z čísla účtu
function rd_get_iban($cislo_uctu = '', $iban_manual = '') {
    if ($iban_manual) {
        return $iban_manual;
    }
    if ($cislo_uctu) {
        return rd_cislo_uctu_to_iban($cislo_uctu);
    }
    return '';
}


/* ============================================================
   ONBOARDING WIZARD — zobrazí se při prvním přihlášení autoškoly
   ============================================================ */
add_action('admin_init', 'rd_onboarding_redirect');
add_action('admin_init', 'rd_onboarding_post_handler');

// Odstranit "Děkujeme za používání WordPressu" z admin footeru
add_filter('admin_footer_text', '__return_empty_string', 99);
add_filter('update_footer', '__return_empty_string', 99);

function rd_onboarding_post_handler() {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') return;
    if (!rd_je_autoskola_admin()) return;
    $page = $_GET['page'] ?? '';
    if ($page !== 'refdrive-onboarding') return;
    $as = rd_get_my_autoskola();
    if (!$as) return;

    global $wpdb;
    $krok = max(1, min(4, intval($_POST['rd_krok'] ?? 1)));

    // Zpět tlačítko
    if (isset($_POST['rd_krok_back']) && check_admin_referer('rd_onboarding_back')) {
        $back = max(1, intval($_POST['rd_krok_back']));
        wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=' . $back));
        exit;
    }

    if (!check_admin_referer('rd_onboarding_' . $krok)) return;

    if ($krok === 1) {
        $cislo_uctu = sanitize_text_field($_POST['cislo_uctu'] ?? '');
        if (empty($cislo_uctu)) {
            set_transient('rd_wiz_err_' . $as->id, 'Číslo účtu je povinné.', 60);
            wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=1'));
            exit;
        }
        $wpdb->update(RD_TABLE_AUTOSKOLY, [
            'cislo_uctu' => $cislo_uctu,
            'iban'       => sanitize_text_field($_POST['iban'] ?? ''),
            'bic'        => sanitize_text_field($_POST['bic'] ?? ''),
            'banka'      => sanitize_text_field($_POST['banka'] ?? ''),
        ], ['id' => $as->id]);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=2'));
        exit;
    }

    if ($krok === 2) {
        $tier_id = intval($_POST['tier_id'] ?? 0);
        $tier = $tier_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d AND aktivni=1 LIMIT 1", $tier_id)) : null;
        if (!$tier) {
            set_transient('rd_wiz_err_' . $as->id, 'Vyberte prosím balíček.', 60);
            wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=2'));
            exit;
        }
        $wpdb->insert(RD_TABLE_AS_PLATBY, [
            'autoskola_id' => $as->id,
            'tier_id'      => $tier_id,
            'typ'          => 'mesicni',
            'castka'       => $tier->cena_mesic,
            'stav'         => 'ceka_potvrzeni',
        ]);
        $platba_id_new = $wpdb->insert_id;
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['tier_id' => $tier_id, 'stav' => 'ceka_potvrzeni'], ['id' => $as->id]);
        $as_fresh = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as->id));
        rd_odeslat_proforma_fakturu($as_fresh, $tier, $platba_id_new);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=3'));
        exit;
    }

    if ($krok === 3) {
        $cena = intval($_POST['cena_kus'] ?? 0);
        if ($cena < 1) {
            set_transient('rd_wiz_err_' . $as->id, 'Zadejte platnou cenu (minimálně 1 Kč).', 60);
            wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=3'));
            exit;
        }
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['cena_kus' => $cena], ['id' => $as->id]);
        rd_as_cena_log($as->id, $cena, 'onboarding');
        wp_safe_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=4'));
        exit;
    }

    if ($krok === 4 && isset($_POST['rd_potvrdit_onboarding'])) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['onboarding_done' => 1], ['id' => $as->id]);
        $admin_email = rd_admin_notif_email();
        $as_fresh = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as->id));
        $tier_name = $as_fresh->tier_id ? ($wpdb->get_var($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d", $as_fresh->tier_id)) ?: '—') : '—';
        wp_mail($admin_email,
            'RefDrive: Autoškola dokončila onboarding — ' . esc_html($as_fresh->nazev),
            rd_email_wrap('Nová autoškola připravena',
                '<p>Autoškola <strong>' . esc_html($as_fresh->nazev) . '</strong> dokončila nastavení profilu a čeká na potvrzení platby.</p>'
                . '<p>Balíček: <strong>' . esc_html($tier_name) . '</strong></p>'
                . rd_email_btn('Potvrdit platbu →', admin_url('admin.php?page=refdrive-autoskoly'))
            ),
            ['Content-Type: text/html; charset=UTF-8']
        );
        wp_safe_redirect(admin_url('admin.php?page=refdrive&rd_onboarding=done'));
        exit;
    }
}

function rd_onboarding_redirect() {
    if (!rd_je_autoskola_admin()) return;
    $as = rd_get_my_autoskola();
    if (!$as || !empty($as->onboarding_done)) return;
    $page = $_GET['page'] ?? '';
    // Nechat wizard stránku projít (včetně kroků)
    if ($page === 'refdrive-onboarding') return;
    if (defined('DOING_AJAX') && DOING_AJAX) return;
    if ($_SERVER['REQUEST_METHOD'] === 'POST') return;
    wp_redirect(admin_url('admin.php?page=refdrive-onboarding&krok=1'));
    exit;
}

