                var pages = Math.ceil(total / PAGE);

                function render() {
                    for (var i = 0; i < rows.length; i++) {
                        if (state === 0) {
                            rows[i].style.display = i < 3 ? "" : "none";
                        } else {
                            var from = (state-1)*PAGE;
                            var to = state*PAGE;
                            rows[i].style.display = (i>=from && i<to) ? "" : "none";
