                        p.style.cssText = "display:flex;align-items:center;gap:8px;justify-content:center";
                        var bc = document.createElement("button"); bc.type="button";
                        bc.style.cssText = "font-size:11px;padding:4px 10px;border:1px solid #d1d5db;border-radius:6px;background:#f9fafb;cursor:pointer;color:#6b7280";
                        bc.textContent = "▲ Sbalit"; bc.onclick = function(){ state=0; render(); };
                        var bp = document.createElement("button"); bp.type="button";
                        bp.style.cssText = "font-size:13px;padding:4px 12px;border:1px solid #d1d5db;border-radius:6px;background:#fff;cursor:pointer" + (state<=1?";opacity:.3":"");
                        bp.textContent = "←"; bp.onclick = function(){ if(state>1){state--;render();} };
                        var inf = document.createElement("span");
                        inf.style.cssText = "font-size:12px;color:#374151;font-weight:600;min-width:90px;text-align:center";
                        inf.textContent = ((state-1)*PAGE+1) + "–" + Math.min(state*PAGE,total) + " / " + total;
                        var bn = document.createElement("button"); bn.type="button";
                        bn.style.cssText = "font-size:13px;padding:4px 12px;border:1px solid #d1d5db;border-radius:6px;background:#fff;cursor:pointer" + (state>=pages?";opacity:.3":"");
                        bn.textContent = "→"; bn.onclick = function(){ if(state<pages){state++;render();} };
                        p.appendChild(bc); p.appendChild(bp); p.appendChild(inf); p.appendChild(bn);
                        wrap.appendChild(p);
                    }
                }
                render();
            })(tables[t]);
        }
    }
    document.addEventListener("DOMContentLoaded", rdShowMore);

    // rdShowMore pro mobilní karty (rd-show-mobile divy)
    document.addEventListener("DOMContentLoaded", function() {
        var mobileWrappers = document.querySelectorAll(".rd-show-mobile");
        for (var w = 0; w < mobileWrappers.length; w++) {
            (function(wrapper) {
                var cards = wrapper.querySelectorAll(":scope > div");
