                wrapper.setAttribute("data-sm", "1");

                var total = cards.length;
                var PAGE = 10;
                var state = 0;

                // Wrap div vložíme NA ZAČÁTEK wrapper divu (ne před něj)
                var wrap = document.createElement("div");
                wrap.style.cssText = "text-align:center;padding:0 0 10px";
                wrapper.insertBefore(wrap, wrapper.firstChild);

                function render() {
                    for (var i = 0; i < cards.length; i++) {
                        if (state === 0) {
                            cards[i].style.display = i < 3 ? "" : "none";
                        } else {
                            var from = (state-1)*PAGE;
                            var to = state*PAGE;
                            cards[i].style.display = (i>=from && i<to) ? "" : "none";
                        }
                    }
                    wrap.innerHTML = "";
                    if (state === 0) {
                        var b = document.createElement("button");
