    });
    function rdSortTable(th) {
        var table = th.closest("table");
        var col = Array.from(th.parentNode.children).indexOf(th);
        var asc = !th.classList.contains("asc");
        th.parentNode.querySelectorAll("th").forEach(function(t){t.classList.remove("asc","desc");});
        th.classList.add(asc ? "asc" : "desc");
        var tbody = table.querySelector("tbody");
        // Separate main rows from sub-rows (e.g. OOP audit rows)
        var rows = Array.from(tbody.querySelectorAll("tr")).filter(function(r){return !r.dataset.oopFor;});
        rows.sort(function(a,b){
            var av = a.cells[col] ? a.cells[col].dataset.val || a.cells[col].innerText.trim() : "";
            var bv = b.cells[col] ? b.cells[col].dataset.val || b.cells[col].innerText.trim() : "";
            var an = parseFloat(av.replace(/[^0-9.-]/g,"")), bn = parseFloat(bv.replace(/[^0-9.-]/g,""));
            if (!isNaN(an) && !isNaN(bn)) return asc ? an-bn : bn-an;
            return asc ? av.localeCompare(bv,"cs") : bv.localeCompare(av,"cs");
        });
        // Append main rows, then immediately append their sub-row if exists
        rows.forEach(function(r){
            tbody.appendChild(r);
            var pi = r.dataset.pi;
            if (pi) {
                var sub = tbody.querySelector("tr[data-oop-for=\""+pi+"\"]");
                if (sub) tbody.appendChild(sub);
            }
        });
    }
    </script>
