/* ============================================================
   WORKFLOW ZMĚN REGISTRAČNÍCH ÚDAJŮ AUTOŠKOLY
   Pole podléhající schválení: nazev, ico, dic, ulice, psc, mesto, telefon, email, oop_url
   ============================================================ */

define('RD_POLE_SCHVALENI', [
    'nazev'   => 'Název autoškoly',
    'ico'     => 'IČ',
    'dic'     => 'DIČ',
    'ulice'   => 'Ulice',
    'psc'     => 'PSČ',
    'mesto'   => 'Město',
    'telefon' => 'Telefon',
    'email'   => 'Email',
    'oop_url' => 'URL obchodních podmínek',
    'oop_verze' => 'Verze OOP',
]);

// Přidat submenu pro žádosti o změnu v hlavním adminu
add_action('admin_menu', 'rd_zmeny_menu', 20);
function rd_zmeny_menu() {
    if (!current_user_can('manage_options')) return;
    global $wpdb;
    $cekajici = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_ZMENY . " WHERE stav='ceka'");
    $label = 'Žádosti o změnu' . ($cekajici > 0 ? ' <span class="awaiting-mod count-' . $cekajici . '"><span class="pending-count">' . $cekajici . '</span></span>' : '');
    add_submenu_page('refdrive', 'Žádosti o změnu', $label, 'manage_options', 'refdrive-zmeny', 'rd_admin_zmeny');
}

// Stránka žádostí v hlavním adminu
function rd_admin_zmeny() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');

    // Schválit žádost
    if (isset($_GET['schvalit']) && check_admin_referer('rd_zmena_schvalit_' . intval($_GET['schvalit']))) {
        $z = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_ZMENY . " WHERE id=%d AND stav='ceka' LIMIT 1", intval($_GET['schvalit'])));
        if ($z) {
            $wpdb->update(RD_TABLE_AUTOSKOLY, [$z->pole => $z->nova_hodnota], ['id' => $z->autoskola_id]);
            // Pokud jde o email, aktualizovat i WP uživatele
            if ($z->pole === 'email') {
                $as = $wpdb->get_row($wpdb->prepare("SELECT wp_user_id FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $z->autoskola_id));
                if ($as && $as->wp_user_id) {
                    wp_update_user(['ID' => $as->wp_user_id, 'user_email' => $z->nova_hodnota]);
                }
            }
            // Logovat změnu OOP URL
            if ($z->pole === 'oop_url') {
                rd_as_oop_log($z->autoskola_id, $z->nova_hodnota, 'nastaveni');
            }
            $wpdb->update(RD_TABLE_ZMENY, ['stav' => 'schvaleno', 'vyrizeno' => current_time('mysql')], ['id' => $z->id]);
            // Email autoškole - schválení
            $as_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $z->autoskola_id));
            if ($as_row) {
                rd_email_autoskola($as_row->email,
                    'RefDrive: Změna údajů schválena',
                    rd_email_wrap('Změna údajů schválena',
                        '<p>Vaše žádost o změnu pole <strong>' . esc_html($z->pole_label) . '</strong> byla schválena.</p>'
                        . '<p>Nová hodnota: <strong>' . esc_html($z->nova_hodnota) . '</strong></p>'
                        . rd_email_btn('Přejít do administrace →', admin_url('admin.php?page=refdrive'))
                    )
                );
            }
            echo '<div class="notice notice-success"><p>✓ Změna schválena a uložena.</p></div>';
        }
    }

    // Zamítnout žádost
    if (isset($_POST['rd_zamitnout_zmenu']) && check_admin_referer('rd_zmena_zamitnout_' . intval($_POST['zmena_id']))) {
        $z_id  = intval($_POST['zmena_id']);
        $duvod = sanitize_textarea_field($_POST['duvod'] ?? '');
        $z = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_ZMENY . " WHERE id=%d AND stav='ceka' LIMIT 1", $z_id));
        if ($z) {
            $wpdb->update(RD_TABLE_ZMENY, ['stav' => 'zamitnuto', 'duvod_zamitnuti' => $duvod, 'vyrizeno' => current_time('mysql')], ['id' => $z_id]);
            $as_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $z->autoskola_id));
            if ($as_row) {
                rd_email_autoskola($as_row->email,
                    'RefDrive: Žádost o změnu zamítnuta',
                    rd_email_wrap('Žádost o změnu zamítnuta',
                        '<p>Vaše žádost o změnu pole <strong>' . esc_html($z->pole_label) . '</strong> byla zamítnuta.</p>'
                        . ($duvod ? '<p>Důvod: <strong>' . esc_html($duvod) . '</strong></p>' : '')
                        . '<p>Pokud máte dotazy, kontaktujte nás na <a href="mailto:' . esc_attr(get_option('rd_faktura_email', 'info@refdrive.pro')) . '" style="color:#7c3aed">' . esc_html(get_option('rd_faktura_email', 'info@refdrive.pro')) . '</a>.</p>'
                        . rd_email_btn('Přejít do administrace →', admin_url('admin.php?page=refdrive'), 'secondary')
                    )
                );
            }
            echo '<div class="notice notice-success"><p>✓ Žádost zamítnuta, autoškola informována.</p></div>';
        }
    }

    $zmeny = $wpdb->get_results(
        "SELECT z.*, a.nazev as as_nazev, a.email as as_email
         FROM " . RD_TABLE_ZMENY . " z
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=z.autoskola_id
         ORDER BY z.stav='ceka' DESC, z.vytvoreno DESC
         LIMIT 100"
    );
    $stav_label = ['ceka' => '⏳ Čeká', 'schvaleno' => 'Schváleno', 'zamitnuto' => '✗ Zamítnuto'];
    $stav_color = ['ceka' => '#d97706', 'schvaleno' => '#16a34a', 'zamitnuto' => '#dc2626'];
    ?>
    <div class="wrap">
    <h1>Žádosti o změnu registračních údajů</h1>
    <div style="max-width:900px">

    <?php if (empty($zmeny)): ?>
    <p style="color:#999;padding:16px 0">Žádné žádosti.</p>
    <?php else: ?>
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Autoškola</th>
            <th onclick="rdSortTable(this)">Pole</th>
            <th onclick="rdSortTable(this)">Původní hodnota</th>
            <th onclick="rdSortTable(this)">Nová hodnota</th>
            <th onclick="rdSortTable(this)">Datum</th>
            <th onclick="rdSortTable(this)">Stav</th>
            <th style="color:#6b7280">Poznámka</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach ($zmeny as $z):
            $sc = $z->stav === 'ceka' ? '#d97706' : ($z->stav === 'schvaleno' ? '#15803d' : '#dc2626');
            $sb = $z->stav === 'ceka' ? '#fef3c7' : ($z->stav === 'schvaleno' ? '#dcfce7' : '#fee2e2');
            $sl = $z->stav === 'ceka' ? 'Čeká' : ($z->stav === 'schvaleno' ? 'Schváleno' : 'Zamítnuto');
            $pole_labels = ['nazev'=>'Název','email'=>'E-mail','telefon'=>'Telefon','ico'=>'IČO','dic'=>'DIČ','adresa'=>'Adresa','ulice'=>'Ulice','mesto'=>'Město','psc'=>'PSČ','oop_url'=>'URL obchodních podmínek'];
