            <td><span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:<?php echo $sb; ?>;color:<?php echo $sc; ?>"><?php echo $sl; ?></span></td>
            <td style="font-size:11px;color:#dc2626"><?php echo ($z->stav === 'zamitnuto' && $z->duvod_zamitnuti) ? esc_html($z->duvod_zamitnuti) : ''; ?></td>
