                <button style="display:inline-flex;align-items:center;height:28px;font-size:11px;padding:0 10px;background:#fee2e2;color:#dc2626;border:1px solid #fca5a5;border-radius:5px;white-space:nowrap;cursor:pointer" onclick="var el=document.getElementById('rd-zf-<?php echo $z->id; ?>');el.style.display=el.style.display==='none'?'table-row':'none';">✕ Zamítnout</button>
            <?php endif; ?>
            </td>
        </tr>
        <?php if ($z->stav === 'ceka'): ?>
        <tr id="rd-zf-<?php echo $z->id; ?>" style="display:none;background:#fff8f8">
            <td colspan="7" style="padding:10px 14px">
                <form method="post" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
                    <?php wp_nonce_field('rd_zmena_zamitnout_' . $z->id); ?>
                    <input type="hidden" name="zmena_id" value="<?php echo $z->id; ?>">
                    <input type="hidden" name="rd_zamitnout_zmenu" value="1">
