function rd_podat_zadost_o_zmenu($autoskola_id, $pole, $nova_hodnota) {
    global $wpdb;
    $pole_labels = RD_POLE_SCHVALENI;
    if (!isset($pole_labels[$pole])) return false;
    $stara = $wpdb->get_var($wpdb->prepare("SELECT `$pole` FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $autoskola_id));
    if ($stara === $nova_hodnota) return false; // Beze změny
    // Zrušit předchozí čekající žádost pro stejné pole
    $wpdb->delete(RD_TABLE_ZMENY, ['autoskola_id' => $autoskola_id, 'pole' => $pole, 'stav' => 'ceka']);
    $wpdb->insert(RD_TABLE_ZMENY, [
        'autoskola_id'  => $autoskola_id,
        'pole'          => $pole,
        'pole_label'    => $pole_labels[$pole],
        'stara_hodnota' => $stara,
        'nova_hodnota'  => sanitize_text_field($nova_hodnota),
        'stav'          => 'ceka',
    ]);
    // Notifikace adminovi
    $admin_email = rd_admin_notif_email();
    $as_row = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $autoskola_id));
    wp_mail($admin_email,
        'RefDrive: Žádost o změnu údajů — ' . esc_html($as_row->nazev ?? ''),
        rd_email_wrap('Žádost o změnu údajů',
            '<p>Autoškola <strong>' . esc_html($as_row->nazev ?? '') . '</strong> žádá o změnu pole <strong>' . esc_html($pole_labels[$pole]) . '</strong>.</p>'
            . '<table style="width:100%;border-collapse:collapse;font-size:13px;margin:12px 0">'
            . '<tr><td style="padding:6px 12px;color:#6b7280;border-bottom:1px solid #f3f4f6">Stará hodnota</td><td style="padding:6px 12px;border-bottom:1px solid #f3f4f6">' . esc_html($stara ?: '—') . '</td></tr>'
            . '<tr><td style="padding:6px 12px;color:#6b7280">Nová hodnota</td><td style="padding:6px 12px;font-weight:700">' . esc_html($nova_hodnota) . '</td></tr>'
            . '</table>'
            . rd_email_btn('Schválit nebo zamítnout →', admin_url('admin.php?page=refdrive-zmeny'))
        ),
        ['Content-Type: text/html; charset=UTF-8']
    );
    return true;
}



function rd_odeslat_proforma_fakturu($as, $tier, $platba_id_new) {
    global $wpdb;
    // Proforma faktura autoškole emailem
    $platba_id_new = $wpdb->insert_id;
    $vs_as         = str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($platba_id_new, 6, '0', STR_PAD_LEFT);
    $castka_dph   = round($tier->cena_mesic * 1.21);
    $cislo_uctu_p = get_option('rd_cislo_uctu', '');
    $iban_p       = rd_get_iban(get_option('rd_cislo_uctu', ''), get_option('rd_iban', ''));
    $bic_p        = get_option('rd_bic', '');
    $banka_p      = get_option('rd_banka', '');
    $splatnost_p  = intval(get_option('rd_splatnost', 14));
    $faktura_pozn_p = get_option('rd_faktura_pozn', '');
    $dod_nazev    = get_option('rd_faktura_nazev', get_bloginfo('name'));
    $dod_ico      = get_option('rd_faktura_ico', '');
    $dod_dic      = get_option('rd_faktura_dic', '');
    $dod_ulice    = get_option('rd_faktura_ulice', '');
    $dod_mesto    = get_option('rd_faktura_mesto', '');
    $dod_psc      = get_option('rd_faktura_psc', '');
    $dod_adresa   = trim($dod_ulice . ', ' . $dod_psc . ' ' . $dod_mesto, ', ');

    // Sestavit obsah emailu
    $tabulka = '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:16px 0">'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Dodavatel</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($dod_nazev) . '</td></tr>'
        . ($dod_ico ? '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">IČ dodavatele</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($dod_ico) . '</td></tr>' : '')
        . ($dod_dic ? '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">DIČ dodavatele</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($dod_dic) . '</td></tr>' : '')
        . ($dod_adresa ? '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Adresa</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($dod_adresa) . '</td></tr>' : '')
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Odběratel</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($as->nazev) . '</td></tr>'
        . ($as->ico ? '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">IČ odběratele</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($as->ico) . '</td></tr>' : '')
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Balíček</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($tier->nazev) . ($tier->popis ? ' — ' . esc_html($tier->popis) : '') . '</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Bez DPH</td><td style="padding:7px 0;font-size:13px;text-align:right;border-bottom:1px solid #e5e7eb;color:#6b7280">' . number_format($tier->cena_mesic) . ' Kč</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;font-weight:500">Celkem s DPH</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;color:#7c3aed">' . number_format($castka_dph) . ' Kč</td></tr>'
        . '</table>';

    $platebni = '<div style="background:#f9f8ff;border:1px solid #e5e7eb;border-radius:8px;padding:16px 20px;margin-top:4px">'
        . '<p style="font-size:11px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px">Platební instrukce</p>'
        . '<p style="font-size:13px;color:#111827;line-height:2;margin:0">'
        . 'Číslo účtu: <strong>' . esc_html($cislo_uctu_p) . '</strong><br>'
        . ($iban_p ? 'IBAN: <strong>' . esc_html($iban_p) . '</strong><br>' : '')
        . ($bic_p  ? 'BIC/SWIFT: <strong>' . esc_html($bic_p) . '</strong><br>' : '')
        . ($banka_p ? 'Banka: <strong>' . esc_html($banka_p) . '</strong><br>' : '')
        . 'Variabilní symbol: <strong>' . $vs_as . '</strong>'
        . ($faktura_pozn_p ? '<br><br><em style="color:#6b7280">' . esc_html($faktura_pozn_p) . '</em>' : '')
        . '</p></div>';

    $qr_html = '';
    if ($iban_p) {
        $iban_clean = preg_replace('/\s+/', '', $iban_p);
        $spd = 'SPD*1.0*ACC:' . $iban_clean . '*AM:' . number_format($castka_dph, 2, '.', '') . '*CC:CZK*MSG:Predplatne+RefDrive*X-VS:' . $vs_as;
        $qr_html = '<div style="margin-top:20px;text-align:center">'
            . '<p style="font-size:11px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.08em;margin:0 0 8px">Zaplatit mobilní bankou</p>'
            . '<img loading="eager" src="https://api.qrserver.com/v1/create-qr-code/?size=160x160&ecc=M&data=' . rawurlencode($spd) . '" width="160" height="160" alt="QR platba" style="display:block;margin:0 auto;border-radius:8px;border:1px solid #e5e7eb">'
            . '<p style="font-size:11px;color:#9ca3af;margin:6px 0 0">Naskenujte QR kód v mobilní aplikaci své banky</p>'
            . '</div>';
    }

    $zaver = '<p style="font-size:13px;color:#6b7280;margin-top:16px">Po připsání platby na účet vám zašleme potvrzení a váš přístup bude aktivován — obvykle do 2 pracovních dnů.</p>';

    $proforma = rd_email_wrap(
        'Proforma faktura — ' . esc_html($tier->nazev),
        '<p>Děkujeme za výběr balíčku <strong>' . esc_html($tier->nazev) . '</strong>. Po přijetí platby bude váš přístup aktivován.</p>'
        . $tabulka . $platebni . $qr_html . $zaver
    );
    rd_email_autoskola($as->email, 'RefDrive: Proforma faktura — ' . $tier->nazev, $proforma);
}

