// Přepsat starý text souhlasu pokud obsahuje starý text
add_action('init', function() {
    $current = get_option('rd_text_reg_souhlas', '');
    if ($current && strpos($current, 'obchodními podmínkami</a>. Beru') !== false && strpos($current, 'RefDrive.pro') === false) {
        $new_val = str_replace('>obchodními podmínkami<', '>obchodními podmínkami platformy RefDrive.pro<', $current);
        update_option('rd_text_reg_souhlas', $new_val);
    }
}, 1);
function rd_aktivace() {
    // Naplánovat cron pro expirace kódů
    if (!wp_next_scheduled('rd_kody_expirace_check')) {
        wp_schedule_event(strtotime('tomorrow 08:00'), 'daily', 'rd_kody_expirace_check');
    }
    if (!wp_next_scheduled('rd_predplatne_check')) {
        wp_schedule_event(strtotime('tomorrow 09:00'), 'daily', 'rd_predplatne_check');
    }
    if (!wp_next_scheduled('rd_ridici_retence_check')) {
        wp_schedule_event(strtotime('tomorrow 10:00'), 'daily', 'rd_ridici_retence_check');
    }
    // Přepsat starý text souhlasu
    $old = get_option('rd_text_reg_souhlas', '');
    if ($old && (strpos($old, 'RefDrive.pro') === false || strpos($old, 'certifikovaného OZO') !== false)) { delete_option('rd_text_reg_souhlas'); }
    global $wpdb;
    $c = $wpdb->get_charset_collate();
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    dbDelta("CREATE TABLE IF NOT EXISTS " . RD_TABLE_KODY . " (
        id            INT AUTO_INCREMENT PRIMARY KEY,
        firma_nazev   VARCHAR(200) NOT NULL,
        firma_email   VARCHAR(200) NOT NULL,
