        'op_souhlas_ip'    => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN op_souhlas_ip VARCHAR(45) DEFAULT NULL",
        'oop_url_verze'    => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN oop_url_verze VARCHAR(500) DEFAULT NULL",
        'oop_verze'        => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN oop_verze VARCHAR(50) DEFAULT NULL",
        'stripe_pk'        => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN stripe_pk VARCHAR(200) DEFAULT NULL",
        'stripe_sk'        => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN stripe_sk VARCHAR(200) DEFAULT NULL",
        'stripe_aktivni'   => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN stripe_aktivni TINYINT(1) DEFAULT 0",
        'stripe_overeno'   => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN stripe_overeno TINYINT(1) DEFAULT 0",
        'predplatne_expiruje' => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN predplatne_expiruje DATE DEFAULT NULL",
        'expir_email_7d'      => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN expir_email_7d TINYINT(1) DEFAULT 0",
        'expir_email_0d'      => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN expir_email_0d TINYINT(1) DEFAULT 0",
        'expir_email_7po'     => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN expir_email_7po TINYINT(1) DEFAULT 0",
        'expir_grace_od'      => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN expir_grace_od DATE DEFAULT NULL",
        'expir_email_arch'    => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN expir_email_arch TINYINT(1) DEFAULT 0",
        'anonymizovano'       => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN anonymizovano TINYINT(1) DEFAULT 0",
        'onboarding_done'     => "ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN onboarding_done TINYINT(1) DEFAULT 0",
    ];
    foreach ($as_sloupce as $sloupec => $sql) {
        if (!in_array($sloupec, $cols_as)) $wpdb->query($sql);
    }

    // Tabulka žádostí o změnu registračních údajů
    dbDelta("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_zmeny_zadosti (
        id               INT AUTO_INCREMENT PRIMARY KEY,
        autoskola_id     INT NOT NULL,
        pole             VARCHAR(50) NOT NULL,
        pole_label       VARCHAR(100) NOT NULL,
        stara_hodnota    TEXT,
        nova_hodnota     TEXT,
        stav             VARCHAR(20) DEFAULT 'ceka',
        duvod_zamitnuti  TEXT,
        vytvoreno        DATETIME DEFAULT CURRENT_TIMESTAMP,
        vyrizeno         DATETIME DEFAULT NULL,
        INDEX idx_as (autoskola_id),
        INDEX idx_stav (stav)
    ) $c;");

    // Přidat autoskola_id do rd_kody pokud ještě není
    $cols_kody = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_KODY);
    if (!in_array('autoskola_id', $cols_kody)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN autoskola_id INT DEFAULT NULL");
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN expiruje DATE DEFAULT NULL");
    }

    // Přidat autoskola_id do rd_ridici pokud ještě není
    $cols_ridici = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_RIDICI);
    if (!in_array('autoskola_id', $cols_ridici)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_RIDICI . " ADD COLUMN autoskola_id INT DEFAULT NULL");
    }
    if (!in_array('retence_email_30d', $cols_ridici)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_RIDICI . " ADD COLUMN retence_email_30d TINYINT(1) DEFAULT 0");
    }

    // Přidat nakupni_cena a cena_smer do rd_firma_autoskola
    $cols_fa = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_FIRMA_AS);
    if (!in_array('nakupni_cena', $cols_fa)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_FIRMA_AS . " ADD COLUMN nakupni_cena INT DEFAULT NULL");
    }
    if (!in_array('cena_smer', $cols_fa)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_FIRMA_AS . " ADD COLUMN cena_smer VARCHAR(10) DEFAULT NULL");
    }
    // Doplnit nakupni_cena z historických objednávek (pro existující firmy)
    $fa_rows = $wpdb->get_results("SELECT * FROM " . RD_TABLE_FIRMA_AS);
    foreach ($fa_rows as $fa) {
        // Hledat přes všechny objednávky - stav zaplaceno/hotovo/prevod_ok
        $obj_rows = $wpdb->get_results(
            "SELECT data FROM " . RD_TABLE_OBJ . " WHERE stav IN ('zaplaceno','hotovo','prevod_ok') ORDER BY vytvoreno DESC"
        );
        // Načíst email firmy pro spárování
        $firma_email_migr = $wpdb->get_var($wpdb->prepare(
            "SELECT email FROM {$wpdb->prefix}rd_firmy WHERE id=%d LIMIT 1",
            intval($fa->firma_id)
        ));
        foreach ($obj_rows as $obj) {
            $d = json_decode($obj->data ?? '{}', true);
            $d_firma_id = intval($d['firma_id'] ?? 0);
            $d_as_id    = intval($d['autoskola_id'] ?? 0);
            $d_cena     = intval($d['cena'] ?? 0);
            $d_email    = $d['firma_email'] ?? '';
            // Spárovat přes firma_id nebo email
            $firma_match = ($d_firma_id === intval($fa->firma_id)) ||
                           ($firma_email_migr && $d_email === $firma_email_migr);
            $as_match = $d_as_id === intval($fa->autoskola_id);
            if ($firma_match && $as_match && $d_cena > 0) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE " . RD_TABLE_FIRMA_AS . " SET nakupni_cena=%d WHERE id=%d",
                    $d_cena, $fa->id
                ));
                break;
            }
        }
    }

    // Přidat autoskola_id do rd_objednavky pokud ještě není
    $cols_obj_as = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_OBJ);
    $obj_sloupce = [
        'oop_url_snapshot'      => "ALTER TABLE " . RD_TABLE_OBJ . " ADD COLUMN oop_url_snapshot VARCHAR(500) DEFAULT NULL",
        'oop_verze_snapshot'    => "ALTER TABLE " . RD_TABLE_OBJ . " ADD COLUMN oop_verze_snapshot VARCHAR(50) DEFAULT NULL",
        'oop_souhlas_datum'=> "ALTER TABLE " . RD_TABLE_OBJ . " ADD COLUMN oop_souhlas_datum DATETIME DEFAULT NULL",
        'oop_souhlas_ip'   => "ALTER TABLE " . RD_TABLE_OBJ . " ADD COLUMN oop_souhlas_ip VARCHAR(45) DEFAULT NULL",
    ];
    foreach ($obj_sloupce as $sloupec => $sql) {
        if (!in_array($sloupec, $cols_obj_as)) $wpdb->query($sql);
    }
    $cols_obj = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_OBJ);
    if (!in_array('autoskola_id', $cols_obj)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_OBJ . " ADD COLUMN autoskola_id INT DEFAULT NULL");
    }

    // Přidat dic do rd_firmy pokud ještě není
    $cols_firmy = $wpdb->get_col("SHOW COLUMNS FROM {$wpdb->prefix}rd_firmy");
    if (!in_array('dic', $cols_firmy)) {
        $wpdb->query("ALTER TABLE {$wpdb->prefix}rd_firmy ADD COLUMN dic VARCHAR(20) DEFAULT NULL");
    }

    // v6.1.0 — přidat cena_kus do rd_autoskoly pokud ještě není
    $cols_as = $wpdb->get_col("SHOW COLUMNS FROM " . RD_TABLE_AUTOSKOLY);
    if (!in_array('cena_kus', $cols_as)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN cena_kus INT NOT NULL DEFAULT 99");
    }

    // v6.1.0 — tabulka pro sledování změn cen a lhůt pro firmy
    dbDelta("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_as_cena_log (
        id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
        autoskola_id bigint(20) UNSIGNED NOT NULL,
        cena_kus int(11) NOT NULL,
        zdroj varchar(32) NOT NULL DEFAULT 'nastaveni',
        vytvoreno datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (id),
        KEY autoskola_id (autoskola_id)
    ) $charset_collate;");

    dbDelta("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_as_oop_log (
        id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
        autoskola_id bigint(20) UNSIGNED NOT NULL,
        oop_url varchar(500) NOT NULL DEFAULT '',
        zdroj varchar(32) NOT NULL DEFAULT 'nastaveni',
        vytvoreno datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (id),
        KEY autoskola_id (autoskola_id)
    ) $charset_collate;");

    // Vložit výchozí tiery pokud ještě neexistují
    $existing_tiery = $wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AS_TIERY);
    if (!$existing_tiery) {
        $tiery = [
            ['nazev'=>'Starter',    'popis'=>'Pro vyzkoušení platformy',     'limit_kodu'=>5,    'cena_mesic'=>190,  'poradi'=>1],
            ['nazev'=>'Základní',   'popis'=>'Ideální pro začátek',         'limit_kodu'=>50,   'cena_mesic'=>1490, 'poradi'=>2],
            ['nazev'=>'Standard',   'popis'=>'Pro aktivní autoškoly',       'limit_kodu'=>200,  'cena_mesic'=>2990, 'poradi'=>3],
            ['nazev'=>'Pro',        'popis'=>'Pro velké autoškoly',         'limit_kodu'=>500,  'cena_mesic'=>5490, 'poradi'=>4],
            ['nazev'=>'Neomezený', 'popis'=>'Bez omezení počtu kódů',      'limit_kodu'=>99999,'cena_mesic'=>9490, 'poradi'=>5],
        ];
        foreach ($tiery as $t) {
            $wpdb->insert(RD_TABLE_AS_TIERY, $t);
        }
    }

    // Výchozí autoškola pro migraci stávajících dat (Test s.r.o.)
    $existing_as = $wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AUTOSKOLY);
    if (!$existing_as) {
        $tier_id = $wpdb->get_var("SELECT id FROM " . RD_TABLE_AS_TIERY . " WHERE poradi=4 LIMIT 1");
        $wpdb->insert(RD_TABLE_AUTOSKOLY, [
            'slug'      => 'test-sro',
            'nazev'     => 'Test s.r.o.',
            'email'     => 'test@refdrive.pro',
            'telefon'   => '',
            'ico'       => '00000001',
            'dic'       => 'CZ00000001',
            'ulice'     => 'Testovací 1',
            'mesto'     => 'Praha',
            'psc'       => '10000',
            'kraj'      => 'Hlavní město Praha',
            'tier_id'   => $tier_id,
            'stav'      => 'aktivni',
            'op_souhlas'=> 1,
        ]);
        $as_id = $wpdb->insert_id;

        // Vytvořit WP uživatele pro testovací autoškolu
        if (!get_user_by('email', 'test@refdrive.pro')) {
            $wp_user_id = wp_create_user('test-autoskola', 'Test1234!', 'test@refdrive.pro');
            if (!is_wp_error($wp_user_id)) {
                $wp_user = new WP_User($wp_user_id);
                $wp_user->set_role('autoskola_admin');
                wp_update_user(['ID' => $wp_user_id, 'display_name' => 'Test s.r.o.', 'first_name' => 'Test', 'last_name' => 's.r.o.']);
                update_user_meta($wp_user_id, 'rd_autoskola_id', $as_id);
                $wpdb->update(RD_TABLE_AUTOSKOLY, ['wp_user_id' => $wp_user_id], ['id' => $as_id]);
            }
        }

        // Migrovat stávající kódy, řidiče a objednávky pod výchozí autoškolu
        $wpdb->query($wpdb->prepare("UPDATE " . RD_TABLE_KODY . " SET autoskola_id=%d WHERE autoskola_id IS NULL", $as_id));
        $wpdb->query($wpdb->prepare("UPDATE " . RD_TABLE_RIDICI . " SET autoskola_id=%d WHERE autoskola_id IS NULL", $as_id));
        $wpdb->query($wpdb->prepare("UPDATE " . RD_TABLE_OBJ . " SET autoskola_id=%d WHERE autoskola_id IS NULL", $as_id));
        // Migrovat stávající firmy pod výchozí autoškolu
        $firmy = $wpdb->get_col("SELECT id FROM {$wpdb->prefix}rd_firmy");
        foreach ($firmy as $firma_id) {
            $wpdb->insert(RD_TABLE_FIRMA_AS, [
                'firma_id'     => $firma_id,
                'autoskola_id' => $as_id,
                'kmenova'      => 1,
            ]);
        }
    }

    rd_vytvorit_stranky();
    // Menu vytvořit až po stránkách (potřebuje jejich ID)
    add_action('init', 'rd_vytvorit_menu', 99);
}

function rd_vytvorit_menu() {
    // Vytvořit menu pokud neexistuje
    $menu_name = 'Hlavní menu';
    $menu_exists = wp_get_nav_menu_object($menu_name);
    if ($menu_exists) return; // Již existuje

    $menu_id = wp_create_nav_menu($menu_name);
    if (is_wp_error($menu_id)) return;

    // Přidat položky menu
    $polozky = [
        ['title' => 'Objednávka',         'slug' => 'objednavka'],
    ];

    foreach ($polozky as $p) {
        $page = get_page_by_path($p['slug']);
        if ($page) {
            wp_update_nav_menu_item($menu_id, 0, [
                'menu-item-title'     => $p['title'],
                'menu-item-object'    => 'page',
                'menu-item-object-id' => $page->ID,
                'menu-item-type'      => 'post_type',
                'menu-item-status'    => 'publish',
            ]);
        }
    }

    // Přiřadit menu k lokaci šablony
    $locations = get_theme_mod('nav_menu_locations', []);
    $locations['primary'] = $menu_id;
    set_theme_mod('nav_menu_locations', $locations);
}

function rd_vytvorit_stranky() {
    $stranky = [
        ['title' => 'Školení řidičů',       'slug' => 'skoleni-ridicu',        'content' => '[rd_uvod_platform]',           'home' => true],
        ['title' => 'Přihlášení',            'slug' => 'prihlaseni',            'content' => '[rd_prihlaseni]',              'home' => false],
        ['title' => 'Kurz',                  'slug' => 'kurz',                  'content' => '[rd_kurz]',                    'home' => false],
        ['title' => 'Závěrečný test',        'slug' => 'zaverecny-test',        'content' => '[rd_kviz]',                    'home' => false],
        ['title' => 'Certifikát',            'slug' => 'certifikat',            'content' => '[rd_certifikat]',              'home' => false],
        ['title' => 'Objednávka',            'slug' => 'objednavka',            'content' => '[rd_objednavka]',              'home' => false],
        ['title' => 'Děkujeme',              'slug' => 'dekujeme',              'content' => '[rd_dekujeme]',                'home' => false],
        ['title' => 'Firemní přístup',       'slug' => 'firma-portal',          'content' => '[rd_firma_portal]',            'home' => false],
        ['title' => 'Novinky 2026',          'slug' => 'novinky-2026',          'content' => '[rd_novinky]',                 'home' => false],
        ['title' => 'FAQ',                    'slug' => 'faq',                   'content' => '[rd_faq]',                      'home' => false],
        ['title' => 'Jak to funguje',      'slug' => 'jaktofunguje',          'content' => '[rd_jaktofunguje]',             'home' => false],
        ['title' => 'Legislativa',           'slug' => 'legislativa',           'content' => '[rd_legislativa]',             'home' => false],
        ['title' => 'Ověření certifikátu',   'slug' => 'overit',                'content' => '[rd_overit]',                  'home' => false],
        ['title' => 'Lektor',                'slug' => 'lektor',                'content' => '[rd_lektor]',                  'home' => false],
        // v6.0.0
        ['title' => 'Registrace autoškoly',  'slug' => 'registrace-autoskoly',  'content' => '[rd_registrace_autoskoly]',    'home' => false],
    ];
    foreach ($stranky as $s) {
        $existing = get_page_by_path($s['slug']);
        if (!$existing) {
            $id = wp_insert_post(['post_title' => $s['title'], 'post_name' => $s['slug'],
                'post_content' => $s['content'], 'post_status' => 'publish', 'post_type' => 'page']);
            if ($s['home']) { update_option('page_on_front', $id); update_option('show_on_front', 'page'); }
            // Fullwidth template pro jaktofunguje
            if ($s['slug'] === 'jaktofunguje' && $id) update_post_meta($id, '_wp_page_template', 'page-fullwidth.php');
        } elseif (empty(trim($existing->post_content)) || trim($existing->post_content) === $s['slug']) {
            wp_update_post(['ID' => $existing->ID, 'post_content' => $s['content']]);
        } elseif (strpos($existing->post_content, '[rd_') === false) {
            // Stránka existuje ale shortcode chybí (text bez hranatých závorek)
            wp_update_post(['ID' => $existing->ID, 'post_content' => $s['content']]);
        }
    }
}

