// Zpracovat akce poptávek autoškoly (Potvrdit / Odmítnout)
add_action('admin_init', function() {
    if (!rd_je_autoskola_admin()) return;
    if (empty($_GET['rd_poptavka_akce']) || empty($_GET['pid']) || empty($_GET['_wpnonce'])) return;

    $pid   = intval($_GET['pid']);
    $akce  = sanitize_key($_GET['rd_poptavka_akce']);
    if (!wp_verify_nonce($_GET['_wpnonce'], 'rd_popt_' . $akce . '_' . $pid)) return;

    global $wpdb;
    $as     = rd_get_my_autoskola();
    if (!$as) return;

    $popt = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}rd_poptavky WHERE id=%d AND autoskola_id=%d AND stav='nova' LIMIT 1",
        $pid, $as->id
    ));
    if (!$popt) return;

    $from    = get_option('rd_smtp_from', get_option('admin_email'));
    $fname   = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $fname . ' <' . $from . '>'];

    if ($akce === 'potvrdit') {
        $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'potvrzena'], ['id' => $pid]);
        wp_mail($popt->firma_email,
            'Vaše poptávka školení — autoškola potvrdila zájem',
            rd_email_wrap('Autoškola přijala vaši poptávku',
                '<p>Dobrý den, <strong>' . esc_html($popt->firma_nazev) . '</strong>,</p>'
                . '<p>autoškola <strong>' . esc_html($as->nazev) . '</strong> vaši poptávku přijala a pracuje na navýšení kapacity pro <strong>' . intval($popt->pocet) . ' řidičů</strong>.</p>'
                . '<p>Jakmile bude kapacita připravena, obdržíte okamžitě další email s odkazem pro dokončení objednávky.</p>'
                . '<p style="font-size:12px;color:#6b7280">Obvykle to trvá jen několik hodin. Děkujeme za trpělivost.</p>'
            ),
            $headers
        );

    } elseif ($akce === 'odmitnout') {
        // Autoškola odmítne — hledat jinou s dostatečnou kapacitou
        $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $pid]);

        $jina_as = $wpdb->get_row($wpdb->prepare(
            "SELECT a.* FROM " . RD_TABLE_AUTOSKOLY . " a
             WHERE a.stav='aktivni' AND a.id != %d
               AND " . rd_sql_kapacita_podminka('a', intval($popt->pocet)) . "
             LIMIT 1",
            $as->id
        ));

        if ($jina_as) {
            $jina_url = add_query_arg('ref', $jina_as->slug, home_url('/objednavka/'));
            wp_mail($popt->firma_email,
                'Vaše poptávka školení — alternativní autoškola',
                rd_email_wrap('Poptávka vyřízena — alternativní autoškola',
                    '<p>Dobrý den, <strong>' . esc_html($popt->firma_nazev) . '</strong>,</p>'
                    . '<p>autoškola <strong>' . esc_html($as->nazev) . '</strong> bohužel nemůže váš zájem o <strong>' . intval($popt->pocet) . ' řidičů</strong> v tuto chvíli obsloužit.</p>'
                    . '<p>Dovolujeme si vám nabídnout alternativní autoškolu: <strong>' . esc_html($jina_as->nazev) . '</strong>'
                    . ($jina_as->mesto ? ' (' . esc_html($jina_as->mesto) . ')' : '') . ', která má pro vás kapacitu.</p>'
                    . rd_email_btn('Objednat u ' . esc_html($jina_as->nazev) . ' →', $jina_url)
                ),
                $headers
            );
        } else {
            // Žádná alternativa
            wp_mail($popt->firma_email,
                'Vaše poptávka školení — omlouváme se',
                rd_email_wrap('Kapacity momentálně vyčerpány',
                    '<p>Dobrý den, <strong>' . esc_html($popt->firma_nazev) . '</strong>,</p>'
                    . '<p>autoškola <strong>' . esc_html($as->nazev) . '</strong> bohužel nemůže vaši poptávku obsloužit a v tuto chvíli nejsou k dispozici ani alternativní autoškoly s dostatečnou kapacitou pro <strong>' . intval($popt->pocet) . ' řidičů</strong>.</p>'
                    . '<p>Ozveme se vám, jakmile bude kapacita obnovena.</p>'
                ),
                $headers
            );
        }
    }

    wp_redirect(admin_url('admin.php?page=refdrive'));
    exit;
});

// Přesměrovat ?ref= z hlavní stránky na /objednavka/
add_action('template_redirect', function() {
    if (is_front_page() && !empty($_GET['ref'])) {
