add_action('login_footer', function() { ?>
<script>
document.addEventListener("DOMContentLoaded", function() {
    var form = document.getElementById("loginform");
    if (!form) return;
    if (document.getElementById("rd-logo")) return;

    var logo = document.createElement("div");
    logo.id = "rd-logo";
    logo.innerHTML = "<span class=\"rd-logo-text\">RefDrive.pro</span><span class=\"rd-logo-sub\">Portál autoškol</span>";
    form.insertBefore(logo, form.firstChild);

    var links = document.createElement("div");
    links.id = "rd-links";
    var forgetRow = form.querySelector(".forgetmenot");
    var lostLink = null;
    if (forgetRow) { lostLink = forgetRow.querySelector("a"); if (lostLink) lostLink.parentNode.removeChild(lostLink); }
    if (!lostLink) { var navEl = document.getElementById("nav"); if (navEl) lostLink = navEl.querySelector("a"); }
    var backEl = document.getElementById("backtoblog");
    var backLink = backEl ? backEl.querySelector("a") : null;
    if (lostLink) { var a1 = lostLink.cloneNode(true); links.appendChild(a1); }
    if (backLink) { var a2 = backLink.cloneNode(true); links.appendChild(a2); }
    if (links.children.length) form.appendChild(links);

    function hideCapsLock() {
        document.querySelectorAll(".indicator-hint, .caps-lock-warning, [class*=\"indicator\"]").forEach(function(el) {
            el.style.cssText = "display:none!important;height:0!important;overflow:hidden!important;";
        });
    }
    hideCapsLock();
    new MutationObserver(function(mutations) {
        mutations.forEach(function(m) {
            m.addedNodes.forEach(function(node) {
                if (node.nodeType !== 1) return;
                if (node.className && node.className.indexOf("indicator") !== -1) { node.style.cssText = "display:none!important;height:0!important;"; }
            });
            if (m.type === "attributes" && m.target.className && m.target.className.indexOf("indicator") !== -1) { m.target.style.cssText = "display:none!important;height:0!important;"; }
        });
    }).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ["style"] });
});
window.addEventListener("pageshow", function(e) { if (e.persisted) { window.location.reload(); } });
</script>
<?php });

