// Zavřít session okamžitě při WordPress loopback (Site Health test)
add_action('init', function() {
    if (session_status() !== PHP_SESSION_ACTIVE) return;
    $ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
    if (strpos($ua, 'WordPress') !== false) {
        session_write_close();
    }
}, 2);

// Pojistka — zavřít session po dokončení WP bootstrapu, před jakýmkoliv HTTP outbound requestem
add_action('wp_loaded', function() {
    if (session_status() === PHP_SESSION_ACTIVE) {
        session_write_close();
    }
}, 999);

// Zavřít session těsně před renderingem šablony — data jsou již přečtena z init hooků
// Výjimka: stránky kde shortcodes aktivně zapisují do session (přihlášení, kurz, kvíz)
add_action('template_redirect', function() {
    if (session_status() !== PHP_SESSION_ACTIVE) return;
    $uri = $_SERVER['REQUEST_URI'] ?? '';
    $session_pages = ['prihlaseni', 'kurz', 'kviz', 'certifikat', 'dekujeme', 'overit'];
    foreach ($session_pages as $p) {
        if (strpos($uri, $p) !== false) return;
    }
    session_write_close();
}, 1);

// Helper — vrací true pokud je aktuální požadavek REST API nebo WordPress loopback
function rd_is_rest() {
    if (defined('REST_REQUEST') && REST_REQUEST) return true;
    if (isset($_SERVER['REQUEST_URI'])) {
        $rest_prefix = function_exists('rest_get_url_prefix') ? rest_get_url_prefix() : 'wp-json';
        if (strpos($_SERVER['REQUEST_URI'], '/' . $rest_prefix . '/') !== false) return true;
    }
    // WordPress Site Health loopback test
    $ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
    if (strpos($ua, 'WordPress') !== false) return true;
    return false;
}

// Secure + HttpOnly flag na session cookies — nastaveno přímo při načtení pluginu (viz začátek souboru)

// Objednávka – nepřihlášená firma bez ref odkazu → na přihlášení
// Nepřihlášená firma S ref odkazem → může objednat (vytvoří si účet)
add_action('template_redirect', function() {
    if (!is_page('objednavka')) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    // Pustit: přihlášená firma NEBO firma přicházející přes ref odkaz
    if (empty($_SESSION['rd_firma_id']) && empty($_GET['ref'])) {
        wp_redirect(home_url('/firma-portal/?rd_login=1'));
        exit;
    }
}, 1);

// Zakázat cachování stránky /objednavka/ — cena se musí číst čerstvě z DB
add_action('template_redirect', function() {
    if (!is_page('objednavka')) return;
    // Bez ?ref= vždy přesměrovat
    if (empty($_GET['ref'])) {
        wp_redirect(home_url('/#autoskoly'));
        exit;
    }

    if (!defined('DONOTCACHEPAGE')) define('DONOTCACHEPAGE', true);
    if (!defined('DONOTCACHEDB'))   define('DONOTCACHEDB',   true);
    if (!headers_sent()) {
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
        header('Pragma: no-cache');
        header('Expires: Thu, 01 Jan 1970 00:00:00 GMT');
    }
}, 1);

// Přesměrovat přihlášeného řidiče z firemního portálu a objednávky
add_action('template_redirect', function() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    // Pouze pokud je student přihlášen (má rd_kod)
    if (!isset($_SESSION['rd_kod'])) return;
    if (isset($_SESSION['rd_firma_id']) || isset($_SESSION['rd_lektor'])) return;
    $uri = trim(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), '/');
    // Na /prihlaseni/ přesměrovat přihlášeného studenta jinam
    if (strpos($uri, 'prihlaseni') !== false) {
        global $wpdb;
        $splnil = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1",
            $_SESSION['rd_kod']
        ));
        if ($splnil) {
            $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
            $_SESSION['rd_cert_jmeno'] = $splnil->jmeno;
            $_SESSION['rd_cert_datum'] = date('d.m.Y', strtotime($splnil->datum_skoleni));
            $_SESSION['rd_cert_firma'] = $kr ? $kr->firma_nazev : '';
            $_SESSION['rd_cert_score'] = $splnil->score;
            $_SESSION['rd_cert_uuid']  = $splnil->cert_uuid;
            $_SESSION['rd_cert_kod']   = $_SESSION['rd_kod'];
            $_SESSION['rd_cert_token'] = $_SESSION['rd_token'] ?? '';
            wp_redirect(home_url('/certifikat/')); exit;
        }
        wp_redirect(home_url('/kurz/')); exit;
    }
}, 1);

// Opravit prázdné stránky při každém načtení
add_action('init', function() {
    if (!is_admin()) return;
    $fix = ['novinky-2026' => '[rd_novinky]', 'faq' => '[rd_faq]', 'jaktofunguje' => '[rd_jaktofunguje]', 'lektor' => '[rd_lektor]', 'legislativa' => '[rd_legislativa]', 'overit' => '[rd_overit]', 'prihlaseni' => '[rd_prihlaseni]', 'kurz' => '[rd_kurz]', 'certifikat' => '[rd_certifikat]', 'firma-portal' => '[rd_firma_portal]'];
    foreach ($fix as $slug => $shortcode) {
        $page = get_page_by_path($slug);
        if ($page && empty(trim($page->post_content))) {
            wp_update_post(['ID' => $page->ID, 'post_content' => $shortcode]);
        }
    }
}, 20);

add_action('customize_register', function($wp_customize) {
    $themes = rd_get_color_themes();
    $choices = [];
    foreach ($themes as $key => $t) {
        $choices[$key] = $t['name'];
    }

    $wp_customize->add_section('rd_color_section', [
        'title'    => 'Barevné téma',
        'priority' => 30,
    ]);

    $wp_customize->add_setting('rd_color_theme', [
        'default'           => 'aurora',
        'sanitize_callback' => 'sanitize_text_field',
        'transport'         => 'postMessage',
    ]);

    $wp_customize->add_control('rd_color_theme', [
        'label'   => 'Vyberte barevné téma',
        'section' => 'rd_color_section',
        'type'    => 'radio',
        'choices' => $choices,
    ]);
});

add_action('customize_save_after', function($manager) {
    $val = $manager->get_setting('rd_color_theme');
    if ($val) {
        $v = sanitize_text_field($val->value());
        update_option('rd_color_theme', $v);
        set_theme_mod('rd_color_theme', $v);
    }
});

// Live preview via postMessage
add_action('customize_preview_init', function() {
