add_action('phpmailer_init', 'rd_smtp_setup');

// Přepsat From header přímo v wp_mail
add_filter('wp_mail', function($args) {
    if (!get_option('rd_smtp_on', 0)) return $args;
    $from      = get_option('rd_smtp_from', '');
    $from_name = get_option('rd_smtp_from_name', get_bloginfo('name'));
    if (!$from) return $args;
    // Odstranit existující From headers a přidat správný
    $headers = is_array($args['headers']) ? $args['headers'] : explode("\n", $args['headers']);
    $headers = array_filter($headers, function($h) {
        return stripos($h, 'from:') === false;
    });
    $headers[] = 'From: ' . $from_name . ' <' . $from . '>';
    $args['headers'] = array_values($headers);
    return $args;
}, 999);

// Vynutit odesílatele přes phpmailer s nejvyšší prioritou
add_action('phpmailer_init', function($phpmailer) {
    if (!get_option('rd_smtp_on', 0)) return;
    $from = get_option('rd_smtp_from', '');
    $name = get_option('rd_smtp_from_name', get_bloginfo('name'));
    if ($from) {
        $phpmailer->From     = $from;
        $phpmailer->FromName = $name ?: 'RefDrive';
        $phpmailer->Sender   = $from;
        $phpmailer->clearReplyTos();
        $phpmailer->addReplyTo($from, $name ?: 'RefDrive');
    }
}, 999);

// Vynutit správného odesílatele z nastavení SMTP
add_filter('wp_mail_from', function($email) {
    if (!get_option('rd_smtp_on', 0)) return $email;
    $from = get_option('rd_smtp_from', '');
    return $from ?: $email;
});
add_filter('wp_mail_from_name', function($name) {
    if (!get_option('rd_smtp_on', 0)) return $name;
    $from_name = get_option('rd_smtp_from_name', '');
    return $from_name ?: $name;
});
function rd_smtp_setup($phpmailer) {
    if (!get_option('rd_smtp_on', 0)) return;
    $host = get_option('rd_smtp_host', '');
    $user = get_option('rd_smtp_user', '');
    $pass = get_option('rd_smtp_pass', '');
    if (!$host || !$user || !$pass) return;
    $enc  = get_option('rd_smtp_enc', 'tls');
    $port = intval(get_option('rd_smtp_port', 587));
    $from = get_option('rd_smtp_from', $user);
    $name = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $phpmailer->isSMTP();
    // Zkusit více hostů/portů pro případ blokování
    $phpmailer->Host       = $host . ':' . $port . ';' . $host . ':465;' . $host . ':25';
    $phpmailer->SMTPAuth   = true;
    $phpmailer->Username   = $user;
    $phpmailer->Password   = $pass;
    $phpmailer->SMTPSecure = $enc === 'none' ? '' : $enc;
    $phpmailer->Port       = $port;
    $phpmailer->From       = $from;
    $phpmailer->FromName   = $name;
    $phpmailer->Timeout    = 15;
    $phpmailer->SMTPOptions = ['ssl' => ['verify_peer' => false, 'verify_peer_name' => false, 'allow_self_signed' => true]];
    if ($enc === 'none') $phpmailer->SMTPAutoTLS = false;
}

// Ověření SMTP připojení
add_action('admin_post_rd_smtp_test', 'rd_smtp_test');
function rd_smtp_test() {
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) wp_die('Přístup odepřen');
    check_admin_referer('rd_smtp_test_nonce');

    $to        = sanitize_email($_POST['test_email'] ?? get_option('admin_email'));
    $from      = get_option('rd_smtp_from', get_option('admin_email'));
    $from_name = get_option('rd_smtp_from_name', get_bloginfo('name'));

    // Zachytit SMTP chybu
    $smtp_err = '';
    add_action('wp_mail_failed', function($error) use (&$smtp_err) {
        $smtp_err = $error->get_error_message();
    });

    $result = wp_mail(
        $to,
        'Test SMTP – RefDrive',
        '<p>SMTP funguje správně! Tento email byl odeslán přes váš SMTP server na adresu <strong>' . esc_html($to) . '</strong>.</p>',
        [
            'Content-Type: text/html; charset=UTF-8',
            'From: ' . $from_name . ' <' . $from . '>',
        ]
    );

    if ($result) {
        $status = 'ok';
        $msg = urlencode('Email odeslán na ' . $to);
    } else {
        $status = 'err';
        $msg = urlencode($smtp_err ?: 'wp_mail() vrátilo false – zkontroluj SMTP přihlašovací údaje');
    }

    wp_redirect(admin_url('admin.php?page=refdrive-email&smtp_test=' . $status . '&smtp_msg=' . $msg));
    exit;
}

