   ============================================================ */
add_action('init', 'rd_init', 1);
function rd_init() {
    if (!session_id() && !headers_sent() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();

    // Odhlášení
    if (isset($_GET['odhlasit']) && $_GET['odhlasit'] == '1') {
        foreach (['rd_kod','rd_jmeno','rd_firma_email','rd_firma_nazev','rd_token',
                  'rd_cert_jmeno','rd_cert_datum','rd_cert_firma','rd_cert_score',
                  'rd_cert_uuid','rd_cert_kod','rd_cert_token',
                  'rd_firma_id','rd_login_email','rd_token'] as $k) {
            unset($_SESSION[$k]);
        }
        // Smazat cookie rd_ridic
        setcookie('rd_ridic', '', time() - 3600, '/', '', is_ssl(), false);
        session_regenerate_id(true);
        wp_redirect(home_url('/')); exit;
    }

    // Smazat certifikát pokud řidič není přihlášen
    if (!isset($_SESSION['rd_kod']) && !isset($_SESSION['rd_cert_jmeno'])) {
        // nic
    } elseif (!isset($_SESSION['rd_kod']) && isset($_SESSION['rd_cert_jmeno'])) {
        // Certifikát platí jen těsně po testu - po 24h smazat
        // Prozatím nechat, ale chránit přístup
    }

    // Obnovit session z tokenu v URL
    if (!isset($_SESSION['rd_kod']) && isset($_GET['token'])) {
        global $wpdb;
        $t = sanitize_text_field($_GET['token']);
        $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE token=%s", $t));
        if ($r) {
            // Odhlásit ostatní session před přihlášením řidiče
            // Reset počítadla po úspěšném přihlášení
            delete_transient($ip_key);
            unset($_SESSION['rd_lektor'], $_SESSION['rd_firma_id'], $_SESSION['rd_firma_email']);
            $_SESSION['rd_kod']         = $r->kod;
            $_SESSION['rd_jmeno']       = $r->ridic_jmeno ?: ($r->zamestnanec_jmeno ?? '');
            $_SESSION['rd_firma_email'] = $r->firma_email;
            $_SESSION['rd_firma_nazev'] = $r->firma_nazev;
            $_SESSION['rd_token']       = $t;
        }
    }
}

add_action('plugins_loaded', 'rd_migrace');
function rd_migrace() {
    global $wpdb;
    // Sloupec obrazek v rd_lekce
    $lekce_cols = $wpdb->get_col("DESCRIBE {$wpdb->prefix}rd_lekce", 0);
    if (is_array($lekce_cols) && !in_array('obrazek', $lekce_cols)) {
        $wpdb->query("ALTER TABLE {$wpdb->prefix}rd_lekce ADD COLUMN obrazek VARCHAR(500) DEFAULT NULL AFTER obsah");
    }
    $cols = $wpdb->get_col("DESCRIBE " . RD_TABLE_KODY, 0);
    if (!in_array('ridic_jmeno',   $cols)) $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN ridic_jmeno VARCHAR(200) DEFAULT NULL AFTER pouzit");
    if (!in_array('datum_pouziti', $cols)) $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN datum_pouziti DATETIME DEFAULT NULL AFTER ridic_jmeno");
    if (!in_array('token',         $cols)) $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN token VARCHAR(64) DEFAULT NULL AFTER datum_pouziti");
    // Tabulka firem
    if ($wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}rd_firmy'") != "{$wpdb->prefix}rd_firmy") {
        $c = $wpdb->get_charset_collate();
        $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_firmy (
            id INT AUTO_INCREMENT PRIMARY KEY, nazev VARCHAR(200) NOT NULL,
            email VARCHAR(200) NOT NULL UNIQUE, ico VARCHAR(20) DEFAULT NULL,
            ulice VARCHAR(200) DEFAULT NULL, mesto VARCHAR(100) DEFAULT NULL,
            psc VARCHAR(10) DEFAULT NULL, telefon VARCHAR(50) DEFAULT NULL,
            login_token VARCHAR(64) DEFAULT NULL, token_expiry DATETIME DEFAULT NULL,
            vytvoreno DATETIME DEFAULT CURRENT_TIMESTAMP
        ) $c");
    }
    // Tabulka objednávek
    if ($wpdb->get_var("SHOW TABLES LIKE '" . RD_TABLE_OBJ . "'") != RD_TABLE_OBJ) {
        $c = $wpdb->get_charset_collate();
        $wpdb->query("CREATE TABLE IF NOT EXISTS " . RD_TABLE_OBJ . " (
            id INT AUTO_INCREMENT PRIMARY KEY, pi_id VARCHAR(100) NOT NULL,
            firma_nazev VARCHAR(200), firma_email VARCHAR(200), pocet INT DEFAULT 0,
            stav VARCHAR(50) DEFAULT 'ceka', data TEXT, vytvoreno DATETIME DEFAULT CURRENT_TIMESTAMP
        ) $c");
    }
    // Jednorázová oprava: doplnit autoskola_id do kódů a vazeb firma-autoškola
    // pro objednávky které byly potvrzeny bez autoskola_id (verze před 6.3.4)
    // Synchronizovat kody_tento_mesic = celkový počet prodaných kódů (nový model bez měsíčního resetu)
    if (defined('RD_TABLE_AUTOSKOLY') && defined('RD_TABLE_KODY')) {
        $autoskoly_fix = $wpdb->get_results(
            "SELECT id, kody_tento_mesic FROM " . RD_TABLE_AUTOSKOLY . " WHERE stav='aktivni'"
        );
        foreach ($autoskoly_fix as $as_fix) {
            $skutecne = (int)$wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d",
                $as_fix->id
            ));
            if ($skutecne !== (int)$as_fix->kody_tento_mesic) {
                $wpdb->update(RD_TABLE_AUTOSKOLY, ['kody_tento_mesic' => $skutecne], ['id' => $as_fix->id]);
            }
        }
    }

    // Doplnit autoskola_id do rd_ridici přes rd_kody (pro historické záznamy)
    if (defined('RD_TABLE_RIDICI') && defined('RD_TABLE_KODY')) {
        $wpdb->query(
            "UPDATE " . RD_TABLE_RIDICI . " r
             INNER JOIN " . RD_TABLE_KODY . " k ON k.kod = r.kod
             SET r.autoskola_id = k.autoskola_id
             WHERE r.autoskola_id IS NULL AND k.autoskola_id IS NOT NULL"
        );
    }

    // Vždy zkontrolovat a doplnit chybějící vazby (nejen jednou)
    if (defined('RD_TABLE_OBJ') && defined('RD_TABLE_FIRMA_AS')) {
        $obj_hotove = $wpdb->get_results(
            "SELECT o.firma_nazev, o.firma_email, o.autoskola_id, o.data
             FROM " . RD_TABLE_OBJ . " o
             WHERE o.stav='zaplaceno' AND o.firma_email != ''"
        );
        foreach ($obj_hotove as $o) {
            $as_id_fix = $o->autoskola_id;
            if (!$as_id_fix) {
                $d = json_decode($o->data ?? '{}', true);
                $as_id_fix = intval($d['autoskola_id'] ?? 0);
            }
            if (!$as_id_fix) continue;
            // Doplnit autoskola_id do kódů bez vazby
            $wpdb->query($wpdb->prepare(
                "UPDATE " . RD_TABLE_KODY . " SET autoskola_id=%d WHERE firma_email=%s AND autoskola_id IS NULL",
                $as_id_fix, $o->firma_email
            ));
            // Doplnit vazbu firma-autoškola pokud chybí
            $firma_id = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$wpdb->prefix}rd_firmy WHERE email=%s LIMIT 1", $o->firma_email
            ));
            if ($firma_id) {
                $exists = $wpdb->get_var($wpdb->prepare(
                    "SELECT id FROM " . RD_TABLE_FIRMA_AS . " WHERE firma_id=%d AND autoskola_id=%d LIMIT 1",
                    $firma_id, $as_id_fix
                ));
                if (!$exists) {
                    $wpdb->insert(RD_TABLE_FIRMA_AS, [
                        'firma_id'     => $firma_id,
                        'autoskola_id' => $as_id_fix,
                        'kmenova'      => 1,
                    ]);
                }
            }
        }
    }

    // Tabulka zákonů (Legislativa stránka)
    if ($wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}rd_leg_zakony'") != "{$wpdb->prefix}rd_leg_zakony") {
        $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_leg_zakony (
            id INT AUTO_INCREMENT PRIMARY KEY,
            sekce VARCHAR(100) DEFAULT 'proc_povinne',
            zkratka VARCHAR(20) DEFAULT '§',
            nazev VARCHAR(300) NOT NULL,
            podtitulek VARCHAR(200) DEFAULT '',
            obsah TEXT,
            poradi INT DEFAULT 0
        ) {$wpdb->get_charset_collate()}");
    }
    // Tabulka kroků školení a postihů (Legislativa stránka)
    if ($wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}rd_leg_kroky'") != "{$wpdb->prefix}rd_leg_kroky") {
        $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_leg_kroky (
            id INT AUTO_INCREMENT PRIMARY KEY,
            sekce VARCHAR(100) DEFAULT 'obsah',
            nadpis VARCHAR(200) NOT NULL,
            text TEXT,
            poradi INT DEFAULT 0
        ) {$wpdb->get_charset_collate()}");
    }

    // Tabulka poptávek (firmy u vyčerpané autoškoly)
    if ($wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}rd_poptavky'") != "{$wpdb->prefix}rd_poptavky") {
        $c = $wpdb->get_charset_collate();
        $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_poptavky (
            id INT AUTO_INCREMENT PRIMARY KEY,
            autoskola_id INT NOT NULL,
            firma_nazev VARCHAR(200) NOT NULL,
            firma_email VARCHAR(200) NOT NULL,
            pocet INT DEFAULT 1,
            stav VARCHAR(50) DEFAULT 'nova',
            jina_as_id INT DEFAULT NULL,
            cena_pri_poptavce INT DEFAULT NULL,
            vytvoreno DATETIME DEFAULT CURRENT_TIMESTAMP
        ) $c");
    }
    // Migrace: přidat sloupce pokud chybí (živé instalace)
    if ($wpdb->get_var("SHOW TABLES LIKE '{$wpdb->prefix}rd_poptavky'") == "{$wpdb->prefix}rd_poptavky") {
        $cols_popt = $wpdb->get_col("SHOW COLUMNS FROM {$wpdb->prefix}rd_poptavky");
        if (!in_array('jina_as_id', $cols_popt))
            $wpdb->query("ALTER TABLE {$wpdb->prefix}rd_poptavky ADD COLUMN jina_as_id INT DEFAULT NULL");
        if (!in_array('cena_pri_poptavce', $cols_popt))
            $wpdb->query("ALTER TABLE {$wpdb->prefix}rd_poptavky ADD COLUMN cena_pri_poptavce INT DEFAULT NULL");
    }

    // Seed výchozích tierů — spustí se i při update (nejen při aktivaci)
    if (defined('RD_TABLE_AS_TIERY') && $wpdb->get_var("SHOW TABLES LIKE '" . RD_TABLE_AS_TIERY . "'") == RD_TABLE_AS_TIERY) {
        $pocet_tieru = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AS_TIERY);
        if ($pocet_tieru === 0) {
            $tiery_seed = [
                ['nazev'=>'Starter',   'popis'=>'Pro vyzkoušení platformy',  'limit_kodu'=>5,    'cena_mesic'=>190,  'poradi'=>1, 'aktivni'=>1],
                ['nazev'=>'Základní',  'popis'=>'Ideální pro začátek',       'limit_kodu'=>50,   'cena_mesic'=>1490, 'poradi'=>2, 'aktivni'=>1],
                ['nazev'=>'Standard',  'popis'=>'Pro aktivní autoškoly',  'limit_kodu'=>200,  'cena_mesic'=>2990, 'poradi'=>3, 'aktivni'=>1],
                ['nazev'=>'Pro',       'popis'=>'Pro velké autoškoly',    'limit_kodu'=>500,  'cena_mesic'=>5490, 'poradi'=>4, 'aktivni'=>1],
                ['nazev'=>'Neomezený','popis'=>'Bez omezení počtu kódů', 'limit_kodu'=>99999,'cena_mesic'=>9490, 'poradi'=>5, 'aktivni'=>1],
                ['nazev'=>'Pro',       'popis'=>'Pro velké autoškoly',    'limit_kodu'=>500,  'cena_mesic'=>4990, 'poradi'=>3, 'aktivni'=>1],
                ['nazev'=>'Neomezený','popis'=>'Bez omezení počtu kódů', 'limit_kodu'=>99999,'cena_mesic'=>8990, 'poradi'=>4, 'aktivni'=>1],
            ];
            foreach ($tiery_seed as $t) $wpdb->insert(RD_TABLE_AS_TIERY, $t);
        }
    }
}

