add_action('wp_enqueue_scripts', 'rd_assets');
function rd_assets() {
    wp_enqueue_style('rd-theme',  plugin_dir_url(__FILE__) . 'assets/rd-theme.css',  [], RD_VERSION);
    wp_enqueue_style('rd-style',  plugin_dir_url(__FILE__) . 'assets/rd-front.css',  ['rd-theme'], RD_VERSION);
    wp_enqueue_script('rd-script', plugin_dir_url(__FILE__) . 'assets/rd-front.js', [], RD_VERSION, true);
    // Předat AJAX URL a nonce do JS
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    $lekce_done_server = [];
    if (isset($_SESSION['rd_kod'])) {
        global $wpdb;
        $_r = $wpdb->get_row($wpdb->prepare("SELECT lekce_done FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
        $lekce_done_server = $_r && $_r->lekce_done ? json_decode($_r->lekce_done, true) : [];
    }
    wp_localize_script('rd-script', 'rdAjax', [
        'url'         => admin_url('admin-ajax.php'),
        'done'        => $lekce_done_server,
        'celkem'      => count(rd_lekce_source()),
        'verze'       => count(rd_lekce_source()) . '_' . RD_VERSION,
        'kod'         => $_SESSION['rd_kod'] ?? '',
        'firma_nonce' => wp_create_nonce('rd_firma_nonce'),
        'firma_email' => $_SESSION['rd_firma_email'] ?? '',
        'maxKodu'     => 0, // přepsáno inline scriptem na stránce firma-portálu
        'nahled'      => !empty($_SESSION['rd_lektor_preview']) && empty($_SESSION['rd_lektor_zkusebni']) ? 1 : 0,
    ]);
}

