add_action('init', function() {
    global $wpdb;
    $col = $wpdb->get_results("SHOW COLUMNS FROM " . RD_TABLE_KODY . " LIKE 'lekce_done'");
    if (empty($col)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN lekce_done TEXT DEFAULT NULL");
    }
    $col2 = $wpdb->get_results("SHOW COLUMNS FROM " . RD_TABLE_KODY . " LIKE 'aktivni_cas_sec'");
    if (empty($col2)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN aktivni_cas_sec INT DEFAULT 0");
    }
    $col3 = $wpdb->get_results("SHOW COLUMNS FROM " . RD_TABLE_KODY . " LIKE 'zamestnanec_email'");
    if (empty($col3)) {
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN zamestnanec_jmeno VARCHAR(200) DEFAULT NULL");
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN zamestnanec_email VARCHAR(200) DEFAULT NULL");
        $wpdb->query("ALTER TABLE " . RD_TABLE_KODY . " ADD COLUMN kod_odeslan_at DATETIME DEFAULT NULL");
    }
}, 7);


// Lektor náhled kurzu — simulace bez reálného kódu
add_action('init', function() {
    if (empty($_GET['rd_lektor_preview'])) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    // Pouze přihlášený lektor nebo admin
    if (empty($_SESSION['rd_lektor']) && !current_user_can('manage_options')) {
        wp_redirect(home_url('/lektor/')); exit;
    }
    // Nastavit dočasnou náhledovou session
    $_SESSION['rd_kod']         = 'NÁHLED';
    $_SESSION['rd_jmeno']       = 'Náhled lektora';
    $_SESSION['rd_firma_email'] = 'nahled@refdrive.pro';
    $_SESSION['rd_firma_nazev'] = 'Náhled kurzu';
    $_SESSION['rd_token']       = 'lektor-preview';
    $_SESSION['rd_lektor_preview'] = 1;
    wp_redirect(home_url('/kurz/?lektor_nahled=1'));
    exit;
}, 3);

// Lektor zkušební test — přesměruje na zaverecny-test s náhledovou session
add_action('init', function() {
    if (empty($_GET['rd_lektor_zkusebni'])) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    if (empty($_SESSION['rd_lektor']) && !current_user_can('manage_options')) {
        wp_redirect(home_url('/lektor/?tab=test')); exit;
    }
    $_SESSION['rd_kod']            = 'NÁHLED';
    $_SESSION['rd_jmeno']          = 'Náhled lektora';
    $_SESSION['rd_firma_email']    = 'nahled@refdrive.pro';
    $_SESSION['rd_firma_nazev']    = 'Náhled kurzu';
    $_SESSION['rd_token']          = 'lektor-preview';
    $_SESSION['rd_lektor_preview'] = 1;
    $_SESSION['rd_lektor_zkusebni'] = 1;
    // Simulovat dokončený kurz aby byl test přístupný
    global $wpdb;
    $lekce = rd_lekce_source();
    $done = [];
    foreach ($lekce as $i => $l) $done[] = $i;
    $_SESSION['rd_lekce_done'] = $done;
    wp_redirect(home_url('/zaverecny-test/'));
    exit;
}, 3);

// Admin preview — přihlásit studenta vždy čerstvě
add_action('init', function() {
    if (empty($_GET['rd_admin_preview']) || empty($_GET['token'])) return;
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) return;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    global $wpdb;
    $token = sanitize_text_field($_GET['token']);
    $r = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_KODY . " WHERE token=%s LIMIT 1", $token
    ));
    if (!$r) return;
    foreach (['rd_kod','rd_jmeno','rd_firma_email','rd_firma_nazev','rd_token',
              'rd_cert_jmeno','rd_cert_datum','rd_cert_firma','rd_cert_score',
              'rd_cert_token','rd_cert_uuid'] as $k) {
        unset($_SESSION[$k]);
    }
    $_SESSION['rd_kod']         = $r->kod;
    $_SESSION['rd_jmeno']       = $r->ridic_jmeno ?? '';
    $_SESSION['rd_firma_email'] = $r->firma_email;
    $_SESSION['rd_firma_nazev'] = $r->firma_nazev ?? '';
    $_SESSION['rd_token']       = $token;
    wp_redirect(home_url('/kurz/?token=' . $token));
    exit;
}, 3);

// Zajistit refdrive_access pro administrator vždy
