// v6.1.0 — migrace DB pro živé instalace (cena_kus, rd_cena_zmeny)
// Kontroluje existenci sloupce přímo v DB — nespoleháme se na option
add_action('admin_init', function() {
    global $wpdb;
    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    $c = $wpdb->get_charset_collate();

    // Přidat cena_kus do rd_autoskoly pokud chybí
    if (defined('RD_TABLE_AUTOSKOLY')) {
        $col_exists = $wpdb->get_var(
            "SELECT COUNT(*) FROM information_schema.COLUMNS
             WHERE TABLE_SCHEMA = DATABASE()
             AND TABLE_NAME = '" . RD_TABLE_AUTOSKOLY . "'
             AND COLUMN_NAME = 'cena_kus'"
        );
        if (!$col_exists) {
            $wpdb->query("ALTER TABLE " . RD_TABLE_AUTOSKOLY . " ADD COLUMN cena_kus INT NOT NULL DEFAULT 99");
        }
    }

    // Vytvořit tabulku rd_cena_zmeny pokud chybí
    $table = $wpdb->prefix . 'rd_cena_zmeny';
    if ($wpdb->get_var("SHOW TABLES LIKE '$table'") !== $table) {
        dbDelta("CREATE TABLE IF NOT EXISTS $table (
            id              INT AUTO_INCREMENT PRIMARY KEY,
            autoskola_id    INT          NOT NULL,
            firma_id        INT          NOT NULL,
            stara_cena      INT          NOT NULL DEFAULT 0,
            nova_cena       INT          NOT NULL DEFAULT 0,
            lhuta_do        DATE         NOT NULL,
            stav            VARCHAR(20)  NOT NULL DEFAULT 'ceka',
            vytvoreno       DATETIME     DEFAULT CURRENT_TIMESTAMP
        ) $c;");
    }
});

// Export handler — musí být v admin_init před odesláním hlaviček
add_action('admin_init', function() {
    if (!isset($_POST['rd_do_export'])) return;
    if (!check_admin_referer('rd_export_nonce')) return;
    if (!current_user_can('manage_options')) return;
    global $wpdb;

    $data = [];

    // Options — kompletní seznam
    $options_keys = [
        'blogname','blogdescription','siteurl','home',
        'rd_stripe_pk','rd_stripe_sk','rd_stripe_wh',
        'rd_cislo_uctu','rd_iban','rd_bic','rd_banka','rd_splatnost','rd_faktura_pozn',
        'rd_faktura_nazev','rd_faktura_ico','rd_faktura_dic','rd_faktura_ulice',
        'rd_faktura_mesto','rd_faktura_psc','rd_faktura_email',
        'rd_cena_kus','rd_dph',
        'rd_smtp_on','rd_smtp_host','rd_smtp_user','rd_smtp_pass','rd_smtp_enc','rd_smtp_port',
        'rd_smtp_from','rd_smtp_from_name','rd_notif_email','rd_admin_notif_email',
        'rd_vop_text','rd_gdpr_text','rd_cookies_text',
        'rd_email_predmet','rd_email_uvod','rd_email_zaver',
        'rd_lekce_default_cas','rd_color_theme','rd_legal_pages_created',
        'rd_karta_disabled','rd_karta_disabled_msg','rd_rozeslani_disabled',
        'rd_kod_expirace_dni','rd_ai_enabled_autoskola','rd_ai_enabled_firma',
        'rd_comments_disabled','rd_migrace_uvod_platform',
    ];
    foreach ($options_keys as $k) { $data['options'][$k] = get_option($k); }
    // rd_text_* options (texty webu)
    $lektor_texts = $wpdb->get_results("SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE 'rd_text_%' OR option_name LIKE 'rd_txt_%'", ARRAY_A);
    foreach ($lektor_texts as $row) { $data['options'][$row['option_name']] = $row['option_value']; }

    // Stránky
    $pages = get_posts(['post_type'=>'page','post_status'=>'any','numberposts'=>-1]);
    foreach ($pages as $p) {
        $data['pages'][] = ['title'=>$p->post_title,'slug'=>$p->post_name,'content'=>$p->post_content,'status'=>$p->post_status];
    }

    // Plugin tabulky — všechny
    $plugin_tables = [
        'rd_lekce','rd_otazky',
        'rd_as_tiery','rd_autoskoly','rd_as_platby',
        'rd_kody','rd_ridici','rd_firmy','rd_objednavky',
        'rd_firma_autoskola','rd_zmeny_zadosti',
        'rd_novinky','rd_faq','rd_lektor',
    ];
    foreach ($plugin_tables as $t) {
        $full = $wpdb->prefix . $t;
        $exists = $wpdb->get_var("SHOW TABLES LIKE '{$full}'");
        $data['tables'][$t] = $exists ? ($wpdb->get_results("SELECT * FROM {$full}", ARRAY_A) ?: []) : [];
    }

    // WP uživatelé
    foreach (get_users(['fields'=>'all']) as $u) {
        $data['users'][] = ['login'=>$u->user_login,'email'=>$u->user_email,'display_name'=>$u->display_name,'pass_hash'=>$u->user_pass,'roles'=>$u->roles,'registered'=>$u->user_registered];
    }

    // Menu
    foreach (wp_get_nav_menus() as $menu) {
        $items = wp_get_nav_menu_items($menu->term_id);
        $menu_data = ['name'=>$menu->name,'slug'=>$menu->slug,'items'=>[]];
        if ($items) foreach ($items as $item) {
            $menu_data['items'][] = ['title'=>$item->title,'url'=>$item->url,'object'=>$item->object,'object_id'=>$item->object_id,'parent'=>$item->menu_item_parent,'order'=>$item->menu_order,'type'=>$item->type];
        }
        $data['menus'][] = $menu_data;
    }

    $data['_meta'] = ['version'=>RD_VERSION,'site_url'=>get_option('siteurl'),'exported_at'=>date('Y-m-d H:i:s')];

    $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    $filename = 'refdrive-backup-' . date('Y-m-d-His') . '.json';
    nocache_headers();
    header('Content-Type: application/octet-stream');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Content-Length: ' . strlen($json));
    header('Pragma: no-cache');
    echo $json;
    exit;
});

