// --- Export komplet lektora ---
add_action('admin_init', function() {
    if (!isset($_POST['rd_export_lektor_komplet'])) return;
    if (!check_admin_referer('rd_kurz_nonce')) return;
    if (!current_user_can('manage_options')) return;
    global $wpdb;

    // Lekce
    $lekce_raw = rd_lekce_source();
    $lekce = [];
    foreach ($lekce_raw as $i => $l) {
        $lekce[] = ['poradi'=>$i+1,'nazev'=>$l['nazev'],'popis'=>$l['popis'],'cas'=>$l['cas']??180,'obsah'=>$l['obsah']];
    }

    // Otázky
    $otazky_raw = rd_otazky_source(9999);
    $otazky = [];
    foreach ($otazky_raw as $i => $o) {
        $otazky[] = ['poradi'=>$i+1,'otazka'=>$o['otazka'],'odpovedi'=>$o['odpovedi'],'spravna'=>$o['spravna'],'vysvetleni'=>$o['vysvetleni']??''];
    }

    // Texty webu (rd_text_* options)
    $texty_keys = $wpdb->get_col("SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE 'rd_text_%' ORDER BY option_name");
    $texty = [];
    foreach ($texty_keys as $k) {
        $texty[$k] = get_option($k);
    }

    $data = [
        '_meta' => [
            'typ'         => 'refdrive-lektor-komplet',
            'verze'       => RD_VERSION,
            'exportovano' => date('Y-m-d H:i:s'),
            'pocet_lekci' => count($lekce),
            'pocet_otazek'=> count($otazky),
            'pocet_textu' => count($texty),
        ],
        'lekce'   => $lekce,
        'otazky'  => $otazky,
        'texty'   => $texty,
    ];

    $json     = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $filename = 'refdrive-lektor-komplet-' . date('Y-m-d') . '.json';
    nocache_headers();
    header('Content-Type: application/json; charset=utf-8');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Content-Length: ' . strlen($json));
    echo $json;
    exit;
});

