// --- Import lekcí ---
add_action('admin_init', function() {
    if (!isset($_POST['rd_import_lekce'])) return;
    if (!check_admin_referer('rd_kurz_io_nonce')) return;
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) return;
    global $wpdb;

    if (empty($_FILES['rd_lekce_file']['tmp_name'])) {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Nebyl nahrán žádný soubor.'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-lekce')); exit;
    }
    $raw  = file_get_contents($_FILES['rd_lekce_file']['tmp_name']);
    $data = json_decode($raw, true);

    if (!$data || empty($data['lekce']) || !is_array($data['lekce'])) {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Neplatný soubor. Očekávaný formát: JSON s klíčem "lekce".'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-lekce')); exit;
    }
    if (!empty($data['_meta']['typ']) && $data['_meta']['typ'] !== 'refdrive-lekce') {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Špatný typ souboru. Použijte soubor exportovaný z "Export lekcí".'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-lekce')); exit;
    }

    $wpdb->query("DELETE FROM {$wpdb->prefix}rd_lekce");
    $ok = 0;
    usort($data['lekce'], function($a, $b) { return ($a['poradi'] ?? 0) <=> ($b['poradi'] ?? 0); });
    foreach ($data['lekce'] as $i => $l) {
        $res = $wpdb->insert("{$wpdb->prefix}rd_lekce", [
            'poradi' => $i,
            'nazev'  => wp_kses_post(wp_unslash($l['nazev'] ?? '')),
            'popis'  => sanitize_text_field(wp_unslash($l['popis'] ?? '')),
            'cas'    => max(1, intval($l['cas'] ?? 180)),
            'obsah'  => wp_kses_post(wp_unslash($l['obsah'] ?? '')),
        ]);
        if ($res !== false) $ok++;
    }
    set_transient('rd_kurz_io_msg', ['type'=>'success','text'=>"Import lekcí dokončen. Naimportováno {$ok} lekcí."], 30);
    wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-lekce')); exit;
});

