// --- Import otázek ---
add_action('admin_init', function() {
    if (!isset($_POST['rd_import_otazky'])) return;
    if (!check_admin_referer('rd_kurz_io_nonce')) return;
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) return;
    global $wpdb;

    if (empty($_FILES['rd_otazky_file']['tmp_name'])) {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Nebyl nahrán žádný soubor.'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-otazky')); exit;
    }
    $raw  = file_get_contents($_FILES['rd_otazky_file']['tmp_name']);
    $data = json_decode($raw, true);

    if (!$data || empty($data['otazky']) || !is_array($data['otazky'])) {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Neplatný soubor. Očekávaný formát: JSON s klíčem "otazky".'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-otazky')); exit;
    }
    if (!empty($data['_meta']['typ']) && $data['_meta']['typ'] !== 'refdrive-otazky') {
        set_transient('rd_kurz_io_msg', ['type'=>'error','text'=>'Špatný typ souboru. Použijte soubor exportovaný z "Export otázek".'], 30);
        wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-otazky')); exit;
    }

    $allowed_spravna = ['A','B','C','D'];
    $wpdb->query("DELETE FROM {$wpdb->prefix}rd_otazky");
    $ok = 0; $chyby = [];
    usort($data['otazky'], function($a, $b) { return ($a['poradi'] ?? 0) <=> ($b['poradi'] ?? 0); });
    foreach ($data['otazky'] as $i => $o) {
        $spravna = strtoupper(trim($o['spravna'] ?? ''));
        if (!in_array($spravna, $allowed_spravna)) {
            $chyby[] = 'Otázka ' . ($i+1) . ': neplatná správná odpověď "' . esc_html($spravna) . '" (musí být A/B/C/D).';
            continue;
        }
        $res = $wpdb->insert("{$wpdb->prefix}rd_otazky", [
            'poradi'    => $i,
            'otazka'    => sanitize_textarea_field(wp_unslash($o['otazka'] ?? '')),
            'moznost_a' => sanitize_text_field(wp_unslash($o['moznosti']['A'] ?? '')),
            'moznost_b' => sanitize_text_field(wp_unslash($o['moznosti']['B'] ?? '')),
            'moznost_c' => sanitize_text_field(wp_unslash($o['moznosti']['C'] ?? '')),
            'moznost_d' => sanitize_text_field(wp_unslash($o['moznosti']['D'] ?? '')),
            'spravna'   => $spravna,
        ]);
        if ($res !== false) $ok++;
    }
    $msg = "Import otázek dokončen. Naimportováno {$ok} otázek.";
    if ($chyby) $msg .= ' Přeskočeno ' . count($chyby) . ' otázek s chybou: ' . implode(' | ', $chyby);
    $type = $chyby ? 'warning' : 'success';
    set_transient('rd_kurz_io_msg', ['type'=>$type,'text'=>$msg], 30);
    wp_redirect(admin_url('admin.php?page=refdrive-kurz#io-otazky')); exit;
});


