// Přejmenovat první submenu položku superadmina na "Přehled" — musí být po registraci všech menu
add_action('admin_menu', function() {
    if (!current_user_can('manage_options')) return;
    global $submenu;
    if (isset($submenu['refdrive']) && is_array($submenu['refdrive'])) {
        foreach ($submenu['refdrive'] as $k => $item) {
            if (isset($item[2]) && $item[2] === 'refdrive') {
                $submenu['refdrive'][$k][0] = 'Přehled';
                break;
            }
        }
