}, 999);

// Skrýt WP menu pro roli refdrive_admin - jen Školení řidičů
add_action('admin_menu', function() {
    if (current_user_can('manage_options') || !current_user_can('refdrive_access')) return;
    // Odstranit vše kromě refdrive menu
    global $menu, $submenu;
    $keep = ['refdrive', 'refdrive-generator', 'refdrive-absolventi', 'refdrive-objednavky', 'refdrive-platby', 'refdrive-email', 'refdrive-kurz', 'refdrive-legal', 'refdrive-autoskoly', 'refdrive-tiery', 'refdrive-as-platba'];
    // Přidat dynamické stránky autoškol do keep listu
    if (defined('RD_TABLE_AUTOSKOLY')) {
        global $wpdb;
        $as_ids = $wpdb->get_col("SELECT id FROM " . RD_TABLE_AUTOSKOLY);
        foreach ($as_ids as $id) {
            $keep[] = 'refdrive-as-' . $id;
            $keep[] = 'refdrive-as-' . $id . '-kody';
            $keep[] = 'refdrive-as-' . $id . '-absolventi';
            $keep[] = 'refdrive-as-' . $id . '-objednavky';
        }
    }
    foreach ($menu as $key => $item) {
        if (!in_array($item[2] ?? '', $keep)) {
            remove_menu_page($item[2] ?? '');
        }
    }
}, 999);

