add_action('admin_init', function() {
    if (current_user_can('manage_options') || !current_user_can('refdrive_access')) return;
    $screen = get_current_screen();
    if ($screen && in_array($screen->id, ['dashboard', 'profile', 'user-edit'])) {
        wp_redirect(admin_url('admin.php?page=refdrive'));
        exit;
    }
});

// Přesměrovat refdrive_admin po přihlášení na web místo nástěnky
add_filter('login_redirect', function($redirect_to, $request, $user) {
    if (is_wp_error($user)) return $redirect_to;
    // administrator → rovnou na stránku Školení řidičů
    if (in_array('administrator', (array)($user->roles ?? []))) {
        return admin_url('admin.php?page=refdrive');
    }
    // refdrive_admin přesměrovat do administrace
    if (in_array('refdrive_admin', (array)($user->roles ?? [])) && !in_array('administrator', (array)($user->roles ?? []))) {
        return admin_url('admin.php?page=refdrive');
    }
    // autoskola_admin — ověřit stav autoškoly
    if (in_array('autoskola_admin', (array)($user->roles ?? []))) {
        global $wpdb;
        $stav = $wpdb->get_var($wpdb->prepare(
            "SELECT stav FROM " . RD_TABLE_AUTOSKOLY . " WHERE wp_user_id=%d LIMIT 1",
            $user->ID
        ));
        if ($stav === 'ceka_schvaleni') {
            // Odhlásit a přesměrovat na stránku čekání
            wp_logout();
            return add_query_arg('rd_stav', 'ceka_schvaleni', home_url('/registrace-autoskoly/'));
        }
        if ($stav === 'zablokovano') {
            wp_logout();
            return add_query_arg('rd_stav', 'zablokovano', home_url('/registrace-autoskoly/'));
        }
        return admin_url('admin.php?page=refdrive');
    }
    return $redirect_to;
}, 10, 3);

// Blokovat přístup do WP admin pro autoskola_admin pokud není schválená
add_action('admin_init', function() {
    if (!is_user_logged_in()) return;
    $user = wp_get_current_user();
    if (!in_array('autoskola_admin', (array)$user->roles)) return;
    global $wpdb;
    $stav = $wpdb->get_var($wpdb->prepare(
        "SELECT stav FROM " . RD_TABLE_AUTOSKOLY . " WHERE wp_user_id=%d LIMIT 1",
        $user->ID
    ));
    if (in_array($stav, ['ceka_schvaleni', 'zablokovano', null])) {
        wp_logout();
        wp_redirect(add_query_arg('rd_stav', $stav ?? 'ceka_schvaleni', home_url('/registrace-autoskoly/')));
        exit;
    }
});



