            <div style="font-size:11px;color:#9ca3af"><?php echo esc_html($r->firma_nazev?:'—'); ?> · <?php echo esc_html($r->as_nazev??'—'); ?></div>
        </div>
        <div style="text-align:right">
            <div style="font-weight:700;color:<?php echo $r->score>=80?'#15803d':($r->score>=60?'#d97706':'#dc2626'); ?>"><?php echo (int)$r->score; ?> %</div>
            <div style="font-size:11px;color:#9ca3af"><?php echo date('d.m.Y', strtotime($r->datum_skoleni)); ?></div>
        </div>
    </div>
    <?php endforeach; ?>
    </div>
    <?php endif; ?>

    </div><!-- /objednavky panel -->

    </div><!-- /historie -->

    </div><!-- max-width:900px -->
    </div><!-- .wrap -->
    <?php
}

function rd_admin_menu() {
    // Hlavní callback: dashboard pro hlavního admina, přehled kódů pro autoskola_admin
    $main_callback = current_user_can('manage_options') ? 'rd_admin_dashboard' : 'rd_admin_as_firmy';
    // Badge na hlavní menu položce – celkový počet čekajících akcí
    $menu_label = 'Školení řidičů';
    if (current_user_can('manage_options') && defined('RD_TABLE_AUTOSKOLY')) {
        global $wpdb;
        $pending_total = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AUTOSKOLY . " WHERE stav IN ('ceka_schvaleni','ceka_potvrzeni')");
        if ($pending_total > 0) {
            $menu_label .= ' <span class="awaiting-mod count-' . $pending_total . '"><span class="pending-count">' . $pending_total . '</span></span>';
        }
    }
    add_menu_page('RefDrive Školení', $menu_label, 'refdrive_access', 'refdrive', $main_callback, 'dashicons-car', 28);
    // Pro autoškolu přesměrovat hlavní slug na prehled
    if (rd_je_autoskola_admin() && !current_user_can('manage_options') && isset($_GET['page']) && $_GET['page'] === 'refdrive') {
        wp_redirect(admin_url('admin.php?page=refdrive-prehled'));
        exit;
    }

    // Položky relevantní pouze pro autoskola_admin (per-autoškola přehled)
    // Hlavní admin má tyto přehledy v podstromu každé autoškoly
    if (!current_user_can('manage_options')) {
        global $wpdb;
        $moje_as_menu = rd_get_my_autoskola();
        $as_id_menu   = $moje_as_menu ? intval($moje_as_menu->id) : 0;

        // Objednávky čekající na potvrzení
        $ceka_obj = $as_id_menu ? (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_OBJ . " WHERE (autoskola_id=%d OR (autoskola_id IS NULL AND data LIKE %s)) AND stav='prevod_ceka'",
            $as_id_menu, '%"autoskola_id":' . $as_id_menu . '%'
        )) : 0;

        // Nevyřízené poptávky
        $ceka_popt = $as_id_menu ? (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->prefix}rd_poptavky WHERE autoskola_id=%d AND stav='nova'",
            $as_id_menu
        )) : 0;

        $badge_obj  = $ceka_obj  > 0 ? ' <span class="awaiting-mod count-' . $ceka_obj  . '"><span class="pending-count">' . $ceka_obj  . '</span></span>' : '';
        $badge_popt = $ceka_popt > 0 ? ' <span class="awaiting-mod count-' . $ceka_popt . '"><span class="pending-count">' . $ceka_popt . '</span></span>' : '';
        $badge_total = ($ceka_obj + $ceka_popt) > 0 ? ' <span class="awaiting-mod count-' . ($ceka_obj + $ceka_popt) . '"><span class="pending-count">' . ($ceka_obj + $ceka_popt) . '</span></span>' : '';

        // Stejná menu struktura jako hlavní admin
        add_submenu_page('refdrive', 'Přehled', 'Přehled', 'refdrive_access', 'refdrive-prehled', 'rd_admin_as_firmy');
        // Skrýt duplicitní první položku "Školení řidičů" — WP ji přidá automaticky
        remove_submenu_page('refdrive', 'refdrive');
        add_submenu_page('refdrive', 'Absolventi', 'Absolventi', 'refdrive_access', 'refdrive-as-moje-absolventi', 'rd_admin_as_absolventi_all');
        // Objednávky kódů — viditelné pro autoškolu, skryté pro superadmina (má vše na dashboardu)
        add_submenu_page('refdrive', 'Objednávky', 'Objednávky' . ($ceka_obj > 0 ? ' (' . $ceka_obj . ')' : ''), 'refdrive_access', 'refdrive-objednavky', 'rd_admin_objednavky');
        add_submenu_page('refdrive', 'Správa balíčků', 'Správa balíčků', 'refdrive_access', 'refdrive-as-platba', 'rd_admin_as_platba');
        add_submenu_page('refdrive', 'Nastavení', 'Nastavení', 'refdrive_access', 'refdrive-as-nastaveni', 'rd_admin_as_nastaveni');
        // Změna hesla — registrovaná ale skrytá z menu (přístupná přes odkaz v Nastavení)
        add_submenu_page('refdrive', 'Změna hesla', 'Změna hesla', 'refdrive_access', 'refdrive-as-heslo', 'rd_admin_as_heslo');
        // Nastavení profilu (onboarding) — zobrazit jen pokud onboarding nebyl dokončen
        if ($moje_as_menu && empty($moje_as_menu->onboarding_done)) {
            add_submenu_page('refdrive', 'Nastavení profilu', 'Nastavení profilu', 'refdrive_access', 'refdrive-onboarding', 'rd_onboarding_page');
        }

        // Dynamické submenu per firma
        if ($as_id_menu) {
            $firmy_menu = $wpdb->get_results($wpdb->prepare(
                "SELECT DISTINCT firma_nazev, firma_email FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d ORDER BY firma_nazev ASC LIMIT 20",
                $as_id_menu
            ));
            foreach ($firmy_menu as $fi) {
                $fi_slug    = 'refdrive-firma-' . md5($fi->firma_email);
                $fi_label   = mb_strimwidth($fi->firma_nazev, 0, 20, '…');
                // Firma jako separátor
                add_submenu_page('refdrive', $fi->firma_nazev, '· ' . esc_html($fi_label), 'refdrive_access', $fi_slug, function() use ($fi) {
                    rd_admin_firma_detail($fi->firma_email);
                });
                add_submenu_page('refdrive', $fi->firma_nazev . ' — Kódy',       '&nbsp;&nbsp;&nbsp;Kódy',       'refdrive_access', $fi_slug . '-kody',       'rd_admin_firma_kody');
                add_submenu_page('refdrive', $fi->firma_nazev . ' — Absolventi',  '&nbsp;&nbsp;&nbsp;Absolventi',  'refdrive_access', $fi_slug . '-absolventi',  'rd_admin_firma_absolventi');
                add_submenu_page('refdrive', $fi->firma_nazev . ' — Objednávky',  '&nbsp;&nbsp;&nbsp;Objednávky',  'refdrive_access', $fi_slug . '-objednavky',  'rd_admin_firma_objednavky');
            }
        }
    }

        // Objednávky kódů — skrytá stránka
        add_submenu_page(null, 'Objednávky kódů', 'Objednávky kódů', 'manage_options', 'refdrive-objednavky', 'rd_admin_objednavky');
        add_submenu_page('refdrive', 'Paušální balíčky', 'Paušální balíčky', 'manage_options', 'refdrive-tiery', 'rd_admin_tiery');

        global $wpdb;
        if (defined('RD_TABLE_AUTOSKOLY')) {
            $cekajici_schvaleni  = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AUTOSKOLY . " WHERE stav='ceka_schvaleni'");
            $cekajici_platby_cnt = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AUTOSKOLY . " WHERE stav='ceka_potvrzeni'");
            $cekajici_total      = $cekajici_schvaleni + $cekajici_platby_cnt;
            $label_cekajici      = 'Správa autoškol' . ($cekajici_total > 0 ? ' <span class="awaiting-mod count-' . $cekajici_total . '"><span class="pending-count">' . $cekajici_total . '</span></span>' : '');
            add_submenu_page('refdrive', 'Správa autoškol', $label_cekajici, 'manage_options', 'refdrive-autoskoly', 'rd_admin_autoskoly');

            $autoskoly = $wpdb->get_results("SELECT id, nazev, stav FROM " . RD_TABLE_AUTOSKOLY . " ORDER BY nazev ASC");
            // Načti čekající platby pro všechny autoškoly najednou
            $cekajici_per_as = [];
            $platby_cek = $wpdb->get_results("SELECT autoskola_id, COUNT(*) as cnt FROM " . RD_TABLE_AS_PLATBY . " WHERE stav='ceka_potvrzeni' GROUP BY autoskola_id", ARRAY_A);
            foreach ($platby_cek as $p) $cekajici_per_as[$p['autoskola_id']] = (int)$p['cnt'];

            foreach ($autoskoly as $as) {
                $nazev   = mb_strimwidth($as->nazev, 0, 22, '…');
                $ico     = $as->stav === 'aktivni' ? '' : ' ●';
                $cnt     = ($cekajici_per_as[$as->id] ?? 0) + ($as->stav === 'ceka_schvaleni' ? 1 : 0);
                $badge   = $cnt > 0 ? ' <span class="awaiting-mod count-' . $cnt . '"><span class="pending-count">' . $cnt . '</span></span>' : '';
                add_submenu_page('refdrive', $as->nazev, '&nbsp;&nbsp;&nbsp;' . esc_html($nazev . $ico) . $badge, 'manage_options', 'refdrive-as-' . $as->id, 'rd_admin_as_detail');
                add_submenu_page('refdrive', $as->nazev . ' — Kódy',       '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kódy',       'manage_options', 'refdrive-as-' . $as->id . '-kody',       'rd_admin_as_kody');
                add_submenu_page('refdrive', $as->nazev . ' — Absolventi',  '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Absolventi',  'manage_options', 'refdrive-as-' . $as->id . '-absolventi',  'rd_admin_as_absolventi');
                add_submenu_page('refdrive', $as->nazev . ' — Objednávky',  '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Objednávky',  'manage_options', 'refdrive-as-' . $as->id . '-objednavky',  'rd_admin_as_objednavky');
                add_submenu_page('refdrive', $as->nazev . ' — Firmy',       '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Firmy',       'manage_options', 'refdrive-as-' . $as->id . '-firmy',       'rd_admin_as_firmy_superadmin');
            }
        }

        add_submenu_page('refdrive', 'Nastavení', 'Nastavení', 'manage_options', 'refdrive-nastaveni-all', 'rd_admin_nastaveni_all');
        add_submenu_page('refdrive', 'Nástroje',  'Nástroje',  'manage_options', 'refdrive-nastroje',       'rd_admin_nastroje');
    } // end if manage_options

// Blokování/odblokování autoškol – musí být v admin_init (před výstupem HTML)
// WP Cron – odesílat emaily firmám po 12h čekání na autoškolu
add_action('rd_poptavka_cron', 'rd_poptavka_cron_check');
if (!wp_next_scheduled('rd_poptavka_cron')) {
    wp_schedule_event(time(), 'hourly', 'rd_poptavka_cron');
}
function rd_poptavka_cron_check() {
    global $wpdb;
    $from  = get_option('rd_smtp_from', get_option('admin_email'));
    $fname = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $fname . ' <' . $from . '>'];

    // Poptávky starší 12h, stále nova
    $poptavky = $wpdb->get_results(
        "SELECT p.*,
                a.nazev as as_nazev, a.slug as as_slug,
                ja.nazev as jina_nazev, ja.slug as jina_slug, ja.mesto as jina_mesto
         FROM {$wpdb->prefix}rd_poptavky p
         JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=p.autoskola_id
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " ja ON ja.id=p.jina_as_id
         WHERE p.stav='nova'
         AND p.vytvoreno <= DATE_SUB(NOW(), INTERVAL 12 HOUR)"
    );

    foreach ($poptavky as $p) {
        // Zkontrolovat zda autoškola mezitím obnovila kapacitu
        $zbyvajici_as = rd_autoskola_zbyvajici_kapacita($p->autoskola_id);
        $kapacita_obnovena = ($zbyvajici_as === PHP_INT_MAX) || ($zbyvajici_as !== null && $zbyvajici_as >= intval($p->pocet));

        if ($kapacita_obnovena) {
            // Autoškola obnovila kapacitu — firma objedná přímo u ní
            $objednat_url = add_query_arg('ref', $p->as_slug, home_url('/objednavka/'));
            wp_mail(
                $p->firma_email,
                'Vaše poptávka školení — kapacita obnovena',
                rd_email_wrap('Skvělá zpráva — kapacita obnovena!',
                    '<p>Dobrý den, <strong>' . esc_html($p->firma_nazev) . '</strong>,</p>'
                    . '<p>autoškola <strong>' . esc_html($p->as_nazev) . '</strong> obnovila kapacitu a je připravena vaši objednávku přijmout.</p>'
                    . rd_email_btn('Objednat školení →', $objednat_url)
                    . '<p style="font-size:12px;color:#6b7280">Odkaz vás přesměruje přímo na objednávkový formulář.</p>'
                ),
                $headers
            );
            $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'kapacita_obnovena'], ['id' => $p->id]);
        } else {
            // Kapacita stále není — nabídnout alternativy nebo omluva
            if ($p->jina_as_id) {
                // Zkontrolovat zda alternativní autoškola stále má kapacitu
                $jina_kapacita = $wpdb->get_row($wpdb->prepare(
                    "SELECT a.slug, a.nazev, a.mesto FROM " . RD_TABLE_AUTOSKOLY . " a
                     WHERE a.id=%d AND a.stav='aktivni' LIMIT 1",
                    $p->jina_as_id
                ));
                $jina_zbyvajici = $jina_kapacita ? rd_autoskola_zbyvajici_kapacita($p->jina_as_id) : null;
                if ($jina_kapacita && ($jina_zbyvajici === PHP_INT_MAX || ($jina_zbyvajici !== null && $jina_zbyvajici >= intval($p->pocet)))) {
                    $jina_url = add_query_arg('ref', $jina_kapacita->slug, home_url('/objednavka/'));
                    wp_mail(
                        $p->firma_email,
                        'Vaše poptávka školení — kapacita stále nedostupná',
                        rd_email_wrap('Kapacita stále nedostupná — nabízíme alternativu',
                            '<p>Dobrý den, <strong>' . esc_html($p->firma_nazev) . '</strong>,</p>'
                            . '<p>autoškola <strong>' . esc_html($p->as_nazev) . '</strong> v uplynulých 12 hodinách kapacitu neobnovila.</p>'
                            . '<p>Dovolujeme si vám nabídnout alternativní autoškolu: <strong>' . esc_html($jina_kapacita->nazev) . '</strong>'
                            . ($jina_kapacita->mesto ? ' (' . esc_html($jina_kapacita->mesto) . ')' : '') . ', která má pro vás kapacitu.</p>'
                            . rd_email_btn('Objednat u ' . esc_html($jina_kapacita->nazev) . ' →', $jina_url)
                        ),
                        $headers
                    );
                    $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $p->id]);
                    // Email autoškole — firma dostala alternativu (informativně)
                    $email_as = $wpdb->get_var($wpdb->prepare(
                        "SELECT email FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $p->autoskola_id
                    ));
                    if ($email_as) {
                        rd_email_autoskola($email_as,
                            'RefDrive: Firma dostala alternativní autoškolu',
                            rd_email_wrap('Informace o poptávce',
                                '<p>Firma <strong>' . esc_html($p->firma_nazev) . '</strong> čekala na obnovení vaší kapacity, ale ta nebyla v uplynulých 12 hodinách obnovena.</p>'
                                . '<p>Firmě jsme nabídli alternativní autoškolu. Pokud chcete předejít podobným situacím, zvažte navýšení paušálního balíčku.</p>'
                                . rd_email_btn('Správa balíčku →', admin_url('admin.php?page=refdrive-as-platba'))
                            )
                        );
                    }
                } else {
                    // Alternativa také nemá kapacitu — hledat novou nebo omluva
                    $nova_jina = $wpdb->get_row($wpdb->prepare(
                        "SELECT a.* FROM " . RD_TABLE_AUTOSKOLY . " a
                         WHERE a.stav='aktivni' AND a.id != %d AND a.id != %d
                           AND " . rd_sql_kapacita_podminka('a', intval($p->pocet)) . "
                         LIMIT 1",
                        $p->autoskola_id, $p->jina_as_id
                    ));
                    if ($nova_jina) {
                        $nova_url = add_query_arg('ref', $nova_jina->slug, home_url('/objednavka/'));
                        wp_mail($p->firma_email,
                            'Vaše poptávka školení — kapacita stále nedostupná',
                            rd_email_wrap('Kapacita stále nedostupná — nabízíme alternativu',
                                '<p>Dobrý den, <strong>' . esc_html($p->firma_nazev) . '</strong>,</p>'
                                . '<p>autoškola <strong>' . esc_html($p->as_nazev) . '</strong> kapacitu neobnovila. Nabízíme vám alternativu: <strong>' . esc_html($nova_jina->nazev) . '</strong>.</p>'
                                . rd_email_btn('Objednat u alternativní autoškoly →', $nova_url)
                            ),
                            $headers
                        );
                    } else {
                        wp_mail($p->firma_email,
                            'Vaše poptávka školení — kapacita stále nedostupná',
                            rd_email_wrap('Kapacita stále nedostupná',
                                '<p>Dobrý den, <strong>' . esc_html($p->firma_nazev) . '</strong>,</p>'
                                . '<p>autoškola <strong>' . esc_html($p->as_nazev) . '</strong> kapacitu neobnovila a momentálně nejsou k dispozici ani alternativy.</p>'
                                . '<p>Ozveme se vám jakmile bude situace jiná. V případě dotazů nás kontaktujte na <a href="mailto:' . esc_attr(get_option('rd_faktura_email', 'info@refdrive.pro')) . '" style="color:#7c3aed">' . esc_html(get_option('rd_faktura_email', 'info@refdrive.pro')) . '</a>.</p>'
                            ),
                            $headers
                        );
                    }
                    $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $p->id]);
                }
            } else {
                // Žádná alternativa nebyla ani při poptávce
                wp_mail($p->firma_email,
                    'Vaše poptávka školení — kapacita stále nedostupná',
                    rd_email_wrap('Kapacita stále nedostupná',
                        '<p>Dobrý den, <strong>' . esc_html($p->firma_nazev) . '</strong>,</p>'
                        . '<p>autoškola <strong>' . esc_html($p->as_nazev) . '</strong> kapacitu neobnovila a momentálně nejsou k dispozici alternativní autoškoly.</p>'
                        . '<p>Ozveme se vám jakmile bude situace jiná.</p>'
                    ),
                    $headers
                );
                $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $p->id]);
            }
        }
    }
}

add_action('admin_init', function() {
    if (!current_user_can('manage_options')) return;
    global $wpdb;

    // Odblokovat
    if (isset($_GET['rd_as_odblokovat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_odblokovat_' . intval($_GET['rd_as_odblokovat']))) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'aktivni'], ['id'=>intval($_GET['rd_as_odblokovat'])]);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly&rd_zprava=odblokovana')); exit;
    }

    // Zablokovat
    if (isset($_GET['rd_as_blokovat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_blokovat_' . intval($_GET['rd_as_blokovat']))) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'zablokovano'], ['id'=>intval($_GET['rd_as_blokovat'])]);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly&rd_zprava=zablokovana')); exit;
    }

    // Schválit registraci — přesunuto do page callbacku rd_admin_autoskoly()

    // Zamítnout registraci
    if (isset($_POST['rd_as_zamitnout']) && wp_verify_nonce($_POST['_wpnonce'] ?? '', 'rd_as_zamitnout_' . intval($_POST['as_id'] ?? 0))) {
        $as_id = intval($_POST['as_id']);
        $pozn  = sanitize_textarea_field($_POST['rd_as_zamit_pozn'] ?? '');
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'zamitnuto'], ['id'=>$as_id]);
        $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
        if ($as && $as->email) {
            rd_email_autoskola(
                $as->email,
                'RefDrive: Registrace zamítnuta',
                rd_email_wrap('Registrace zamítnuta',
                    '<p>Vaše žádost o registraci autoškoly <strong>' . esc_html($as->nazev) . '</strong> nebyla schválena.</p>'
                    . ($pozn ? '<div style="background:#fef2f2;border-left:3px solid #dc2626;padding:12px 16px;border-radius:6px;margin:16px 0"><strong>Důvod:</strong><br>' . nl2br(esc_html($pozn)) . '</div>' : '')
                    . '<p>Pokud máte dotazy, kontaktujte nás na <a href="mailto:' . esc_attr(get_option('rd_faktura_email', 'info@refdrive.pro')) . '" style="color:#7c3aed">' . esc_html(get_option('rd_faktura_email', 'info@refdrive.pro')) . '</a>.</p>'
                )
            );
        }
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly&rd_zprava=zamitnuta')); exit;
    }

    // Potvrdit platbu balíčku
    if (isset($_GET['rd_as_potvrdit_platbu']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_platba_' . intval($_GET['rd_as_potvrdit_platbu']))) {
        $as_id = intval($_GET['rd_as_potvrdit_platbu']);
        $pid   = intval($_GET['rd_pid'] ?? 0);
        $as    = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
        if ($as) {
            // Načíst konkrétní platbu (pid) nebo poslední čekající
            $nova_platba = $pid
                ? $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE id=%d AND autoskola_id=%d AND stav='ceka_potvrzeni' LIMIT 1", $pid, $as_id))
                : $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='ceka_potvrzeni' ORDER BY id DESC LIMIT 1", $as_id));
            // Platnost od dnešního dne potvrzení (ne od data žádosti)
            // Navazuje na konec stávajícího balíčku pokud ještě platí
            $aktualni_do = $as->predplatne_expiruje ? strtotime($as->predplatne_expiruje) : 0;
            $platnost_od_ts = ($aktualni_do > time()) ? $aktualni_do : time();
            $platnost_od = date('Y-m-d', $platnost_od_ts);
            $platnost_do = date('Y-m-d', strtotime('+1 month', $platnost_od_ts));
            $vyrizeno = current_time('mysql');
            if ($nova_platba) {
                $wpdb->update(RD_TABLE_AS_PLATBY, ['stav'=>'zaplaceno','platnost_od'=>$platnost_od,'platnost_do'=>$platnost_do,'vyrizeno'=>$vyrizeno], ['id'=>$nova_platba->id]);
            } else {
                $wpdb->query($wpdb->prepare(
                    "UPDATE " . RD_TABLE_AS_PLATBY . " SET stav='zaplaceno', platnost_od=%s, platnost_do=%s, vyrizeno=%s WHERE autoskola_id=%d AND stav='ceka_potvrzeni' ORDER BY id DESC LIMIT 1",
                    $platnost_od, $platnost_do, $vyrizeno, $as_id
                ));
            }
            $nova_tier_id = $nova_platba ? $nova_platba->tier_id : $as->tier_id;
            $wpdb->update(RD_TABLE_AUTOSKOLY, [
                'stav'             => 'aktivni',
                'tier_id'          => $nova_tier_id,
                'kody_tento_mesic' => 0,
                'mesic_reset'      => date('Y-m'),
            ], ['id' => $as_id]);
            rd_sync_predplatne_expiruje($as_id);
            $tier = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d LIMIT 1", $nova_tier_id));
            $nova_platba_obj = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='zaplaceno' ORDER BY id DESC LIMIT 1", $as_id));
            $vs_email = $nova_platba_obj ? str_pad($as_id, 4, '0', STR_PAD_LEFT) . str_pad($nova_platba_obj->id, 6, '0', STR_PAD_LEFT) : '';
            rd_email_autoskola(
                $as->email,
                'RefDrive: Platba potvrzena — faktura č. ' . $vs_email,
                rd_email_wrap('Platba potvrzena',
                    '<p>Vaše platba za balíček <strong>' . esc_html($tier->nazev ?? 'Základní') . '</strong> byla potvrzena.</p>'
                    . '<p>Platnost balíčku: <strong>' . date('d.m.Y', strtotime($platnost_do)) . '</strong>.</p>'
                    . '<p>Faktura č. <strong>' . esc_html($vs_email) . '</strong> je připravena ke stažení v administraci.</p>'
                    . '<p>Týden před vypršením platnosti vás upozorníme emailem.</p>'
                    . rd_email_btn('Stáhnout fakturu →', admin_url('admin.php?page=refdrive-as-platba'))
                )
            );
            wp_safe_redirect(admin_url('admin.php?page=refdrive-as-' . $as_id . '&rd_zprava=platba_ok')); exit;
        }
    }

    // Storno platby balíčku — superadmin
    if (isset($_GET['rd_as_storno_platbu']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_storno_platba_' . intval($_GET['rd_as_storno_platbu']))) {
        $as_id   = intval($_GET['rd_as_storno_platbu']);
        $pid     = intval($_GET['rd_pid'] ?? 0);
        $poznamka = sanitize_textarea_field($_GET['rd_poznamka'] ?? '');
        $as      = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
        if ($as && $pid) {
            $platba = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE id=%d AND autoskola_id=%d AND stav='ceka_potvrzeni' LIMIT 1", $pid, $as_id));
            if ($platba) {
                $wpdb->update(RD_TABLE_AS_PLATBY, ['stav'=>'storno', 'poznamka'=>$poznamka, 'vyrizeno'=>current_time('mysql')], ['id'=>$pid]);
                // Pokud autoškola nemá jinou aktivní platbu, vrátit na aktivni nebo pozastavena
                $ma_aktivni = (int)$wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='zaplaceno' AND platnost_do >= CURDATE()", $as_id
                ));
                if (!$ma_aktivni && $as->stav === 'ceka_potvrzeni') {
                    $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'pozastavena'], ['id'=>$as_id]);
                }
                $tier = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d LIMIT 1", $platba->tier_id));
                $vs_storno = str_pad($as_id, 4, '0', STR_PAD_LEFT) . str_pad($pid, 6, '0', STR_PAD_LEFT);
                $poznamka_html = $poznamka ? '<p><strong>Poznámka administrátora:</strong> ' . esc_html($poznamka) . '</p>' : '';
                rd_email_autoskola(
                    $as->email,
                    'RefDrive: Platba balíčku stornována — VS ' . $vs_storno,
                    rd_email_wrap('Platba stornována',
                        '<p>Platba za balíček <strong>' . esc_html($tier->nazev ?? '—') . '</strong> (VS: <strong>' . esc_html($vs_storno) . '</strong>) byla stornována.</p>'
                        . $poznamka_html
                        . '<p>V případě dotazů nás prosím kontaktujte.</p>'
                        . rd_email_btn('Přejít do administrace →', admin_url('admin.php?page=refdrive'))
                    )
                );
                wp_safe_redirect(admin_url('admin.php?page=refdrive-as-' . $as_id . '&rd_zprava=storno_ok')); exit;
            }
        }
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly')); exit;
    }

    // Smazat autoškolu
    if (isset($_GET['rd_as_smazat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_smazat_' . intval($_GET['rd_as_smazat']))) {
        $del_id = intval($_GET['rd_as_smazat']);
        $wpdb->delete(RD_TABLE_RIDICI,  ['autoskola_id' => $del_id]);
        $wpdb->delete(RD_TABLE_KODY,    ['autoskola_id' => $del_id]);
        $wpdb->query($wpdb->prepare("DELETE FROM " . RD_TABLE_OBJ       . " WHERE autoskola_id=%d", $del_id));
        $wpdb->query($wpdb->prepare("DELETE FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d", $del_id));
        $wpdb->query($wpdb->prepare("DELETE FROM " . RD_TABLE_ZMENY     . " WHERE autoskola_id=%d", $del_id));
        $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->prefix}rd_cena_zmeny WHERE autoskola_id=%d", $del_id));
        $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->prefix}rd_firma_autoskola WHERE autoskola_id=%d", $del_id));
        $wp_uid = (int)$wpdb->get_var($wpdb->prepare("SELECT wp_user_id FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $del_id));
        if ($wp_uid) wp_delete_user($wp_uid);
        $wpdb->delete(RD_TABLE_AUTOSKOLY, ['id' => $del_id]);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly&rd_zprava=smazána')); exit;
    }

});



