/* ---- GENERÁTOR KÓDŮ ---- */

/* ---- PŘEHLED KÓDŮ ---- */
function rd_admin_kody() {
    global $wpdb;
    $firma_email = isset($_GET['firma']) ? sanitize_email($_GET['firma']) : '';
    if ($firma_email) {
        // Pro autoskola_admin zobrazit novou stránku firmy, pro hlavního admina starý detail
        if (!current_user_can('manage_options') && rd_je_autoskola_admin()) {
            rd_admin_firma_detail($firma_email);
        } else {
            rd_admin_kody_detail($firma_email);
        }
        return;
    }

        // Filtrovat kódy jen pro vlastní autoškolu pokud je autoskola_admin (fallback pro hlavní admin) $as_filter = '';
    if (!current_user_can('manage_options')) {
        $moje_as = rd_get_my_autoskola();
        if ($moje_as) { $as_filter = 'WHERE autoskola_id=' . intval($moje_as->id) . ' '; }
    }
    $firmy = $wpdb->get_results("SELECT firma_nazev, firma_email, COUNT(*) as celkem, SUM(pouzit) as pouzito, COUNT(*)-SUM(pouzit) as volnych, MAX(vytvoreno) as posledni FROM " . RD_TABLE_KODY . " {$as_filter}GROUP BY firma_nazev, firma_email ORDER BY posledni DESC");
    ?>
    <div class="wrap">
    <h1>Přehled kódů</h1>
    <div style="max-width:900px">
    <table class="widefat rd-sortable" style="font-size:13px">
        <thead><tr><th>Firma</th><th>Email</th><th style="width:90px;text-align:center">Celkem</th><th style="width:90px;text-align:center">Použito</th><th style="width:90px;text-align:center">Volných</th><th style="width:140px">Poslední generování</th><th style="width:80px">Akce</th></tr></thead>
        <tbody>
        <?php foreach ($firmy as $f): ?>
        <tr>
            <td><strong><?php echo esc_html($f->firma_nazev); ?></strong></td>
            <td style="color:#666"><?php echo esc_html($f->firma_email); ?></td>
            <td style="text-align:center"><strong><?php echo $f->celkem; ?></strong></td>
            <td style="text-align:center"><span style="background:#dcfce7;color:#16a34a;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:600"><?php echo $f->pouzito; ?></span></td>
            <td style="text-align:center"><span style="background:#fef3c7;color:#d97706;padding:3px 8px;border-radius:99px;font-size:11px;font-weight:600"><?php echo $f->volnych; ?></span></td>
            <td style="color:#666"><?php echo date('d.m.Y H:i', strtotime($f->posledni)); ?></td>
            <td><a href="?page=refdrive-prehled&firma=<?php echo urlencode($f->firma_email); ?>&nazev=<?php echo urlencode($f->firma_nazev); ?>" class="rd-btn-detail">Detail →</a></td>
        </tr>
        <?php endforeach; ?>
        <?php if (empty($firmy)): ?><tr><td colspan="7" style="text-align:center;color:#999;padding:24px">Zatím žádné kódy.</td></tr><?php endif; ?>
        </tbody>
    </table>
    </div><!-- /max-width:900px -->
    </div><!-- .wrap -->
    <?php
}

function rd_admin_kody_detail($firma_email) {
    global $wpdb;
    $firma_nazev_param = isset($_GET['nazev']) ? sanitize_text_field($_GET['nazev']) : '';
    if ($firma_nazev_param) {
        $firma = $wpdb->get_row($wpdb->prepare("SELECT firma_nazev, firma_email, COUNT(*) as celkem, SUM(pouzit) as pouzito FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND firma_nazev=%s GROUP BY firma_nazev, firma_email", $firma_email, $firma_nazev_param));
    } else {
        $firma = $wpdb->get_row($wpdb->prepare("SELECT firma_nazev, firma_email, COUNT(*) as celkem, SUM(pouzit) as pouzito FROM " . RD_TABLE_KODY . " WHERE firma_email=%s GROUP BY firma_nazev, firma_email ORDER BY MAX(vytvoreno) DESC LIMIT 1", $firma_email));
    }
    if (!$firma) { echo '<div class="wrap"><p>Firma nenalezena.</p></div>'; return; }
    $filtr  = isset($_GET['filtr'])  ? sanitize_text_field($_GET['filtr'])  : 'vse';
    $hledat = isset($_GET['hledat']) ? sanitize_text_field($_GET['hledat']) : '';
    $nazev_url = urlencode($firma_nazev_param);
    $where  = $firma_nazev_param 
        ? $wpdb->prepare("WHERE k.firma_email=%s AND k.firma_nazev=%s", $firma_email, $firma_nazev_param)
        : $wpdb->prepare("WHERE k.firma_email=%s AND k.firma_nazev=%s", $firma_email, $firma->firma_nazev);
    $filtr_stat = isset($_GET['filtr_stat']) ? sanitize_text_field($_GET['filtr_stat']) : '';
    if ($filtr_stat === 'pouzite')    $filtr = 'pouzite';
    if ($filtr_stat === 'nepouzite')  $filtr = 'nepouzite';
    if ($filtr_stat === 'absolventi') $filtr = 'absolventi';
    if ($filtr === 'pouzite')    $where .= " AND k.pouzit=1";
    if ($filtr === 'nepouzite')  $where .= " AND k.pouzit=0";
    if ($filtr === 'absolventi') $where .= " AND k.kod IN (SELECT kod FROM " . RD_TABLE_RIDICI . " WHERE uspech=1)";
    if ($hledat) $where .= $wpdb->prepare(" AND (k.kod LIKE %s OR k.ridic_jmeno LIKE %s)", "%$hledat%", "%$hledat%");
    $kody = $wpdb->get_results("SELECT k.*, COALESCE(k.ridic_jmeno, r.jmeno) as ridic_jmeno, r.score as ridic_score, r.uspech as ridic_uspech, r.datum_skoleni as ridic_datum FROM " . RD_TABLE_KODY . " k LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1) $where ORDER BY k.vytvoreno DESC LIMIT 500");
    ?>
    <div class="wrap">
    <h1><a href="?page=refdrive-prehled" style="color:#2563eb;text-decoration:none;font-size:0.7em;font-weight:400"><svg style="display:inline;vertical-align:middle;margin-right:4px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>Zpět</a><br><svg style="display:inline;vertical-align:middle;margin-right:6px" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0H5m14 0h2M5 21H3m4-10h2m4 0h2M9 7h2m4 0h2"/></svg><?php echo esc_html($firma->firma_nazev); ?></h1>
    <div style="max-width:900px">
    <?php
    $base_url_firma = admin_url('admin.php?page=refdrive-kody&firma=' . urlencode($firma_email) . ($firma_nazev_param ? '&nazev=' . urlencode($firma_nazev_param) : ''));
    $absolventi_firma = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT k.kod) FROM " . RD_TABLE_KODY . " k INNER JOIN " . RD_TABLE_RIDICI . " r ON r.kod=k.kod WHERE k.firma_email=%s AND r.uspech=1", $firma_email));
    ?>
    <div style="display:flex;gap:20px;flex-wrap:wrap;padding:10px 14px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:12px;font-size:13px">
        <a href="<?php echo $base_url_firma; ?>" style="text-decoration:none;color:<?php echo $filtr==='vse'?'#111827':'#6b7280';?>;font-weight:<?php echo $filtr==='vse'?'700':'400';?>">
            Celkem kódů: <strong><?php echo $firma->celkem; ?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url_firma . '&filtr_stat=pouzite'; ?>" style="text-decoration:none;color:<?php echo $filtr==='pouzite'?'#7c3aed':'#6b7280';?>;font-weight:<?php echo $filtr==='pouzite'?'700':'400';?>">
            Použito: <strong><?php echo $firma->pouzito; ?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url_firma . '&filtr_stat=nepouzite'; ?>" style="text-decoration:none;color:<?php echo $filtr==='nepouzite'?'#374151':'#6b7280';?>;font-weight:<?php echo $filtr==='nepouzite'?'700':'400';?>">
            Volných: <strong><?php echo $firma->celkem - $firma->pouzito; ?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url_firma . '&filtr_stat=absolventi'; ?>" style="text-decoration:none;color:<?php echo $filtr==='absolventi'?'#16a34a':'#6b7280';?>;font-weight:<?php echo $filtr==='absolventi'?'700':'400';?>">
            Absolventů: <strong><?php echo $absolventi_firma; ?></strong>
        </a>
    </div>
    <form method="get" style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap">
        <input type="hidden" name="page" value="refdrive-kody">
        <input type="hidden" name="firma" value="<?php echo esc_attr($firma_email); ?>">
            <input type="hidden" name="nazev" value="<?php echo esc_attr($firma_nazev_param ?: $firma->firma_nazev); ?>">
        <input type="text" name="hledat" value="<?php echo esc_attr($hledat); ?>" placeholder="Hledat kód nebo jméno..." class="regular-text">
        <select name="filtr"><option value="vse" <?php selected($filtr,'vse'); ?>>Všechny</option><option value="nepouzite" <?php selected($filtr,'nepouzite'); ?>>Volné</option><option value="pouzite" <?php selected($filtr,'pouzite'); ?>>Použité</option></select>
        <button type="submit" class="rd-btn-detail" style="padding:5px 12px;font-size:13px">Filtrovat</button>
        <?php if ($hledat || $filtr !== 'vse'): ?><a href="?page=refdrive-prehled&firma=<?php echo urlencode($firma_email); ?>" class="button">Zrušit</a><?php endif; ?>
        <a href="<?php echo admin_url('admin-post.php?action=rd_export_firma&firma=' . urlencode($firma_email)); ?>" class="button" style="margin-left:auto"><svg style="display:inline;vertical-align:middle;margin-right:5px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg> Export CSV</a>
    </form>

    <?php if (empty($kody)): ?>
    <p style="color:#6b7280;font-size:13px;margin-top:8px">Žádné kódy.</p>
    <?php else: ?>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px;margin-top:8px">
    <?php foreach ($kody as $k):
        $bs = 'display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700;white-space:nowrap;';
        $expiry_warn = '';
        if ($k->pouzit) {
            $badge = '<span style="' . $bs . 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0">✓ Použit</span>';
        } elseif ($k->ridic_jmeno) {
            $badge = '<span style="' . $bs . 'background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe"><svg style="display:inline;vertical-align:middle;margin-right:3px" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 22h14M5 2h14M17 22v-4.172a2 2 0 00-.586-1.414L12 12M7 22v-4.172a2 2 0 01.586-1.414L12 12"/></svg>Probíhá</span>';
        } else {
            $badge = '<span style="' . $bs . 'background:#fef3c7;color:#92400e;border:1px solid #fde68a">○ Volný</span>';
        }
        $score_key = isset($k->ridic_score) ? $k->ridic_score : (isset($k->score) ? $k->score : null);
        $uspech_key = isset($k->ridic_uspech) ? $k->ridic_uspech : (isset($k->uspech) ? $k->uspech : null);
        if ($k->expiruje && !$k->pouzit) {
            $dni = (int)round((strtotime($k->expiruje) - time()) / 86400);
            if ($dni < 0)       { $badge = '<span style="' . $bs . 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca">✕ Expiroval</span>'; $expiry_warn = '#dc2626'; }
            elseif ($dni <= 30) { $expiry_warn = '#d97706'; }
        }
        $kurz_url = $k->token ? home_url('/kurz/?token=' . $k->token . '&rd_admin_preview=1') : '';
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px 16px;font-size:13px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">
            <code style="font-size:13px;font-weight:700;color:#111827;letter-spacing:.5px"><?php echo esc_html($k->kod); ?></code>
            <span style="font-size:11px;color:#9ca3af"><?php echo date('d.m.Y H:i', strtotime($k->vytvoreno)); ?></span>
        </div>
        <div style="margin-bottom:10px"><?php echo $badge; ?></div>
        <?php if ($k->ridic_jmeno): ?>
        <div style="font-size:12px;color:#374151;margin-bottom:4px">
            <svg style="display:inline;vertical-align:middle;margin-right:3px;opacity:.5" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
            <?php echo esc_html($k->ridic_jmeno); ?>
        </div>
        <?php endif; ?>
        <?php if ($k->pouzit): ?>
        <div style="font-size:12px;color:#374151;margin-bottom:4px">
            Score: <strong><?php echo $score_key !== null ? $score_key . '%' : '—'; ?></strong>
            &nbsp;|&nbsp;
            <?php if ($uspech_key) echo '<span style="color:#16a34a;font-weight:600">✓ Splnil</span>';
                  else echo '<span style="color:#dc2626;font-weight:600">✗ Nesplnil</span>'; ?>
        </div>
        <div style="font-size:11px;color:#6b7280">Použit: <?php echo $k->datum_pouziti ? date('d.m.Y H:i', strtotime($k->datum_pouziti)) : '—'; ?></div>
        <?php endif; ?>
        <div style="font-size:11px;color:#9ca3af;margin-top:6px;border-top:1px solid #f3f4f6;padding-top:6px">
            <?php echo esc_html($k->firma_nazev ?: '—'); ?>
        </div>
        <?php if ($k->expiruje && !$k->pouzit): ?>
        <div style="font-size:11px;color:<?php echo $expiry_warn ?: '#6b7280'; ?>;margin-top:3px">
            <?php $dni_e=(int)round((strtotime($k->expiruje)-time())/86400); $ec=$dni_e<=30?'#dc2626':($dni_e<=90?'#d97706':'#6b7280'); ?>
            <span style="color:<?php echo $ec;?>;font-weight:<?php echo $dni_e<=30?'600':'400';?>">Expiruje: <?php echo date('d.m.Y',strtotime($k->expiruje));?><?php if($dni_e<=30): ?> (<?php echo $dni_e;?> dní!)</span><?php else: ?></span><?php endif; ?>
        </div>
        <?php endif; ?>
        <?php if ($kurz_url): ?>
        <div style="margin-top:10px;display:flex;gap:6px">
            <a href="<?php echo esc_url($kurz_url); ?>" target="_blank" style="font-size:11px;color:#2563eb;text-decoration:none;display:inline-flex;align-items:center;gap:3px">
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71"/></svg> Otevřít
            </a>
            <button onclick="navigator.clipboard.writeText('<?php echo esc_js(home_url('/kurz/?token=' . $k->token)); ?>');this.innerHTML='✓ Zkopírováno'" style="font-size:11px;padding:2px 8px;cursor:pointer;border:1px solid #e5e7eb;border-radius:4px;background:#f9fafb;color:#374151">
                <svg style="display:inline;vertical-align:middle" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 012 2v14a2 2 0 01-2 2H6a2 2 0 01-2-2V6a2 2 0 012-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg> Kopírovat
            </button>
        </div>
        <?php endif; ?>
    </div>
    <?php endforeach; ?>
    </div>
    <p style="color:#666;font-size:12px;margin-top:8px">Zobrazeno: <?php echo count($kody); ?> kódů</p>
    <?php endif; ?>
    </div>
    <?php
}

/* ---- ABSOLVENTI ---- */
/* ============================================================
   ADMIN – OPRÁVNĚNÍ LEKTORA
   ============================================================ */
function rd_admin_lektor_perm() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    $lektor_tbl = $wpdb->prefix . 'rd_lektor';
    $msg = '';
    if (isset($_POST['rd_lektor_zmena_hesla']) && check_admin_referer('rd_lektor_perm_nonce')) {
        $novy = sanitize_text_field($_POST['lektor_novy_kod'] ?? '');
        $nov2 = sanitize_text_field($_POST['lektor_novy_kod2'] ?? '');
        if (strlen($novy) < 6) {
            $msg = '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:10px 14px;font-size:13px;color:#dc2626;margin-bottom:12px">&#10007; P&#345;&#237;stupov&#253; k&#243;d mus&#237; m&#237;t alespo&#328; 6 znak&#367;.</div>';
        } elseif ($novy !== $nov2) {
            $msg = '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:10px 14px;font-size:13px;color:#dc2626;margin-bottom:12px">&#10007; K&#243;dy se neshoduj&#237;.</div>';
        } else {
            $wpdb->query($wpdb->prepare("UPDATE $lektor_tbl SET kod=%s ORDER BY id ASC LIMIT 1", $novy));
            $msg = '<div style="background:#dcfce7;border:1px solid #86efac;border-radius:6px;padding:10px 14px;font-size:13px;color:#15803d;margin-bottom:12px">&#10003; P&#345;&#237;stupov&#253; k&#243;d lektora byl zm&#283;n&#283;n.</div>';
        }
    }
    $lektor_url = home_url('/lektor');
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px;max-width:500px">
        <h2 style="font-size:14px;font-weight:700;margin:0 0 4px">Heslo lektora</h2>
        <p style="font-size:12px;color:#6b7280;margin:0 0 16px">P&#345;&#237;stupov&#253; k&#243;d pro p&#345;ihl&#225;&#353;en&#237; na <a href="<?php echo esc_url($lektor_url); ?>" target="_blank" style="color:#2563eb"><code>/lektor</code></a>. Minim&#225;ln&#283; 6 znak&#367;.</p>
        <?php echo $msg; ?>
        <form method="post">
            <?php wp_nonce_field('rd_lektor_perm_nonce'); ?>
            <div style="display:flex;flex-direction:column;gap:10px;margin-bottom:14px">
                <label style="font-size:13px;color:#374151">
                    <span style="display:block;font-weight:600;margin-bottom:4px">Nov&#253; k&#243;d</span>
                    <input type="password" name="lektor_novy_kod" class="regular-text" autocomplete="new-password" required style="width:100%">
                </label>
                <label style="font-size:13px;color:#374151">
                    <span style="display:block;font-weight:600;margin-bottom:4px">Znovu</span>
                    <input type="password" name="lektor_novy_kod2" class="regular-text" autocomplete="new-password" required style="width:100%">
                </label>
            </div>
            <button type="submit" name="rd_lektor_zmena_hesla" class="rd-btn-confirm" style="font-size:13px;padding:6px 16px">Zm&#283;nit heslo lektora</button>
        </form>
    </div>
    <?php
}



/* ---- OBJEDNÁVKY ---- */
function rd_admin_objednavky() {
    global $wpdb;
    // Storno objednávky od autoškoly
    if (isset($_GET['rd_storno_obj']) && check_admin_referer('rd_storno_obj_' . $_GET['rd_storno_obj'])) {
        $pi_id = sanitize_text_field($_GET['rd_storno_obj']);
        $pozn  = sanitize_textarea_field($_GET['pozn'] ?? '');
        $moje  = rd_get_my_autoskola();
        $row   = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE pi_id=%s", $pi_id));
        if ($row && $row->stav === 'prevod_ceka' && ($moje && $row->autoskola_id === $moje->id || current_user_can('manage_options'))) {
            $wpdb->update(RD_TABLE_OBJ, ['stav' => 'storno', 'poznamka' => $pozn], ['pi_id' => $pi_id]);
            // Email firmě
            $as_nazev = $moje ? $moje->nazev : get_bloginfo('name');
            $telo = rd_email_wrap('Objednávka odmítnuta',
                '<p>Dobrý den, <strong>' . esc_html($row->firma_nazev) . '</strong>,</p>'
                . '<p>Vaše objednávka <strong>' . intval($row->pocet) . ' kódů</strong> u autoškoly <strong>' . esc_html($as_nazev) . '</strong> bohužel nemohla být zpracována.</p>'
                . ($pozn ? '<div style="background:#fef3c7;border:1px solid #fde68a;border-radius:8px;padding:12px 16px;margin:16px 0"><strong>Důvod:</strong> ' . nl2br(esc_html($pozn)) . '</div>' : '')
                . '<p>Pokud jste již provedli platbu, bude vám vrácena. V případě dotazů kontaktujte autoškolu přímo.</p>'
                . rd_email_btn('Vybrat jinou autoškolu →', home_url('/#autoskoly'))
            );
            $headers = ['Content-Type: text/html; charset=UTF-8'];
            wp_mail($row->firma_email, 'Objednávka odmítnuta – ' . $as_nazev, $telo, $headers);
            echo '<div class="notice notice-warning is-dismissible"><p>Objednávka odmítnuta, firma ' . esc_html($row->firma_email) . ' byla informována.</p></div>';
        }
    }

    // Uložit poznámku k objednávce
    if (isset($_POST['rd_ulozit_pozn']) && check_admin_referer('rd_pozn_' . $_POST['rd_ulozit_pozn'])) {
        $pi_id = sanitize_text_field($_POST['rd_ulozit_pozn']);
        $pozn  = sanitize_textarea_field($_POST['poznamka'] ?? '');
        $moje  = rd_get_my_autoskola();
        $row   = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE pi_id=%s", $pi_id));
        if ($row && ($moje && $row->autoskola_id === $moje->id || current_user_can('manage_options'))) {
            $wpdb->update(RD_TABLE_OBJ, ['poznamka' => $pozn], ['pi_id' => $pi_id]);
            echo '<div class="notice notice-success is-dismissible"><p>✓ Poznámka uložena.</p></div>';
        }
    }

    if (isset($_GET['potvrdit']) && (current_user_can('manage_options') || current_user_can('refdrive_access'))) {
        $pi_id = sanitize_text_field($_GET['potvrdit']);
        $row   = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE pi_id=%s", $pi_id));
        if ($row && $row->stav === 'prevod_ceka') {
            if (intval($row->pocet) < 1) {
                echo '<div class="notice notice-error"><p>Chyba: počet kódů je 0 nebo NULL. pi_id=' . esc_html($pi_id) . ', pocet=' . esc_html($row->pocet) . '</p></div>';
                return;
            }
            // Předat autoskola_id z objednávky — session v admin kontextu neexistuje
            $obj_data = json_decode($row->data ?? '{}', true);
            if ($row->autoskola_id) $obj_data['autoskola_id'] = $row->autoskola_id;
            rd_vygenerovat_kody($row->firma_nazev, $row->firma_email, $row->pocet, $pi_id, $obj_data);
            $wpdb->update(RD_TABLE_OBJ, ['stav' => 'zaplaceno'], ['pi_id' => $pi_id]);
            echo '<div class="notice notice-success"><p>✓ Kódy odeslány na ' . esc_html($row->firma_email) . '</p></div>';
        }
    }
    // Filtr pro autoskola_admin - vidí jen své objednávky
    $as_filter_sql = '';
    if (!current_user_can('manage_options')) {
        $moje_as = rd_get_my_autoskola();
        if ($moje_as) {
            // Filtr přes autoskola_id NEBO přes JSON data (starší objednávky bez autoskola_id sloupce)
            $as_id_f = intval($moje_as->id);
            $as_filter_sql = $wpdb->prepare(
                " AND (autoskola_id=%d OR (autoskola_id IS NULL AND data LIKE %s))",
                $as_id_f,
                '%"autoskola_id":' . $as_id_f . '%'
            );
        }
    }

    $hledat_obj  = sanitize_text_field($_GET['hledat'] ?? '');
    $filtr_stav  = sanitize_key($_GET['filtr_stav'] ?? '');
    $extra_where = '';
    if ($hledat_obj) $extra_where .= $wpdb->prepare(" AND (firma_nazev LIKE %s OR firma_email LIKE %s)", "%$hledat_obj%", "%$hledat_obj%");
    if ($filtr_stav) $extra_where .= $wpdb->prepare(" AND stav=%s", $filtr_stav);
    $obj = $wpdb->get_results("SELECT * FROM " . RD_TABLE_OBJ . " WHERE 1=1{$as_filter_sql}{$extra_where} ORDER BY vytvoreno DESC LIMIT 200");

    $stav_labels = [
        'prevod_ceka' => ['label'=>'Čeká na platbu', 'color'=>'#d97706'],
        'zaplaceno'   => ['label'=>'Zaplaceno',               'color'=>'#16a34a'],
        'zruseno'     => ['label'=>'Zrušeno',                 'color'=>'#dc2626'],
        'ceka'        => ['label'=>'Čeká',                    'color'=>'#d97706'],
    ];
    ?>
    <div class="wrap">
    <h1>Objednávky<?php if (!current_user_can('manage_options') && !empty($moje_as)): ?> — <?php echo esc_html($moje_as->nazev); ?><?php endif; ?></h1>
    <div style="max-width:900px">
    <style>
    .rd-obj-table{width:100%;border-collapse:collapse;font-size:13px;margin-top:12px}
