/* ---- NASTAVENÍ EMAILU ---- */
function rd_admin_nastaveni_all() {
    $tab = sanitize_key($_GET['tab'] ?? 'platby');
    $base = admin_url('admin.php?page=refdrive-nastaveni-all');
    $tabs = [
        'platby' => 'Nastavení plateb',
        'email'  => 'Nastavení emailu',
        'kurz'   => 'Nastavení kurzu',
        'lektor' => 'Lektor',
    ];
    ?>
    <div class="wrap">
    <h1>Nastavení</h1>
    <div style="max-width:900px">
    <div style="display:flex;gap:8px;margin-bottom:20px;flex-wrap:wrap">
        <?php foreach ($tabs as $key => $label): ?>
        <a href="<?php echo esc_url(add_query_arg('tab', $key, $base)); ?>"
           style="text-decoration:none;padding:6px 16px;border-radius:6px;font-size:13px;font-weight:600;border:1px solid <?php echo $tab===$key?'#7c3aed':'#e5e7eb'; ?>;background:<?php echo $tab===$key?'#f5f3ff':'#fff'; ?>;color:<?php echo $tab===$key?'#7c3aed':'#374151'; ?>"><?php echo $label; ?></a>
        <?php endforeach; ?>
    </div>
    <?php
    if ($tab === 'platby')      rd_admin_platby_content();
    elseif ($tab === 'email')   rd_admin_email_content();
    elseif ($tab === 'kurz')    rd_admin_kurz_content();
    elseif ($tab === 'lektor')  rd_admin_lektor_perm();
    ?>
    </div><!-- /max-width:900px -->
    </div><!-- .wrap -->
    <?php
}

function rd_admin_email() { rd_admin_email_content(); }
function rd_admin_email_content() {
    // Uložit nastavení
    if (isset($_POST['rd_save_email']) && check_admin_referer('rd_email_nonce')) {
        update_option('rd_email_predmet', sanitize_text_field($_POST['predmet'] ?? ''));
        update_option('rd_email_uvod',    sanitize_textarea_field($_POST['uvod'] ?? ''));
        update_option('rd_email_zaver',   sanitize_textarea_field($_POST['zaver'] ?? ''));
        update_option('rd_smtp_on',       isset($_POST['smtp_on']) ? 1 : 0);
        update_option('rd_smtp_host',     sanitize_text_field($_POST['smtp_host'] ?? ''));
        update_option('rd_smtp_port',     intval($_POST['smtp_port'] ?? 587));
        update_option('rd_smtp_user',     sanitize_text_field($_POST['smtp_user'] ?? ''));
        if (!empty($_POST['smtp_pass'])) update_option('rd_smtp_pass', $_POST['smtp_pass']);
        update_option('rd_smtp_enc',      sanitize_text_field($_POST['smtp_enc'] ?? 'tls'));
        update_option('rd_smtp_from',     sanitize_email($_POST['smtp_from'] ?? ''));
        update_option('rd_notif_email',   sanitize_email($_POST['notif_email'] ?? ''));
        update_option('rd_smtp_from_name',sanitize_text_field($_POST['smtp_from_name'] ?? ''));
        echo '<div class="notice notice-success"><p>✓ Nastavení emailu uloženo.</p></div>';
    }
    // Odeslat testovací email (jeden)
    if (isset($_POST['rd_test_email']) && check_admin_referer('rd_email_nonce')) {
        $test_email = sanitize_email($_POST['test_email']);
        if ($test_email) {
            // Zachytit SMTP chybu
            $smtp_err = '';
            $smtp_err_handler = function($error) use (&$smtp_err) {
                $smtp_err = $error->get_error_message();
            };
            add_action('wp_mail_failed', $smtp_err_handler);

            $result = rd_odeslat_email('Jan Novák (TEST)', $test_email, get_bloginfo('name'), 100, date('d.m.Y'), 'TEST-00000');

            remove_action('wp_mail_failed', $smtp_err_handler);

            if ($smtp_err) {
                echo '<div class="notice notice-error"><p><strong>SMTP chyba:</strong> ' . esc_html($smtp_err) . '</p></div>';
            } elseif ($result === false) {
                echo '<div class="notice notice-error"><p>Email se nepodařilo odeslat. Zkontroluj SMTP přihlašovací údaje.</p></div>';
            } else {
                echo '<div class="notice notice-success"><p>Testovací email odeslán na <strong>' . esc_html($test_email) . '</strong>. Zkontrolujte doručenou poštu i spam.</p></div>';
            }
        }
    }

    // Odeslat všechny testovací emaily
    if (isset($_POST['rd_test_all_emails']) && check_admin_referer('rd_email_nonce')) {
        $test_email = sanitize_email($_POST['test_email']);
        if ($test_email) {
            $_from  = get_option('rd_smtp_from', get_option('admin_email'));
            $_fname = get_option('rd_smtp_from_name', get_bloginfo('name'));
            $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $_fname . ' <' . $_from . '>'];
            $site = get_bloginfo('name');

            // 1. Potvrzení absolvování
            rd_odeslat_email('Jan Novák (TEST)', $test_email, $site, 85, date('d.m.Y'), 'TEST-00001', '42 min');

            // 2. Objednávka přijata + platební instrukce
            // V testu simulujeme účet autoškoly (ne RefDrive)
            $cislo_uctu = '987654321/2010'; // fiktivní účet autoškoly
            $iban       = 'CZ6508000000001234567899'; // fiktivní IBAN autoškoly
            $bic        = 'FIOBCZPPXXX';
            $banka      = 'Fio banka (autoškola)';
            $faktura_pozn = '';
            $telo2 = rd_email_admin_prevod('Testovací firma s.r.o.', $test_email, 5, 594, 'VS-TEST-001');
            // Sestavit fakturu ručně
            $nazev = 'Testovací firma s.r.o.'; $pocet = 5; $cena = get_option('rd_cena_kus', 99);
            $castka = $pocet * $cena; $castka_dph = round($castka * 1.21); $vs = 'VS-TEST-001';
            // Fiktivní autoškola jako dodavatel (v ostrém provozu se bere z rd_autoskoly)
            $dodavatel_nazev  = 'Testovací autoškola s.r.o.';
            $dodavatel_ico    = '12345678';
            $dodavatel_adresa = 'Hlavní 1, 400 01 Ústí nad Labem';
            $css2 = '@media(prefers-color-scheme:dark){.em-bg{background:#0d0d14!important}.em-card{background:#1a1728!important;border-color:#2d2a3e!important}.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}.em-muted{color:#9ca3af!important}.em-row td{border-bottom-color:#2d2a3e!important;color:#f1f0fb!important}.em-footer{border-top-color:#2d2a3e!important}.em-surface{background:#251f38!important;border-color:#2d2a3e!important}pre.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}p[style*="color:#111827"]{color:#111827!important}}';
            $logo2 = '<a href="https://refdrive.pro" style="text-decoration:none;display:block;margin-bottom:20px"><span style="font-family:Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:-0.5px"><span style="color:#7c3aed">ref</span><span style="color:#db2777">drive</span><span style="color:#7c3aed">.pro</span></span><div style="font-size:11px;color:#9ca3af;margin-top:2px">Online školení referentských řidičů</div></a>';
