/**
 * Vrátí aktuální autoškolu podle session nebo ?ref= parametru.
 * Ukládá do session pro celé školení.
 */
function rd_get_current_autoskola() {
    global $wpdb;
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();

    // Priorita 1: ?ref= v URL — vždy přepíše session
    $ref = sanitize_key($_GET['ref'] ?? '');
    if ($ref) {
        $as = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE slug=%s AND stav='aktivni' AND (cislo_uctu != '' AND cislo_uctu IS NOT NULL) LIMIT 1",
            $ref
        ));
        if ($as) {
            $_SESSION['rd_autoskola_id'] = $as->id;
            return $as;
        }
    }

    // Priorita 2: session
    if (!empty($_SESSION['rd_autoskola_id'])) {
        $as = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' AND (cislo_uctu != '' AND cislo_uctu IS NOT NULL) LIMIT 1",
            intval($_SESSION['rd_autoskola_id'])
        ));
        if ($as) return $as;
    }

    return null;
}

/**
 * Vrátí autoškolu přihlášeného wp uživatele (role autoskola_admin).
 */
function rd_get_my_autoskola() {
    global $wpdb;
    if (!is_user_logged_in()) return null;
    $uid = get_current_user_id();
    return $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE wp_user_id=%d LIMIT 1",
        $uid
    ));
}

/**
 * Ověří zda aktuálně přihlášený wp uživatel je admin autoškoly
 * (ne hlavní admin).
 */
function rd_je_autoskola_admin() {
    if (current_user_can('manage_options')) return false;
    return (bool) rd_get_my_autoskola();
}

/**
 * Vrátí stav kapacity autoškoly jako string: 'ok', 'omezena', 'vycerpana'
 */
/**
 * Vrátí všechny aktivní platby (balíčky) autoškoly seřazené podle expirace.
 * Každý záznam má: id, tier_nazev, limit_kodu, platnost_do, zbyvaji (kódy zbývající v tomto balíčku)
 */
function rd_autoskola_aktivni_platby($autoskola_id) {
    global $wpdb;
    $dnes = date('Y-m-d');
    $platby = $wpdb->get_results($wpdb->prepare(
        "SELECT p.id, p.platnost_od, p.platnost_do, p.castka, t.nazev as tier_nazev, t.limit_kodu
         FROM " . RD_TABLE_AS_PLATBY . " p
         LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id
         WHERE p.autoskola_id=%d AND p.stav='zaplaceno' AND p.platnost_do >= %s
         ORDER BY p.platnost_do ASC",
        intval($autoskola_id), $dnes
    ));

    // Zjistit kolik kódů bylo celkem prodáno touto autoškolu
    $prodano = (int)$wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d",
        intval($autoskola_id)
    ));

    // Přiřadit využití ke každému balíčku (FIFO — nejdříve expirující se čerpá první)
    $zbyvá_přiřadit = $prodano;
    foreach ($platby as &$p) {
        if ($p->limit_kodu >= 99999) {
            $p->zbyvaji = PHP_INT_MAX;
            continue;
        }
        $limit = (int)$p->limit_kodu;
        $cerpano = min($zbyvá_přiřadit, $limit);
        $p->zbyvaji = max(0, $limit - $cerpano);
        $zbyvá_přiřadit = max(0, $zbyvá_přiřadit - $cerpano);
    }
    unset($p);
    return $platby;
}

/**
 * Vrátí celkovou zbývající kapacitu autoškoly (součet přes všechny aktivní balíčky).
 * Vrátí PHP_INT_MAX pokud má neomezený balíček.
 * Vrátí null pokud nemá žádný aktivní balíček.
 */
function rd_autoskola_zbyvajici_kapacita($autoskola_id) {
    $platby = rd_autoskola_aktivni_platby($autoskola_id);
    if (empty($platby)) return null;
    $celkem = 0;
    foreach ($platby as $p) {
        if ($p->limit_kodu >= 99999) return PHP_INT_MAX;
        $celkem += $p->zbyvaji;
    }
    return $celkem;
}

function rd_autoskola_kapacita_stav($as) {
    $zbyvaji = rd_autoskola_zbyvajici_kapacita($as->id ?? 0);
    if ($zbyvaji === null || $zbyvaji <= 0) return 'vycerpana';
    if ($zbyvaji === PHP_INT_MAX) return 'ok';
    // Varování pokud zbývá méně než 20% z celkového limitu aktivních balíčků
    $platby = rd_autoskola_aktivni_platby($as->id ?? 0);
    $celkovy_limit = array_sum(array_column((array)$platby, 'limit_kodu'));
    if ($zbyvaji <= max(1, round($celkovy_limit * 0.2))) return 'omezena';
    return 'ok';
}

/**
 * Inkrementuje čítač kódů autoškoly.
 * kody_tento_mesic slouží jako celkový čítač prodaných kódů (bez resetu).
 */
function rd_autoskola_pridat_kody($autoskola_id, $pocet) {
    global $wpdb;
    $as = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1",
        intval($autoskola_id)
    ));
    if (!$as) return false;
    $wpdb->update(
        RD_TABLE_AUTOSKOLY,
        ['kody_tento_mesic' => (int)$as->kody_tento_mesic + $pocet],
        ['id' => $autoskola_id]
    );
    return true;
}

/**
 * Vrátí zbývající kapacitu autoškoly v tomto měsíci. (alias pro zpětnou kompatibilitu)
 * @deprecated Použijte rd_autoskola_zbyvajici_kapacita()
 */

/**
 * Vrátí SQL WHERE podmínku pro autoškoly s dostatečnou kapacitou.
 * Používá subquery přes rd_as_platby místo starého kody_tento_mesic.
 * $min_pocet = minimální počet zbývajících kódů (0 = alespoň 1)
 */
function rd_sql_kapacita_podminka($as_alias = 'a', $min_pocet = 1) {
    global $wpdb;
    $dnes = date('Y-m-d');
    $prodano_sub = "SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id={$as_alias}.id";
    $limit_sub   = "SELECT COALESCE(SUM(p2.limit_kodu),0) FROM " . RD_TABLE_AS_PLATBY . " p2 WHERE p2.autoskola_id={$as_alias}.id AND p2.stav='zaplaceno' AND p2.platnost_do >= '{$dnes}'";
    $neomezeny   = "EXISTS (SELECT 1 FROM " . RD_TABLE_AS_PLATBY . " p3 JOIN " . RD_TABLE_AS_TIERY . " t3 ON t3.id=p3.tier_id WHERE p3.autoskola_id={$as_alias}.id AND p3.stav='zaplaceno' AND p3.platnost_do >= '{$dnes}' AND t3.limit_kodu >= 99999)";
    $min = intval($min_pocet);
    return "({$neomezeny} OR (({$limit_sub}) - ({$prodano_sub})) >= {$min})";
}

/**
 * Synchronizuje predplatne_expiruje na MAX(platnost_do) ze všech zaplacených balíčků.
 * Volat vždy po potvrzení nebo přidání platby.
 */
function rd_sync_predplatne_expiruje($autoskola_id) {
    global $wpdb;
    $max_do = $wpdb->get_var($wpdb->prepare(
        "SELECT MAX(platnost_do) FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='zaplaceno'",
        intval($autoskola_id)
    ));
    if ($max_do) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, [
            'predplatne_expiruje' => $max_do,
            'expir_email_7d'      => 0,
            'expir_email_0d'      => 0,
            'expir_email_7po'     => 0,
            'expir_grace_od'      => null,
        ], ['id' => intval($autoskola_id)]);
    }
}

/**
 * Zaloguje změnu OOP URL autoškoly.
 */
function rd_as_oop_log($autoskola_id, $oop_url, $zdroj = 'nastaveni') {
    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'rd_as_oop_log', [
        'autoskola_id' => intval($autoskola_id),
        'oop_url'      => sanitize_url($oop_url),
        'zdroj'        => $zdroj,
        'vytvoreno'    => current_time('mysql'),
    ]);
}

/**
 * Zaloguje změnu ceny za kód autoškoly.
 * $zdroj: 'onboarding' | 'nastaveni'
 */
function rd_as_cena_log($autoskola_id, $cena_kus, $zdroj = 'nastaveni') {
    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'rd_as_cena_log', [
        'autoskola_id' => intval($autoskola_id),
        'cena_kus'     => intval($cena_kus),
        'zdroj'        => $zdroj,
        'vytvoreno'    => current_time('mysql'),
    ]);
}

/**
 * Přiřadí firmu jako kmenovou k autoškole.
 * Původní kmenová vazba se zachová jako historická (kmenova=0).
 */

/**
 * Vrátí kmenovou autoškolu firmy.
 */
function rd_get_firma_autoskola($firma_id) {
    global $wpdb;
    return $wpdb->get_row($wpdb->prepare(
        "SELECT a.* FROM " . RD_TABLE_AUTOSKOLY . " a
         INNER JOIN " . RD_TABLE_FIRMA_AS . " fa ON fa.autoskola_id=a.id
         WHERE fa.firma_id=%d AND fa.kmenova=1 LIMIT 1",
        intval($firma_id)
    ));
}

/**
 * Odešle notifikační email autoškole.
 */
function rd_email_autoskola($autoskola_email, $predmet, $telo_html, $extra_headers = [], $attachments = []) {
    $from      = get_option('rd_smtp_from', get_option('admin_email'));
    $from_name = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers   = array_merge(['Content-Type: text/html; charset=UTF-8', 'From: ' . $from_name . ' <' . $from . '>'], $extra_headers);
    return wp_mail($autoskola_email, $predmet, $telo_html, $headers, $attachments);
}

/* ============================================================
   v6.1.0 — HELPER: získat autoskola_id z aktuální admin stránky
   ============================================================ */
function rd_admin_get_as_id_from_page() {
    $page = sanitize_key($_GET['page'] ?? '');
    // Formát: refdrive-as-{id} nebo refdrive-as-{id}-kody atd.
    if (preg_match('/^refdrive-as-(\d+)/', $page, $m)) {
        return intval($m[1]);
    }
    return 0;
}

/* ============================================================
   v6.1.0 — ADMIN: DETAIL AUTOŠKOLY (přehled)
   ============================================================ */
function rd_admin_as_detail() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    $as_id = rd_admin_get_as_id_from_page();
    if (!$as_id) wp_die('Autoškola nenalezena');

    // Uložit cenu
    if (isset($_POST['rd_save_as_oop']) && check_admin_referer('rd_as_detail_nonce_' . $as_id)) {
        $new_oop = esc_url_raw(trim($_POST['oop_url'] ?? ''));
        if ($new_oop && filter_var($new_oop, FILTER_VALIDATE_URL)) {
            $wpdb->update(RD_TABLE_AUTOSKOLY, [
                'oop_url'       => $new_oop,
                'oop_url_verze' => $new_oop,
            ], ['id' => $as_id]);
            rd_as_oop_log($as_id, $new_oop);
            echo '<div class="notice notice-success"><p>URL obchodních podmínek uložena.</p></div>';
        } else {
            echo '<div class="notice notice-error"><p>Zadejte platnou URL (musí začínat https://).</p></div>';
        }
        $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    }

    if (isset($_POST['rd_save_as_cena']) && check_admin_referer('rd_as_detail_nonce_' . $as_id)) {
        $nova_cena  = max(1, intval($_POST['cena_kus'] ?? 99));
        $stara_cena = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d", $as_id
        ));

        $wpdb->update(RD_TABLE_AUTOSKOLY, ['cena_kus' => $nova_cena], ['id' => $as_id]);
        rd_as_cena_log($as_id, $nova_cena);

        if ($nova_cena !== $stara_cena && $stara_cena > 0) {
            $kmenove_firmy = $wpdb->get_results($wpdb->prepare(
                "SELECT f.id, f.nazev, f.email
                 FROM {$wpdb->prefix}rd_firmy f
                 INNER JOIN " . RD_TABLE_FIRMA_AS . " fa ON fa.firma_id=f.id
                 WHERE fa.autoskola_id=%d AND fa.kmenova=1",
                $as_id
            ));
            $as_info = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
            $from    = get_option('rd_smtp_from', get_option('admin_email'));
            $fname   = get_option('rd_smtp_from_name', get_bloginfo('name'));
            $emaily_odeslano = 0;

            foreach ($kmenove_firmy as $firma) {
                // Najít cenu z poslední zaplacené objednávky firmy u tétoautoškoly
                $nakupni_cena = 0;
                $last_obj = $wpdb->get_results($wpdb->prepare(
                    "SELECT data FROM " . RD_TABLE_OBJ . "
                     WHERE autoskola_id=%d AND firma_email=%s AND stav IN ('zaplaceno','hotovo','prevod_ok')
                     ORDER BY vytvoreno DESC LIMIT 1",
                    $as_id, $firma->email
                ));
                if ($last_obj) {
                    $ld = json_decode($last_obj[0]->data ?? '{}', true);
                    $nakupni_cena = intval($ld['cena'] ?? 0);
                }

                // Pokud firma nikdy neobjednávala, přeskočit
                if (!$nakupni_cena) continue;

                // Určit nový směr vůči nákupní ceně
                if ($nova_cena > $nakupni_cena) {
                    $novy_smer = 'drazsi';
                } elseif ($nova_cena < $nakupni_cena) {
                    $novy_smer = 'levnejsi';
                } else {
                    continue; // Cena stejná jako nákupní – neinformovat
                }

                // Zjistit poslední odeslaný směr
                $posledni = $wpdb->get_row($wpdb->prepare(
                    "SELECT stav FROM {$wpdb->prefix}rd_cena_zmeny
                     WHERE autoskola_id=%d AND firma_id=%d
                     ORDER BY id DESC LIMIT 1",
                    $as_id, $firma->id
                ));
                $posledni_smer = $posledni ? $posledni->stav : null;

                // Poslat jen pokud se směr změnil
                if ($novy_smer === $posledni_smer) continue;

                // Uložit nový záznam
                $wpdb->insert("{$wpdb->prefix}rd_cena_zmeny", [
                    'autoskola_id' => $as_id,
                    'firma_id'     => $firma->id,
                    'stara_cena'   => $nakupni_cena,
                    'nova_cena'    => $nova_cena,
                    'lhuta_do'     => date('Y-m-d', strtotime('+365 days')),
                    'stav'         => $novy_smer,
                ]);

                // Email
                $telo = rd_email_wrap(
                    'Změna ceny školení',
                    '<p>Dobrý den,</p>'
                    . '<p>autoškola <strong>' . esc_html($as_info->nazev) . '</strong> upravila cenu školení.</p>'
                    . ($novy_smer === 'drazsi'
                        ? '<p>Při příštím nákupu kódů zaplatíte <strong>více než při Vašem posledním nákupu</strong>. Aktuální cenu uvidíte v objednávkovém formuláři.</p>'
                        : '<p>Při příštím nákupu kódů zaplatíte <strong>méně než při Vašem posledním nákupu</strong>. Vaše stávající kódy jsou plně funkční.</p>'
                    )
                );
                wp_mail($firma->email, 'Změna ceny školení — ' . $as_info->nazev, $telo, [
                    'Content-Type: text/html; charset=UTF-8',
                    'From: ' . $fname . ' <' . $from . '>',
                ]);
                $emaily_odeslano++;
            }

            $msg = 'Cena změněna z <strong>' . $stara_cena . ' Kč</strong> na <strong>' . $nova_cena . ' Kč</strong>.';
            if ($emaily_odeslano > 0) $msg .= ' Notifikace odeslána ' . $emaily_odeslano . ' firmám.';
            else $msg .= ' Žádná firma nebyla notifikována (cena nepřekročila jejich nákupní cenu).';
            echo '<div class="notice notice-warning"><p>' . $msg . '</p></div>';
        } else {
            echo '<div class="notice notice-success"><p>Cena za kód uložena.</p></div>';
        }
    }

    $as = $wpdb->get_row($wpdb->prepare(
        "SELECT a.*, t.nazev as tier_nazev, t.limit_kodu, t.cena_mesic,
                 p.castka as platba_castka, p.stav as platba_stav, p.vytvoreno as platba_vytvoreno
         FROM " . RD_TABLE_AUTOSKOLY . " a
         LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=a.tier_id
         LEFT JOIN " . RD_TABLE_AS_PLATBY . " p ON p.id = (
             SELECT id FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=a.id ORDER BY id DESC LIMIT 1
         )
         WHERE a.id=%d LIMIT 1", $as_id
    ));
    if (!$as) wp_die('Autoškola nenalezena');

    $pocet_firem    = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_FIRMA_AS . " WHERE autoskola_id=%d AND kmenova=1", $as_id));
    $pocet_kodu     = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d", $as_id));
    $pocet_abs      = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT r.id) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1", $as_id, $as_id));
    $posledni_platba = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='zaplaceno' ORDER BY platnost_do DESC LIMIT 1", $as_id));

    $stav_labels = [
        'ceka_schvaleni'  => ['label'=>'Čeká na schválení',        'color'=>'#d97706'],
        'vyber_balicek'   => ['label'=>'Vybrat balíček',           'color'=>'#7c3aed'],
        'ceka_platbu'     => ['label'=>'Čeká na platbu',           'color'=>'#6b7280'],
        'ceka_potvrzeni'  => ['label'=>'Čeká na potvrzení platby', 'color'=>'#2563eb'],
        'aktivni'         => ['label'=>'Aktivní',                  'color'=>'#16a34a'],
        'pozastaveno'     => ['label'=>'Pozastaveno',              'color'=>'#dc2626'],
        'zablokovano'     => ['label'=>'Zablokováno',              'color'=>'#111827'],
    ];
    $sl = $stav_labels[$as->stav] ?? ['label'=>$as->stav,'color'=>'#666'];
    ?>
    <div class="wrap">
    <h1>
        <?php echo esc_html($as->nazev); ?>
        <span style="font-size:13px;font-weight:400;background:<?php echo $sl['color']; ?>22;color:<?php echo $sl['color']; ?>;border:1px solid <?php echo $sl['color']; ?>44;border-radius:99px;padding:3px 12px;margin-left:10px;vertical-align:middle"><?php echo $sl['label']; ?></span>
    </h1>
    <?php if (!empty($_GET['rd_zprava'])): ?>
    <?php
        $zpr = sanitize_text_field($_GET['rd_zprava']);
        $zpr_map = [
            'platba_ok'  => ['bg'=>'#dcfce7','brd'=>'#86efac','col'=>'#15803d','txt'=>'✓ Platba potvrzena. Potvrzovací email byl odeslán autoškole.'],
            'storno_ok'  => ['bg'=>'#fee2e2','brd'=>'#fca5a5','col'=>'#dc2626','txt'=>'✕ Platba stornována. Email byl odeslán autoškole.'],
            'zmeneno'    => ['bg'=>'#dcfce7','brd'=>'#86efac','col'=>'#15803d','txt'=>'✓ Změna uložena.'],
            'oop_ok'     => ['bg'=>'#dcfce7','brd'=>'#86efac','col'=>'#15803d','txt'=>'✓ OOP souhlas uložen.'],
