    <div style="background:<?php echo $zs['bg']; ?>;border:1px solid <?php echo $zs['brd']; ?>;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:13px;color:<?php echo $zs['col']; ?>;font-weight:600">
        <?php echo $zs['txt']; ?>
