/* ============================================================
   DETAIL FIRMY PRO AUTOSKOLA_ADMIN
   ============================================================ */
function rd_admin_firma_detail($firma_email) {
    global $wpdb;
    $as = rd_je_autoskola_admin() ? rd_get_my_autoskola() : null;
    $as_id = $as ? $as->id : 0;

    // Základní statistiky firmy
    if ($as_id) {
        $celkem     = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d", $firma_email, $as_id));
        $pouzito    = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=1 AND autoskola_id=%d", $firma_email, $as_id));
        $absolventi = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND uspech=1 AND autoskola_id=%d", $firma_email, $as_id));
    } else {
        $celkem     = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s", $firma_email));
        $pouzito    = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=1", $firma_email));
        $absolventi = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND uspech=1", $firma_email));
    }
    $volnych  = $celkem - $pouzito;
    $posledni = $wpdb->get_var($wpdb->prepare("SELECT MAX(vytvoreno) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s", $firma_email));

    // Info o firmě z rd_firmy
    $firma_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rd_firmy WHERE email=%s LIMIT 1", $firma_email));
    // Fallback z kódů
    $firma_nazev = $firma_row ? $firma_row->nazev : $wpdb->get_var($wpdb->prepare("SELECT firma_nazev FROM " . RD_TABLE_KODY . " WHERE firma_email=%s LIMIT 1", $firma_email));

    // Kmenová autoškola
    $fi_slug_base = $as_id ? 'refdrive-firma-' . md5($firma_email) : '';

    // Objednávky firmy
    if ($as_id) {
        $objednavky   = $wpdb->get_results($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE firma_email=%s AND autoskola_id=%d ORDER BY vytvoreno DESC LIMIT 50", $firma_email, $as_id));
        $nejblizsi_exp = $wpdb->get_var($wpdb->prepare("SELECT MIN(expiruje) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL AND expiruje > NOW() AND autoskola_id=%d", $firma_email, $as_id));
        $score_data   = $wpdb->get_row($wpdb->prepare("SELECT AVG(score) as avg_score, MAX(datum_skoleni) as posledni_abs FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND uspech=1 AND autoskola_id=%d", $firma_email, $as_id));
    } else {
        $objednavky   = $wpdb->get_results($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE firma_email=%s ORDER BY vytvoreno DESC LIMIT 50", $firma_email));
        $nejblizsi_exp = $wpdb->get_var($wpdb->prepare("SELECT MIN(expiruje) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL AND expiruje > NOW()", $firma_email));
        $score_data   = $wpdb->get_row($wpdb->prepare("SELECT AVG(score) as avg_score, MAX(datum_skoleni) as posledni_abs FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND uspech=1", $firma_email));
