/* ============================================================
   FUNKCE PRO PER-FIRMA POHLED (autoskola_admin menu)
   ============================================================ */

function rd_admin_firma_get_context() {
    global $wpdb;
    if (!rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as = rd_get_my_autoskola();
    if (!$as) wp_die('Autoškola nenalezena');
    // Zjistit email firmy z page slug: refdrive-firma-{md5}-kody/absolventi/objednavky
    $page = sanitize_key($_GET['page'] ?? '');
    // Najít email firmy z md5 hashe v page slugu
    $firmy = $wpdb->get_results($wpdb->prepare(
        "SELECT DISTINCT firma_nazev, firma_email FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d",
        $as->id
    ));
    foreach ($firmy as $fi) {
        $slug_base = 'refdrive-firma-' . md5($fi->firma_email);
        if (strpos($page, $slug_base) === 0) {
            return ['as' => $as, 'firma' => $fi];
        }
    }
    wp_die('Firma nenalezena');
}

function rd_admin_firma_kody() {
    global $wpdb;
    $ctx = rd_admin_firma_get_context();
    $as  = $ctx['as'];
    $fi  = $ctx['firma'];
    $kody = $wpdb->get_results($wpdb->prepare(
        "SELECT k.*, r.score as ridic_score, r.uspech as ridic_uspech, r.datum_skoleni as ridic_datum FROM " . RD_TABLE_KODY . " k
         LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1)
         WHERE k.autoskola_id=%d AND k.firma_email=%s ORDER BY k.vytvoreno DESC LIMIT 500",
        $as->id, $fi->firma_email
    ));
    $celkem_fi  = count($kody);
    $pouzito_fi = count(array_filter((array)$kody, fn($k) => $k->pouzit));
    $volnych_fi = $celkem_fi - $pouzito_fi;
    $absol_fi   = (int)$wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND autoskola_id=%d AND uspech=1",
        $fi->firma_email, $as->id
    ));
    $filtr_stat = sanitize_key($_GET['filtr_stat'] ?? '');
    $hledat     = sanitize_text_field($_GET['hledat'] ?? '');
    $page_slug  = sanitize_key($_GET['page'] ?? '');
    $base_url   = admin_url('admin.php?page=' . $page_slug);

    // Filtrovat kódy
    if ($filtr_stat === 'pouzite')    $kody = array_values(array_filter((array)$kody, fn($k) => $k->pouzit));
    if ($filtr_stat === 'nepouzite')  $kody = array_values(array_filter((array)$kody, fn($k) => !$k->pouzit));
    if ($filtr_stat === 'absolventi') $kody = array_values(array_filter((array)$kody, fn($k) => $k->ridic_uspech));
    if ($hledat) $kody = array_values(array_filter((array)$kody, fn($k) => stripos($k->kod,$hledat)!==false || stripos($k->ridic_jmeno??'',$hledat)!==false));
    ?>
    <div class="wrap">
    <h1><?php echo esc_html($fi->firma_nazev); ?> — Kódy</h1>
    <div style="max-width:900px">
    <p><a href="<?php echo admin_url('admin.php?page=refdrive'); ?>" class="rd-back-btn">← Přehled firem</a></p>

    <div style="display:flex;gap:20px;flex-wrap:wrap;padding:10px 14px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:12px;font-size:13px">
        <a href="<?php echo $base_url; ?>" style="text-decoration:none;color:<?php echo !$filtr_stat?'#111827':'#6b7280';?>;font-weight:<?php echo !$filtr_stat?'700':'400';?>">
            Celkem: <strong><?php echo $celkem_fi;?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url.'&filtr_stat=pouzite';?>" style="text-decoration:none;color:<?php echo $filtr_stat==='pouzite'?'#7c3aed':'#6b7280';?>;font-weight:<?php echo $filtr_stat==='pouzite'?'700':'400';?>">
            Použito: <strong><?php echo $pouzito_fi;?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url.'&filtr_stat=nepouzite';?>" style="text-decoration:none;color:<?php echo $filtr_stat==='nepouzite'?'#374151':'#6b7280';?>;font-weight:<?php echo $filtr_stat==='nepouzite'?'700':'400';?>">
            Nepřiřazeno: <strong><?php echo $volnych_fi;?></strong>
        </a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base_url.'&filtr_stat=absolventi';?>" style="text-decoration:none;color:<?php echo $filtr_stat==='absolventi'?'#16a34a':'#6b7280';?>;font-weight:<?php echo $filtr_stat==='absolventi'?'700':'400';?>">
            Absolventů: <strong><?php echo $absol_fi;?></strong>
        </a>
    </div>

    <form method="get" style="display:flex;gap:8px;margin:12px 0">
        <input type="hidden" name="page" value="<?php echo esc_attr($page_slug);?>">
        <?php if($filtr_stat):?><input type="hidden" name="filtr_stat" value="<?php echo esc_attr($filtr_stat);?>"><?php endif;?>
        <input type="text" name="hledat" value="<?php echo esc_attr($hledat);?>" placeholder="Hledat kód nebo jméno..." style="flex:1;min-width:0">
        <button type="submit" class="rd-btn-detail" style="padding:5px 14px;font-size:13px;flex-shrink:0">Hledat</button>
        <?php if($hledat||$filtr_stat):?><a href="<?php echo $base_url;?>" class="rd-btn-detail" style="padding:5px 10px;font-size:13px;flex-shrink:0">×</a><?php endif;?>
    </form>

    <?php echo rd_admin_firma_karty($kody); ?>
    </div><!-- /max-width:900px master wrapper -->
    </div><?php
}

function rd_admin_firma_absolventi() {
    global $wpdb;
    $ctx = rd_admin_firma_get_context();
    $as  = $ctx['as'];
    $fi  = $ctx['firma'];
