    // Pokrýt i staré kódy kde autoskola_id může být NULL
    $ridici = $wpdb->get_results($wpdb->prepare(
        "SELECT DISTINCT r.* FROM " . RD_TABLE_RIDICI . " r
         INNER JOIN " . RD_TABLE_KODY . " k ON k.kod = r.kod
         WHERE (k.autoskola_id=%d OR k.autoskola_id IS NULL)
         AND k.firma_email=%s AND r.uspech=1
         ORDER BY r.datum_skoleni DESC LIMIT 500",
        $as->id, $fi->firma_email
    ));
