    </div><!-- /max-width:900px master wrapper -->
    </div><?php
}

// Helper - kartový render kódů
function rd_admin_firma_karty($kody, $filtr_stav = '') {
    if (empty($kody)) return '<p style="color:#6b7280;margin-top:12px">Žádné kódy.</p>';
    $bs = 'display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700;white-space:nowrap;';
    ob_start();

    // Připrav data pro každý kód
    $rows = [];
    foreach ($kody as $k) {
        $score_val  = $k->ridic_score ?? $k->score ?? null;
        $uspech_val = (string)($k->ridic_uspech ?? $k->uspech ?? '');
        $expiry_warn = '';
        if ($k->pouzit && $uspech_val === '1') {
            $badge = '<span style="' . $bs . 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0">✓ Splněno</span>';
            $badge_txt = '✓ Splněno'; $badge_c = '#15803d'; $badge_bg = '#dcfce7';
        } elseif ($k->pouzit) {
            $badge = '<span style="' . $bs . 'background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe">▶ Probíhá</span>';
            $badge_txt = '▶ Probíhá'; $badge_c = '#1d4ed8'; $badge_bg = '#dbeafe';
        } elseif ($k->ridic_jmeno) {
            $badge = '<span style="' . $bs . 'background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe">▶ Probíhá</span>';
            $badge_txt = '▶ Probíhá'; $badge_c = '#1d4ed8'; $badge_bg = '#dbeafe';
        } else {
            $badge = '<span style="' . $bs . 'background:#fef3c7;color:#92400e;border:1px solid #fde68a">○ Volný</span>';
            $badge_txt = '○ Volný'; $badge_c = '#92400e'; $badge_bg = '#fef3c7';
        }
        if ($k->expiruje && !$k->pouzit) {
            $dni = (int)round((strtotime($k->expiruje) - time()) / 86400);
            if ($dni < 0) { $badge = '<span style="' . $bs . 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca">✕ Expiroval</span>'; $badge_txt = '✕ Expiroval'; $badge_c = '#b91c1c'; $badge_bg = '#fee2e2'; $expiry_warn = '#dc2626'; }
            elseif ($dni <= 30) { $expiry_warn = '#d97706'; }
        }
        $kurz_url = $k->token ? home_url('/kurz/?token=' . $k->token . '&rd_admin_preview=1') : '';
        $rows[] = compact('k','badge','badge_txt','badge_c','badge_bg','score_val','expiry_warn','kurz_url');
    }

    // Filtrování
    if ($filtr_stav === 'pouzito') {
        $rows = array_filter($rows, function($r) { return $r['k']->pouzit && $r['badge_txt'] !== '✕ Expiroval'; });
    } elseif ($filtr_stav === 'volnych') {
        $rows = array_filter($rows, function($r) { return !$r['k']->pouzit && $r['badge_txt'] !== '✕ Expiroval'; });
    } elseif ($filtr_stav === 'absolventi') {
        $rows = array_filter($rows, function($r) { return $r['badge_txt'] === '✓ Splněno'; });
    }
    $rows = array_values($rows);
    ?>
    <!-- Desktop tabulka -->
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px;margin-top:8px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Kód</th>
            <th onclick="rdSortTable(this)">Stav</th>
            <th onclick="rdSortTable(this)">Řidič</th>
            <th onclick="rdSortTable(this)">Score</th>
            <th onclick="rdSortTable(this)">Datum</th>
            <th onclick="rdSortTable(this)">Expiruje</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach ($rows as $row):
            $k = $row['k']; ?>
        <tr>
            <td><code style="font-size:12px;font-weight:700;letter-spacing:.5px"><?php echo esc_html($k->kod); ?></code><div style="font-size:10px;color:#9ca3af"><?php echo date('d.m.Y H:i', strtotime($k->vytvoreno)); ?></div></td>
            <td><?php echo $row['badge']; ?></td>
            <td style="font-size:12px"><?php echo $k->ridic_jmeno ? esc_html($k->ridic_jmeno) : '<span style="color:#9ca3af">—</span>'; ?></td>
            <td style="font-weight:700;color:<?php echo $row['score_val'] !== null ? ($row['score_val'] >= 80 ? '#16a34a' : '#dc2626') : '#9ca3af'; ?>"><?php echo $row['score_val'] !== null ? $row['score_val'] . '%' : '—'; ?></td>
            <td style="font-size:12px;color:#6b7280"><?php echo $k->datum_pouziti ? date('d.m.Y H:i', strtotime($k->datum_pouziti)) : '—'; ?></td>
            <td style="font-size:12px;color:<?php echo $row['expiry_warn'] ?: '#6b7280'; ?>"><?php echo ($k->expiruje && !$k->pouzit) ? date('d.m.Y', strtotime($k->expiruje)) : '—'; ?></td>
            <td><?php if ($row['kurz_url']): ?><a href="<?php echo esc_url($row['kurz_url']); ?>" target="_blank" style="font-size:11px;color:#2563eb;text-decoration:none">🔗 Kurz</a><?php endif; ?></td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>
    <!-- Mobilní karty -->
    <div class="rd-show-mobile" style="display:none;margin-top:8px">
    <?php foreach ($rows as $row): $k = $row['k']; ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
            <code style="font-size:13px;font-weight:700;letter-spacing:.5px;color:#111827"><?php echo esc_html($k->kod); ?></code>
            <span style="font-size:11px;font-weight:700;color:<?php echo $row['badge_c']; ?>;background:<?php echo $row['badge_bg']; ?>;padding:3px 10px;border-radius:99px"><?php echo $row['badge_txt']; ?></span>
        </div>
        <div style="font-size:12px;display:flex;flex-direction:column;gap:4px">
            <?php if ($k->ridic_jmeno): ?><div><span style="color:#6b7280">Řidič:</span> <?php echo esc_html($k->ridic_jmeno); ?></div><?php endif; ?>
            <?php if ($row['score_val'] !== null): ?><div><span style="color:#6b7280">Score:</span> <strong style="color:<?php echo $row['score_val'] >= 80 ? '#16a34a' : '#dc2626'; ?>"><?php echo $row['score_val']; ?>%</strong></div><?php endif; ?>
            <?php if ($k->datum_pouziti): ?><div><span style="color:#6b7280">Datum:</span> <?php echo date('d.m.Y H:i', strtotime($k->datum_pouziti)); ?></div><?php endif; ?>
            <?php if ($k->expiruje && !$k->pouzit): ?><div><span style="color:#6b7280">Expiruje:</span> <span style="color:<?php echo $row['expiry_warn'] ?: '#6b7280'; ?>"><?php echo date('d.m.Y', strtotime($k->expiruje)); ?></span></div><?php endif; ?>
        </div>
        <?php if ($row['kurz_url']): ?><div style="margin-top:8px"><a href="<?php echo esc_url($row['kurz_url']); ?>" target="_blank" style="font-size:11px;color:#2563eb;text-decoration:none">🔗 Otevřít kurz</a></div><?php endif; ?>
    </div>
    <?php endforeach; ?>
    </div>
    <p style="color:#666;font-size:12px;margin-top:8px">Zobrazeno: <?php echo count($kody); ?> kódů</p>
    <?php
    return ob_get_clean();
}
