/* ============================================================
   FIRMY KONKRÉTNÍ AUTOŠKOLY (pro hlavního admina - podstrom AS)
   ============================================================ */
function rd_admin_as_firmy_superadmin() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    $as_id = rd_admin_get_as_id_from_page();
    if (!$as_id) wp_die('Autoškola nenalezena');

    $as = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    if (!$as) wp_die('Autoškola nenalezena');

    // Pokud je vybrána konkrétní firma, zobrazit její detail
    $firma_email = sanitize_email($_GET['firma'] ?? '');
    if ($firma_email) {
        // Nastavit kontext - jako by byl as_id z URL pro rd_admin_firma_detail
        // Předáme $as_id přes globální proměnnou dočasně
        add_filter('rd_firma_detail_as_id', function() use ($as_id) { return $as_id; });
        rd_admin_firma_detail_for_admin($firma_email, $as_id);
        return;
    }

    // Seznam firem autoškoly
    $firmy = $wpdb->get_results($wpdb->prepare(
        "SELECT firma_nazev, firma_email,
                COUNT(*) as celkem, SUM(pouzit) as pouzito,
                COUNT(*)-SUM(pouzit) as volnych, MAX(vytvoreno) as posledni
         FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d
         GROUP BY firma_nazev, firma_email ORDER BY posledni DESC",
        $as_id
    ));
    $base_url = admin_url('admin.php?page=refdrive-as-' . $as_id . '-firmy');
    ?>
    <div class="wrap">
    <h1><?php echo esc_html($as->nazev); ?> — Firmy</h1>
    <div style="max-width:900px">
    <a href="<?php echo admin_url('admin.php?page=refdrive-as-' . $as_id); ?>" class="rd-back-btn" style="margin-bottom:12px;display:inline-block">← Zpět na detail</a>
    <style>
    .rd-t{width:100%;border-collapse:collapse;font-size:13px;margin-top:12px}
    .rd-t th{background:#f9fafb;padding:9px 12px;text-align:left;font-weight:600;font-size:12px;color:#374151;border-bottom:2px solid #e5e7eb;white-space:nowrap}
    .rd-t td{padding:10px 12px;border-bottom:1px solid #f3f4f6;vertical-align:middle}
    .rd-t tr:hover td{background:#fafafa}
    .rd-t tr{cursor:pointer}
    @media(max-width:700px){
      .rd-t thead{display:none}
      .rd-t tr{display:block;margin-bottom:10px;background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:4px 0;cursor:auto}
      .rd-t td{display:flex;justify-content:space-between;align-items:center;padding:6px 14px;border-bottom:1px solid #f9fafb;font-size:13px}
      .rd-t td:last-child{border-bottom:none}
      .rd-t td::before{content:attr(data-label);font-weight:600;color:#6b7280;font-size:12px;margin-right:8px;flex-shrink:0;min-width:80px}
      .rd-t td:first-child{flex-direction:column;align-items:flex-start}
      .rd-t td:first-child::before{margin-bottom:2px}
      .rd-firm-bar{display:none}
    }
    </style>
    <?php if (empty($firmy)): ?>
    <p style="color:#999;padding:16px 0">Žádné firmy.</p>
    <?php else: ?>
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Firma</th>
            <th onclick="rdSortTable(this)" style="text-align:center">Celkem</th>
            <th onclick="rdSortTable(this)" style="text-align:center">Použito</th>
            <th onclick="rdSortTable(this)" style="text-align:center">Volných</th>
            <th onclick="rdSortTable(this)">Využití</th>
            <th onclick="rdSortTable(this)">Poslední obj.</th>
        </tr></thead>
        <tbody>
        <?php foreach ($firmy as $f):
            $pct = $f->celkem > 0 ? round($f->pouzito / $f->celkem * 100) : 0;
