            <td style="text-align:center;color:#7c3aed;font-weight:700" data-val="<?php echo intval($f->pouzito); ?>"><?php echo intval($f->pouzito); ?></td>
            <td style="text-align:center;color:#6b7280;font-weight:700" data-val="<?php echo intval($f->volnych); ?>"><?php echo intval($f->volnych); ?></td>
            <td>
                <div style="display:flex;align-items:center;gap:8px">
                    <div style="width:80px;background:#f3f4f6;border-radius:99px;height:5px;overflow:hidden">
                        <div style="height:100%;width:<?php echo $pct; ?>%;background:<?php echo $pct>=90?'#16a34a':($pct>=70?'#d97706':'#7c3aed'); ?>;border-radius:99px"></div>
                    </div>
                    <span style="font-size:11px;color:#6b7280"><?php echo $pct; ?> %</span>
