        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
            <div>
                <a href="<?php echo esc_url($detail_url); ?>" style="font-weight:700;color:#111827;text-decoration:none;font-size:14px"><?php echo esc_html($f->firma_nazev); ?></a>
                <div style="font-size:11px;color:#9ca3af"><?php echo esc_html($f->firma_email); ?></div>
            </div>
            <span style="font-size:11px;color:#6b7280;white-space:nowrap"><?php echo date('d.m.Y', strtotime($f->posledni)); ?></span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;text-align:center;font-size:12px;margin-bottom:10px">
            <div><div style="font-weight:700;font-size:16px"><?php echo intval($f->celkem); ?></div><div style="color:#6b7280">celkem</div></div>
            <div><div style="font-weight:700;font-size:16px;color:#7c3aed"><?php echo intval($f->pouzito); ?></div><div style="color:#6b7280">použito</div></div>
            <div><div style="font-weight:700;font-size:16px;color:#6b7280"><?php echo intval($f->volnych); ?></div><div style="color:#6b7280">volných</div></div>
