// Detail firmy v kontextu konkrétní autoškoly (pro hlavního admina)
function rd_admin_firma_detail_for_admin($firma_email, $as_id) {
    global $wpdb;
    $as = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    $back_url = admin_url('admin.php?page=refdrive-as-' . $as_id . '-firmy');

    $celkem     = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d", $firma_email, $as_id));
    $pouzito    = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=1 AND autoskola_id=%d", $firma_email, $as_id));
    $volnych    = $celkem - $pouzito;
    $absolventi = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND autoskola_id=%d AND uspech=1", $firma_email, $as_id));
    $posledni   = $wpdb->get_var($wpdb->prepare("SELECT MAX(vytvoreno) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d", $firma_email, $as_id));
    $firma_row  = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rd_firmy WHERE email=%s LIMIT 1", $firma_email));
    $firma_nazev = $firma_row ? $firma_row->nazev : $wpdb->get_var($wpdb->prepare("SELECT firma_nazev FROM " . RD_TABLE_KODY . " WHERE firma_email=%s LIMIT 1", $firma_email));

    $kody = $wpdb->get_results($wpdb->prepare(
        "SELECT k.*, r.score as ridic_score, r.uspech as ridic_uspech, r.datum_skoleni as ridic_datum FROM " . RD_TABLE_KODY . " k
         LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1)
         WHERE k.autoskola_id=%d AND k.firma_email=%s ORDER BY k.vytvoreno DESC LIMIT 500",
        $as_id, $firma_email
    ));
    ?>
    <div class="wrap">
    <h1 style="display:flex;align-items:center;gap:10px">
        <?php echo esc_html($firma_nazev); ?>
        <span style="font-size:12px;font-weight:400;color:#6b7280"><?php echo esc_html($firma_email); ?></span>
    </h1>
    <p><a href="<?php echo esc_url($back_url); ?>" class="rd-back-btn">← <?php echo esc_html($as->nazev); ?> — Firmy</a></p>

    <!-- Stats – klikatelné filtry -->
    <?php $filtr_stav = sanitize_key($_GET['filtr_stav'] ?? ''); ?>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px;margin:16px 0">
    <?php foreach ([
        ['vse',       'Kódů celkem', $celkem],
        ['pouzito',   'Použito',     $pouzito],
        ['volnych',   'Volných',     $volnych],
        ['absolventi','Absolventů',  $absolventi],
    ] as [$key,$label,$val]):
        $active = ($filtr_stav === $key || ($key === 'vse' && $filtr_stav === ''));
        $url = add_query_arg('filtr_stav', $key === 'vse' ? '' : $key);
    ?>
    <a href="<?php echo esc_url($url); ?>" style="text-decoration:none">
        <div style="background:#fff;border:1px solid <?php echo $active ? '#7c3aed' : '#e5e7eb'; ?>;border-radius:8px;padding:12px 10px;text-align:center<?php echo $active ? ';box-shadow:0 0 0 1px #7c3aed' : ''; ?>">
            <div style="font-size:22px;font-weight:700;color:<?php echo $active ? '#7c3aed' : '#111827'; ?>;line-height:1.2"><?php echo number_format($val); ?></div>
            <div style="font-size:12px;color:#6b7280;margin-top:2px"><?php echo $label; ?></div>
        </div>
    </a>
    <?php endforeach; ?>
    </div>

    <!-- Kontakt -->
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:16px 20px;margin-bottom:16px">
        <h2 style="font-size:14px;font-weight:700;margin:0 0 12px;padding-bottom:8px;border-bottom:1px solid #f3f4f6">Kontakt a fakturace</h2>
        <table style="font-size:13px;width:100%;border-collapse:collapse">
            <tr><td style="padding:5px 0;color:#6b7280;width:160px">Email</td><td><a href="mailto:<?php echo esc_attr($firma_email); ?>" style="color:#2563eb"><?php echo esc_html($firma_email); ?></a></td></tr>
            <?php if ($firma_row && $firma_row->telefon): ?><tr><td style="padding:5px 0;color:#6b7280">Telefon</td><td><a href="tel:<?php echo esc_attr($firma_row->telefon); ?>" style="color:#2563eb"><?php echo esc_html($firma_row->telefon); ?></a></td></tr><?php endif; ?>
            <?php if ($firma_row && $firma_row->ico): ?><tr><td style="padding:5px 0;color:#6b7280">IČ</td><td><strong><?php echo esc_html($firma_row->ico); ?></strong></td></tr><?php endif; ?>
            <?php if ($firma_row && $firma_row->ulice): ?><tr><td style="padding:5px 0;color:#6b7280">Adresa</td><td><?php echo esc_html(trim($firma_row->ulice . ', ' . $firma_row->psc . ' ' . $firma_row->mesto, ', ')); ?></td></tr><?php endif; ?>
            <?php if ($posledni): ?><tr><td style="padding:5px 0;color:#6b7280">Poslední kódy</td><td><?php echo date('d.m.Y', strtotime($posledni)); ?></td></tr><?php endif; ?>
        </table>
    </div>
    <!-- Kódy -->
    <?php echo rd_admin_firma_karty($kody, $filtr_stav); ?>
    </div><!-- /max-width:900px -->
    </div><!-- .wrap -->
    <?php
}


