/* ================================================================
   AUTOSKOLA_ADMIN – FIRMY A KÓDY
   ================================================================ */
function rd_admin_as_nastaveni() {
    global $wpdb;
    if (!rd_je_autoskola_admin() && !current_user_can('manage_options')) wp_die('Přístup odepřen');
    $as = rd_je_autoskola_admin() ? rd_get_my_autoskola() : $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", intval($_GET['as_id'] ?? 0)));
    if (!$as) { echo '<div class="wrap"><p>Autoškola nenalezena.</p></div>'; return; }

    $nonce_key = 'rd_as_nastaveni_' . $as->id;

    // Uložit cenu za kód
    if (isset($_POST['rd_as_save_cena']) && check_admin_referer('rd_as_cena_nonce_' . $as->id)) {
        $nova_cena = max(1, intval($_POST['cena_kus'] ?? 99));
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['cena_kus' => $nova_cena], ['id' => $as->id]);
        rd_as_cena_log($as->id, $nova_cena);
        $as = rd_get_my_autoskola();
        echo '<div class="notice notice-success"><p>✓ Cena za kód uložena: <strong>' . intval($nova_cena) . ' Kč</strong>.</p></div>';
    }

    // Žádost o změnu registračních údajů
    if (isset($_POST['rd_zadost_zmenu']) && check_admin_referer($nonce_key)) {
        $pole_schvaleni = RD_POLE_SCHVALENI;
        $zmeneno = 0;
        $jiz_ceka = [];
        foreach ($pole_schvaleni as $pole => $label) {
            if (!isset($_POST[$pole])) continue;
            $nova = $pole === 'email' ? sanitize_email($_POST[$pole]) : sanitize_text_field($_POST[$pole]);
            if (empty($nova)) continue;
            $stara = $as->$pole ?? '';
            if ($nova === $stara) continue;
            // Zkontrolovat zda už nečeká žádost pro toto pole
            $ceka = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_ZMENY . " WHERE autoskola_id=%d AND pole=%s AND stav='ceka'", $as->id, $pole));
            if ($ceka) {
                $jiz_ceka[] = $label;
                continue;
            }
            if (rd_podat_zadost_o_zmenu($as->id, $pole, $nova)) {
                $zmeneno++;
            }
        }
        if ($zmeneno > 0) {
            echo '<div class="notice notice-success is-dismissible"><p>✓ Žádost o změnu odeslána. Změna bude aktivní po schválení správcem.</p></div>';
        }
        if (!empty($jiz_ceka)) {
            echo '<div class="notice notice-warning is-dismissible"><p>⚠ Pro tato pole již čeká žádost o schválení: <strong>' . esc_html(implode(', ', $jiz_ceka)) . '</strong></p></div>';
        }
        if ($zmeneno === 0 && empty($jiz_ceka)) {
            echo '<div class="notice notice-info is-dismissible"><p>Žádné změny nebyly detekovány.</p></div>';
        }
        $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as->id));
    }

    // Změna hesla
    if (isset($_POST['rd_zmena_hesla']) && check_admin_referer($nonce_key)) {
        $stare  = $_POST['heslo_stare'] ?? '';
        $nove   = $_POST['heslo_nove'] ?? '';
        $nove2  = $_POST['heslo_nove2'] ?? '';
        $wp_user = wp_get_current_user();
        if (!wp_check_password($stare, $wp_user->user_pass, $wp_user->ID)) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Současné heslo je nesprávné.</p></div>';
        } elseif (strlen($nove) < 8) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nové heslo musí mít alespoň 8 znaků.</p></div>';
        } elseif ($nove !== $nove2) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nová hesla se neshodují.</p></div>';
        } else {
            wp_set_password($nove, $wp_user->ID);
            // Znovu přihlásit aby session zůstala platná
            wp_set_auth_cookie($wp_user->ID, true);
            echo '<div class="notice notice-success is-dismissible"><p>✓ Heslo bylo úspěšně změněno.</p></div>';
        }
    }

    // Reset hesla emailem
    if (isset($_POST['rd_reset_hesla']) && check_admin_referer($nonce_key)) {
        $wp_user = wp_get_current_user();
        $reset_key = get_password_reset_key($wp_user);
        if (!is_wp_error($reset_key)) {
            $reset_url = network_site_url("wp-login.php?action=rp&key=$reset_key&login=" . rawurlencode($wp_user->user_login), 'login');
            rd_email_autoskola($as->email,
                'RefDrive: Reset hesla',
                rd_email_wrap('Reset hesla',
                    '<p>Byl odeslán odkaz pro reset hesla pro váš účet na RefDrive.</p>'
                    . '<p>Odkaz je platný 24 hodin.</p>'
                    . rd_email_btn('Nastavit nové heslo →', $reset_url)
                    . '<p style="font-size:13px;color:#6b7280">Pokud jste o reset nepožádali, tento email ignorujte.</p>'
                )
            );
            echo '<div class="notice notice-success is-dismissible"><p>✓ Odkaz pro reset hesla byl odeslán na <strong>' . esc_html($as->email) . '</strong>.</p></div>';
        } else {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nepodařilo se vygenerovat odkaz pro reset. Zkuste to prosím znovu.</p></div>';
        }
    }

    // Uložit platební údaje (převod)
    if (isset($_POST['rd_save_platebni_as']) && check_admin_referer($nonce_key)) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, [
            'cislo_uctu'   => sanitize_text_field($_POST['cislo_uctu'] ?? ''),
            'iban'         => sanitize_text_field($_POST['iban'] ?? ''),
            'bic'          => sanitize_text_field($_POST['bic'] ?? ''),
            'banka'        => sanitize_text_field($_POST['banka'] ?? ''),
            'faktura_pozn' => sanitize_textarea_field($_POST['faktura_pozn'] ?? ''),
        ], ['id' => $as->id]);
        // Po uložení přesměrovat na dashboard (krok 2)
        wp_redirect(add_query_arg(['page' => 'refdrive', 'rd_saved' => '1'], admin_url('admin.php')));
        exit;
    }

    // Uložit Stripe
    if (isset($_POST['rd_save_as_stripe']) && check_admin_referer($nonce_key)) {
        $stripe_pk      = sanitize_text_field($_POST['stripe_pk'] ?? '');
        $stripe_sk      = sanitize_text_field($_POST['stripe_sk'] ?? '');
        $stripe_aktivni = isset($_POST['stripe_aktivni']) ? 1 : 0;
        $old = $wpdb->get_row($wpdb->prepare("SELECT stripe_pk, stripe_sk, stripe_overeno FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d", $as->id));
        $overeno = $old->stripe_overeno ?? 0;
        if (!$stripe_aktivni || $stripe_pk !== $old->stripe_pk || $stripe_sk !== $old->stripe_sk) $overeno = 0;
        $wpdb->update(RD_TABLE_AUTOSKOLY, [
            'stripe_pk'      => $stripe_pk,
            'stripe_sk'      => $stripe_sk,
            'stripe_aktivni' => $stripe_aktivni,
            'stripe_overeno' => $overeno,
        ], ['id' => $as->id]);
        $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as->id));
        echo '<div class="notice notice-success is-dismissible"><p>✓ Stripe nastavení uloženo.</p></div>';
    }

    // Ověřit Stripe
    if (isset($_POST['rd_verify_as_stripe']) && check_admin_referer($nonce_key)) {
        $as_tmp = $wpdb->get_row($wpdb->prepare("SELECT stripe_sk FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d", $as->id));
        $overeno = 0;
        if (!empty($as_tmp->stripe_sk)) {
            $response = wp_remote_get('https://api.stripe.com/v1/balance', [
                'headers' => ['Authorization' => 'Bearer ' . $as_tmp->stripe_sk],
                'timeout' => 10,
            ]);
            if (!is_wp_error($response) && wp_remote_retrieve_response_code($response) === 200) {
                $overeno = 1;
                echo '<div class="notice notice-success is-dismissible"><p>✓ Stripe klíče jsou platné a funkční.</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>✗ Stripe ověření selhalo — zkontrolujte Secret Key.</p></div>';
            }
            $wpdb->update(RD_TABLE_AUTOSKOLY, ['stripe_overeno' => $overeno], ['id' => $as->id]);
            $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as->id));
        } else {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nejprve uložte Stripe Secret Key.</p></div>';
        }
    }
