function rd_admin_as_heslo() {
    global $wpdb;
    if (!rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as = rd_get_my_autoskola();
    if (!$as) { echo '<div class="wrap"><p>Autoškola nenalezena.</p></div>'; return; }

    $nonce_key = 'rd_as_heslo_' . $as->id;

    // Změna hesla
    if (isset($_POST['rd_zmena_hesla']) && check_admin_referer($nonce_key)) {
        $stare  = $_POST['heslo_stare'] ?? '';
        $nove   = $_POST['heslo_nove'] ?? '';
        $nove2  = $_POST['heslo_nove2'] ?? '';
        $wp_user = wp_get_current_user();
        if (!wp_check_password($stare, $wp_user->user_pass, $wp_user->ID)) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Současné heslo je nesprávné.</p></div>';
        } elseif (strlen($nove) < 8) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nové heslo musí mít alespoň 8 znaků.</p></div>';
        } elseif ($nove !== $nove2) {
            echo '<div class="notice notice-error is-dismissible"><p>✗ Nová hesla se neshodují.</p></div>';
        } else {
            wp_set_password($nove, $wp_user->ID);
            wp_set_auth_cookie($wp_user->ID, true);
            echo '<div class="notice notice-success is-dismissible"><p>✓ Heslo bylo úspěšně změněno.</p></div>';
        }
    }

    // Reset hesla - odstraněno, dává smysl jen na přihlašovací stránce
    ?>
    <div class="wrap">
    <h1>Změna hesla — <?php echo esc_html($as->nazev); ?></h1>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:24px;margin-top:16px;max-width:500px">
        <h2 style="font-size:15px;margin-top:0;margin-bottom:4px">Nové heslo</h2>
        <p style="color:#6b7280;font-size:13px;margin-bottom:16px">Minimální délka hesla je 8 znaků.</p>
        <form method="post">
            <?php wp_nonce_field($nonce_key); ?>
            <table class="form-table" style="margin:0 0 16px">
                <tr><th style="width:200px">Současné heslo</th><td><input type="password" name="heslo_stare" class="regular-text" autocomplete="current-password"></td></tr>
                <tr><th>Nové heslo</th><td><input type="password" name="heslo_nove" class="regular-text" autocomplete="new-password"></td></tr>
                <tr><th>Nové heslo znovu</th><td><input type="password" name="heslo_nove2" class="regular-text" autocomplete="new-password"></td></tr>
            </table>
            <input type="submit" name="rd_zmena_hesla" class="rd-btn-detail" style="font-size:13px;padding:7px 16px" value="Změnit heslo">
        </form>
    </div>
    </div>
    <?php
}

function rd_admin_as_firmy() {
    global $wpdb;
    if (!rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as = rd_get_my_autoskola();
    if (!$as) { echo '<div class="wrap"><p>Autoškola nenalezena.</p></div>'; return; }
    $id = $as->id;

    // Smazat firmu včetně kódů a absolventů
    if (isset($_GET['rd_smazat_firmu']) && isset($_GET['_wpnonce'])) {
        $del_email = sanitize_email($_GET['rd_smazat_firmu']);
        if (wp_verify_nonce($_GET['_wpnonce'], 'rd_smazat_firmu_' . md5($del_email . $id))) {
            // Smazat řidiče (absolventy) přes JOIN
            $kody_ids = $wpdb->get_col($wpdb->prepare(
                "SELECT kod FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d",
                $del_email, $id
            ));
            if ($kody_ids) {
                $placeholders = implode(',', array_fill(0, count($kody_ids), '%s'));
                $wpdb->query(vsprintf(
                    "DELETE FROM " . RD_TABLE_RIDICI . " WHERE kod IN ($placeholders)",
                    array_map('esc_sql', $kody_ids)
                ));
            }
            // Smazat kódy
            $wpdb->query($wpdb->prepare(
                "DELETE FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d",
                $del_email, $id
            ));
            // Smazat objednávky
            $wpdb->query($wpdb->prepare(
                "DELETE FROM " . RD_TABLE_OBJ . " WHERE firma_email=%s AND autoskola_id=%d",
                $del_email, $id
            ));
            echo '<div class="notice notice-success"><p>Firma a všechna její data (kódy, absolventi, certifikáty) byla trvale smazána.</p></div>';
        }
    }

    // Detail firmy?
    $firma_email = isset($_GET['firma']) ? sanitize_email($_GET['firma']) : '';
    if ($firma_email) {
        rd_admin_kody_detail_as($firma_email, $id);
        return;
    }

    $filtr_stat = sanitize_key($_GET['filtr_stat'] ?? '');
    $hledat     = sanitize_text_field($_GET['hledat'] ?? '');
    $base       = admin_url('admin.php?page=refdrive-prehled');

    $celkem_k   = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d", $id));
    $pouzito_k  = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d AND pouzit=1", $id));
    $absolventi = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT r.id) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1", $id, $id));
    $firem      = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT firma_email) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d AND firma_email!=''", $id));

    // Kapacita — stack balíčků
    $aktivni_platby = rd_autoskola_aktivni_platby($id);
    $celkem_zbyvaji = rd_autoskola_zbyvajici_kapacita($id);

    // Poslední objednávky
    $ceka_prev  = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_OBJ . " WHERE autoskola_id=%d AND stav='prevod_ceka'", $id));
    $ceka_balicek = $wpdb->get_row($wpdb->prepare(
        "SELECT p.*, t.nazev as tier_nazev FROM " . RD_TABLE_AS_PLATBY . " p LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id WHERE p.autoskola_id=%d AND p.stav='ceka_potvrzeni' ORDER BY p.id DESC LIMIT 1",
        $id
    ));
    $posledni   = $wpdb->get_results($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE autoskola_id=%d ORDER BY vytvoreno DESC LIMIT 50", $id));
    $stav_l = ['ceka'=>'Čeká','zaplaceno'=>'Zaplaceno','hotovo'=>'Hotovo','prevod_ceka'=>'Čeká na platbu','prevod_ok'=>'Zaplaceno','storno'=>'Storno'];
    $stav_c = ['ceka'=>'#d97706','zaplaceno'=>'#16a34a','hotovo'=>'#16a34a','prevod_ceka'=>'#d97706','prevod_ok'=>'#16a34a','storno'=>'#dc2626'];

    $w_base = $wpdb->prepare("WHERE k.autoskola_id=%d", $id);
    if ($hledat) $w_base .= $wpdb->prepare(" AND (k.firma_nazev LIKE %s OR k.firma_email LIKE %s)", "%$hledat%", "%$hledat%");

    // Agregáty se VŽDY počítají ze všech kódů firmy (bez filtru stavu),
    // filtr_stat ovlivňuje jen které firmy se v seznamu zobrazí (HAVING).
    $having = '';
    if ($filtr_stat==='pouzite')    $having = 'HAVING SUM(k.pouzit) > 0';
    if ($filtr_stat==='nepouzite')  $having = 'HAVING (COUNT(*)-SUM(k.pouzit)) > 0';
    if ($filtr_stat==='absolventi') $having = 'HAVING SUM(k.kod IN (SELECT kod FROM ' . RD_TABLE_RIDICI . ' WHERE uspech=1)) > 0';

    $firmy = $wpdb->get_results("SELECT f.id as firma_id, k.firma_nazev, k.firma_email, COUNT(*) as celkem, SUM(k.pouzit) as pouzito, COUNT(*)-SUM(k.pouzit) as volnych, MAX(k.vytvoreno) as posledni FROM " . RD_TABLE_KODY . " k LEFT JOIN {$wpdb->prefix}rd_firmy f ON f.email=k.firma_email $w_base GROUP BY k.firma_nazev, k.firma_email $having ORDER BY posledni DESC");
    ?>
