            <td><strong><?php echo esc_html($o->firma_nazev); ?></strong><div style="font-size:11px;color:#9ca3af"><?php echo esc_html($o->firma_email); ?></div></td>
            <td style="text-align:center;font-weight:700"><?php echo (int)$o->pocet; ?></td>
            <td><span style="font-size:11px;font-weight:600;color:<?php echo $o_c; ?>;background:<?php echo $o_bg; ?>;padding:2px 8px;border-radius:99px"><?php echo $o_l; ?></span></td>
            <td style="color:#6b7280;font-size:12px" data-val="<?php echo strtotime($o->vytvoreno); ?>"><?php echo date('d.m.Y H:i', strtotime($o->vytvoreno)); ?></td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>
    <div class="rd-show-mobile" style="display:none">
    <?php foreach($posledni as $o):
        $o_c  = $stav_c[$o->stav] ?? '#6b7280';
        $o_l  = $stav_l[$o->stav] ?? $o->stav;
        $o_bg = ['prevod_ceka'=>'#fef3c7','zaplaceno'=>'#dcfce7','hotovo'=>'#dcfce7','prevod_ok'=>'#dcfce7','zruseno'=>'#fee2e2','ceka'=>'#fef3c7','storno'=>'#fee2e2'][$o->stav] ?? '#f3f4f6';
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;gap:10px">
        <div>
            <strong style="font-size:13px"><?php echo esc_html($o->firma_nazev); ?></strong>
            <div style="font-size:11px;color:#9ca3af"><?php echo date('d.m.Y H:i', strtotime($o->vytvoreno)); ?></div>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:12px;font-weight:700"><?php echo (int)$o->pocet; ?> kódů</span>
            <span style="font-size:11px;font-weight:600;color:<?php echo $o_c; ?>;background:<?php echo $o_bg; ?>;padding:2px 8px;border-radius:99px"><?php echo $o_l; ?></span>
        </div>
    </div>
    <?php endforeach; ?>
    </div>
    <?php endif; ?>

    </div><!-- /max-width:900px master wrapper -->
    </div><!-- /.wrap -->
    <?php
}

/* ================================================================
   AUTOSKOLA_ADMIN – DETAIL FIRMY (kódy)
   ================================================================ */
function rd_admin_kody_detail_as($firma_email, $as_id) {
    global $wpdb;
    $firma = $wpdb->get_row($wpdb->prepare(
        "SELECT firma_nazev,firma_email,COUNT(*) as celkem,SUM(pouzit) as pouzito FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND autoskola_id=%d GROUP BY firma_nazev,firma_email LIMIT 1",
        $firma_email, $as_id
    ));
    if (!$firma) { echo '<div class="wrap"><p>Firma nenalezena.</p></div>'; return; }

    $filtr = sanitize_key($_GET['filtr_stat'] ?? 'vse');
    $hledat = sanitize_text_field($_GET['hledat'] ?? '');
    $base = admin_url('admin.php?page=refdrive-prehled&firma='.urlencode($firma_email));

    $w = $wpdb->prepare("WHERE k.firma_email=%s AND k.autoskola_id=%d", $firma_email, $as_id);
    if ($filtr==='pouzite')    $w .= " AND k.pouzit=1";
    if ($filtr==='nepouzite')  $w .= " AND k.pouzit=0";
    if ($filtr==='absolventi') $w .= " AND k.kod IN (SELECT kod FROM " . RD_TABLE_RIDICI . " WHERE uspech=1)";
    if ($hledat) $w .= $wpdb->prepare(" AND (k.kod LIKE %s OR k.ridic_jmeno LIKE %s)", "%$hledat%", "%$hledat%");

    $kody = $wpdb->get_results("SELECT k.*, COALESCE(k.ridic_jmeno, r.jmeno) as ridic_jmeno, r.score as ridic_score, r.uspech as ridic_uspech, r.datum_skoleni as ridic_datum FROM " . RD_TABLE_KODY . " k LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1) $w ORDER BY k.vytvoreno DESC LIMIT 500");
    $abs = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT k.kod) FROM " . RD_TABLE_KODY . " k INNER JOIN " . RD_TABLE_RIDICI . " r ON r.kod=k.kod WHERE k.firma_email=%s AND k.autoskola_id=%d AND r.uspech=1", $firma_email, $as_id));
    ?>
    <div class="wrap">
    <p><a href="<?php echo admin_url('admin.php?page=refdrive');?>" class="rd-back-btn">← Zpět na firmy</a></p>
    <h1><?php echo esc_html($firma->firma_nazev);?> — <?php echo esc_html($as->nazev ?? ''); ?></h1>
    <div style="max-width:900px">
    <p>
        <a href="<?php echo wp_nonce_url(admin_url('admin.php?page=refdrive-prehled&rd_smazat_firmu='.urlencode($firma_email)), 'rd_smazat_firmu_'.md5($firma_email.$as_id)); ?>" class="rd-btn-del" onclick="return confirm('Trvale smazat firmu <?php echo esc_js($firma->firma_nazev); ?> a veškerá její data? Akce je NEVRATNÁ.')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/></svg> Smazat celou firmu</a>
    </p>
    <?php
    $as_oop = $wpdb->get_var($wpdb->prepare("SELECT oop_url FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    if ($as_oop): ?>
    <div class="rd-info-chip rd-chip-blue" style="margin-bottom:12px;font-size:.82rem">
        Nákup kódů je přímý obchodní vztah mezi firmou <strong><?php echo esc_html($firma->firma_nazev); ?></strong> a vaší autoškolu.
        Obchodní podmínky: <a href="<?php echo esc_url($as_oop); ?>" target="_blank" style="color:inherit;font-weight:600"><?php echo esc_html($as_oop); ?></a>
    </div>
    <?php endif; ?>
    <div style="display:flex;gap:20px;flex-wrap:wrap;padding:10px 14px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:12px;font-size:13px">
        <a href="<?php echo admin_url('admin.php?page=refdrive-prehled&firma='.urlencode($firma_email));?>" style="text-decoration:none;color:<?php echo $filtr==='vse'?'#111827':'#6b7280';?>;font-weight:<?php echo $filtr==='vse'?'700':'400';?>">Celkem: <strong><?php echo (int)$firma->celkem;?></strong></a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base.'&filtr_stat=pouzite';?>" style="text-decoration:none;color:<?php echo $filtr==='pouzite'?'#7c3aed':'#6b7280';?>;font-weight:<?php echo $filtr==='pouzite'?'700':'400';?>">Použito: <strong><?php echo (int)$firma->pouzito;?></strong></a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base.'&filtr_stat=nepouzite';?>" style="text-decoration:none;color:<?php echo $filtr==='nepouzite'?'#374151':'#6b7280';?>;font-weight:<?php echo $filtr==='nepouzite'?'700':'400';?>">Volných: <strong><?php echo (int)$firma->celkem-(int)$firma->pouzito;?></strong></a>
        <span style="color:#e5e7eb">|</span>
        <a href="<?php echo $base.'&filtr_stat=absolventi';?>" style="text-decoration:none;color:<?php echo $filtr==='absolventi'?'#16a34a':'#6b7280';?>;font-weight:<?php echo $filtr==='absolventi'?'700':'400';?>">Absolventů: <strong><?php echo $abs;?></strong></a>
    </div>
    <form method="get" style="display:flex;gap:8px;margin:12px 0">
        <input type="hidden" name="page" value="refdrive-as-moje-firmy">
        <input type="hidden" name="firma" value="<?php echo esc_attr($firma_email);?>">
        <?php if($filtr!=='vse'): ?><input type="hidden" name="filtr_stat" value="<?php echo esc_attr($filtr);?>"><?php endif; ?>
        <input type="text" name="hledat" value="<?php echo esc_attr($hledat);?>" placeholder="Hledat kód nebo jméno..." class="regular-text">
        <button type="submit" class="button">Hledat</button>
        <?php if($hledat||$filtr!=='vse'): ?><a href="<?php echo $base;?>" class="button">Zrušit</a><?php endif; ?>
    </form>
    <?php echo rd_admin_firma_karty($kody); ?>
    </div><!-- /max-width:900px master wrapper -->
    </div>
    <?php
}

/* ================================================================
   AUTOSKOLA_ADMIN – ABSOLVENTI
   ================================================================ */
function rd_admin_as_absolventi_all() {
    global $wpdb;
    if (!rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as = rd_get_my_autoskola();
    if (!$as) { echo '<div class="wrap"><p>Autoškola nenalezena.</p></div>'; return; }
    $id = $as->id;

    if (isset($_GET['rd_export_abs']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_export_abs_'.$id)) {
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=absolventi-'.sanitize_title($as->nazev).'-'.date('Y-m-d').'.csv');
        $f = fopen('php://output', 'w');
        fprintf($f, chr(0xEF).chr(0xBB).chr(0xBF));
        fputcsv($f, ['Jméno','Firma','Email','Kód','Score (%)','Datum'], ';');
        foreach ($wpdb->get_results($wpdb->prepare("SELECT DISTINCT r.* FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1 ORDER BY r.datum_skoleni DESC", $id, $id)) as $r)
            fputcsv($f, [$r->jmeno,$r->firma_nazev,$r->firma_email,$r->kod,$r->score,date('d.m.Y H:i',strtotime($r->datum_skoleni))], ';');
        fclose($f); exit;
    }

    $hledat = sanitize_text_field($_GET['hledat'] ?? '');
    $w = $wpdb->prepare("WHERE (autoskola_id=%d OR kod IN (SELECT kod FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d)) AND uspech=1", $id, $id);
    if ($hledat) $w .= $wpdb->prepare(" AND (jmeno LIKE %s OR firma_nazev LIKE %s OR kod LIKE %s)", "%$hledat%", "%$hledat%", "%$hledat%");
    $ridici = $wpdb->get_results("SELECT * FROM " . RD_TABLE_RIDICI . " $w ORDER BY datum_skoleni DESC LIMIT 500");
    $pocet  = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT r.id) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1", $id, $id));
    ?>
    <div class="wrap">
    <style>
    .rd-cert-btn{display:inline-flex;align-items:center;gap:5px;color:#374151;text-decoration:none;font-size:12px;padding:4px 10px;border:1px solid #e5e7eb;border-radius:6px;background:#fff;cursor:pointer;white-space:nowrap}
    .rd-cert-btn:hover{background:#f9fafb;color:#374151!important}
    .rd-export-btn{display:inline-flex;align-items:center;gap:6px;color:#374151;text-decoration:none;font-size:12px;padding:5px 12px;border:1px solid #e5e7eb;border-radius:6px;background:#fff;cursor:pointer;white-space:nowrap}
    .rd-export-btn:hover{background:#f9fafb;color:#374151!important}
    </style>
    <h1>Absolventi — <?php echo esc_html($as->nazev);?> <span style="font-size:14px;font-weight:400;color:#6b7280">(<?php echo $pocet;?> celkem)</span></h1>
    <div style="max-width:900px">
    <div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:16px;flex-wrap:wrap">
        <a href="<?php echo wp_nonce_url(admin_url('admin.php?page=refdrive-as-moje-absolventi&rd_export_abs=1'),'rd_export_abs_'.$id);?>" class="rd-export-btn" style="flex-shrink:0"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg> Export CSV</a>
        <form method="get" style="display:flex;gap:6px;flex:1;min-width:0">
            <input type="hidden" name="page" value="refdrive-as-moje-absolventi">
            <input type="text" name="hledat" value="<?php echo esc_attr($hledat);?>" placeholder="Hledat..." class="regular-text" style="flex:1;min-width:0">
            <button type="submit" class="rd-btn-detail" style="flex-shrink:0;padding:5px 12px;font-size:13px">Hledat</button>
            <?php if($hledat): ?><a href="<?php echo admin_url('admin.php?page=refdrive-as-moje-absolventi');?>" class="rd-btn-detail" style="flex-shrink:0;padding:5px 10px;font-size:13px">×</a><?php endif; ?>
        </form>
    </div>
    <?php if(empty($ridici)): ?>
    <p style="color:#999;padding:20px 0">Žádní absolventi<?php echo $hledat?' pro zadaný filtr':'';?>.</p>
    <?php else: ?>
    <!-- Desktop tabulka -->
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Jméno</th>
            <th onclick="rdSortTable(this)">Firma</th>
            <th onclick="rdSortTable(this)">Kód</th>
            <th onclick="rdSortTable(this)" style="text-align:center">Score</th>
            <th onclick="rdSortTable(this)">Absolvováno</th>
            <th onclick="rdSortTable(this)">Trvání</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach($ridici as $r):
            $access_key_as = bin2hex(random_bytes(16));
            set_transient('rd_cert_access_' . $access_key_as, $r->kod, HOUR_IN_SECONDS);
            $cert_url = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($r->kod) . '&access=' . $access_key_as;
            $trvani_str = $r->trvani_min > 0 ? intval($r->trvani_min) . ' min' : '—';
        ?>
        <tr>
            <td><strong><?php echo esc_html($r->jmeno); ?></strong></td>
            <td style="font-size:12px;color:#6b7280"><?php echo esc_html($r->firma_nazev ?: '—'); ?></td>
            <td><code style="font-size:11px;background:#f3f4f6;padding:2px 6px;border-radius:3px"><?php echo esc_html($r->kod); ?></code></td>
            <td style="text-align:center;font-weight:700;color:<?php echo $r->score >= 80 ? '#16a34a' : '#dc2626'; ?>"><?php echo intval($r->score); ?>%</td>
            <td style="color:#6b7280;font-size:12px"><?php echo date('d.m.Y H:i', strtotime($r->datum_skoleni)); ?></td>
            <td style="color:#6b7280;font-size:12px"><?php echo $trvani_str; ?></td>
            <td><a href="<?php echo esc_url($cert_url); ?>" target="_blank" class="rd-cert-btn"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="6"/><path d="M8 14l-2 7 6-3 6 3-2-7"/></svg> Certifikát</a></td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>
    <!-- Mobilní karty -->
    <div class="rd-show-mobile" style="display:none">
    <?php foreach($ridici as $r):
        $access_key_as2 = bin2hex(random_bytes(16));
        set_transient('rd_cert_access_' . $access_key_as2, $r->kod, HOUR_IN_SECONDS);
        $cert_url2 = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($r->kod) . '&access=' . $access_key_as2;
        $trvani_str = $r->trvani_min > 0 ? intval($r->trvani_min) . ' min' : '—';
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
            <strong style="font-size:14px"><?php echo esc_html($r->jmeno); ?></strong>
            <span style="font-size:16px;font-weight:700;color:<?php echo $r->score >= 80 ? '#16a34a' : '#dc2626'; ?>"><?php echo intval($r->score); ?>%</span>
        </div>
        <div style="font-size:12px;display:flex;flex-direction:column;gap:4px;margin-bottom:10px">
            <div><span style="color:#6b7280">Firma:</span> <?php echo esc_html($r->firma_nazev ?: '—'); ?></div>
            <div><span style="color:#6b7280">Kód:</span> <code style="font-size:11px;background:#f3f4f6;padding:1px 5px;border-radius:3px"><?php echo esc_html($r->kod); ?></code></div>
            <div><span style="color:#6b7280">Absolvováno:</span> <?php echo date('d.m.Y H:i', strtotime($r->datum_skoleni)); ?></div>
            <div><span style="color:#6b7280">Trvání:</span> <?php echo $trvani_str; ?></div>
        </div>
        <a href="<?php echo esc_url($cert_url2); ?>" target="_blank" class="rd-cert-btn"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="6"/><path d="M8 14l-2 7 6-3 6 3-2-7"/></svg> Certifikát</a>
    </div>
    <?php endforeach; ?>
    </div>
    <?php endif; ?>
    </div><!-- /max-width:900px master wrapper -->
    </div>
    <?php
}


function rd_admin_as_kody() {
    global $wpdb;
    // Pustit hlavního admina i autoskola_admin (jen pro svou AS)
    if (!current_user_can('manage_options') && !rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as_id = rd_admin_get_as_id_from_page();
    if (!$as_id) {
        // Autoskola_admin - přesměrovat na svou AS
        if (rd_je_autoskola_admin()) {
            $my_as = rd_get_my_autoskola();
            if ($my_as) {
                wp_redirect(admin_url('admin.php?page=refdrive-as-' . $my_as->id . '-kody'));
                exit;
            }
        }
        wp_die('Autoškola nenalezena');
    }
    // Autoskola_admin smí jen svou AS
    if (!current_user_can('manage_options') && rd_je_autoskola_admin()) {
        $my_as = rd_get_my_autoskola();
        if (!$my_as || $my_as->id != $as_id) wp_die('Přístup odepřen');
    }

    $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    if (!$as) wp_die('Autoškola nenalezena');

    // Filtr stavu (stejný jako u autoskola_admin)
    $stav_filter = sanitize_key($_GET['stav'] ?? 'vse');
    $firma_filter = sanitize_email($_GET['firma'] ?? '');
    $mesic_filter = preg_match('/^\d{4}-\d{2}$/', $_GET['mesic'] ?? '') ? $_GET['mesic'] : '';
    $base_url = admin_url('admin.php?page=refdrive-as-' . $as_id . '-kody');

    $where = "WHERE k.autoskola_id=" . intval($as_id);
    if ($stav_filter === 'volny')   $where .= " AND k.pouzit=0 AND (k.expiruje IS NULL OR k.expiruje > NOW())";
    if ($stav_filter === 'pouzity') $where .= " AND k.pouzit=1";
    if ($stav_filter === 'expiry')  $where .= " AND k.expiruje IS NOT NULL AND k.expiruje <= NOW() AND k.pouzit=0";
    if ($firma_filter) $where .= $wpdb->prepare(" AND k.firma_email=%s", $firma_filter);
    if ($mesic_filter) $where .= $wpdb->prepare(" AND DATE_FORMAT(k.vytvoreno, '%%Y-%%m')=%s", $mesic_filter);

    $kody = $wpdb->get_results(
        "SELECT k.*, r.score as ridic_score, r.uspech as ridic_uspech, r.datum_skoleni as ridic_datum FROM " . RD_TABLE_KODY . " k
         LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1)
         {$where} ORDER BY k.vytvoreno DESC LIMIT 500"
    );

    $celkem   = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=" . intval($as_id));
    $volnych  = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=" . intval($as_id) . " AND pouzit=0 AND (expiruje IS NULL OR expiruje > NOW())");
    $pouzito  = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=" . intval($as_id) . " AND pouzit=1");
    $expiry   = (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=" . intval($as_id) . " AND expiruje IS NOT NULL AND expiruje <= NOW() AND pouzit=0");
    ?>
    <div class="wrap">
    <h1><?php echo esc_html($as->nazev); ?> — Kódy</h1>
    <p><a href="<?php echo admin_url('admin.php?page=refdrive-as-' . $as_id); ?>" class="rd-back-btn">← Zpět na přehled</a></p>

    <?php if ($mesic_filter): ?>
    <div style="background:#fef3c7;border:1px solid #fde68a;border-radius:6px;padding:8px 14px;margin-bottom:12px;font-size:13px;color:#92400e;display:flex;align-items:center;justify-content:space-between;max-width:900px">
        <span>Filtrováno: kódy vydané v <strong><?php echo esc_html($mesic_filter); ?></strong></span>
        <a href="<?php echo esc_url($base_url); ?>" style="color:#92400e;font-weight:600;font-size:12px">✕ Zrušit filtr</a>
    </div>
    <?php endif; ?>

    <!-- Mini dashboard -->
    <div style="max-width:900px">
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">
        <?php foreach ([
            ['Celkem',     $celkem,  'vse'],
            ['Volné',      $volnych, 'volny'],
            ['Použité',    $pouzito, 'pouzity'],
            ['Expirované', $expiry,  'expiry'],
        ] as [$label,$val,$filter]):
            $active_b = $stav_filter === $filter ? 'border-color:#7c3aed;box-shadow:0 0 0 1px #7c3aed' : '#e5e7eb';
            $num_col  = $stav_filter === $filter ? '#7c3aed' : '#111827'; ?>
        <a href="<?php echo esc_url(add_query_arg('stav', $filter, $base_url)); ?>" style="text-decoration:none;flex:1;min-width:80px">
            <div style="background:#fff;border:1px solid <?php echo $active_b; ?>;border-radius:8px;padding:12px 10px;text-align:center">
                <div style="font-size:22px;font-weight:700;color:<?php echo $num_col; ?>;line-height:1.2"><?php echo number_format($val); ?></div>
                <div style="font-size:12px;color:#6b7280;margin-top:2px"><?php echo $label; ?></div>
            </div>
        </a>
        <?php endforeach; ?>
    </div>
    <?php if ($firma_filter): ?>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
        <a href="<?php echo esc_url($base_url); ?>" class="rd-btn-detail" style="padding:4px 10px;font-size:12px">× Zrušit filtr</a>
        <strong style="font-size:13px"><?php echo esc_html($firma_filter); ?></strong>
    </div>
    <?php endif; ?>
    <?php echo rd_admin_firma_karty($kody); ?>
    </div>
    <?php
}

/* ============================================================
   v6.1.0 — ADMIN: ABSOLVENTI KONKRÉTNÍ AUTOŠKOLY
   ============================================================ */
function rd_admin_as_absolventi() {
    global $wpdb;
    if (!current_user_can('manage_options') && !rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as_id = rd_admin_get_as_id_from_page();
    if (!$as_id) {
        if (rd_je_autoskola_admin()) {
            $my_as = rd_get_my_autoskola();
            if ($my_as) {
                wp_redirect(admin_url('admin.php?page=refdrive-as-' . $my_as->id . '-absolventi'));
                exit;
            }
        }
        wp_die('Autoškola nenalezena');
    }
    if (!current_user_can('manage_options') && rd_je_autoskola_admin()) {
        $my_as = rd_get_my_autoskola();
        if (!$my_as || $my_as->id != $as_id) wp_die('Přístup odepřen');
    }

    $as = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    if (!$as) wp_die('Autoškola nenalezena');

    $ridici = $wpdb->get_results($wpdb->prepare(
        "SELECT DISTINCT r.* FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1 ORDER BY r.datum_skoleni DESC LIMIT 500",
        $as_id, $as_id
    ));

    // Export CSV
    if (isset($_GET['rd_as_export_abs']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_export_abs_' . $as_id)) {
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename=absolventi-' . sanitize_title($as->nazev) . '-' . date('Y-m-d') . '.csv');
        $f = fopen('php://output', 'w');
        fprintf($f, chr(0xEF).chr(0xBB).chr(0xBF));
        fputcsv($f, ['Jméno','Firma','Email','Kód','Score (%)','Výsledek','Datum'], ';');
        foreach ($ridici as $r) {
            fputcsv($f, [$r->jmeno,$r->firma_nazev,$r->firma_email,$r->kod,$r->score,$r->uspech?'Splnil':'Nesplnil',date('d.m.Y H:i',strtotime($r->datum_skoleni))], ';');
        }
        fclose($f); exit;
    }
    ?>
    <div class="wrap">
    <h1><?php echo esc_html($as->nazev); ?> — Absolventi</h1>
    <div style="max-width:900px">
    <div style="display:flex;gap:8px;align-items:center;margin-bottom:12px;flex-wrap:wrap">
        <a href="<?php echo admin_url('admin.php?page=refdrive-as-' . $as_id); ?>" class="rd-back-btn">← Zpět na detail</a>
        <a href="<?php echo wp_nonce_url(admin_url('admin.php?page=refdrive-as-' . $as_id . '-absolventi&rd_as_export_abs=1'), 'rd_as_export_abs_' . $as_id); ?>" class="rd-export-btn"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg> Export CSV</a>
    </div>
    <style>
    .rd-export-btn{display:inline-flex;align-items:center;gap:6px;color:#374151;text-decoration:none;font-size:12px;padding:5px 12px;border:1px solid #e5e7eb;border-radius:6px;background:#fff;cursor:pointer;white-space:nowrap}
    .rd-export-btn:hover{background:#f9fafb;color:#374151!important}
    .rd-cert-btn{display:inline-flex;align-items:center;gap:5px;color:#374151;text-decoration:none;font-size:12px;padding:4px 10px;border:1px solid #e5e7eb;border-radius:6px;background:#fff;cursor:pointer;white-space:nowrap}
    .rd-cert-btn:hover{background:#f9fafb;color:#374151!important}
    .rd-t{width:100%;border-collapse:collapse;font-size:13px;margin-top:12px}
    .rd-t th{background:#f9fafb;padding:9px 12px;text-align:left;font-weight:600;font-size:12px;color:#374151;border-bottom:2px solid #e5e7eb;white-space:nowrap}
    .rd-t td{padding:10px 12px;border-bottom:1px solid #f3f4f6;vertical-align:middle}
    .rd-t tr:hover td{background:#fafafa}
    .rd-badge{display:inline-flex;align-items:center;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:700}
    @media(max-width:700px){
      .rd-t thead{display:none}
