            <th onclick="rdSortTable(this)">Trvání</th>
            <th onclick="rdSortTable(this)">Datum</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach ($ridici as $r):
            $access_key_f = bin2hex(random_bytes(16));
            set_transient('rd_cert_access_' . $access_key_f, $r->kod, HOUR_IN_SECONDS);
            $cert_url = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($r->kod) . '&access=' . $access_key_f; ?>
        <tr>
            <td><strong><?php echo esc_html($r->jmeno); ?></strong><div style="font-size:11px;color:#9ca3af"><code><?php echo esc_html($r->kod); ?></code></div></td>
            <td style="color:#374151"><?php echo esc_html($r->firma_nazev); ?><div style="font-size:11px;color:#9ca3af"><?php echo esc_html($r->firma_email); ?></div></td>
            <td style="font-weight:700;color:<?php echo $r->score>=80?'#15803d':'#dc2626'; ?>" data-val="<?php echo intval($r->score); ?>"><?php echo intval($r->score); ?> %</td>
            <td><?php echo $r->uspech ? '<span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:#dcfce7;color:#15803d">✓ Splnil</span>' : '<span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:#fee2e2;color:#b91c1c">✗ Nesplnil</span>'; ?></td>
            <td style="color:#6b7280"><?php echo $r->trvani_min ? intval($r->trvani_min) . ' min' : '—'; ?></td>
            <td style="color:#6b7280;font-size:12px" data-val="<?php echo strtotime($r->datum_skoleni); ?>"><?php echo date('d.m.Y H:i', strtotime($r->datum_skoleni)); ?></td>
            <td><?php if ($r->uspech): ?><a href="<?php echo esc_url($cert_url); ?>" target="_blank" class="rd-btn-detail" style="font-size:11px;padding:3px 8px">📄 Certifikát</a><?php else: ?>—<?php endif; ?></td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>
    <div class="rd-show-mobile" style="display:none">
    <?php foreach ($ridici as $r): ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">
        <div>
            <strong><?php echo esc_html($r->jmeno); ?></strong>
            <div style="font-size:11px;color:#9ca3af"><?php echo esc_html($r->firma_nazev); ?> · <?php echo date('d.m.Y', strtotime($r->datum_skoleni)); ?></div>
        </div>
        <div style="text-align:right">
            <div style="font-weight:700;color:<?php echo $r->score>=80?'#15803d':'#dc2626'; ?>"><?php echo intval($r->score); ?> %</div>
            <div style="font-size:10px;color:#9ca3af"><?php echo $r->uspech?'Splnil':'Nesplnil'; ?></div>
        </div>
