function rd_admin_as_objednavky() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    $as_id = rd_admin_get_as_id_from_page();
    if (!$as_id) wp_die('Autoškola nenalezena');

    $as = $wpdb->get_row($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
    if (!$as) wp_die('Autoškola nenalezena');

    // Potvrdit převod
    if (isset($_GET['potvrdit']) && (current_user_can('manage_options') || rd_je_autoskola_admin())) {
        $pi_id = sanitize_text_field($_GET['potvrdit']);
        // Fallback pro objednávky bez autoskola_id v sloupci (starší)
        $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_OBJ . " WHERE pi_id=%s AND (autoskola_id=%d OR autoskola_id IS NULL)", $pi_id, $as_id));
        if ($row && $row->stav === 'prevod_ceka') {
            $obj_data = json_decode($row->data ?? '{}', true);
            $obj_data['autoskola_id'] = $as_id; // Vždy nastavit autoskola_id
            rd_vygenerovat_kody($row->firma_nazev, $row->firma_email, $row->pocet, $pi_id, $obj_data);
            $wpdb->update(RD_TABLE_OBJ, ['stav'=>'zaplaceno','autoskola_id'=>$as_id], ['pi_id'=>$pi_id]);
            echo '<div class="notice notice-success"><p>✓ Platba potvrzena, kódy odeslány na <strong>' . esc_html($row->firma_email) . '</strong>.</p></div>';
            echo '<div class="notice notice-warning" style="border-left-color:#d97706"><p><strong>⚠ Nezapomeňte vystavit fakturu!</strong> Jste povinni firmě <strong>' . esc_html($row->firma_nazev) . '</strong> vystavit řádný daňový doklad (fakturu) za přijaté školení. Doklad zašlete na <strong>' . esc_html($row->firma_email) . '</strong>.</p></div>';
        }
    }

    $objednavky = $wpdb->get_results($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_OBJ . " WHERE autoskola_id=%d OR (autoskola_id IS NULL AND data LIKE %s) ORDER BY vytvoreno DESC LIMIT 200",
        $as_id,
        '%"autoskola_id":' . $as_id . '%'
    ));
    $stav_labels = [
        'prevod_ceka' => ['label'=>'Čeká na platbu', 'color'=>'#d97706'],
        'zaplaceno'   => ['label'=>'Zaplaceno',               'color'=>'#16a34a'],
        'zruseno'     => ['label'=>'Zrušeno',                 'color'=>'#dc2626'],
        'ceka'        => ['label'=>'Čeká',                    'color'=>'#d97706'],
    ];
    ?>
    <div class="wrap">
    <h1><?php echo esc_html($as->nazev); ?> — Objednávky</h1>
    <div style="max-width:900px">
    <a href="<?php echo admin_url('admin.php?page=refdrive-as-' . $as_id); ?>" class="rd-back-btn" style="margin-bottom:12px;display:inline-block">← Zpět na detail</a>
    <?php if (empty($objednavky)): ?>
    <p style="color:#999;padding:16px 0">Žádné objednávky.</p>
    <?php else: ?>
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Firma</th>
            <th onclick="rdSortTable(this)" style="text-align:center">Kódů</th>
            <th onclick="rdSortTable(this)">Částka s DPH</th>
            <th onclick="rdSortTable(this)">VS</th>
            <th onclick="rdSortTable(this)">Stav</th>
            <th onclick="rdSortTable(this)">Datum</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach ($objednavky as $o):
            $data_decoded = json_decode($o->data ?? '{}', true);
            $cena_kus = intval($data_decoded['cena'] ?? 0);
            if (!$cena_kus && $o->autoskola_id) $cena_kus = (int)$wpdb->get_var($wpdb->prepare("SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $o->autoskola_id));
            $castka_dph = $cena_kus > 0 ? number_format(round($o->pocet * $cena_kus * 1.21)) . ' Kč' : '—';
