        ?>
        <tr>
            <td><strong><?php echo esc_html($o->firma_nazev); ?></strong><div style="font-size:11px;color:#9ca3af"><?php echo esc_html($o->firma_email); ?></div></td>
            <td style="text-align:center;font-weight:700" data-val="<?php echo (int)$o->pocet; ?>"><?php echo (int)$o->pocet; ?></td>
            <td><?php echo $castka_dph; ?></td>
            <td><code style="font-size:11px;background:#f3f4f6;padding:1px 6px;border-radius:3px"><?php echo esc_html($vs); ?></code></td>
            <td><span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:<?php echo $so[1]; ?>;color:<?php echo $so[2]; ?>"><?php echo $so[0]; ?></span></td>
            <td style="color:#6b7280;font-size:12px" data-val="<?php echo strtotime($o->vytvoreno); ?>"><?php echo date('d.m.Y H:i', strtotime($o->vytvoreno)); ?></td>
            <td><?php if ($o->stav === 'prevod_ceka' && !current_user_can('manage_options')): ?>
                <a href="<?php echo esc_url(add_query_arg(['potvrdit'=>$o->pi_id], admin_url('admin.php?page=refdrive-as-'.$as_id.'-objednavky'))); ?>" style="font-size:11px;padding:3px 10px;background:#dcfce7;color:#15803d;border:1px solid #86efac;border-radius:5px;text-decoration:none" onclick="return confirm('Potvrdit?')">✓ Potvrdit</a>
            <?php endif; ?></td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>
    <div class="rd-show-mobile" style="display:none">
    <?php foreach ($objednavky as $o):
        $data_decoded = json_decode($o->data ?? '{}', true);
        $cena_kus = intval($data_decoded['cena'] ?? 0);
        if (!$cena_kus && $o->autoskola_id) $cena_kus = (int)$wpdb->get_var($wpdb->prepare("SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $o->autoskola_id));
        $castka_dph = $cena_kus > 0 ? number_format(round($o->pocet * $cena_kus * 1.21)) . ' Kč' : '—';
        $so = (['zaplaceno'=>['Zaplaceno','#dcfce7','#15803d'],'prevod_ok'=>['Zaplaceno','#dcfce7','#15803d'],'hotovo'=>['Zaplaceno','#dcfce7','#15803d'],'prevod_ceka'=>['Čeká na platbu','#fef3c7','#d97706'],'ceka'=>['Čeká na platbu','#fef3c7','#d97706'],'storno'=>['Storno','#fee2e2','#dc2626'],'zruseno'=>['Storno','#fee2e2','#dc2626']][$o->stav] ?? [$o->stav,'#f3f4f6','#6b7280']);
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">
            <strong><?php echo esc_html($o->firma_nazev); ?></strong>
            <span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:<?php echo $so[1]; ?>;color:<?php echo $so[2]; ?>"><?php echo $so[0]; ?></span>
        </div>
        <div style="font-size:12px;color:#6b7280"><?php echo (int)$o->pocet; ?> kódů · <?php echo $castka_dph; ?> · <?php echo date('d.m.Y H:i', strtotime($o->vytvoreno)); ?></div>
