    </div><!-- /max-width:900px -->
    </div><!-- .wrap -->
    <?php
}


function rd_admin_autoskoly() {
    global $wpdb;
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');

    $filter = sanitize_key($_GET['filter'] ?? 'vse');
    $hledat = sanitize_text_field($_GET['hledat'] ?? '');
    $base   = admin_url('admin.php?page=refdrive-autoskoly');

    // Handlers
    if (isset($_GET['rd_as_schvalit']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_schvalit_' . intval($_GET['rd_as_schvalit']))) {
        $as_id = intval($_GET['rd_as_schvalit']);
        $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
        if ($as && $as->stav === 'ceka_schvaleni') {
            $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'ceka_potvrzeni'], ['id'=>$as_id]);
            rd_email_autoskola($as->email, 'RefDrive: Registrace schválena',
                rd_email_wrap('Registrace schválena', '<p>Vaše registrace autoškoly <strong>' . esc_html($as->nazev) . '</strong> byla schválena. Nyní prosím proveďte platbu za vybraný balíček.</p>' . rd_email_btn('Přejít do administrace →', admin_url('admin.php?page=refdrive')))
            );
        }
        wp_safe_redirect(admin_url('admin.php?page=refdrive-autoskoly&rd_zprava=schvalena')); exit;
    }

    if (isset($_GET['rd_as_potvrdit_platbu']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_platba_' . intval($_GET['rd_as_potvrdit_platbu']))) {
        $as_id = intval($_GET['rd_as_potvrdit_platbu']);
        $pid   = intval($_GET['rd_pid'] ?? 0);
        $as    = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id));
        if ($as) {
            $nova_platba = $pid
                ? $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE id=%d AND autoskola_id=%d AND stav='ceka_potvrzeni' LIMIT 1", $pid, $as_id))
                : $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d AND stav='ceka_potvrzeni' ORDER BY id DESC LIMIT 1", $as_id));
            if ($nova_platba) {
                $tier = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d LIMIT 1", $nova_platba->tier_id));
                $platnost_od = date('Y-m-d');
                $platnost_do = date('Y-m-d', strtotime('+' . intval(get_option('rd_kod_expirace_dni', 30)) . ' days'));
                if ($nova_platba) $wpdb->update(RD_TABLE_AS_PLATBY, ['stav'=>'zaplaceno','platnost_od'=>$platnost_od,'platnost_do'=>$platnost_do], ['id'=>$nova_platba->id]);
                $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'aktivni','tier_id'=>$nova_platba->tier_id,'predplatne_expiruje'=>$platnost_do], ['id'=>$as_id]);
            }
        }
        wp_safe_redirect(admin_url('admin.php?page=refdrive-as-' . $as_id . '&rd_zprava=platba_ok')); exit;
    }

    if (isset($_GET['rd_as_blokovat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_blokovat_' . intval($_GET['rd_as_blokovat']))) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'zablokovano'], ['id'=>intval($_GET['rd_as_blokovat'])]);
        wp_safe_redirect($base); exit;
    }
    if (isset($_GET['rd_as_odblokovat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_odblokovat_' . intval($_GET['rd_as_odblokovat']))) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav'=>'aktivni'], ['id'=>intval($_GET['rd_as_odblokovat'])]);
        wp_safe_redirect($base); exit;
    }
    if (isset($_GET['rd_as_smazat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_as_smazat_' . intval($_GET['rd_as_smazat']))) {
        $id = intval($_GET['rd_as_smazat']);
        $wpdb->delete(RD_TABLE_AS_PLATBY, ['autoskola_id'=>$id]);
        $wpdb->delete(RD_TABLE_AUTOSKOLY, ['id'=>$id]);
        wp_safe_redirect($base); exit;
    }

    // Čekající platby
    $cekajici_platby = $wpdb->get_results(
        "SELECT p.*, a.nazev as as_nazev, a.email as as_email, t.nazev as tier_nazev, p.castka as cena_mesic
         FROM " . RD_TABLE_AS_PLATBY . " p
         JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=p.autoskola_id
         LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id
         WHERE p.stav='ceka_potvrzeni' ORDER BY p.vytvoreno ASC"
    );

    // Autoškoly
    $where = "WHERE 1=1";
    if ($filter === 'ceka')        $where .= " AND stav IN ('ceka_schvaleni','ceka_potvrzeni')";
    elseif ($filter === 'aktivni') $where .= " AND stav='aktivni'";
    elseif ($filter === 'pozastaveno') $where .= " AND stav IN ('pozastavena','predplatne_expirovano')";
    elseif ($filter === 'zablokovano') $where .= " AND stav='zablokovano'";
    if ($hledat) $where .= $wpdb->prepare(" AND (nazev LIKE %s OR email LIKE %s OR ico LIKE %s)", "%$hledat%", "%$hledat%", "%$hledat%");

    $autoskoly = $wpdb->get_results(
        "SELECT a.*, t.nazev as tier_nazev FROM " . RD_TABLE_AUTOSKOLY . " a
         LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=a.tier_id
         $where ORDER BY a.nazev ASC LIMIT 100"
    );

    $stav_map = [
        'aktivni'               => ['Aktivní',           '#dcfce7','#15803d'],
        'ceka_schvaleni'        => ['Čeká na schválení', '#fef3c7','#d97706'],
        'ceka_potvrzeni'        => ['Čeká na platbu',    '#dbeafe','#1d4ed8'],
        'predplatne_expirovano' => ['Expirováno',         '#fee2e2','#dc2626'],
        'pozastavena'           => ['Pozastavena',        '#fef3c7','#d97706'],
        'zablokovano'           => ['Zablokováno',        '#fee2e2','#dc2626'],
    ];
    ?>
    <div class="wrap">
    <h1>Správa autoškol</h1>
    <div style="max-width:900px">

    <?php if (!empty($_GET['rd_zprava'])): ?>
    <div style="background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:13px;color:#15803d;font-weight:600">
        <?php echo ['schvalena'=>'✓ Autoškola schválena.','platba_ok'=>'✓ Platba potvrzena.'][$_GET['rd_zprava']] ?? '✓ Hotovo.'; ?>
    </div>
    <?php endif; ?>

    <?php foreach ($cekajici_platby as $p):
        $vs = str_pad($p->autoskola_id, 4, '0', STR_PAD_LEFT) . str_pad($p->id, 6, '0', STR_PAD_LEFT);
    ?>
    <div style="background:#fff;border:1px solid #fde68a;border-left:4px solid #d97706;border-radius:8px;padding:12px 16px;margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;gap:12px">
        <span style="font-size:13px;color:#374151">
            <strong style="color:#1d4ed8"><?php echo esc_html($p->as_nazev); ?></strong>
            — čeká na potvrzení platby balíčku <strong><?php echo esc_html($p->tier_nazev ?? '—'); ?></strong>
            · VS: <code style="font-size:12px;background:#fef3c7;padding:1px 6px;border-radius:3px"><?php echo esc_html($vs); ?></code>
            · <?php echo number_format(round($p->cena_mesic * 1.21)); ?> Kč s DPH
        </span>
        <a href="<?php echo esc_url(admin_url('admin.php?page=refdrive-as-'.$p->autoskola_id)); ?>" style="font-size:12px;color:#d97706;text-decoration:none;white-space:nowrap;flex-shrink:0">Detail →</a>
    </div>
    <?php endforeach; ?>

    <!-- Filtr + hledání -->
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:16px 0 10px">
        <?php foreach (['vse'=>'Vše','ceka'=>'Čekající','aktivni'=>'Aktivní','pozastaveno'=>'Pozastaveno','zablokovano'=>'Zablokováno'] as $k=>$v): ?>
        <a href="<?php echo esc_url(add_query_arg(['filter'=>$k,'hledat'=>$hledat], $base)); ?>"
           class="rd-btn-detail" style="<?php echo $filter===$k ? 'box-shadow:0 0 0 2px #7c3aed;background:#f5f3ff;color:#7c3aed' : ''; ?>"><?php echo $v; ?></a>
        <?php endforeach; ?>
        <form method="get" style="display:flex;gap:6px;margin-left:auto">
            <input type="hidden" name="page" value="refdrive-autoskoly">
            <?php if ($filter !== 'vse'): ?><input type="hidden" name="filter" value="<?php echo esc_attr($filter); ?>"><?php endif; ?>
            <input type="text" name="hledat" value="<?php echo esc_attr($hledat); ?>" placeholder="Hledat název, email, IČ..." style="min-width:220px">
            <button type="submit" class="rd-btn-detail" style="padding:5px 12px;font-size:13px">Hledat</button>
            <?php if ($hledat): ?><a href="<?php echo esc_url(add_query_arg('filter', $filter, $base)); ?>" class="rd-btn-detail" style="padding:5px 10px">×</a><?php endif; ?>
        </form>
    </div>

    <?php if (empty($autoskoly)): ?>
    <p style="color:#999;padding:16px 0">Žádné autoškoly.</p>
    <?php else: ?>
    <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
        <thead><tr>
            <th onclick="rdSortTable(this)">Autoškola</th>
            <th onclick="rdSortTable(this)">Balíček</th>
            <th onclick="rdSortTable(this)">Kapacita</th>
            <th onclick="rdSortTable(this)">Expiruje</th>
            <th onclick="rdSortTable(this)">Registrace</th>
            <th onclick="rdSortTable(this)">Stav</th>
            <th></th>
        </tr></thead>
        <tbody>
        <?php foreach ($autoskoly as $as):
            $zbyvaji = rd_autoskola_zbyvajici_kapacita($as->id);
            $exp_ts  = $as->predplatne_expiruje ? strtotime($as->predplatne_expiruje) : null;
            $exp_dnu = $exp_ts ? ceil(($exp_ts - time()) / 86400) : null;
            $exp_col = $exp_dnu === null ? '#9ca3af' : ($exp_dnu <= 7 ? '#dc2626' : ($exp_dnu <= 14 ? '#d97706' : '#6b7280'));
            $sl = $stav_map[$as->stav] ?? [$as->stav, '#f3f4f6', '#374151'];
        ?>
        <tr>
            <td>
                <a href="<?php echo esc_url(admin_url('admin.php?page=refdrive-as-'.$as->id)); ?>" style="font-weight:700;color:#111827;text-decoration:none"><?php echo esc_html($as->nazev); ?></a>
                <div style="font-size:11px;color:#9ca3af"><?php echo esc_html($as->email); ?></div>
            </td>
            <td style="color:#6b7280"><?php echo esc_html($as->tier_nazev ?? '—'); ?></td>
            <td style="font-weight:700;color:<?php echo $zbyvaji === null ? '#dc2626' : ($zbyvaji === PHP_INT_MAX ? '#6b7280' : ($zbyvaji <= 0 ? '#dc2626' : ($zbyvaji <= 5 ? '#d97706' : '#15803d'))); ?>">
                <?php echo $zbyvaji === PHP_INT_MAX ? '∞' : ($zbyvaji === null ? '0' : number_format($zbyvaji)); ?>
            </td>
            <td style="color:<?php echo $exp_col; ?>" data-val="<?php echo $exp_ts ?? 0; ?>">
                <?php echo $exp_ts ? date('d.m.Y', $exp_ts) : '—'; ?>
                <?php if ($exp_dnu !== null && $exp_dnu <= 14 && $exp_dnu > 0): ?><span style="font-size:10px"> (za <?php echo $exp_dnu; ?> dní)</span><?php endif; ?>
            </td>
            <td style="color:#6b7280;font-size:12px" data-val="<?php echo strtotime($as->vytvoreno); ?>"><?php echo date('d.m.Y', strtotime($as->vytvoreno)); ?></td>
            <td><span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:<?php echo $sl[1]; ?>;color:<?php echo $sl[2]; ?>"><?php echo $sl[0]; ?></span></td>
            <td style="white-space:nowrap">
                <?php if ($as->stav !== 'zablokovano'): ?>
                <a href="<?php echo esc_url(wp_nonce_url(add_query_arg(['rd_as_blokovat'=>$as->id], $base), 'rd_as_blokovat_'.$as->id)); ?>" class="rd-btn-del" style="font-size:11px;padding:3px 8px" onclick="return confirm('Zablokovat <?php echo esc_js($as->nazev); ?>?')">Blokovat</a>
                <?php else: ?>
                <a href="<?php echo esc_url(wp_nonce_url(add_query_arg(['rd_as_odblokovat'=>$as->id], $base), 'rd_as_odblokovat_'.$as->id)); ?>" class="rd-btn-confirm" style="font-size:11px;padding:3px 8px" onclick="return confirm('Odblokovat?')">✓ Odblokovat</a>
                <?php endif; ?>
                <a href="<?php echo esc_url(wp_nonce_url(add_query_arg(['rd_as_smazat'=>$as->id], $base), 'rd_as_smazat_'.$as->id)); ?>" class="rd-btn-del" style="font-size:11px;padding:3px 8px;margin-left:4px" onclick="return confirm('POZOR: Trvale smazat <?php echo esc_js($as->nazev); ?>? NEVRATNÉ.')">Smazat</a>
            </td>
        </tr>
        <?php endforeach; ?>
        </tbody>
    </table>

    <!-- Mobilní karty -->
    <div class="rd-show-mobile" style="display:none">
    <?php foreach ($autoskoly as $as):
        $sl = $stav_map[$as->stav] ?? [$as->stav, '#f3f4f6', '#374151'];
    ?>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
            <div>
                <a href="<?php echo esc_url(admin_url('admin.php?page=refdrive-as-'.$as->id)); ?>" style="font-weight:700;color:#111827;text-decoration:none;font-size:14px"><?php echo esc_html($as->nazev); ?></a>
                <div style="font-size:11px;color:#9ca3af"><?php echo esc_html($as->email); ?></div>
            </div>
            <span style="padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;background:<?php echo $sl[1]; ?>;color:<?php echo $sl[2]; ?>"><?php echo $sl[0]; ?></span>
        </div>
        <div style="font-size:12px;color:#6b7280"><?php echo esc_html($as->tier_nazev ?? '—'); ?> · reg. <?php echo date('d.m.Y', strtotime($as->vytvoreno)); ?></div>
    </div>
    <?php endforeach; ?>
    </div>

    <p style="color:#6b7280;font-size:12px;margin-top:8px">Celkem <?php echo count($autoskoly); ?> autoškol</p>
    <?php endif; ?>

    </div><!-- max-width:900px -->
    </div><!-- .wrap -->
    <?php
}


/* ============================================================
   v6.0.0 — REGISTRACE AUTOŠKOLY (shortcode [rd_registrace_autoskoly])
   ============================================================ */
add_shortcode('rd_registrace_autoskoly', 'rd_sc_registrace_autoskoly');
function rd_sc_registrace_autoskoly() {
    global $wpdb;
    ob_start();

    // Zobrazit stavovou hlášku pokud přišel přesměrovaný uživatel
    if (!empty($_GET['rd_stav'])) {
        $rd_stav = sanitize_key($_GET['rd_stav']);
        if ($rd_stav === 'ceka_schvaleni'): ?>
        <div class="rd-page" style="max-width:520px;margin:0 auto;min-height:60vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:60px 20px">
            <div style="width:80px;height:80px;background:rgba(217,119,6,.12);border-radius:50%;display:flex;align-items:center;justify-content:center;margin-bottom:28px">
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#d97706" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
            </div>
            <h2 style="font-size:1.6rem;font-weight:800;color:var(--au-text-1);margin-bottom:16px">Registrace čeká na schválení</h2>
            <p style="color:var(--au-text-2);line-height:1.7;max-width:400px">Vaše registrace byla přijata a čeká na schválení administrátorem. Jakmile bude schválena, dostanete email s dalšími pokyny.</p>
            <p style="color:var(--au-text-3);font-size:.85rem;margin-top:16px">Obvyklá doba zpracování: 1–2 pracovní dny.</p>
        </div>
        <?php return ob_get_clean();
        elseif ($rd_stav === 'zablokovano'): ?>
        <div class="rd-page" style="max-width:520px;margin:0 auto;min-height:60vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:60px 20px">
            <div style="width:80px;height:80px;background:rgba(220,38,38,.12);border-radius:50%;display:flex;align-items:center;justify-content:center;margin-bottom:28px">
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#dc2626" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
            </div>
            <h2 style="font-size:1.6rem;font-weight:800;color:var(--au-text-1);margin-bottom:16px">Přístup zablokován</h2>
            <p style="color:var(--au-text-2);line-height:1.7;max-width:400px">Váš účet byl zablokován administrátorem. Pro více informací nás kontaktujte na <a href="mailto:<?php echo esc_attr(get_option('rd_faktura_email', get_option('admin_email'))); ?>"><?php echo esc_html(get_option('rd_faktura_email', get_option('admin_email'))); ?></a>.</p>
        </div>
        <?php return ob_get_clean();
        endif;
    }

    $msg = '';
    $ok  = false;

    if (isset($_POST['rd_reg_autoskola']) && check_admin_referer('rd_reg_as_nonce', '_rd_as_nonce')) {
        $nazev   = sanitize_text_field($_POST['nazev'] ?? '');
        $email   = sanitize_email($_POST['email'] ?? '');
        $telefon = sanitize_text_field($_POST['telefon'] ?? '');
        $ico     = sanitize_text_field($_POST['ico'] ?? '');
        $dic     = sanitize_text_field($_POST['dic'] ?? '');
        $ulice   = sanitize_text_field($_POST['ulice'] ?? '');
        $mesto   = sanitize_text_field($_POST['mesto'] ?? '');
        $psc     = sanitize_text_field($_POST['psc'] ?? '');
        $heslo   = $_POST['heslo'] ?? '';
        $heslo2  = $_POST['heslo2'] ?? '';
        $op      = intval($_POST['op_souhlas'] ?? 0);
        $oop_url = esc_url_raw(trim($_POST['oop_url'] ?? ''));

        // Validace
        $chyby = [];
        if (!$nazev) $chyby[] = 'Zadejte název autoškoly.';
        if (!is_email($email)) $chyby[] = 'Zadejte platnou emailovou adresu.';
        if (!$ico || strlen($ico) < 6) $chyby[] = 'Zadejte platné IČ.';
        if (!$ulice || !$mesto || !$psc) $chyby[] = 'Zadejte úplnou adresu (ulice, město, PSČ).';
        if (strlen($heslo) < 8) $chyby[] = 'Heslo musí mít alespoň 8 znaků.';
        if ($heslo !== $heslo2) $chyby[] = 'Hesla se neshodují.';
        if (!$op) $chyby[] = 'Musíte souhlasit s obchodními podmínkami.';
        if (!$oop_url || !filter_var($oop_url, FILTER_VALIDATE_URL)) $chyby[] = 'Zadejte platnou URL adresu vašich obchodních podmínek (musí začínat https://).';
        if (email_exists($email)) $chyby[] = 'Tento email je již registrován.';
        if ($wpdb->get_var($wpdb->prepare("SELECT id FROM " . RD_TABLE_AUTOSKOLY . " WHERE email=%s LIMIT 1", $email))) $chyby[] = 'Autoškola s tímto emailem již existuje.';
        if ($ico && $wpdb->get_var($wpdb->prepare("SELECT id FROM " . RD_TABLE_AUTOSKOLY . " WHERE ico=%s LIMIT 1", $ico))) $chyby[] = 'Autoškola s tímto IČ je již registrována.';

        if ($chyby) {
            $msg = '<div class="rd-alert rd-alert-err"><div class="rd-alert-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg></div><span>' . implode('<br>', array_map('esc_html', $chyby)) . '</span></div>';
        } else {
            // Vytvořit WP uživatele
            $slug = rd_generovat_as_slug($nazev);
            $wp_uid = wp_insert_user([
                'user_login'   => $email,
                'user_email'   => $email,
                'display_name' => $nazev,
                'user_pass'    => $heslo,
                'role'         => 'autoskola_admin',
            ]);

            if (is_wp_error($wp_uid)) {
                $msg = '<div class="rd-alert rd-alert-err"><div class="rd-alert-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg></div><span>' . esc_html($wp_uid->get_error_message()) . '</span></div>';
            } else {
                $wpdb->insert(RD_TABLE_AUTOSKOLY, [
                    'slug'       => $slug,
                    'nazev'      => $nazev,
                    'email'      => $email,
                    'telefon'    => $telefon,
                    'ico'        => $ico,
                    'dic'        => $dic,
                    'ulice'      => $ulice,
                    'mesto'      => $mesto,
                    'psc'        => $psc,
                    'wp_user_id' => $wp_uid,
                    'stav'             => 'ceka_schvaleni',
                    'op_souhlas'       => 1,
                    'op_souhlas_datum' => current_time('mysql'),
                    'op_souhlas_ip'    => rd_get_ip(),
                    'oop_url'          => $oop_url,
                    'oop_url_verze'    => $oop_url,
                ]);
                rd_as_oop_log($as->id ?? 0, $oop_url, 'onboarding');

                // Notifikace hlavnímu adminovi
                $admin_email = rd_admin_notif_email();
                wp_mail($admin_email,
                    'RefDrive: Nová registrace autoškoly — ' . $nazev,
                    rd_email_wrap('Nová autoškola čeká na schválení',
                        '<p>Autoškola <strong>' . esc_html($nazev) . '</strong> (' . esc_html($email) . ', IČ: ' . esc_html($ico) . ') se zaregistrovala a čeká na vaše schválení.</p>'
                         . '<p>Obchodní podmínky autoškoly: <a href="' . esc_url($oop_url) . '">' . esc_html($oop_url) . '</a></p>'
                         . rd_email_btn('Schválit v administraci →', admin_url('admin.php?page=refdrive-autoskoly'))
                    ),
                    ['Content-Type: text/html; charset=UTF-8']
                );

                // Potvrzení autoškole
                rd_email_autoskola($email, 'RefDrive: Registrace přijata',
                    rd_email_wrap('Registrace přijata',
                        '<p>Děkujeme za registraci autoškoly <strong>' . esc_html($nazev) . '</strong>.</p>'
                        . '<p>Vaše registrace čeká na schválení — obvykle to trvá do 1–2 pracovních dnů. Jakmile bude schválena, dostanete email s dalšími pokyny.</p>'
                        . '<p class="rd-hint-text" style="font-size:13px">Pokud do 2 pracovních dnů nedostanete odpověď, napište nám na <a href="mailto:' . esc_attr(get_option('rd_faktura_email', 'info@refdrive.pro')) . '" style="color:#7c3aed">' . esc_html(get_option('rd_faktura_email', 'info@refdrive.pro')) . '</a>.</p>'
                    )
                );

                $ok  = true;
                $msg = '
<div class="rd-page" style="max-width:600px;margin:0 auto;min-height:60vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:60px 20px">
    <div style="width:80px;height:80px;border-radius:50%;background:rgba(52,211,153,.15);display:flex;align-items:center;justify-content:center;margin-bottom:28px">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="var(--rd-green)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
    </div>
    <h2 style="font-size:1.6rem;font-weight:800;color:var(--au-text-1);margin-bottom:16px">Registrace byla úspěšně odeslána!</h2>
    <p style="font-size:1rem;color:var(--au-text-2);line-height:1.7;max-width:400px">Zkontrolujte email — jakmile schválíme vaši registraci, dostanete pokyny k dalšímu postupu.</p>
</div>';
            }
        }
    }

    if ($ok) {
        echo $msg;
        return ob_get_clean();
    }
    ?>
    <div class="rd-page" style="max-width:600px;margin:0 auto">
        <div class="rd-hero-wrap" style="margin-bottom:0;padding-bottom:24px">
