/**
 * Generuje unikátní slug pro autoškolu z jejího názvu.
 */
function rd_generovat_as_slug($nazev) {
    global $wpdb;
    $base = sanitize_title($nazev);
    $base = preg_replace('/[^a-z0-9\-]/', '', $base);
    $base = trim($base, '-') ?: 'autoskola';
    $slug = $base;
    $i = 1;
    while ($wpdb->get_var($wpdb->prepare("SELECT id FROM " . RD_TABLE_AUTOSKOLY . " WHERE slug=%s LIMIT 1", $slug))) {
        $slug = $base . '-' . $i;
        $i++;
    }
    return $slug;
}

/**
 * Zaregistruje WP roli autoskola_admin při aktivaci pluginu.
 */
add_action('init', function() {
    if (!get_role('autoskola_admin')) {
        add_role('autoskola_admin', 'Autoškola Admin', [
            'read'             => true,
            'refdrive_access'  => true,
        ]);
    }
    // Ujistit se že administrator má refdrive_access
    $role = get_role('administrator');
    if ($role && !$role->has_cap('refdrive_access')) {
        $role->add_cap('refdrive_access');
    }
});

/**
 * Wrap pro email notifikace — stejný styl jako stávající emaily.
 */
// Helper pro konzistentní emailové tlačítko (MSO-kompatibilní tabulkový layout)
function rd_email_btn($text, $url, $color = 'primary') {
    $bg = $color === 'secondary' ? '#6b7280' : '#7c3aed';
    return '<table cellpadding="0" cellspacing="0" style="margin:16px 0"><tr>'
        . '<td style="background:' . $bg . ';border-radius:8px;mso-padding-alt:0">'
        . '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="' . esc_url($url) . '" style="height:42px;v-text-anchor:middle;width:220px;" arcsize="10%" stroke="f" fillcolor="' . $bg . '"><w:anchorlock/><center style="color:#ffffff;font-family:Arial,sans-serif;font-size:13px;font-weight:700;">' . esc_html($text) . '</center></v:roundrect><![endif]-->'
        . '<!--[if !mso]><!-->'
        . '<a href="' . esc_url($url) . '" class="em-btn-link" style="display:inline-block;background:' . $bg . ';color:#ffffff!important;font-family:Arial,sans-serif;font-size:13px;font-weight:700;line-height:42px;padding:0 24px;text-decoration:none;border-radius:8px;white-space:nowrap"><span style="color:#ffffff!important">' . esc_html($text) . '</span></a>'
        . '<!--<![endif]-->'
        . '</td></tr></table>';
}

function rd_email_wrap($nadpis, $obsah) {
    $site     = get_bloginfo('name');
    $logo_url = home_url('/');
    $dark_css = '@media(prefers-color-scheme:dark){.em-bg{background:#0d0d14!important}.em-card{background:#1a1728!important;border-color:#2d2a3e!important}.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}.em-muted{color:#9ca3af!important}.em-row td{border-bottom-color:#2d2a3e!important;color:#f1f0fb!important}.em-surface{background:#251f38!important;border-color:#2d2a3e!important}.em-footer{border-top-color:#2d2a3e!important}.em-logo-text{fill:url(#rg-dark)!important}.em-btn-link,.em-btn-link span{color:#ffffff!important}}';

    $html  = '<!DOCTYPE html><html lang="cs"><head><meta charset="UTF-8"><style>' . $dark_css . '</style></head>';
    $html .= '<body style="margin:0;padding:0;font-family:Arial,sans-serif">';
    $html .= '<div class="em-bg" style="background:#f5f5f7;padding:32px 16px">';
    $html .= '<div class="em-card" style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;border:1px solid #e5e7eb;overflow:hidden">';
    $html .= '<div style="height:4px;background:linear-gradient(90deg,#7c3aed,#db2777)"></div>';
    $html .= '<div style="padding:28px 32px 24px">';
    // Logo
    $html .= '<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px"><tr><td>';
    $html .= '<span style="font-family:Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:-0.5px"><span style="color:#7c3aed">ref</span><span style="color:#db2777">drive</span><span style="color:#7c3aed">.pro</span></span>';
    $html .= '<div style="font-size:11px;color:#9ca3af;margin-top:2px">Online školení referentských řidičů</div>';
    $html .= '</td></tr></table>';
    // Obsah
    $html .= '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 16px">' . esc_html($nadpis) . '</h2>';
    $html .= '<div class="em-text" style="font-size:14px;color:#374151;line-height:1.7">' . $obsah . '</div>';
    $html .= '</div>';
    // Footer
    $html .= '<div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb">';
    $html .= '<p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">' . esc_html($site) . ' &mdash; <a href="' . esc_url($logo_url) . '" style="color:#7c3aed">refdrive.pro</a></p>';
    $html .= '</div>';
    $html .= '</div></div></div></body></html>';
    return $html;
}


/* ---- NASTAVENÍ KURZU ---- */
// Handler výběru balíčku autoškoly — musí být v admin_init
add_action('admin_init', function() {
    if (!isset($_POST['rd_as_vybrat_tier'])) return;
    if (!check_admin_referer('rd_as_tier_nonce')) return;
    if (!rd_je_autoskola_admin()) return;
    $as = rd_get_my_autoskola();
    if (!$as) return;
    global $wpdb;

    $tier_id = intval($_POST['tier_id'] ?? 0);
    $tier = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE id=%d AND aktivni=1 LIMIT 1", $tier_id));
    if (!$tier) { wp_safe_redirect(add_query_arg('rd_err', 'tier', admin_url('admin.php?page=refdrive-as-platba'))); exit; }

    // Vytvoř záznam čekající platby
    $wpdb->insert(RD_TABLE_AS_PLATBY, [
        'autoskola_id' => $as->id,
        'tier_id'      => $tier->id,
        'castka'       => $tier->cena_mesic,
        'stav'         => 'ceka_potvrzeni',
        'vytvoreno'    => current_time('mysql'),
    ]);
    $pid = $wpdb->insert_id;
    $vs  = str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($pid, 6, '0', STR_PAD_LEFT);

    // Nastav stav autoškoly — jen pokud ještě není aktivní (první balíček)
    if ($as->stav !== 'aktivni') {
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['stav' => 'ceka_potvrzeni', 'tier_id' => $tier->id], ['id' => $as->id]);
    }

    // Odešli email autoškole s platebními instrukcemi
    $cislo_uctu = get_option('rd_cislo_uctu', '');
    $iban = get_option('rd_iban', '');
    $castka_dph = number_format(round($tier->cena_mesic * 1.21));
    rd_email_autoskola(
        $as->email,
        'RefDrive: Pokyny k platbě balíčku ' . $tier->nazev,
        rd_email_wrap('Platební instrukce',
            '<p>Děkujeme za výběr balíčku <strong>' . esc_html($tier->nazev) . '</strong>.</p>'
            . '<p>Pro aktivaci balíčku prosím proveďte platbu:</p>'
            . '<table style="font-size:14px;border-collapse:collapse;width:100%;max-width:400px">'
            . '<tr><td style="padding:6px 0;color:#6b7280">Částka s DPH</td><td style="font-weight:700">' . $castka_dph . ' Kč</td></tr>'
            . '<tr><td style="padding:6px 0;color:#6b7280">Variabilní symbol</td><td style="font-weight:700">' . esc_html($vs) . '</td></tr>'
            . ($iban ? '<tr><td style="padding:6px 0;color:#6b7280">IBAN</td><td style="font-weight:700">' . esc_html($iban) . '</td></tr>' : '')
            . ($cislo_uctu ? '<tr><td style="padding:6px 0;color:#6b7280">Číslo účtu</td><td style="font-weight:700">' . esc_html($cislo_uctu) . '</td></tr>' : '')
            . '</table>'
            . '<p>Balíček aktivujeme do 2 pracovních dnů po přijetí platby.</p>'
        )
    );

    // Notifikace adminovi
    $admin_email = get_option('rd_admin_notif_email', get_option('admin_email'));
    wp_mail($admin_email,
        'RefDrive: Nová žádost o balíček — ' . $as->nazev,
        rd_email_wrap('Nová žádost o balíček',
            '<p>Autoškola <strong>' . esc_html($as->nazev) . '</strong> požádala o balíček <strong>' . esc_html($tier->nazev) . '</strong>.</p>'
            . '<p>VS: <strong>' . esc_html($vs) . '</strong> · Částka: <strong>' . $castka_dph . ' Kč s DPH</strong></p>'
            . rd_email_btn('Potvrdit platbu →', admin_url('admin.php?page=refdrive-as-' . $as->id))
        ),
        ['Content-Type: text/html; charset=UTF-8']
    );

    wp_safe_redirect(add_query_arg('rd_ok', 'tier', admin_url('admin.php?page=refdrive-as-platba'))); exit;
});

// Handler pro paušální balíčky — musí být v admin_init před výstupem HTML
add_action('admin_init', function() {
    if (!current_user_can('manage_options')) return;
    global $wpdb;

    if (isset($_POST['rd_tier_ulozit']) && check_admin_referer('rd_tier_ulozit')) {
        $id   = intval($_POST['tier_id'] ?? 0);
        $data = [
            'nazev'      => sanitize_text_field($_POST['nazev'] ?? ''),
            'popis'      => sanitize_text_field($_POST['popis'] ?? ''),
            'limit_kodu' => intval($_POST['limit_kodu'] ?? 50),
            'cena_mesic' => intval($_POST['cena_mesic'] ?? 990),
            'poradi'     => intval($_POST['poradi'] ?? 0),
            'aktivni'    => isset($_POST['aktivni']) ? 1 : 0,
        ];
        if ($id) $wpdb->update(RD_TABLE_AS_TIERY, $data, ['id' => $id]);
        else     $wpdb->insert(RD_TABLE_AS_TIERY, $data);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-tiery')); exit;
    }

    if (isset($_GET['rd_tier_smazat']) && wp_verify_nonce($_GET['_wpnonce'] ?? '', 'rd_tier_smazat_' . intval($_GET['rd_tier_smazat']))) {
        $wpdb->delete(RD_TABLE_AS_TIERY, ['id' => intval($_GET['rd_tier_smazat'])]);
        wp_safe_redirect(admin_url('admin.php?page=refdrive-tiery')); exit;
    }
});

