function rd_admin_kurz() { rd_admin_kurz_content(); }
function rd_admin_kurz_content() {
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    global $wpdb;

    if (isset($_POST['rd_reset_lekce']) && check_admin_referer('rd_kurz_nonce')) {
        $wpdb->query("DELETE FROM {$wpdb->prefix}rd_lekce");
        $def_cas = intval(get_option('rd_lekce_default_cas', 180));
        foreach (rd_get_lekce() as $i => $l) {
            $wpdb->insert("{$wpdb->prefix}rd_lekce", [
                'poradi' => $i,
                'nazev'  => $l['nazev'],
                'popis'  => $l['popis'],
                'cas'    => $def_cas,
                'obsah'  => $l['obsah'],
            ]);
        }
        do_action('rd_obsah_resetovan', 'lekce', rd_kdo_resetoval());
        echo '<div class="notice notice-success"><p>Lekce byly resetovány na výchozí obsah z pluginu.</p></div>';
    }

    if (isset($_POST['rd_reset_otazky']) && check_admin_referer('rd_kurz_nonce')) {
        $wpdb->query("DELETE FROM {$wpdb->prefix}rd_otazky");
        foreach (rd_get_otazky() as $i => $o) {
            $wpdb->insert("{$wpdb->prefix}rd_otazky", [
                'poradi'    => $i,
                'otazka'    => $o['otazka'],
                'moznost_a' => $o['moznosti']['A'],
                'moznost_b' => $o['moznosti']['B'],
                'moznost_c' => $o['moznosti']['C'],
                'moznost_d' => $o['moznosti']['D'],
                'spravna'   => $o['spravna'],
            ]);
        }
        do_action('rd_obsah_resetovan', 'otazky', rd_kdo_resetoval());
        echo '<div class="notice notice-success"><p>Testové otázky byly resetovány na výchozí obsah z pluginu.</p></div>';
    }

    if (isset($_POST['rd_save_kurz_cas']) && check_admin_referer('rd_kurz_nonce')) {
        $new_cas = max(1, intval($_POST['rd_lekce_default_cas']));
        update_option('rd_lekce_default_cas', $new_cas);
        // Pokud zaškrtnuto — aktualizovat i existující lekce v DB
        if (!empty($_POST['rd_apply_cas_all'])) {
            $wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}rd_lekce SET cas = %d", $new_cas));
            echo '<div class="notice notice-success"><p>Výchozí čas uložen a aplikován na všechny lekce v databázi.</p></div>';
        } else {
            echo '<div class="notice notice-success"><p>Výchozí čas lekce uložen. Existující lekce nebyly změněny.</p></div>';
        }
    }

    $default_cas = intval(get_option('rd_lekce_default_cas', 180));
    $db_lekce    = intval($wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}rd_lekce"));
    $db_otazky   = intval($wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}rd_otazky"));
    $kod_lekce   = count(rd_get_lekce());
    $kod_otazky  = count(rd_get_otazky());
    ?>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px;margin-bottom:16px">
        <h2>Výchozí čas lekce</h2>
        <p style="color:#666;font-size:13px">Výchozí čas pro nové lekce. Lektor může čas každé lekce změnit individuálně v Portálu lektora.</p>
        <form method="post">
            <?php wp_nonce_field('rd_kurz_nonce'); ?>
            <table class="form-table">
                <tr>
                    <th>Výchozí čas (sekundy)</th>
                    <td>
                        <input type="number" name="rd_lekce_default_cas" value="<?php echo esc_attr($default_cas); ?>" min="1" step="1" class="small-text">
                        <span style="margin-left:8px;color:#666"><?php echo round($default_cas/60,1); ?> min</span>
                        <p class="description">Minimum: 1 s. Doporučené: 120 s (2 min), 180 s (3 min), 240 s (4 min)</p>
                    </td>
                </tr>
            </table>
            <p><label><input type="checkbox" name="rd_apply_cas_all" value="1" style="margin-right:6px">Aplikovat nový čas i na všechny existující lekce v databázi</label></p>
            <input type="submit" name="rd_save_kurz_cas" class="rd-btn-detail" style="padding:6px 14px;font-size:13px" value="Uložit výchozí čas">
        </form>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px;margin-bottom:16px">
        <h2>Reset obsahu kurzu</h2>
        <p style="color:#666;font-size:13px"><strong>Pozor:</strong> Reset přepíše veškeré změny provedené lektorem. Tato akce je nevratná.</p>
        <table class="form-table" style="margin-bottom:16px">
            <tr>
                <th>Lekce v databázi</th>
                <td><strong><?php echo $db_lekce; ?></strong> záznamů &nbsp;|&nbsp; Plugin obsahuje <strong><?php echo $kod_lekce; ?></strong> výchozích lekcí</td>
            </tr>
            <tr>
                <th>Otázky v databázi</th>
                <td><strong><?php echo $db_otazky; ?></strong> záznamů &nbsp;|&nbsp; Plugin obsahuje <strong><?php echo $kod_otazky; ?></strong> výchozích otázek</td>
            </tr>
        </table>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
        <form method="post" onsubmit="return confirm('Resetovat lekce? Tato akce přepíše veškeré změny lektora.')">
            <?php wp_nonce_field('rd_kurz_nonce'); ?>
            <input type="submit" name="rd_reset_lekce" class="rd-btn-detail" style="padding:6px 14px;font-size:13px" value="Resetovat lekce z pluginu">
        </form>
        <form method="post" onsubmit="return confirm('Resetovat testové otázky? Tato akce přepíše veškeré změny.')">
            <?php wp_nonce_field('rd_kurz_nonce'); ?>
            <input type="submit" name="rd_reset_otazky" class="rd-btn-detail" style="padding:6px 14px;font-size:13px" value="Resetovat testové otázky z pluginu">
        </form>
        </div>
    </div>

    <?php
    // Zpráva z import/export redirectu
    $io_msg = get_transient('rd_kurz_io_msg');
    if ($io_msg) {
        delete_transient('rd_kurz_io_msg');
        $color = $io_msg['type'] === 'success' ? 'success' : ($io_msg['type'] === 'warning' ? 'warning' : 'error');
        echo '<div class="notice notice-' . $color . ' is-dismissible" style="margin-top:16px;max-width:700px"><p>' . esc_html($io_msg['text']) . '</p></div>';
    }
    ?>

    <!-- ========== EXPORT / IMPORT LEKCÍ ========== -->
    <div id="io-lekce" style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px;margin-bottom:16px">
        <h2 style="display:flex;align-items:center;gap:8px">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="12" y1="18" x2="12" y2="12"/><line x1="9" y1="15" x2="15" y2="15"/></svg>
