function rd_admin_export() { rd_admin_export_content(); }
function rd_admin_export_content() {
    global $wpdb;

    // ===== IMPORT KOMPLET LEKTORA =====
    if (isset($_POST['rd_do_import_lektor']) && check_admin_referer('rd_export_nonce')) {
        if (empty($_FILES['rd_import_lektor_file']['tmp_name'])) {
            echo '<div class="notice notice-error"><p>Nebyl nahrán žádný soubor.</p></div>';
        } else {
            $json = file_get_contents($_FILES['rd_import_lektor_file']['tmp_name']);
            $data = json_decode($json, true);
            if (!$data || empty($data['_meta']) || ($data['_meta']['typ'] ?? '') !== 'refdrive-lektor-komplet') {
                echo '<div class="notice notice-error"><p>Neplatný soubor — použijte soubor exportovaný přes "Export komplet lektora".</p></div>';
            } else {
                // Lekce
                if (!empty($data['lekce'])) {
                    $wpdb->query("DELETE FROM " . RD_TABLE_LEKCE);
                    foreach ($data['lekce'] as $l) {
                        $wpdb->insert(RD_TABLE_LEKCE, [
                            'poradi' => intval($l['poradi']),
                            'nazev'  => sanitize_text_field($l['nazev']),
                            'popis'  => sanitize_text_field($l['popis']),
                            'cas'    => intval($l['cas']),
                            'obsah'  => wp_kses_post($l['obsah']),
                        ]);
                    }
                }
                // Otázky
                if (!empty($data['otazky'])) {
                    $wpdb->query("DELETE FROM " . RD_TABLE_OTAZKY);
                    foreach ($data['otazky'] as $o) {
                        $wpdb->insert(RD_TABLE_OTAZKY, [
                            'poradi'      => intval($o['poradi']),
                            'otazka'      => sanitize_text_field($o['otazka']),
                            'odpovedi'    => is_array($o['odpovedi']) ? json_encode($o['odpovedi'], JSON_UNESCAPED_UNICODE) : $o['odpovedi'],
                            'spravna'     => sanitize_text_field($o['spravna']),
                            'vysvetleni'  => sanitize_text_field($o['vysvetleni'] ?? ''),
                        ]);
                    }
                }
                // Texty
                if (!empty($data['texty'])) {
                    foreach ($data['texty'] as $k => $v) {
                        if (strpos($k, 'rd_text_') === 0) {
                            update_option(sanitize_key($k), sanitize_textarea_field($v));
                        }
                    }
                }
                $pocet_l = count($data['lekce'] ?? []);
                $pocet_o = count($data['otazky'] ?? []);
                $pocet_t = count($data['texty'] ?? []);
                echo '<div class="notice notice-success"><p>✓ Import dokončen: ' . $pocet_l . ' lekcí, ' . $pocet_o . ' otázek, ' . $pocet_t . ' textů.</p></div>';
            }
        }
    }

    // ===== IMPORT =====
    if (isset($_POST['rd_do_import']) && check_admin_referer('rd_export_nonce')) {
        if (empty($_FILES['rd_import_file']['tmp_name'])) {
            echo '<div class="notice notice-error"><p>Nebyl nahrán žádný soubor.</p></div>';
        } else {
            $json = file_get_contents($_FILES['rd_import_file']['tmp_name']);
            $data = json_decode($json, true);
            if (!$data || empty($data['_meta'])) {
                echo '<div class="notice notice-error"><p>Neplatný soubor zálohy.</p></div>';
            } else {
                $old_url = $data['_meta']['site_url'];
                $new_url = get_option('siteurl');
                $replaced = 0;

                // Funkce pro nahrazení URL
                $replace_url = function($val) use ($old_url, $new_url, &$replaced) {
                    if (is_string($val) && $old_url !== $new_url) {
                        $new = str_replace($old_url, $new_url, $val);
                        if ($new !== $val) $replaced++;
                        return $new;
                    }
                    return $val;
                };

                // 1. Options
                foreach ($data['options'] ?? [] as $k => $v) {
                    if (in_array($k, ['siteurl','home'])) continue; // URL nechat nové
                    update_option($k, $replace_url($v));
                }

                // 2. Stránky
                foreach ($data['pages'] ?? [] as $p) {
                    $existing = get_page_by_path($p['slug']);
                    $post_data = [
                        'post_title'   => $p['title'],
                        'post_name'    => $p['slug'],
                        'post_content' => $replace_url($p['content']),
                        'post_status'  => $p['status'] ?? 'publish',
                        'post_type'    => 'page',
                    ];
                    if ($existing) {
                        $post_data['ID'] = $existing->ID;
                        wp_update_post($post_data);
                    } else {
                        wp_insert_post($post_data);
                    }
                }

                // 3. Plugin tabulky
                $prod_tables = ['rd_kody', 'rd_ridici', 'rd_objednavky']; // produkční data — varovat
                foreach ($data['tables'] ?? [] as $t => $rows) {
                    $full = $wpdb->prefix . $t;
                    $wpdb->query("TRUNCATE TABLE {$full}");
                    foreach ($rows as $row) {
                        foreach ($row as &$v) { $v = $replace_url($v); }
                        $wpdb->insert($full, $row);
                    }
                }

                // 4. Uživatelé — přidat i aktualizovat
                foreach ($data['users'] ?? [] as $u) {
                    $existing = get_user_by('login', $u['login']);
                    if ($existing) {
                        // Aktualizovat existujícího
                        wp_update_user([
                            'ID'           => $existing->ID,
                            'user_email'   => $u['email'],
                            'display_name' => $u['display_name'],
                        ]);
                        $wpdb->update($wpdb->users, ['user_pass' => $u['pass_hash']], ['ID' => $existing->ID]);
                        $existing->set_role('');
                        foreach ($u['roles'] as $role) { $existing->add_role($role); }
                    } else {
                        $uid = wp_insert_user([
                            'user_login'      => $u['login'],
                            'user_email'      => $u['email'],
                            'display_name'    => $u['display_name'],
                            'user_pass'       => wp_generate_password(),
                            'user_registered' => $u['registered'],
                            'role'            => $u['roles'][0] ?? 'subscriber',
                        ]);
                        if (!is_wp_error($uid)) {
                            $wpdb->update($wpdb->users, ['user_pass' => $u['pass_hash']], ['ID' => $uid]);
                            $user_obj = get_user_by('id', $uid);
                            foreach ($u['roles'] as $role) { $user_obj->add_role($role); }
                        }
                    }
                }

                // 5. Menu
                foreach ($data['menus'] ?? [] as $menu_data) {
                    $menu_id = wp_create_nav_menu($menu_data['name']);
                    if (is_wp_error($menu_id)) {
                        $existing_menu = get_term_by('slug', $menu_data['slug'], 'nav_menu');
                        if ($existing_menu) $menu_id = $existing_menu->term_id;
                    }
                    if (!is_wp_error($menu_id) && !empty($menu_data['items'])) {
                        foreach ($menu_data['items'] as $item) {
                            wp_update_nav_menu_item($menu_id, 0, [
                                'menu-item-title'     => $item['title'],
                                'menu-item-url'       => $replace_url($item['url']),
                                'menu-item-status'    => 'publish',
                                'menu-item-type'      => $item['type'] ?? 'custom',
                                'menu-item-parent-id' => 0,
                            ]);
                        }
                    }
                }

                $msg = 'Import dokončen — stránky, tabulky, uživatelé a menu obnoveny.';
                if ($replaced > 0) $msg .= " Nahrazeno {$replaced}× URL ({$old_url} → {$new_url}).";
                echo '<div class="notice notice-success"><p>' . esc_html($msg) . '</p></div>';
            }
        }
    }

    ?>

    <div style="background:#fef3c7;border:1px solid #fde68a;border-radius:8px;padding:12px 16px;margin-bottom:20px;font-size:12px;color:#92400e">
        ⚠️ <strong>Bezpečnost:</strong> Záloha obsahuje SMTP heslo a hash hesel uživatelů. Uchovávejte soubor na bezpečném místě.
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px">

        <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px">
            <h2 style="font-size:14px;font-weight:700;margin:0 0 6px">⬇ Export zálohy</h2>
            <p style="color:#6b7280;font-size:12px;margin:0 0 14px">Stáhne kompletní zálohu — nastavení plateb, emailů, SMTP, autoškoly, paušální balíčky, kódy, objednávky, firmy, žádosti o změny, lekce, otázky, WP uživatele a menu.</p>
            <form method="post">
                <?php wp_nonce_field('rd_export_nonce'); ?>
                <button type="submit" name="rd_do_export" class="rd-btn-confirm" style="padding:6px 14px;font-size:13px">⬇ Stáhnout zálohu</button>
            </form>
        </div>

        <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:20px">
            <h2 style="font-size:14px;font-weight:700;margin:0 0 6px">⬆ Import zálohy</h2>
            <p style="color:#6b7280;font-size:12px;margin:0 0 14px"><strong style="color:#dc2626">Pozor:</strong> Přepíše stávající data. Nejdřív exportujte zálohu.</p>
            <form method="post" enctype="multipart/form-data">
                <?php wp_nonce_field('rd_export_nonce'); ?>
                <input type="file" name="rd_import_file" accept=".json" style="display:block;margin-bottom:10px;font-size:12px">
                <button type="submit" name="rd_do_import" class="rd-btn-del" style="padding:6px 14px;font-size:13px">⬆ Importovat zálohu</button>
            </form>
        </div>



    </div><!-- /grid -->
