function rd_admin_reset() { rd_admin_reset_content(); }
function rd_admin_reset_content() {
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    global $wpdb;

    if (isset($_POST['rd_reset_data']) && check_admin_referer('rd_reset_nonce')) {
        $co = $_POST['reset_co'] ?? [];

        if (in_array('ridici', $co)) {
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_RIDICI);
        }
        if (in_array('kody', $co)) {
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_KODY);
        }
        if (in_array('objednavky', $co)) {
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_OBJ);
            $wpdb->query("TRUNCATE TABLE {$wpdb->prefix}rd_poptavky");
        }
        if (in_array('firmy', $co)) {
            $wpdb->query("TRUNCATE TABLE {$wpdb->prefix}rd_firmy");
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_FIRMA_AS);
            $wpdb->query("TRUNCATE TABLE {$wpdb->prefix}rd_cena_zmeny");
        }
        if (in_array('autoskoly', $co)) {
            // Smazat WP uživatele s rolí autoskola_admin
            $as_users = $wpdb->get_col(
                "SELECT user_id FROM {$wpdb->usermeta} WHERE meta_key='{$wpdb->prefix}capabilities' AND meta_value LIKE '%autoskola_admin%'"
            );
            foreach ($as_users as $uid) wp_delete_user(intval($uid));

            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_AUTOSKOLY);
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_AS_PLATBY);
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_FIRMA_AS);
            $wpdb->query("TRUNCATE TABLE {$wpdb->prefix}rd_cena_zmeny");
            $wpdb->query("TRUNCATE TABLE " . RD_TABLE_ZMENY);
        }        if (in_array('firmy', $co) || in_array('autoskoly', $co) || in_array('kody', $co) || in_array('ridici', $co)) {
            // Zneplatnit aktivní session (smaže session soubory)
            $session_path = session_save_path() ?: sys_get_temp_dir();
            if (is_dir($session_path)) {
                foreach (glob($session_path . '/sess_*') as $f) {
                    $data = file_get_contents($f);
                    if ($data && (strpos($data, 'rd_firma_id') !== false || strpos($data, 'rd_kod') !== false || strpos($data, 'rd_lektor') !== false)) {
                        @unlink($f);
                    }
                }
            }
        }

        $smazano = implode(', ', array_map(function($k) {
            return ['ridici'=>'Řidiči','kody'=>'Kódy','objednavky'=>'Objednávky','firmy'=>'Firmy','autoskoly'=>'Autoškoly + WP uživatelé'][$k] ?? $k;
        }, $co));
        echo '<div class="notice notice-success"><p><strong>Reset dokončen.</strong> Smazáno: ' . esc_html($smazano) . '</p></div>';
    }

    // Počty záznamů
    $pocty = [
        'autoskoly'  => (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_AUTOSKOLY),
        'kody'       => (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_KODY),
        'ridici'     => (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI),
        'firmy'      => (int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}rd_firmy"),
        'objednavky' => (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_OBJ),
        'poptavky'   => (int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}rd_poptavky"),
        'zmeny'      => (int)$wpdb->get_var("SELECT COUNT(*) FROM " . RD_TABLE_ZMENY),
    ];
    ?>
