// Globální export absolventů za zvolené období
add_action('admin_post_rd_export_absolventi_all', function() {
    if (!current_user_can('manage_options')) wp_die('Přístup odepřen');
    check_admin_referer('rd_export_abs_all');
    global $wpdb;
    $od  = sanitize_text_field($_GET['od'] ?? date('Y-01-01'));
    $do  = sanitize_text_field($_GET['do'] ?? date('Y-m-d'));
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename=absolventi-' . $od . '-' . $do . '.csv');
    $f = fopen('php://output', 'w');
    fprintf($f, chr(0xEF).chr(0xBB).chr(0xBF));
    fputcsv($f, ['Jméno','Firma','Email firmy','Autoškola','Kód','Score (%)','Datum'], ';');
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT r.*, a.nazev as as_nazev FROM " . RD_TABLE_RIDICI . " r
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=r.autoskola_id
         WHERE r.uspech=1 AND r.datum_skoleni BETWEEN %s AND %s
         ORDER BY r.datum_skoleni DESC",
        $od . ' 00:00:00', $do . ' 23:59:59'
    ));
    foreach ($rows as $r) fputcsv($f, [$r->jmeno, $r->firma_nazev, $r->firma_email, $r->as_nazev ?? '—', $r->kod, $r->score, date('d.m.Y H:i', strtotime($r->datum_skoleni))], ';');
    fclose($f); exit;
});

add_action('admin_post_rd_export_absolventi', function() {
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) wp_die('Přístup odepřen');
    global $wpdb;
    $data = $wpdb->get_results("SELECT * FROM " . RD_TABLE_RIDICI . " ORDER BY datum_skoleni DESC");
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename=absolventi.csv');
    $f = fopen('php://output', 'w'); fprintf($f, chr(0xEF).chr(0xBB).chr(0xBF));
    fputcsv($f, ['Jméno','Firma','Email','Kód','Score (%)','Výsledek','Datum'], ';');
    foreach ($data as $r) fputcsv($f, [$r->jmeno,$r->firma_nazev,$r->firma_email,$r->kod,$r->score,$r->uspech?'Splnil':'Nesplnil',date('d.m.Y H:i',strtotime($r->datum_skoleni))], ';');
    fclose($f); exit;
});

add_action('admin_post_rd_export_firma', function() {
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) wp_die('Přístup odepřen');
    global $wpdb;
    $email = sanitize_email($_GET['firma'] ?? '');
    $data  = $wpdb->get_results($wpdb->prepare("SELECT k.*, COALESCE(k.ridic_jmeno,r.jmeno) as jmeno_ridice, r.score, r.uspech FROM " . RD_TABLE_KODY . " k LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.kod=k.kod WHERE k.firma_email=%s ORDER BY k.vytvoreno DESC", $email));
    $nazev = $data ? $data[0]->firma_nazev : $email;
    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename=kody-' . sanitize_title($nazev) . '.csv');
    $f = fopen('php://output', 'w'); fprintf($f, chr(0xEF).chr(0xBB).chr(0xBF));
    fputcsv($f, ['Kód','Vygenerován','Stav','Jméno řidiče','Score (%)','Test','Použit'], ';');
    foreach ($data as $k) fputcsv($f, [$k->kod,date('d.m.Y H:i',strtotime($k->vytvoreno)),$k->pouzit?'Použit':'Volný',$k->jmeno_ridice??'—',$k->score??'—',$k->pouzit?($k->uspech===null?'Probíhá':($k->uspech?'Splnil':'Nesplnil')):'—',$k->datum_pouziti?date('d.m.Y H:i',strtotime($k->datum_pouziti)):'—'], ';');
    fclose($f); exit;
});


/* ---- AKTUALIZACE MENU POLOŽEK ---- */
add_action('init', function() {
    // Přejmenovat "Pro firmy" na "Firemní přístup" a opravit odkaz v menu
    $menus = wp_get_nav_menus();
    foreach ($menus as $menu) {
        $items = wp_get_nav_menu_items($menu->term_id);
        if (!$items) continue;
        foreach ($items as $item) {
            $changed = false;
            $args = [
                'menu-item-title'  => $item->title,
                'menu-item-url'    => $item->url,
                'menu-item-status' => 'publish',
            ];
            if ($item->title === 'Pro firmy') {
                $args['menu-item-title'] = 'Firemní přístup';
                $changed = true;
            }
            if (strpos($item->url, 'pro-zamestnavatele') !== false) {
                $args['menu-item-url'] = home_url('/firma-portal/');
                $changed = true;
            }
            if ($changed) {
                wp_update_nav_menu_item($menu->term_id, $item->ID, $args);
            }
        }
    }
}, 20);

