// ── Rozeslání kódů zaměstnancům ──────────────────────────────────────────────
add_action('wp_ajax_rd_rozeslat_kody', 'rd_ajax_rozeslat_kody');
add_action('wp_ajax_nopriv_rd_rozeslat_kody', 'rd_ajax_rozeslat_kody');
function rd_ajax_rozeslat_kody() {
    ob_start(); // zachytit případné PHP warnings/notices před JSON outputem
    if (!session_id()) @session_start();

    global $wpdb;
    $firma_email = !empty($_SESSION['rd_firma_email'])
        ? $_SESSION['rd_firma_email']
        : sanitize_email($_POST['firma_email'] ?? '');
    if (!$firma_email) { ob_end_clean(); wp_send_json_error('not_logged_in'); }

    // Ověř že firma skutečně existuje v DB
    $firma_row = $wpdb->get_row($wpdb->prepare(
        "SELECT nazev FROM {$wpdb->prefix}rd_firmy WHERE email=%s LIMIT 1", $firma_email
    ));
    if (!$firma_row) { ob_end_clean(); wp_send_json_error('not_logged_in'); }

    $firma_nazev = !empty($_SESSION['rd_firma_nazev']) ? $_SESSION['rd_firma_nazev'] : ($firma_row->nazev ?? '');

    $zamestnanci = json_decode(stripslashes($_POST['zamestnanci'] ?? '[]'), true);
    if (!is_array($zamestnanci) || empty($zamestnanci)) { ob_end_clean(); wp_send_json_error('no_data'); }

    // Deduplikace emailů v importu
    $seen_emails = [];
    $zamestnanci_clean = [];
    foreach ($zamestnanci as $z) {
        $email_norm = strtolower(trim($z['email'] ?? ''));
        if (!$email_norm) continue;
        if (isset($seen_emails[$email_norm])) continue; // duplicita v CSV
        $seen_emails[$email_norm] = true;
        $zamestnanci_clean[] = $z;
    }

    // Zjisti emaily které již mají přiřazený kód nebo již absolvovaly
    $uz_prirazen = $wpdb->get_col($wpdb->prepare(
        "SELECT LOWER(zamestnanec_email) FROM " . RD_TABLE_KODY .
        " WHERE firma_email=%s AND pouzit=0 AND zamestnanec_email IS NOT NULL AND zamestnanec_email!=''",
        $firma_email
    ));
    $uz_absolvoval = $wpdb->get_col($wpdb->prepare(
        "SELECT LOWER(firma_email) FROM " . RD_TABLE_RIDICI .
        " WHERE firma_email=%s AND uspech=1",
        $firma_email
    ));
    // Absolventi – potřebujeme emaily ze zamestnanec_email
    $uz_absolvoval_emails = $wpdb->get_col($wpdb->prepare(
        "SELECT LOWER(k.zamestnanec_email) FROM " . RD_TABLE_KODY . " k
         INNER JOIN " . RD_TABLE_RIDICI . " r ON r.kod=k.kod AND r.uspech=1
         WHERE k.firma_email=%s AND k.zamestnanec_email IS NOT NULL AND k.zamestnanec_email!=''",
        $firma_email
    ));
    $uz_prirazen = array_map('strtolower', $uz_prirazen);
    $uz_absolvoval_emails = array_map('strtolower', $uz_absolvoval_emails);

    // Odfiltruj přeskočené – vrátí výsledky pro ně, zbývající pošle
    $vysledky = [];
    $k_odeslani = [];
    foreach ($zamestnanci_clean as $z) {
        $email_norm = strtolower(trim($z['email'] ?? ''));
        if (in_array($email_norm, $uz_absolvoval_emails)) {
            $vysledky[] = ['jmeno' => $z['jmeno'], 'email' => $z['email'], 'stav' => 'absolvoval', 'msg' => 'Přeskočeno — zaměstnanec již absolvoval školení'];
        } elseif (in_array($email_norm, $uz_prirazen)) {
            $vysledky[] = ['jmeno' => $z['jmeno'], 'email' => $z['email'], 'stav' => 'prirazen', 'msg' => 'Přeskočeno — zaměstnanec již má přiřazený kód (lze znovu odeslat z tabulky)'];
        } else {
            $k_odeslani[] = $z;
        }
    }

    // Načti volné kódy firmy (nepoužité, bez přiřazeného zaměstnance)
    $volne_kody = $wpdb->get_results($wpdb->prepare(
        "SELECT id, kod, expiruje FROM " . RD_TABLE_KODY .
        " WHERE firma_email=%s AND pouzit=0 AND (zamestnanec_email IS NULL OR zamestnanec_email='') ORDER BY vytvoreno ASC",
        $firma_email
    ));

    if (empty($k_odeslani)) {
        // Vše přeskočeno – vrátit přeskočené záznamy jako výsledek
        ob_end_clean();
        wp_send_json_success(['vysledky' => $vysledky]);
        return;
    }

    if (count($volne_kody) < count($k_odeslani)) {
        ob_end_clean(); wp_send_json_error(['msg' => 'Nemáte dostatek volných kódů. Máte ' . count($volne_kody) . ' volných, zadali jste ' . count($k_odeslani) . ' nových zaměstnanců.']);
    }

    foreach ($k_odeslani as $i => $z) {
        $jmeno = sanitize_text_field($z['jmeno'] ?? '');
        $email  = sanitize_email($z['email'] ?? '');
        if (!$jmeno || !is_email($email)) {
            $vysledky[] = ['jmeno' => $jmeno, 'email' => $email, 'stav' => 'chyba', 'msg' => 'Neplatné jméno nebo e-mail'];
            continue;
        }
        $kod_row = array_values($volne_kody)[$i];
        $kod = $kod_row->kod;

        // Nejdřív sestavit a odeslat e-mail — kód přiřadíme až po úspěšném odeslání
        $token = $wpdb->get_var($wpdb->prepare("SELECT token FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
        $odkaz = home_url('/kurz/?token=' . $token);
        $expiruje = $kod_row->expiruje ? date('d.m.Y', strtotime($kod_row->expiruje)) : '—';

        $predmet = 'Váš přístup ke školení referentských řidičů — ' . $firma_nazev;
        $html = rd_email_wrap(
            'Školení referentských řidičů',
            '<p style="margin:0 0 20px">Dobrý den, <strong>' . esc_html($jmeno) . '</strong>,</p>'
            . '<p>Váš zaměstnavatel <strong>' . esc_html($firma_nazev) . '</strong> vám zpřístupnil online školení referentských řidičů. Prosíme, absolvujte ho co nejdříve.</p>'
            . '<table width="100%" cellpadding="0" cellspacing="0" style="margin:16px 0"><tbody>'
            . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Přístupový kód</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb;color:#7c3aed;letter-spacing:1px">' . esc_html($kod) . '</td></tr>'
            . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280">Platnost do</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#111827">' . $expiruje . '</td></tr>'
            . '</tbody></table>'
            . rd_email_btn('Zahájit školení →', $odkaz)
            . '<p style="font-size:12px;color:#6b7280;margin-top:16px">Odkaz funguje i bez zadání kódu.</p>'
        );
        $ok = wp_mail($email, $predmet, $html, ['Content-Type: text/html; charset=UTF-8']);

        if ($ok) {
            // Email odeslán — teprve teď přiřadit kód zaměstnanci
            $wpdb->update(RD_TABLE_KODY, [
                'zamestnanec_jmeno' => $jmeno,
                'zamestnanec_email' => $email,
                'kod_odeslan_at'    => current_time('mysql'),
            ], ['id' => $kod_row->id]);
            $vysledky[] = ['jmeno' => $jmeno, 'email' => $email, 'kod' => $kod, 'stav' => 'ok', 'msg' => 'Odesláno'];
        } else {
            // Email selhal — kód zůstane volný, firma může zkusit znovu
            $vysledky[] = ['jmeno' => $jmeno, 'email' => $email, 'stav' => 'chyba_smtp', 'msg' => 'Chyba při odesílání e-mailu — kód nebyl přiřazen, zkuste znovu'];
        }
    }
    ob_end_clean(); // vyčistit buffer před JSON odpovědí
    wp_send_json_success(['vysledky' => $vysledky]);
}

// ── Upload obrázku lekce (lektor) ────────────────────────────────────────────
add_action('wp_ajax_rd_upload_lekce_obrazek',        'rd_ajax_upload_lekce_obrazek');
add_action('wp_ajax_nopriv_rd_upload_lekce_obrazek', 'rd_ajax_upload_lekce_obrazek');
function rd_ajax_upload_lekce_obrazek() {
    if (!session_id()) @session_start();
    // Ověřit že je přihlášen lektor nebo admin
    if (empty($_SESSION['rd_lektor']) && !current_user_can('manage_options')) {
        wp_send_json_error('Nemáte oprávnění.');
    }

    // Pomocná funkce — smazat starý obrázek z media library podle URL
    $smazat_stary = function($url) {
        if (!$url) return;
        $att_id = attachment_url_to_postid($url);
        if ($att_id) wp_delete_attachment($att_id, true);
    };

    // Akce: odstranit obrázek
    if (($_POST['rezim'] ?? '') === 'odstranit') {
        $smazat_stary(esc_url_raw($_POST['stary_url'] ?? ''));
        wp_send_json_success(['url' => '']);
    }

    if (empty($_FILES['obrazek'])) {
        wp_send_json_error('Žádný soubor.');
    }

    $file = $_FILES['obrazek'];
    // Kontrola typu
    $povolene = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
    $finfo = finfo_open(FILEINFO_MIME_TYPE);
    $mime  = finfo_file($finfo, $file['tmp_name']);
    finfo_close($finfo);
    if (!in_array($mime, $povolene)) {
        wp_send_json_error('Povolené formáty: JPG, PNG, WebP, GIF.');
    }
    // Limit velikosti 5 MB
    if ($file['size'] > 5 * 1024 * 1024) {
        wp_send_json_error('Maximální velikost je 5 MB.');
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';

    $overrides = ['test_form' => false];
    $moved = wp_handle_upload($file, $overrides);

    if (isset($moved['error'])) {
        wp_send_json_error($moved['error']);
    }

    // Vytvořit přílohu v media library
    $attachment = [
        'post_mime_type' => $moved['type'],
        'post_title'     => sanitize_file_name(pathinfo($moved['file'], PATHINFO_FILENAME)),
        'post_content'   => '',
        'post_status'    => 'inherit',
    ];
    $attach_id = wp_insert_attachment($attachment, $moved['file']);
    if ($attach_id) {
        $meta = wp_generate_attachment_metadata($attach_id, $moved['file']);
        wp_update_attachment_metadata($attach_id, $meta);
    }

    // Smazat předchozí obrázek pokud byl nahraný (zabránit hromadění)
    $smazat_stary(esc_url_raw($_POST['stary_url'] ?? ''));

    wp_send_json_success(['url' => $moved['url']]);
}


add_action('wp_ajax_rd_objednavka_prevod',        'rd_ajax_objednavka_prevod');
add_action('wp_ajax_nopriv_rd_objednavka_prevod', 'rd_ajax_objednavka_prevod');
// Notifikace původní autoškoly když firma skutečně objedná jinde
function rd_notifikovat_puvodni_autoskolu($firma_email, $firma_nazev, $nova_as_id) {
    global $wpdb;
    // Najít poptávky této firmy ve stavu zrusena_ceka u jiných autoškol
    $poptavky = $wpdb->get_results($wpdb->prepare(
        "SELECT p.*, a.email as_email FROM {$wpdb->prefix}rd_poptavky p
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=p.autoskola_id
         WHERE p.firma_email=%s AND p.stav='zrusena_ceka' AND p.autoskola_id != %d",
        $firma_email, $nova_as_id
    ));
    foreach ($poptavky as $p) {
        $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'zrusena_firmou'], ['id' => $p->id]);
        if ($p->as_email) {
            rd_email_autoskola($p->as_email,
                'RefDrive: Firma objednala u jiné autoškoly',
                rd_email_wrap('Firma zrušila čekání',
                    '<p>Firma <strong>' . esc_html($firma_nazev) . '</strong> čekala na obnovení vaší kapacity, ale mezitím uskutečnila objednávku u jiné autoškoly.</p>'
                    . '<p style="font-size:13px;color:#6b7280">Pokud plánujete navýšit balíček, tato poptávka již není aktivní.</p>'
                    . rd_email_btn('Správa balíčku →', admin_url('admin.php?page=refdrive-as-platba'))
                )
            );
        }
    }
}

function rd_ajax_objednavka_prevod() {
    ob_start();
    global $wpdb;

    $raw  = stripslashes($_POST['data'] ?? '{}');
    $d    = json_decode($raw, true);
    if (!is_array($d)) { ob_end_clean(); wp_send_json_error('Neplatná data'); }

    $pocet = intval($d['pocet'] ?? 1);
    $email = sanitize_email($d['firma_email'] ?? '');
    $nazev = sanitize_text_field($d['firma_nazev'] ?? '');
    $as_id = intval($d['autoskola_id'] ?? 0);

    if ($pocet < 1 || !$email || !$nazev) { ob_end_clean(); wp_send_json_error('Neplatná data'); }

    // Načíst cenu z autoškoly
    $cena = intval(get_option('rd_cena_kus', 99));
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        $as_cena = $wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1", $as_id
        ));
        if ($as_cena > 0) $cena = intval($as_cena);
    }

    // Kontrola kapacity
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        $zbyvajici = rd_autoskola_zbyvajici_kapacita($as_id);
        if ($zbyvajici !== null && $pocet > $zbyvajici) {
            ob_end_clean();
            wp_send_json_error('Autoškola nemá dostatek kapacity. Zbývá ' . $zbyvajici . ' kódů.');
        }
    }

    $d['cena'] = $cena;
    $oop_snap  = $as_id ? (string)$wpdb->get_var($wpdb->prepare("SELECT oop_url FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id)) : '';
    $oop_verze_snap = $as_id ? (string)$wpdb->get_var($wpdb->prepare("SELECT oop_verze FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id)) : '';

    // Uložit objednávku
    $wpdb->insert(RD_TABLE_OBJ, [
        'pi_id'             => 'PREVOD-TMP-' . time(),
        'firma_nazev'       => $nazev,
        'firma_email'       => $email,
        'pocet'             => $pocet,
        'stav'              => 'prevod_ceka',
        'autoskola_id'      => $as_id ?: null,
        'data'              => json_encode($d),
        'oop_url_snapshot'  => $oop_snap,
        'oop_verze_snapshot' => $oop_verze_snap,
        'oop_souhlas_datum' => current_time('mysql'),
        'oop_souhlas_ip'    => rd_get_ip(),
    ]);
    $obj_id = $wpdb->insert_id;
    if (!$obj_id) { ob_end_clean(); wp_send_json_error('Chyba při ukládání objednávky'); }

    $vs = str_pad($as_id, 3, '0', STR_PAD_LEFT) . str_pad($obj_id, 7, '0', STR_PAD_LEFT);
    $wpdb->update(RD_TABLE_OBJ, ['pi_id' => 'PREVOD-' . $vs], ['id' => $obj_id]);

    // Platební údaje
    $castka     = $pocet * $cena;
    $castka_dph = round($castka * 1.21);
    $splatnost  = 14;
    $cislo_uctu = get_option('rd_cislo_uctu', '—');
    $iban       = rd_get_iban(get_option('rd_cislo_uctu', ''), get_option('rd_iban', ''));
    $bic        = get_option('rd_bic', '');
    $banka      = get_option('rd_banka', '');

    if ($as_id && !empty($as_row = $wpdb->get_row($wpdb->prepare(
        "SELECT cislo_uctu, iban, bic, banka, splatnost FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id
    )))) {
        if ($as_row->cislo_uctu) $cislo_uctu = $as_row->cislo_uctu;
        if ($as_row->iban)       $iban = rd_get_iban($as_row->cislo_uctu, $as_row->iban);
        if ($as_row->bic)        $bic  = $as_row->bic;
        if ($as_row->banka)      $banka = $as_row->banka;
        if ($as_row->splatnost)  $splatnost = intval($as_row->splatnost);
    }

    $splatnost_datum = date('d.m.Y', strtotime('+' . $splatnost . ' days'));

    // Email firmě
    $telo = rd_email_wrap('Objednávka přijata',
        '<p>Dobrý den, <strong>' . esc_html($nazev) . '</strong>,</p>'
        . '<p>Vaši objednávku jsme zaevidovali. Po připsání platby vám zašleme přístupové kódy.</p>'
        . '<table width="100%" cellpadding="0" cellspacing="0" style="margin:16px 0"><tbody>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Počet kódů</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb">' . $pocet . ' ks</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Cena s DPH</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb">' . number_format($castka_dph, 0, ',', ' ') . ' Kč</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Číslo účtu</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($cislo_uctu) . '</td></tr>'
        . ($iban ? '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">IBAN</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb">' . esc_html($iban) . '</td></tr>' : '')
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Variabilní symbol</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb">' . $vs . '</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280">Splatnost</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right">' . $splatnost_datum . '</td></tr>'
        . '</tbody></table>'
    );

    $_from   = get_option('rd_smtp_from', get_option('admin_email'));
    $_fname  = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $_fname . ' <' . $_from . '>'];
    wp_mail($email, 'Objednávka přijata – ' . $nazev, $telo, $headers);

    // Notifikace adminu
    $notif      = get_option('rd_notif_email', get_option('admin_email'));
    $admin_telo = rd_email_admin_prevod($nazev, $email, $pocet, $castka_dph, $vs);
    wp_mail($notif, 'Nová objednávka převodem – ' . $nazev, $admin_telo, $headers);

    // Notifikovat původní autoškoly kde firma čekala (stav zrusena_ceka)
    if ($as_id) rd_notifikovat_puvodni_autoskolu($email, $nazev, $as_id);

    ob_end_clean();
    wp_send_json_success(['vs' => $vs]);
}

// ── Přeřadit kód jinému zaměstnanci ─────────────────────────────────────────
add_action('wp_ajax_rd_priradit_kod', 'rd_ajax_priradit_kod');
add_action('wp_ajax_nopriv_rd_priradit_kod', 'rd_ajax_priradit_kod');
function rd_ajax_priradit_kod() {
    ob_start();
    if (!session_id()) @session_start();

    global $wpdb;
    $firma_email = !empty($_SESSION['rd_firma_email'])
        ? $_SESSION['rd_firma_email']
        : sanitize_email($_POST['firma_email'] ?? '');
    if (!$firma_email) { ob_end_clean(); wp_send_json_error('not_logged_in'); }

    $kod         = sanitize_text_field($_POST['kod'] ?? '');
    $nove_jmeno  = sanitize_text_field($_POST['nove_jmeno'] ?? '');
    $novy_email  = sanitize_email($_POST['novy_email'] ?? '');

    if (!$kod || !$nove_jmeno || !is_email($novy_email)) {
        ob_end_clean(); wp_send_json_error('invalid_data');
    }

    // Ověř že kód patří firmě a ještě není použit
    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s AND firma_email=%s AND pouzit=0",
        $kod, $firma_email
    ));
    if (!$row) { ob_end_clean(); wp_send_json_error('not_found'); }

    $firma_nazev    = $_SESSION['rd_firma_nazev'] ?? '';
    $puvodni_jmeno  = $row->zamestnanec_jmeno ?? '';
    $puvodni_email  = $row->zamestnanec_email ?? '';
    $expiruje       = $row->expiruje ? date('d.m.Y', strtotime($row->expiruje)) : '—';
    $odkaz          = home_url('/kurz/?token=' . $row->token);

    // 1. Notifikace původnímu zaměstnanci
    if ($puvodni_email && is_email($puvodni_email)) {
        $html_puvodni = rd_email_wrap(
            'Přístup ke školení zrušen',
            '<p>Dobrý den, <strong>' . esc_html($puvodni_jmeno) . '</strong>,</p>'
            . '<p>Váš přístupový kód <strong>' . esc_html($kod) . '</strong> ke školení referentských řidičů od zaměstnavatele <strong>' . esc_html($firma_nazev) . '</strong> byl zrušen a přeřazen jinému zaměstnanci.</p>'
            . '<p style="font-size:12px;color:#6b7280">Pokud si myslíte, že jde o chybu, kontaktujte svého zaměstnavatele.</p>'
        );
        wp_mail($puvodni_email, 'Přístup ke školení byl zrušen — ' . $firma_nazev, $html_puvodni, ['Content-Type: text/html; charset=UTF-8']);
    }

    // 2. Email novému zaměstnanci
    $html_novy = rd_email_wrap(
        'Školení referentských řidičů',
        '<p style="margin:0 0 20px">Dobrý den, <strong>' . esc_html($nove_jmeno) . '</strong>,</p>'
        . '<p>Váš zaměstnavatel <strong>' . esc_html($firma_nazev) . '</strong> vám zpřístupnil online školení referentských řidičů. Prosíme, absolvujte ho co nejdříve.</p>'
        . '<table width="100%" cellpadding="0" cellspacing="0" style="margin:16px 0"><tbody>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Přístupový kód</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb;color:#7c3aed;letter-spacing:1px">' . esc_html($kod) . '</td></tr>'
        . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280">Platnost do</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#111827">' . $expiruje . '</td></tr>'
        . '</tbody></table>'
        . rd_email_btn('Zahájit školení →', $odkaz)
        . '<p style="font-size:12px;color:#6b7280;margin-top:16px">Odkaz funguje i bez zadání kódu.</p>'
    );
    $ok = wp_mail($novy_email, 'Váš přístup ke školení referentských řidičů — ' . $firma_nazev, $html_novy, ['Content-Type: text/html; charset=UTF-8']);

    if ($ok) {
        $wpdb->update(RD_TABLE_KODY, [
            'zamestnanec_jmeno' => $nove_jmeno,
            'zamestnanec_email' => $novy_email,
            'kod_odeslan_at'    => current_time('mysql'),
        ], ['id' => $row->id]);
        ob_end_clean();
        wp_send_json_success(['msg' => 'Kód přeřazen a e-mail odeslán.']);
    } else {
        ob_end_clean();
        wp_send_json_error(['msg' => 'Chyba při odesílání e-mailu novému zaměstnanci.']);
    }
}

// ── Znovu odeslat kód zaměstnanci ────────────────────────────────────────────
add_action('wp_ajax_rd_znovu_odeslat_kod', 'rd_ajax_znovu_odeslat_kod');
add_action('wp_ajax_nopriv_rd_znovu_odeslat_kod', 'rd_ajax_znovu_odeslat_kod');
function rd_ajax_znovu_odeslat_kod() {
    if (!session_id()) @session_start();

    global $wpdb;
    $firma_email = !empty($_SESSION['rd_firma_email'])
        ? $_SESSION['rd_firma_email']
        : sanitize_email($_POST['firma_email'] ?? '');
    if (!$firma_email) { wp_send_json_error('not_logged_in'); }
    $kod = sanitize_text_field($_POST['kod'] ?? '');

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s AND firma_email=%s AND pouzit=0",
        $kod, $firma_email
    ));
    if (!$row || !$row->zamestnanec_email) { wp_send_json_error('not_found'); }

    $token = $row->token;
    $odkaz = home_url('/kurz/?token=' . $token);
    $expiruje = $row->expiruje ? date('d.m.Y', strtotime($row->expiruje)) : '—';
    $firma_nazev = $_SESSION['rd_firma_nazev'] ?? '';

    $predmet = 'Váš přístup ke školení referentských řidičů — ' . $firma_nazev;
    $html = rd_email_wrap(
        'Školení referentských řidičů',
        '<p style="margin:0 0 20px">Dobrý den, <strong>' . esc_html($row->zamestnanec_jmeno) . '</strong>,</p>'
        . '<p>Zasíláme vám připomenutí přístupu ke školení od <strong>' . esc_html($firma_nazev) . '</strong>.</p>'
        . '<table width="100%" cellpadding="0" cellspacing="0" style="margin:16px 0"><tbody>'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Přístupový kód</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;border-bottom:1px solid #e5e7eb;color:#7c3aed;letter-spacing:1px">' . esc_html($kod) . '</td></tr>'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280">Platnost do</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#111827">' . $expiruje . '</td></tr>'
        . '</tbody></table>'
        . rd_email_btn('Zahájit školení →', $odkaz)
    );
    $ok = wp_mail($row->zamestnanec_email, $predmet, $html, ['Content-Type: text/html; charset=UTF-8']);

    if ($ok) {
        $wpdb->update(RD_TABLE_KODY, ['kod_odeslan_at' => current_time('mysql')], ['id' => $row->id]);
    }
    wp_send_json_success(['ok' => $ok]);
}
add_action('wp_ajax_rd_pripocti_cas', 'rd_ajax_pripocti_cas');
function rd_ajax_pripocti_cas() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    if (!isset($_SESSION['rd_kod'])) { wp_send_json_error('not_logged_in'); }
    $sekund = intval($_POST['sekundy'] ?? 0);
    // Sanitní limit — jedno volání nemůže přidat víc než 5 minut (chrání proti
    // odeslání nesmyslné hodnoty, např. po probuzení zařízení ze spánku).
    if ($sekund < 1 || $sekund > 300) { wp_send_json_error('invalid'); }
    global $wpdb;
    $kod = $_SESSION['rd_kod'];
    $wpdb->query($wpdb->prepare(
        "UPDATE " . RD_TABLE_KODY . " SET aktivni_cas_sec = aktivni_cas_sec + %d WHERE kod=%s",
        $sekund, $kod
    ));
    wp_send_json_success(['ok' => true]);
}

add_action('wp_ajax_nopriv_rd_dokoncit_lekci', 'rd_ajax_dokoncit_lekci');
add_action('wp_ajax_rd_dokoncit_lekci', 'rd_ajax_dokoncit_lekci');
function rd_ajax_dokoncit_lekci() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    if (!isset($_SESSION['rd_kod'])) { wp_send_json_error('not_logged_in'); }
    $n = intval($_POST['lekce'] ?? 0);
    $max_lekci = count(rd_lekce_source());
    if ($n < 1 || $n > $max_lekci) { wp_send_json_error('invalid'); }
    $kod = $_SESSION['rd_kod'];
    // Uložit dokončenou lekci do DB (do tabulky kódů jako JSON)
    global $wpdb;
    $row = $wpdb->get_row($wpdb->prepare("SELECT lekce_done FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
    $done = $row && $row->lekce_done ? json_decode($row->lekce_done, true) : [];
    if (!in_array($n, $done)) $done[] = $n;
    $wpdb->update(RD_TABLE_KODY, ['lekce_done' => json_encode($done)], ['kod' => $kod]);
    $celkem_lekci = count(rd_lekce_source());
    $vse = count($done) >= $celkem_lekci;
    if ($vse) { $_SESSION['rd_kurz_done'] = $kod; }
    wp_send_json_success(['done' => $done, 'all' => $vse]);
}

add_action('wp_ajax_nopriv_rd_get_progress', 'rd_ajax_get_progress');
add_action('wp_ajax_rd_get_progress', 'rd_ajax_get_progress');
function rd_ajax_get_progress() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    if (!isset($_SESSION['rd_kod'])) { wp_send_json_success(['done' => []]); }
    global $wpdb;
    $row = $wpdb->get_row($wpdb->prepare("SELECT lekce_done FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
    $done = $row && $row->lekce_done ? json_decode($row->lekce_done, true) : [];
    $celkem_lekci = count(rd_lekce_source());
    wp_send_json_success(['done' => $done, 'all' => count($done) >= $celkem_lekci]);
}


// ============================================================
//   INLINE EDITACE — jen pro přihlášeného lektora
// ============================================================

function rd_get_text($key, $default) {
    return get_option('rd_text_' . $key, $default);
}

function rd_editable($key, $default, $class = '') {
    return esc_html(rd_get_text($key, $default));
}

add_action('wp_ajax_rd_save_text', function() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    if (!wp_verify_nonce($_POST['nonce'] ?? '', 'rd_inline_edit')) {
        wp_send_json_error('Neplatný nonce');
    }
    if (empty($_SESSION['rd_lektor'])) {
        wp_send_json_error('Nejste přihlášen jako lektor');
    }
    $key = sanitize_key($_POST['key'] ?? '');
    $val = sanitize_textarea_field($_POST['val'] ?? '');
    if (!$key) wp_send_json_error('Chybí klíč');
    update_option('rd_text_' . $key, $val);
    wp_send_json_success(['val' => $val]);
});

// REST API endpoint jako alternativa
add_action('rest_api_init', function() {
    register_rest_route('refdrive/v1', '/save-text', [
        'methods'  => 'POST',
        'callback' => function($req) {
            if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
            if (empty($_SESSION['rd_lektor'])) {
                return new WP_Error('forbidden', 'Nejste lektor', ['status' => 403]);
            }
            // Číst z POST body (form-encoded)
            $params = $req->get_body_params();
            $key = sanitize_key($params['key'] ?? '');
            $val = sanitize_textarea_field($params['val'] ?? '');
            if (!$key) return new WP_Error('bad_request', 'Chybí klíč', ['status' => 400]);
            update_option('rd_text_' . $key, $val);
            return new WP_REST_Response(['success' => true, 'val' => $val], 200);
        },
        'permission_callback' => '__return_true',
    ]);
});

add_action('wp_footer', function() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    if (empty($_SESSION['rd_lektor'])) return;
    $nonce = wp_create_nonce('rd_inline_edit');
    $ajax  = admin_url('admin-ajax.php');
    ?>
