<div id="rd-edit-overlay">
  <div id="rd-edit-box">
    <label>Upravit text</label>
    <textarea id="rd-edit-field" rows="3"></textarea>
    <p class="rd-edit-hint">Pouze obsah — font a vzhled se nemění.</p>
    <div class="rd-edit-actions">
      <button class="rd-cancel-btn" onclick="rdCloseEdit()">Zrušit</button>
      <button class="rd-save-btn" id="rd-save-btn" onclick="rdSaveEdit()">Uložit</button>
    </div>
  </div>
</div>
<script>
var rdCurrentWrap=null;
function rdOpenEdit(btn){rdCurrentWrap=btn.closest('.rd-inline-wrap');document.getElementById('rd-edit-field').value=rdCurrentWrap.dataset.val;document.getElementById('rd-edit-overlay').classList.add('active');setTimeout(function(){document.getElementById('rd-edit-field').focus();},50);}
function rdCloseEdit(){document.getElementById('rd-edit-overlay').classList.remove('active');rdCurrentWrap=null;}
function rdSaveEdit(){if(!rdCurrentWrap)return;var key=rdCurrentWrap.dataset.key;var val=document.getElementById('rd-edit-field').value.trim();var btn=document.getElementById('rd-save-btn');btn.disabled=true;btn.textContent='Ukládám…';var body='action=rd_save_text&nonce=<?php echo $nonce; ?>&key='+encodeURIComponent(key)+'&val='+encodeURIComponent(val);fetch('<?php echo esc_url(rest_url('refdrive/v1/save-text')); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-WP-Nonce':'<?php echo wp_create_nonce("wp_rest"); ?>'},body:body}).then(function(r){return r.json();}).then(function(d){if(d.val){rdCurrentWrap.childNodes[0].textContent=d.val;rdCurrentWrap.dataset.val=d.val;rdCloseEdit();}else{alert('Chyba: '+JSON.stringify(d));}btn.disabled=false;btn.textContent='Uložit';}).catch(function(e){alert('Fetch error: '+e);btn.disabled=false;btn.textContent='Uložit';});}
document.getElementById('rd-edit-overlay').addEventListener('click',function(e){if(e.target===this)rdCloseEdit();});
</script>
    <?php
});





function rd_vygenerovat_kody_test($email, $headers, $start, $logo, $end) {
    $kody_test = ['TST-AABBCC', 'TST-DDEEFF', 'TST-GGHHII'];
    $telo  = $start . $logo;
    $telo .= '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 8px">Přístupové kódy ke školení</h2>';
    $telo .= '<p class="em-muted" style="font-size:14px;color:#6b7280;margin:0 0 24px;line-height:1.6">Platba byla přijata. Níže najdete přístupové kódy pro vaše zaměstnance.</p>';
    $telo .= '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-bottom:20px">';
    $telo .= '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Firma</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb;color:#111827">Testovací firma s.r.o.</td></tr>';
    $telo .= '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280">Počet kódů</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#111827">3 ks</td></tr>';
    $telo .= '</table>';
    $telo .= '<div class="em-surface" style="background:#f9f8ff;border:1px solid #e5e7eb;border-radius:8px;padding:16px 20px;margin-bottom:20px">';
    $telo .= '<p style="font-size:11px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px" class="em-label">Přístupové kódy</p>';
    $telo .= '<pre class="em-text" style="margin:0;font-family:monospace;font-size:13px;line-height:2;background:none;border:none;padding:0;color:#111827">' . implode("
", $kody_test) . '</pre>';
    $telo .= '</div>';
    $telo .= '<p class="em-muted" style="font-size:13px;color:#6b7280;margin:0">Každý kód je jednorázový.</p>';
    $telo .= $end;
    wp_mail($email, 'TEST: Přístupové kódy ke školení', $telo, $headers);
}

function rd_email_admin_prevod($nazev, $email, $pocet, $castka, $vs) {
    $start = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>@media(prefers-color-scheme:dark){.em-bg{background:#0d0d14!important}.em-card{background:#1a1728!important;border-color:#2d2a3e!important}.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}.em-muted{color:#9ca3af!important}.em-row td{border-bottom-color:#2d2a3e!important;color:#f1f0fb!important}.em-footer{border-top-color:#2d2a3e!important}}</style></head><body style="margin:0;padding:0;font-family:Arial,sans-serif"><div class="em-bg" style="background:#f5f5f7;padding:32px 16px"><div class="em-card" style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;border:1px solid #e5e7eb;overflow:hidden"><div style="height:4px;background:linear-gradient(90deg,#7c3aed,#db2777)"></div><div style="padding:28px 32px 24px">';
    $logo = '<a href="https://refdrive.pro" style="text-decoration:none;display:block;margin-bottom:20px"><span style="font-family:Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:-0.5px"><span style="color:#7c3aed">ref</span><span style="color:#db2777">drive</span><span style="color:#7c3aed">.pro</span></span><div style="font-size:11px;color:#9ca3af;margin-top:2px">Online školení referentských řidičů</div></a>';
    $end = '</div><div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb"><p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">Automaticky odesláno systémem <strong>refdrive.pro</strong></p></div></div></div></body></html>';
    $body = '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 8px">Nová objednávka převodem</h2>'
          . '<p class="em-muted" style="font-size:14px;color:#6b7280;margin:0 0 24px;line-height:1.6">Zákazník objednal školení a zvolil platbu bankovním převodem. Po přijetí platby potvrďte objednávku v administraci.</p>'
          . '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">'
          . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Firma</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . esc_html($nazev) . '</td></tr>'
          . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Email</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . esc_html($email) . '</td></tr>'
          . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Počet kódů</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . intval($pocet) . ' ks</td></tr>'
          . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Variabilní symbol</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . esc_html($vs) . '</td></tr>'
          . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;font-weight:500" class="em-text">Celkem s DPH</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#7c3aed">' . intval($castka) . ' Kč</td></tr>'
          . '</table>';
    return $start . $logo . $body . $end;
}


