/* ============================================================
   v6.0.0 — AUTOŠKOLA: STRÁNKA VÝBĚRU / OBNOVY BALÍČKU
   ============================================================ */
function rd_admin_as_platba() {
    if (!rd_je_autoskola_admin()) wp_die('Přístup odepřen');
    $as = rd_get_my_autoskola();
    if (!$as) wp_die('Autoškola nenalezena');

    global $wpdb;

    // Uložit platební a fakturační údaje autoškoly
    if (isset($_POST['rd_as_save_platba']) && check_admin_referer('rd_as_platba_nonce_' . $as->id)) {
        $wpdb->update(RD_TABLE_AUTOSKOLY, [
            'faktura_nazev' => sanitize_text_field($_POST['faktura_nazev'] ?? ''),
            'faktura_ico'   => sanitize_text_field($_POST['faktura_ico']   ?? ''),
            'faktura_ulice' => sanitize_text_field($_POST['faktura_ulice'] ?? ''),
            'faktura_mesto' => sanitize_text_field($_POST['faktura_mesto'] ?? ''),
            'faktura_psc'   => sanitize_text_field($_POST['faktura_psc']   ?? ''),
            'cislo_uctu'    => sanitize_text_field($_POST['cislo_uctu']    ?? ''),
            'iban'          => sanitize_text_field($_POST['iban']           ?? ''),
            'bic'           => sanitize_text_field($_POST['bic']            ?? ''),
            'banka'         => sanitize_text_field($_POST['banka']          ?? ''),
            'splatnost'     => max(1, intval($_POST['splatnost']            ?? 14)),
            'faktura_pozn'  => sanitize_textarea_field($_POST['faktura_pozn'] ?? ''),
        ], ['id' => $as->id]);
        $as = rd_get_my_autoskola();
        echo '<div class="notice notice-success"><p>Platební a fakturační údaje uloženy.</p></div>';
    }

    // Uložit cenu za kód
    if (isset($_POST['rd_as_save_cena']) && check_admin_referer('rd_as_cena_nonce_' . $as->id)) {
        $nova_cena  = max(1, intval($_POST['cena_kus'] ?? 99));
        $stara_cena = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d", $as->id
        ));
        $wpdb->update(RD_TABLE_AUTOSKOLY, ['cena_kus' => $nova_cena], ['id' => $as->id]);
        rd_as_cena_log($as->id, $nova_cena);
        // Obnovit $as
        $as = rd_get_my_autoskola();

        if ($nova_cena !== $stara_cena && $stara_cena > 0) {
            $kmenove_firmy = $wpdb->get_results($wpdb->prepare(
                "SELECT f.id, f.nazev, f.email FROM {$wpdb->prefix}rd_firmy f
                 INNER JOIN " . RD_TABLE_FIRMA_AS . " fa ON fa.firma_id=f.id
                 WHERE fa.autoskola_id=%d AND fa.kmenova=1", $as->id
            ));
            $from  = get_option('rd_smtp_from', get_option('admin_email'));
            $fname = get_option('rd_smtp_from_name', get_bloginfo('name'));
            $emaily_odeslano = 0;
            foreach ($kmenove_firmy as $firma) {
                // Zjistit nákupní cenu z poslední objednávky
                $nakupni_cena = 0;
                $last_obj = $wpdb->get_results($wpdb->prepare(
                    "SELECT data FROM " . RD_TABLE_OBJ . "
                     WHERE autoskola_id=%d AND firma_email=%s AND stav IN ('zaplaceno','hotovo','prevod_ok')
                     ORDER BY vytvoreno DESC LIMIT 1",
                    $as->id, $firma->email
                ));
                if ($last_obj) {
                    $ld = json_decode($last_obj[0]->data ?? '{}', true);
                    $nakupni_cena = intval($ld['cena'] ?? 0);
                }
                if (!$nakupni_cena) continue;
                $novy_smer = $nova_cena > $nakupni_cena ? 'drazsi' : ($nova_cena < $nakupni_cena ? 'levnejsi' : null);
                if (!$novy_smer) continue;
                $posledni = $wpdb->get_row($wpdb->prepare(
                    "SELECT stav FROM {$wpdb->prefix}rd_cena_zmeny WHERE autoskola_id=%d AND firma_id=%d ORDER BY id DESC LIMIT 1",
                    $as->id, $firma->id
                ));
                if ($posledni && $posledni->stav === $novy_smer) continue;
                $wpdb->insert("{$wpdb->prefix}rd_cena_zmeny", [
                    'autoskola_id' => $as->id, 'firma_id' => $firma->id,
                    'stara_cena'   => $nakupni_cena, 'nova_cena' => $nova_cena,
                    'lhuta_do'     => date('Y-m-d', strtotime('+365 days')),
                    'stav'         => $novy_smer,
                ]);
                $telo = rd_email_wrap('Změna ceny školení',
                    '<p>Dobrý den,</p>'
                    . '<p>autoškola <strong>' . esc_html($as->nazev) . '</strong> upravila cenu školení.</p>'
                    . ($novy_smer === 'drazsi'
                        ? '<p>Při příštím nákupu kódů zaplatíte <strong>více než při Vašem posledním nákupu</strong>. Aktuální cenu uvidíte v objednávkovém formuláři.</p>'
                        : '<p>Při příštím nákupu kódů zaplatíte <strong>méně než při Vašem posledním nákupu</strong>. Vaše stávající kódy jsou plně funkční.</p>'
                    )
                );
                wp_mail($firma->email, 'Změna ceny školení — ' . $as->nazev, $telo,
                    ['Content-Type: text/html; charset=UTF-8', 'From: ' . $fname . ' <' . $from . '>']
                );
                $emaily_odeslano++;
            }
            $msg = 'Cena změněna na <strong>' . $nova_cena . ' Kč</strong>.';
            if ($emaily_odeslano > 0) $msg .= ' Notifikace odeslána ' . $emaily_odeslano . ' firmám.';
            echo '<div class="notice notice-warning"><p>' . $msg . '</p></div>';
        } else {
            echo '<div class="notice notice-success"><p>Cena za kód uložena: <strong>' . intval($as->cena_kus) . ' Kč</strong>.</p></div>';
        }
    }

    // Starter je dostupný pouze v onboarding wizardu — ve změně balíčku ho skryjeme
    $starter_id = $wpdb->get_var("SELECT id FROM " . RD_TABLE_AS_TIERY . " WHERE nazev='Starter' LIMIT 1");
    $tiery = $wpdb->get_results("SELECT * FROM " . RD_TABLE_AS_TIERY . " WHERE aktivni=1 AND (nazev != 'Starter') ORDER BY poradi ASC");
    $aktivni_platby_pb = rd_autoskola_aktivni_platby($as->id);
    $celkem_zbyvaji_pb = rd_autoskola_zbyvajici_kapacita($as->id);
    $posledni_platba = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_AS_PLATBY . " WHERE autoskola_id=%d ORDER BY id DESC LIMIT 1",
        $as->id
    ));
    $cekajici_platba = $wpdb->get_row($wpdb->prepare(
        "SELECT p.*, t.nazev as tier_nazev FROM " . RD_TABLE_AS_PLATBY . " p LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id WHERE p.autoskola_id=%d AND p.stav='ceka_potvrzeni' ORDER BY p.id DESC LIMIT 1",
        $as->id
    ));
    $cislo_uctu = get_option('rd_cislo_uctu', '');
    $iban = rd_get_iban(get_option('rd_cislo_uctu', ''), get_option('rd_iban', ''));
    $vs = $posledni_platba ? str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($posledni_platba->id, 6, '0', STR_PAD_LEFT) : str_pad($as->id, 4, '0', STR_PAD_LEFT) . '??????';
    ?>
    <div class="wrap">
    <h1>Správa balíčků — <?php echo esc_html($as->nazev); ?></h1>

    <?php if ($as->stav === 'aktivni' && !empty($aktivni_platby_pb)): ?>
    <div class="card" style="padding:24px;margin-top:16px;border-left:4px solid #16a34a;max-width:900px">
        <h2 style="color:#16a34a;display:flex;align-items:center;gap:8px;margin-top:0">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
            <?php if($celkem_zbyvaji_pb === PHP_INT_MAX): ?>Neomezená kapacita<?php else: ?>Zbývá celkem: <strong><?php echo number_format($celkem_zbyvaji_pb); ?> kódů</strong><?php endif; ?>
        </h2>
        <?php if($celkem_zbyvaji_pb !== PHP_INT_MAX): ?>
        <table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:8px">
            <?php foreach($aktivni_platby_pb as $ap_pb):
                $limit_pb = (int)$ap_pb->limit_kodu;
                $zbyvaji_pb = (int)$ap_pb->zbyvaji;
                $pct_pb = $limit_pb > 0 ? min(100, round(($limit_pb - $zbyvaji_pb) / $limit_pb * 100)) : 0;
                $do_pb = strtotime($ap_pb->platnost_do);
                $dnu = ceil(($do_pb - time()) / 86400);
            ?>
            <tr style="border-top:1px solid #e5e7eb">
                <td style="padding:6px 0;font-weight:600"><?php echo esc_html($ap_pb->tier_nazev); ?></td>
                <td style="padding:6px 8px">
                    <div style="display:flex;align-items:center;gap:8px">
                        <div style="width:100px;background:#f3f4f6;border-radius:99px;height:5px;overflow:hidden">
                            <div style="height:100%;width:<?php echo $pct_pb; ?>%;background:<?php echo $pct_pb>=90?'#dc2626':($pct_pb>=70?'#d97706':'#16a34a'); ?>;border-radius:99px"></div>
                        </div>
                        <span style="font-size:12px;color:#6b7280">zbývá <strong><?php echo number_format($zbyvaji_pb); ?></strong> z <?php echo number_format($limit_pb); ?></span>
                    </div>
                </td>
                <td style="padding:6px 0;font-size:12px;color:<?php echo $dnu<=7?'#dc2626':($dnu<=14?'#d97706':'#6b7280'); ?>;text-align:right;white-space:nowrap">
                    vyprší <?php echo date('d.m.Y', $do_pb); ?><?php if($dnu<=14): ?> <strong>(za <?php echo $dnu; ?> dní)</strong><?php endif; ?>
                </td>
            </tr>
            <?php endforeach; ?>
        </table>
        <?php endif; ?>
    </div>
    <?php endif; ?>

    <?php if ($cekajici_platba): ?>
    <div class="card" style="padding:24px;margin-top:16px;border-left:4px solid #2563eb;max-width:900px">
        <h2 style="color:#2563eb;display:flex;align-items:center;gap:8px;margin-top:0">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#2563eb" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
            Čeká na potvrzení platby: <?php echo esc_html($cekajici_platba->tier_nazev); ?>
        </h2>
        <p style="font-size:13px;color:#374151;margin:0 0 12px">Proforma faktura byla odeslána na <strong><?php echo esc_html($as->email); ?></strong>. Jakmile platba dorazí na účet, aktivujeme balíček — obvykle do 2 pracovních dnů.</p>
        <?php $vs_cek = str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($cekajici_platba->id, 6, '0', STR_PAD_LEFT); ?>
        <table class="widefat" style="font-size:13px;max-width:400px">
            <tr><th>Balíček</th><td><strong><?php echo esc_html($cekajici_platba->tier_nazev); ?></strong></td></tr>
            <tr><th>Částka s DPH</th><td><strong><?php echo number_format(round($cekajici_platba->castka * 1.21)); ?> Kč</strong> / měsíc</td></tr>
            <tr><th>Variabilní symbol</th><td><strong><?php echo esc_html($vs_cek); ?></strong></td></tr>
        </table>
    </div>
    <?php endif; ?>

    <div class="card" style="max-width:900px;padding:24px;margin-top:16px">
        <h2><?php echo $as->stav === 'aktivni' ? 'Změnit balíček' : 'Vyberte balíček'; ?></h2>
        <p style="color:#666;font-size:13px;margin-bottom:20px">Ceny jsou bez DPH. Fakturaci zajišťuje RefDrive.pro. Po výběru obdržíte platební instrukce.</p>
        <form method="post">
            <?php wp_nonce_field('rd_as_tier_nonce'); ?>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin-bottom:20px">
            <?php foreach ($tiery as $t):
                $je_aktivni = ($aktualni_tier && $aktualni_tier->id == $t->id && $as->stav === 'aktivni');
            ?>
            <label style="border:2px solid <?php echo $je_aktivni ? '#16a34a' : '#e5e7eb'; ?>;border-radius:12px;padding:20px;cursor:pointer;text-align:center;transition:border-color .15s;<?php echo $je_aktivni ? 'background:#f0fdf4' : ''; ?>">
                <input type="radio" name="tier_id" value="<?php echo $t->id; ?>" style="display:none" <?php checked($je_aktivni); ?> required>
                <div style="font-weight:800;font-size:15px;color:#111827;margin-bottom:4px"><?php echo esc_html($t->nazev); ?></div>
                <div style="font-size:12px;color:#6b7280;margin-bottom:12px"><?php echo esc_html($t->popis); ?></div>
                <div style="font-size:24px;font-weight:900;color:#7c3aed"><?php echo number_format($t->cena_mesic); ?> Kč</div>
                <div style="font-size:11px;color:#9ca3af;margin-bottom:12px">/měsíc</div>
                <div style="background:#f3f4f6;border-radius:6px;padding:6px;font-size:12px;color:#374151">
                    <?php echo $t->limit_kodu >= 99999 ? '∞ neomezený počet kódů' : number_format($t->limit_kodu) . ' kódů / měsíc'; ?>
                </div>
                <?php if ($je_aktivni): ?><div style="color:#16a34a;font-size:12px;font-weight:700;margin-top:8px;display:flex;align-items:center;gap:4px"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg> Aktivní</div><?php endif; ?>
            </label>
            <?php endforeach; ?>
            </div>
            <button type="submit" name="rd_as_vybrat_tier" class="rd-btn-detail" style="font-size:13px;padding:7px 16px">Vybrat balíček →</button>
        </form>
    </div>
    <?php
    // Historie plateb balíčků
    $historie = $wpdb->get_results($wpdb->prepare(
        "SELECT p.*, t.nazev as tier_nazev, t.limit_kodu, t.popis as tier_popis, t.cena_mesic as tier_cena FROM " . RD_TABLE_AS_PLATBY . " p
         LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id
         WHERE p.autoskola_id=%d ORDER BY p.id DESC",
        $as->id
    ));
    if (!empty($historie)): ?>
    <div class="card" style="max-width:900px;padding:24px;margin-top:16px">
        <h2 style="margin-top:0">Historie objednávek</h2>
        <!-- Desktop tabulka -->
        <table class="widefat rd-sortable rd-hide-mobile" style="font-size:13px">
            <thead>
                <tr>
                    <th onclick="rdSortTable(this)">Balíček</th>
                    <th onclick="rdSortTable(this)">Limit kódů</th>
                    <th onclick="rdSortTable(this)">Cena / měsíc</th>
                    <th onclick="rdSortTable(this)">Variabilní symbol</th>
                    <th onclick="rdSortTable(this)">Platnost od</th>
                    <th onclick="rdSortTable(this)">Platnost do</th>
                    <th onclick="rdSortTable(this)">Stav</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
            <?php foreach ($historie as $h):
                $dnes = time();
                $do_ts = $h->platnost_do ? strtotime($h->platnost_do) : null;
                $vs_h  = str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($h->id, 6, '0', STR_PAD_LEFT);
                if ($h->stav === 'zaplaceno' && $do_ts && $do_ts < $dnes) $stav_label = '<span style="font-size:12px;font-weight:600;color:#6b7280;background:#f3f4f6;padding:3px 10px;border-radius:99px">Vypršelo</span>';
                elseif ($h->stav === 'zaplaceno') $stav_label = '<span style="font-size:12px;font-weight:600;color:#16a34a;background:#dcfce7;padding:3px 10px;border-radius:99px">✓ Aktivní</span>';
                elseif ($h->stav === 'ceka_potvrzeni') $stav_label = '<span style="font-size:12px;font-weight:600;color:#d97706;background:#fef3c7;padding:3px 10px;border-radius:99px">Čeká na platbu</span>';
                else $stav_label = '<span style="font-size:12px;color:#6b7280;background:#f3f4f6;padding:3px 10px;border-radius:99px">' . esc_html($h->stav) . '</span>';
                $expiry_warning = $do_ts && $h->stav === 'zaplaceno' && ($do_ts - $dnes) < 14 * 86400 && $do_ts > $dnes;
            ?>
            <tr style="<?php echo $expiry_warning ? 'background:#fffbeb' : ''; ?>">
                <td><strong><?php echo esc_html($h->tier_nazev ?: '—'); ?></strong><div style="font-size:11px;color:#9ca3af"><?php echo date('d.m.Y', strtotime($h->vytvoreno)); ?></div></td>
                <td><?php echo $h->limit_kodu >= 99999 ? '∞ Neomezený' : number_format($h->limit_kodu) . ' / měsíc'; ?></td>
                <td><?php echo number_format(round($h->castka * 1.21)); ?> Kč s DPH<div style="font-size:11px;color:#9ca3af"><?php echo number_format($h->castka); ?> Kč bez DPH</div></td>
                <td><code style="font-size:12px"><?php echo esc_html($vs_h); ?></code></td>
                <td><?php echo $h->platnost_od ? date('d.m.Y', strtotime($h->platnost_od)) : '—'; ?></td>
                <td><?php if ($h->platnost_do): echo date('d.m.Y', strtotime($h->platnost_do)); if ($expiry_warning): ?> <span style="color:#d97706;font-size:11px;font-weight:600">⚠ za <?php echo ceil(($do_ts - $dnes) / 86400); ?> dní</span><?php endif; else: ?>—<?php endif; ?></td>
                <td><?php echo $stav_label; ?></td>
                <td><?php if ($h->stav === 'zaplaceno'): ?><a href="<?php echo esc_url(rd_faktura_url($h->id, $as->id)); ?>" target="_blank" style="display:inline-flex;align-items:center;gap:4px;font-size:12px;color:#374151;text-decoration:none;border:1px solid #d1d5db;border-radius:4px;padding:3px 9px;white-space:nowrap">📄 Faktura</a><?php endif; ?></td>
            </tr>
            <?php endforeach; ?>
            </tbody>
        </table>
        <!-- Mobilní karty -->
        <div class="rd-show-mobile" style="display:none">
            <?php foreach ($historie as $h):
                $dnes = time();
                $do_ts = $h->platnost_do ? strtotime($h->platnost_do) : null;
                $vs_h  = str_pad($as->id, 4, '0', STR_PAD_LEFT) . str_pad($h->id, 6, '0', STR_PAD_LEFT);
                if ($h->stav === 'zaplaceno' && $do_ts && $do_ts < $dnes) { $stav_label = 'Vypršelo'; $stav_c = '#6b7280'; $stav_bg = '#f3f4f6'; }
                elseif ($h->stav === 'zaplaceno') { $stav_label = '✓ Aktivní'; $stav_c = '#16a34a'; $stav_bg = '#dcfce7'; }
                elseif ($h->stav === 'ceka_potvrzeni') { $stav_label = 'Čeká na platbu'; $stav_c = '#d97706'; $stav_bg = '#fef3c7'; }
                else { $stav_label = $h->stav; $stav_c = '#6b7280'; $stav_bg = '#f3f4f6'; }
                $expiry_warning = $do_ts && $h->stav === 'zaplaceno' && ($do_ts - $dnes) < 14 * 86400 && $do_ts > $dnes;
            ?>
            <div style="border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin-bottom:10px;background:#fff">
                <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">
                    <div>
                        <strong style="font-size:14px"><?php echo esc_html($h->tier_nazev ?: '—'); ?></strong>
                        <div style="font-size:11px;color:#9ca3af;margin-top:2px"><?php echo date('d.m.Y', strtotime($h->vytvoreno)); ?></div>
                    </div>
                    <span style="font-size:12px;font-weight:600;color:<?php echo $stav_c; ?>;background:<?php echo $stav_bg; ?>;padding:3px 10px;border-radius:99px;white-space:nowrap"><?php echo $stav_label; ?></span>
                </div>
                <div style="font-size:13px;display:flex;flex-direction:column;gap:5px;margin-bottom:10px">
                    <div style="display:flex;justify-content:space-between">
                        <span style="color:#6b7280">Cena</span>
                        <span><strong><?php echo number_format(round($h->castka * 1.21)); ?> Kč</strong> <span style="color:#9ca3af;font-size:11px">s DPH</span></span>
                    </div>
                    <div style="display:flex;justify-content:space-between">
                        <span style="color:#6b7280">Limit</span>
                        <span><?php echo $h->limit_kodu >= 99999 ? '∞ Neomezený' : number_format($h->limit_kodu) . ' kódů / měsíc'; ?></span>
                    </div>
                    <div style="display:flex;justify-content:space-between">
                        <span style="color:#6b7280">Platnost</span>
                        <span>
                            <?php echo $h->platnost_od ? date('d.m.Y', strtotime($h->platnost_od)) : '—'; ?>
                            <?php if ($h->platnost_do): ?> → <?php echo date('d.m.Y', strtotime($h->platnost_do)); ?><?php if ($expiry_warning): ?> <span style="color:#d97706">⚠</span><?php endif; ?><?php endif; ?>
                        </span>
                    </div>
                </div>
                <div style="display:flex;justify-content:space-between;align-items:center;padding-top:8px;border-top:1px solid #f3f4f6">
                    <code style="font-size:11px;color:#6b7280;background:#f9fafb;padding:2px 6px;border-radius:3px">VS: <?php echo esc_html($vs_h); ?></code>
                    <?php if ($h->stav === 'zaplaceno'): ?>
                    <a href="<?php echo esc_url(rd_faktura_url($h->id, $as->id)); ?>" target="_blank" style="font-size:12px;color:#374151;text-decoration:none;border:1px solid #d1d5db;border-radius:4px;padding:4px 10px">📄 Faktura</a>
                    <?php endif; ?>
                </div>
            </div>
            <?php endforeach; ?>
        </div>
    </div>
    <?php endif; ?>
    </div>
    <script>
    document.querySelectorAll('input[name="tier_id"]').forEach(function(r) {
        r.closest('label').addEventListener('click', function() {
            document.querySelectorAll('input[name="tier_id"]').forEach(function(x) {
                x.closest('label').style.borderColor = '#e5e7eb';
                x.closest('label').style.background = '';
            });
            this.style.borderColor = '#7c3aed';
            this.style.background = '#faf5ff';
            r.checked = true;
        });
    });
    </script>
    <?php
}


