add_action('init', function() {
    if (get_option('rd_legal_pages_created')) return;
    $pages = [
        ['post_title' => 'Všeobecné obchodní podmínky', 'post_name' => 'vseobecne-podminky',   'post_content' => '[rd_vop]'],
        ['post_title' => 'Ochrana osobních údajů',      'post_name' => 'ochrana-osobnich-udaju', 'post_content' => '[rd_gdpr]'],
    ];
    foreach ($pages as $page) {
        if (!get_page_by_path($page['post_name'])) {
            wp_insert_post(array_merge($page, ['post_status' => 'publish', 'post_type' => 'page']));
        }
    }
    update_option('rd_legal_pages_created', 1);
}, 20);

