    // Zpracování formuláře
    $sent = false; $err = '';
    if (isset($_POST['rd_kontakt_send']) && wp_verify_nonce($_POST['rd_kontakt_nonce'] ?? '', 'rd_kontakt_form')) {
        $jmeno  = sanitize_text_field($_POST['rd_k_jmeno'] ?? '');
        $sender = sanitize_email($_POST['rd_k_email'] ?? '');
        $zprava = sanitize_textarea_field($_POST['rd_k_zprava'] ?? '');
        if (!$jmeno || !$sender || !$zprava) {
            $err = 'Vyplňte prosím všechna pole.';
        } elseif (!is_email($sender)) {
            $err = 'Zadejte platnou emailovou adresu.';
        } else {
            $to      = $email ?: get_option('admin_email');
            $subject = 'Kontaktní formulář – ' . $jmeno;
            $body    = '<p><strong>Jméno:</strong> ' . esc_html($jmeno) . '</p>'
                     . '<p><strong>Email:</strong> <a href="mailto:' . esc_attr($sender) . '">' . esc_html($sender) . '</a></p>'
                     . '<p><strong>Zpráva:</strong><br>' . nl2br(esc_html($zprava)) . '</p>';
            $headers = ['Content-Type: text/html; charset=UTF-8', 'Reply-To: ' . $jmeno . ' <' . $sender . '>'];
            $sent    = wp_mail($to, $subject, rd_email_wrap($subject, $body), $headers);
            if (!$sent) $err = 'Nepodařilo se odeslat zprávu. Zkuste to prosím znovu.';
        }
    }

