function rd_html_to_pdf($html, $filename) {
    // Zkusit wkhtmltopdf
    $wk = trim(shell_exec('which wkhtmltopdf 2>/dev/null'));
    if ($wk && is_executable($wk)) {
        $tmp_html = tempnam(sys_get_temp_dir(), 'rd_cert_') . '.html';
        $tmp_pdf  = tempnam(sys_get_temp_dir(), 'rd_cert_') . '.pdf';
        file_put_contents($tmp_html, $html);
        $cmd = escapeshellcmd($wk) . ' --quiet --page-size A4 --margin-top 0 --margin-bottom 0 --margin-left 0 --margin-right 0 --enable-local-file-access ' . escapeshellarg($tmp_html) . ' ' . escapeshellarg($tmp_pdf) . ' 2>/dev/null';
        exec($cmd);
        if (file_exists($tmp_pdf) && filesize($tmp_pdf) > 1000) {
            header('Content-Type: application/pdf');
            header('Content-Disposition: attachment; filename="' . $filename . '"');
            header('Content-Length: ' . filesize($tmp_pdf));
            header('Cache-Control: no-store');
            readfile($tmp_pdf);
            @unlink($tmp_html);
            @unlink($tmp_pdf);
            return true;
        }
        @unlink($tmp_html);
        @unlink($tmp_pdf);
    }
    // Fallback — vrátit printable HTML
    header('Content-Type: text/html; charset=UTF-8');
    echo $html;
    return false;
}

/* ============================================================
   PDF CERTIFIKÁT — NATIVNÍ GENERÁTOR BEZ ZÁVISLOSTÍ
   ============================================================ */

class RD_PDF {
    private $page = '';
    private $W = 595.28;
    private $H = 841.89;

    private function hex2rgb($h) {
        return [hexdec(substr($h,0,2))/255, hexdec(substr($h,2,2))/255, hexdec(substr($h,4,2))/255];
    }

    private function clean($s) {
        $fr = ['á','č','ď','é','ě','í','ň','ó','ř','š','ť','ú','ů','ý','ž','Á','Č','Ď','É','Ě','Í','Ň','Ó','Ř','Š','Ť','Ú','Ů','Ý','Ž'];
        $to = ['a','c','d','e','e','i','n','o','r','s','t','u','u','y','z','A','C','D','E','E','I','N','O','R','S','T','U','U','Y','Z'];
        $s = str_replace($fr, $to, $s);
        $s = str_replace(['\\','(',')'], ['\\\\','\\(','\\)'], $s);
        return $s;
    }

    private function text($x, $y, $text, $size, $color, $bold = false) {
        [$r,$g,$b] = $this->hex2rgb($color);
        $font = $bold ? 'Helvetica-Bold' : 'Helvetica';
        $text = $this->clean($text);
        $this->page .= sprintf("BT /%s %d Tf %.3f %.3f %.3f rg %d %d Td (%s) Tj ET\n", $font, $size, $r, $g, $b, $x, $y, $text);
    }

    private function rect($x, $y, $w, $h, $color, $fill = true) {
        [$r,$g,$b] = $this->hex2rgb($color);
        $rg = $fill ? 'rg' : 'RG';
        $cmd = $fill ? 'f' : 'S';
        $this->page .= sprintf("%.3f %.3f %.3f %s %.2f %.2f %.2f %.2f re %s\n", $r, $g, $b, $rg, $x, $y, $w, $h, $cmd);
    }

    private function line($x1, $y1, $x2, $y2, $color, $w = 1) {
        [$r,$g,$b] = $this->hex2rgb($color);
        $this->page .= sprintf("%.3f %.3f %.3f RG %.2f w %.2f %.2f m %.2f %.2f l S\n", $r, $g, $b, $w, $x1, $y1, $x2, $y2);
    }

    public function generate($jmeno, $firma, $datum, $score, $cert_id, $verify_url, $trvani, $lekce) {
        $this->rect(0, $this->H - 8, $this->W, 8, '7c3aed');
        $this->text(50, $this->H - 42, 'refdrive.pro', 22, '7c3aed', true);
        $this->text(390, $this->H - 38, 'Vydano: ' . $datum, 10, '9ca3af');
        $this->line(50, $this->H - 58, $this->W - 50, $this->H - 58, '7c3aed', 1.5);
        $this->text(50, $this->H - 83, 'OSVEDCENI O ABSOLVOVANI SKOLENI REFERENTSKYCH RIDICU', 9, '9ca3af', true);
        $this->text(50, $this->H - 108, 'Skoleni referentskych ridicu', 24, '111827', true);
        $this->text(50, $this->H - 143, 'udeluje se', 12, '6b7280');
        $this->text(50, $this->H - 178, $jmeno, 28, '7c3aed', true);
        $this->line(50, $this->H - 195, $this->W - 50, $this->H - 195, 'ede9fe', 1);

        $y = $this->H - 222;
        $rows = [
            ['Zamestnavatel', $firma],
            ['Datum absolvovani', $datum],
            ['Delka skoleni', $trvani],
            ['Vysledek zaverecneho testu', $score . '%'],
            ['Cislo certifikatu', $cert_id],
        ];
        foreach ($rows as $row) {
            $this->text(50, $y, $row[0], 10, '6b7280');
            $this->text(240, $y, $row[1], 10, '111827', true);
            $this->line(50, $y - 9, $this->W - 50, $y - 9, 'f3f4f6', 0.5);
            $y -= 25;
        }

        $y -= 12;
        $lc = count($lekce);
        $oh = $lc * 17 + 36;
        $this->rect(45, $y - $oh + 14, $this->W - 90, $oh, 'f9fafb');
        $this->text(55, $y, 'OSNOVA SKOLENI - §349 ZP c. 262/2006 Sb. a NV c. 168/2002 Sb.', 8, '9ca3af', true);
        $y -= 18;
        foreach ($lekce as $i => $l) {
            $nazev = is_array($l) ? ($l['nazev'] ?? '') : (is_object($l) ? $l->nazev : '');
            $this->text(55, $y, ($i+1) . '. ' . $nazev, 9, '374151');
            $y -= 16;
        }

        $this->line(50, 108, $this->W - 50, 108, 'e5e7eb', 0.5);
        $this->text(50, 92, 'Skoleni probehlo dle §103 a §349 ZP c. 262/2006 Sb. a NV c. 168/2002 Sb.', 8, '9ca3af');
        $this->text(50, 78, 'E-learning je plne uznatelny dozorovymi organy. Overit: ' . $verify_url, 8, '9ca3af');
        $this->text(50, 64, 'Vydal: refdrive.pro — Online skoleni referentskych ridicu', 8, '9ca3af');
        $this->rect(420, 26, 126, 78, 'f3f4f6');
        $this->text(430, 92, 'Overit certifikat:', 7, '9ca3af');
        $this->text(430, 78, 'refdrive.pro/overit', 8, '7c3aed', true);
        $this->text(430, 64, 'ID: ' . $cert_id, 8, '374151', true);
        $this->text(430, 50, $datum, 7, '9ca3af');
        $this->rect(0, 0, $this->W, 7, 'db2777');
    }

    public function output($filename) {
        $stream = $this->page;
        $len = strlen($stream);
        $objs = [
            1 => "<< /Type /Catalog /Pages 2 0 R >>",
            2 => "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
            3 => "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Contents 4 0 R /Resources << /Font << /Helvetica << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> /Helvetica-Bold << /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >> >> >> >>",
            4 => "<< /Length $len >>\nstream\n$stream\nendstream",
        ];
        $body = "%PDF-1.4\n";
        $offs = [];
        foreach ($objs as $n => $o) {
            $offs[$n] = strlen($body);
            $body .= "$n 0 obj\n$o\nendobj\n";
        }
        $xref = strlen($body);
        $cnt = count($objs) + 1;
        $body .= "xref\n0 $cnt\n0000000000 65535 f \n";
        foreach ($offs as $off) {
            $body .= str_pad($off, 10, '0', STR_PAD_LEFT) . " 00000 n \n";
        }
        $body .= "trailer\n<< /Size $cnt /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        header('Content-Length: ' . strlen($body));
        header('Cache-Control: no-store');
        echo $body;
    }
}

