// AJAX — stažení PDF
add_action('wp_ajax_rd_pdf_cert', 'rd_pdf_cert_ajax');
add_action('wp_ajax_nopriv_rd_pdf_cert', 'rd_pdf_cert_ajax');
function rd_pdf_cert_ajax() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    $uuid = sanitize_text_field($_POST['uuid'] ?? '');
    if (!$uuid) wp_die('Chybí UUID');
    global $wpdb;
    $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_RIDICI . " WHERE cert_uuid=%s AND uspech=1 LIMIT 1", $uuid));
    if (!$r) wp_die('Certifikát nenalezen');
    $lekce = rd_lekce_source();
    $jmeno   = $r->jmeno;
    $firma   = $r->firma_nazev;
    $datum   = date('d. m. Y', strtotime($r->datum_skoleni));
    $score   = intval($r->score);
    $cert_id = strtoupper($r->kod);
    $verify_url = home_url('/overit/?id=' . $uuid);
    $trvani  = isset($r->trvani_min) && $r->trvani_min > 0 ? $r->trvani_min . ' min' : 'absolvovano online';
    $pdf = new RD_PDF();
    $pdf->generate($jmeno, $firma, $datum, $score, $cert_id, $verify_url, $trvani, $lekce);
    $pdf->output('certifikat-refdrive-' . $cert_id . '.pdf');
    exit;
}


