// AJAX pro admin PDF
add_action('wp_ajax_rd_pdf_admin', 'rd_pdf_admin_handler');
function rd_pdf_admin_handler() {
    if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) wp_die('Přístup odepřen');
    $kod = sanitize_text_field($_GET['kod'] ?? '');
    if (!wp_verify_nonce($_GET['nonce'] ?? '', 'rd_pdf_admin_' . $kod)) wp_die('Neplatný token');
    global $wpdb;
    $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $kod));
    if (!$r) wp_die('Řidič nenalezen');
    // Zajistit cert_uuid
    if (empty($r->cert_uuid)) {
        $uuid = wp_generate_uuid4();
        $wpdb->update(RD_TABLE_RIDICI, ['cert_uuid' => $uuid], ['id' => $r->id]);
        $r->cert_uuid = $uuid;
    }
    $lekce = rd_lekce_source();
    // Načíst název autoškoly
    $as_nazev_cert = 'RefDrive.pro';
    if (!empty($r->autoskola_id)) {
        $as_nazev_cert = $wpdb->get_var($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $r->autoskola_id)) ?: 'RefDrive.pro';
    } elseif (!empty($_SESSION['rd_autoskola_id'])) {
        $as_nazev_cert = $wpdb->get_var($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", intval($_SESSION['rd_autoskola_id']))) ?: 'RefDrive.pro';
    } elseif (!empty($_SESSION['rd_kod'])) {
        $kod_row = $wpdb->get_row($wpdb->prepare("SELECT autoskola_id FROM " . RD_TABLE_KODY . " WHERE kod=%s LIMIT 1", $_SESSION['rd_kod']));
        if ($kod_row && $kod_row->autoskola_id) {
            $as_nazev_cert = $wpdb->get_var($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $kod_row->autoskola_id)) ?: 'RefDrive.pro';
        }
    }
    $html = rd_cert_html(
        $r->jmeno, $r->firma_nazev,
        date('d. m. Y', strtotime($r->datum_skoleni)),
        intval($r->score), strtoupper($r->kod),
        home_url('/overit/?id=' . $r->cert_uuid),
        isset($r->trvani_min) && $r->trvani_min > 0 ? $r->trvani_min . ' min' : 'absolvováno online',
        $lekce, $as_nazev_cert
    );
    rd_html_to_pdf($html, 'certifikat-refdrive-' . strtoupper($r->kod) . '.pdf');
    exit;
}


