// PDF print endpoint - pro admin i lektor preview
add_action('init', function() {
    if (isset($_GET['rd_cert_print'])) {
        $kod   = sanitize_text_field($_GET['kod'] ?? '');
        $nonce = sanitize_text_field($_GET['nonce'] ?? '');
        if (!$kod || !wp_verify_nonce($nonce, 'rd_cert_print_' . $kod)) return;
        if (!(current_user_can('manage_options') || current_user_can('refdrive_access'))) return;
        global $wpdb;
        $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $kod));
        if (!$r) wp_die('Certifikát nenalezen');
        if (empty($r->cert_uuid)) {
            $uuid = wp_generate_uuid4();
            $wpdb->update(RD_TABLE_RIDICI, ['cert_uuid' => $uuid], ['id' => $r->id]);
            $r->cert_uuid = $uuid;
        }
        $lekce = rd_lekce_source();
        $as_nazev_cert2 = 'RefDrive.pro';
        if (!empty($r->autoskola_id)) {
            $as_nazev_cert2 = $wpdb->get_var($wpdb->prepare("SELECT nazev FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $r->autoskola_id)) ?: 'RefDrive.pro';
        }
        rd_output_cert_page($r->jmeno, $r->firma_nazev, date('d. m. Y', strtotime($r->datum_skoleni)), intval($r->score), strtoupper($r->kod), home_url('/overit/?id=' . $r->cert_uuid), isset($r->trvani_min) && $r->trvani_min > 0 ? $r->trvani_min . ' min' : 'absolvováno online', $lekce, 'certifikat-refdrive-' . strtoupper($r->kod), $as_nazev_cert2);
    }
    if (isset($_GET['rd_cert_preview'])) {
        if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
        if (!isset($_SESSION['rd_lektor'])) return;
        $lekce = rd_lekce_source();
        rd_output_cert_page('Jan Novák', 'Testovací firma s.r.o.', date('d. m. Y'), 85, 'PREVIEW', home_url('/overit/?id=preview'), '45 min', $lekce, 'certifikat-refdrive-PREVIEW');
    }
}, 7);

function rd_output_cert_page($jmeno, $firma, $datum, $score, $cert_id, $verify_url, $trvani, $lekce, $filename, $autoskola_nazev = 'RefDrive.pro') {
    $html = rd_cert_html($jmeno, $firma, $datum, $score, $cert_id, $verify_url, $trvani, $lekce, $autoskola_nazev);
    $print_btn = '<style>@media print{.rd-print-bar{display:none!important}body{background:#fff!important;padding:0!important}}</style>'
        . '<div class="rd-print-bar" style="text-align:center;padding:20px;background:#e8e4f0">'
        . '<button onclick="window.print()" style="background:linear-gradient(90deg,#7c3aed,#db2777);color:#fff;border:none;border-radius:8px;padding:12px 32px;font-size:15px;font-weight:700;cursor:pointer;font-family:Arial,sans-serif">&#8659; Uložit jako PDF</button>'
        . '<p style="margin-top:8px;font-size:11px;color:#6b7280;font-family:Arial,sans-serif">V dialogu tisku zvolte: <strong>Uložit jako PDF</strong></p>'
        . '</div>';
    $html = str_replace('</body>', $print_btn . '</body>', $html);
    header('Content-Type: text/html; charset=UTF-8');
    echo $html;
    exit;
}



