function rd_sc_jaktofunguje() {
    $file = plugin_dir_path(__FILE__) . 'jaktofunguje.html';
    if (!file_exists($file)) return '<p>Stránka není k dispozici.</p>';
    $html = file_get_contents($file);
    add_action('wp_head', function() {
        echo '<link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet">' . "\n";
    }, 1);
    preg_match('/<style>(.*?)<\/style>/s', $html, $style_m);
    preg_match('/<body>(.*?)<\/body>/s', $html, $body_m);
    $style = isset($style_m[1]) ? $style_m[1] : '';
    $body  = isset($body_m[1])  ? $body_m[1]  : '';

    // ── DYNAMICKÁ CENA NEJLEVNĚJŠÍHO BALÍČKU ────────────────────────────────
    global $wpdb;
    $min_cena = $wpdb->get_var("SELECT MIN(cena_mesic) FROM " . RD_TABLE_AS_TIERY . " WHERE aktivni=1");
    $min_cena = $min_cena !== null ? number_format((float)$min_cena, 0, ',', ' ') : '190';
    $body = str_replace('{{RD_MIN_TIER_PRICE}}', esc_html($min_cena), $body);

    // Přesunout :root proměnné na #rd-jtf-wrap
    $style = preg_replace('/\:root\s*\{/', '#rd-jtf-wrap {', $style);

    // ── PŘEMOSTĚNÍ NA AURORA BAREVNÉ TÉMA ──────────────────────────────────
    // Lokální proměnné --v1/--v2/--p1/--p2 stránky napojíme na globální
    // --rd-grad-from / --rd-grad-to / --rd-accent-1 / --rd-accent-2,
    // které plugin injektuje do :root podle zvoleného barevného schématu.
    // Tím se změna tématu v Customizeru projeví i na /jaktofunguje.
    $style .= '
#rd-jtf-wrap {
  --v1: var(--rd-grad-from, #7c3aed);
  --v2: var(--rd-accent-1,  #a78bfa);
  --v3: var(--rd-grad-from, #7c3aed);
  --p1: var(--rd-grad-to,   #db2777);
  --p2: var(--rd-accent-2,  #f472b6);
}';

    // ── SVĚTLÉ TÉMA ─────────────────────────────────────────────────────────
    $style .= '
[data-theme="light"] #rd-jtf-wrap {
  --bg:    #f3f1ff;
  --s1:    #ffffff;
  --s2:    #ede9ff;
  --border:rgba(0,0,0,.08);
  --v1:    var(--rd-grad-from, #7c3aed);
  --v2:    var(--rd-grad-from, #6d28d9);
  --v3:    var(--rd-grad-from, #5b21b6);
  --p1:    var(--rd-grad-to,   #db2777);
  --p2:    var(--rd-grad-to,   #be185d);
  --g1:    #16a34a;
  --g2:    #15803d;
  --b1:    #0284c7;
  --b2:    #0369a1;
  --o1:    #ea580c;
  --o2:    #c2410c;
  --t1:    #100828;
  --t2:    #4a3b7c;
  --t3:    #64748b;
  background:#f3f1ff;
  color:#100828;
}';
    return '<div id="rd-jtf-wrap"><style>' . $style . '</style>' . $body . '</div>';
}
function rd_sc_faq() {
    global $wpdb;
    $rows = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}rd_faq ORDER BY poradi ASC", ARRAY_A);
    // Seskupit podle kategorie
    $faq = [];
    foreach ((array)$rows as $r) {
        $faq[$r['kategorie']][] = [$r['otazka'], $r['odpoved']];
    }
    ob_start(); ?>
    <style>
    .rd-faq-sekce { margin: 32px 0; }
