    .rd-faq-item { border: 1px solid var(--au-border); border-radius: 10px; margin-bottom: 8px; overflow: hidden; }
    .rd-faq-q { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; cursor: pointer; font-weight: 600; font-size: .95rem; gap: 12px; }
