    .rd-faq-item.open .rd-faq-a { display: block; }
    .rd-faq-item.open .rd-faq-icon { transform: rotate(45deg); }
    </style>
    <div class="rd-hero-wrap" style="margin-bottom:0;border-bottom:1px solid var(--au-border);padding-bottom:12px">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:28px">
        <a href="javascript:history.back()" style="display:inline-flex;align-items:center;gap:5px;font-size:.85rem;color:var(--au-text-2);text-decoration:none;opacity:.7;transition:opacity .15s;white-space:nowrap" onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.7"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg> Zpět</a>
        <div class="rd-hero-badge" style="margin-bottom:0"><?php echo rd_editable('faq_badge', 'Často kladené otázky'); ?></div>
      </div>
    </div>
    <div class="rd-faq" style="margin-top:32px">
    <?php foreach ($faq as $sekce => $otazky): ?>
    <div class="rd-faq-sekce">
        <div class="rd-faq-label"><?php echo esc_html($sekce); ?></div>
        <?php foreach ($otazky as $i => [$q, $a]): $id = 'faq-' . sanitize_title($sekce) . '-' . $i; ?>
        <div class="rd-faq-item" id="<?php echo $id; ?>">
            <div class="rd-faq-q" onclick="this.closest('.rd-faq-item').classList.toggle('open')">
                <?php echo esc_html($q); ?>
                <svg class="rd-faq-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            </div>
            <div class="rd-faq-a"><?php echo esc_html($a); ?></div>
