function rd_sc_lektor() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    global $wpdb;

    // Logout
    if (isset($_POST['rd_lektor_logout']) || isset($_GET['odhlasit_lektora'])) {
        unset($_SESSION['rd_lektor']);
        setcookie('rd_lektor_login', '', time() - 3600, '/', '', is_ssl(), false);
        wp_redirect(home_url('/lektor/')); exit;
    }

    // Login
    if (isset($_POST['rd_lektor_kod'])) {
        $kod = sanitize_text_field($_POST['rd_lektor_kod']);
        // Bruteforce ochrana
        $lk_ip  = 'rd_lk_' . md5(rd_get_ip());
        $lk_cnt = (int)get_transient($lk_ip);
        if ($lk_cnt >= 5) {
            // Zobrazit chybu - příliš mnoho pokusů
        } else {
        $lektor = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rd_lektor WHERE kod=%s", $kod));
        if ($lektor) {
            delete_transient($lk_ip);
            unset($_SESSION['rd_firma_id'], $_SESSION['rd_firma_email'], $_SESSION['rd_kod'], $_SESSION['rd_token']);
            $_SESSION['rd_lektor'] = $lektor->id;
            setcookie('rd_lektor_login', base64_encode($lektor->id), time() + 86400*7, '/', '', is_ssl(), true);
            wp_redirect(home_url('/lektor/')); exit;
        } else {
            set_transient($lk_ip, $lk_cnt + 1, 15 * MINUTE_IN_SECONDS);
            $_SESSION['rd_lektor_err'] = ($lk_cnt >= 4)
                ? 'Příliš mnoho neúspěšných pokusů. Zkuste to znovu za 15 minut.'
                : 'Nesprávný přihlašovací kód.';
            wp_redirect(home_url('/lektor/')); exit;
        }
        } // end bruteforce else
    }

    if (empty($_SESSION['rd_lektor'])) {
        ob_start(); ?>
<div class="rd-page rd-center">
  <div class="rd-login-card">
    <div class="rd-login-icon-wrap">
      <div class="rd-login-icon">
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M12 2L2 7l10 5 10-5-10-5z" stroke="url(#lek-g1)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
          <path d="M2 17l10 5 10-5" stroke="url(#lek-g1)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
          <path d="M2 12l10 5 10-5" stroke="url(#lek-g1)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
          <defs>
            <linearGradient id="lek-g1" x1="2" y1="2" x2="22" y2="22"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient>
          </defs>
        </svg>
      </div>
    </div>
    <h2>Portál lektora</h2>
    <p class="rd-login-sub">Zadejte přístupový kód pro správu obsahu kurzu</p>
    <form method="post" class="rd-form">
      <?php wp_nonce_field('rd_lektor_login'); ?>
      <div class="rd-field"><label>Přístupový kód</label><input type="password" name="rd_lektor_kod" placeholder="••••••••" required autocomplete="off"></div>
      <button type="submit" class="rd-btn rd-btn-primary rd-btn-full">Přihlásit se →</button>
    </form>
  </div>
</div>
        <?php return ob_get_clean();
    }

    // Handle AJAX saves
    if (isset($_POST['rd_action'])) {
        check_admin_referer('rd_lektor_action');
        $action = sanitize_text_field($_POST['rd_action']);

        if ($action === 'save_lekce') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_lekce");
            $lekce = json_decode(stripslashes($_POST['lekce_json']), true);
            foreach ((array)$lekce as $i => $l) {
                $wpdb->insert("{$wpdb->prefix}rd_lekce", [
                    'poradi' => $i,
                    'nazev'  => sanitize_text_field($l['nazev']),
                    'popis'  => sanitize_text_field($l['popis']),
                    'cas'    => (int)($l['cas']),
                    'obsah'  => wp_kses_post($l['obsah']),
                    'obrazek'=> isset($l['obrazek']) ? esc_url_raw($l['obrazek']) : null,
                ]);
            }
            wp_redirect(home_url('/lektor/?tab=lekce&saved=1')); exit;
        }

        if ($action === 'save_otazky') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_otazky");
            $otazky = json_decode(stripslashes($_POST['otazky_json']), true);
            foreach ((array)$otazky as $i => $o) {
                $wpdb->insert("{$wpdb->prefix}rd_otazky", [
                    'poradi'    => $i,
                    'otazka'    => sanitize_textarea_field($o['otazka']),
                    'moznost_a' => sanitize_textarea_field($o['a']),
                    'moznost_b' => sanitize_textarea_field($o['b']),
                    'moznost_c' => sanitize_textarea_field($o['c']),
                    'moznost_d' => sanitize_textarea_field($o['d']),
                    'spravna'   => sanitize_text_field($o['spravna']),
                ]);
            }
            wp_redirect(home_url('/lektor/?tab=test&saved=1')); exit;
        }

        if ($action === 'save_novinky') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_novinky");
            $novinky = json_decode(stripslashes($_POST['novinky_json']), true);
            foreach ((array)$novinky as $i => $n) {
                $wpdb->insert("{$wpdb->prefix}rd_novinky", [
                    'poradi' => $i,
                    'tag'    => sanitize_text_field($n['tag']),
                    'nazev'  => sanitize_text_field($n['nazev']),
                    'obsah'  => wp_kses_post($n['obsah']),
                ]);
            }
            wp_redirect(home_url('/lektor/?tab=novinky&saved=1')); exit;
        }

        if ($action === 'reset_lekce') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_lekce");
            do_action('rd_obsah_resetovan', 'lekce', rd_kdo_resetoval());
            wp_redirect(home_url('/lektor/?tab=lekce&reset=1')); exit;
        }
        if ($action === 'reset_otazky') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_otazky");
            do_action('rd_obsah_resetovan', 'otazky', rd_kdo_resetoval());
            wp_redirect(home_url('/lektor/?tab=test&reset=1')); exit;
        }
        if ($action === 'reset_novinky') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_novinky");
            do_action('rd_obsah_resetovan', 'novinky', rd_kdo_resetoval());
            wp_redirect(home_url('/lektor/?tab=novinky&reset=1')); exit;
        }

        if ($action === 'save_legislativa') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_leg_zakony");
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_leg_kroky");
            $zakony = json_decode(stripslashes($_POST['zakony_json']), true);
            foreach ((array)$zakony as $i => $z) {
                $wpdb->insert("{$wpdb->prefix}rd_leg_zakony", [
                    'sekce'      => sanitize_text_field($z['sekce']),
                    'zkratka'    => sanitize_text_field($z['zkratka']),
                    'nazev'      => sanitize_text_field($z['nazev']),
                    'podtitulek' => sanitize_text_field($z['podtitulek']),
                    'obsah'      => wp_kses_post($z['obsah']),
                    'poradi'     => $i,
                ]);
            }
            $kroky = json_decode(stripslashes($_POST['kroky_json']), true);
            foreach ((array)$kroky as $i => $k) {
                $wpdb->insert("{$wpdb->prefix}rd_leg_kroky", [
                    'sekce'  => sanitize_text_field($k['sekce']),
                    'nadpis' => sanitize_text_field($k['nadpis']),
                    'text'   => wp_kses_post($k['text']),
                    'poradi' => $i,
                ]);
            }
            wp_redirect(home_url('/lektor/?tab=legislativa&saved=1')); exit;
        }

        if ($action === 'reset_legislativa') {
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_leg_zakony");
            $wpdb->query("DELETE FROM {$wpdb->prefix}rd_leg_kroky");
            wp_redirect(home_url('/lektor/?tab=legislativa&reset=1')); exit;
        }
    }

    $tab = isset($_GET['tab']) ? sanitize_text_field($_GET['tab']) : 'lekce';
    $saved = isset($_GET['saved']);
    $reset = isset($_GET['reset']);
    $lekce = rd_lekce_source();
    $otazky = rd_otazky_source(999); // Lektor vidí vždy všechny otázky
    $novinky = rd_novinky_source();
    $leg_zakony  = rd_leg_zakony_source('proc_povinne');
    $leg_postihy = rd_leg_zakony_source('postihy');
    $leg_kroky   = rd_leg_kroky_source('obsah');

    ob_start(); ?>
