  <?php endif; ?>

</div>
<script>
(function() {

  // Přidat chip na konec editoru – globální funkce (musí být přístupná z onclick)
  window.rdAddChip = function(btn, color) {
    var wrap = btn.closest('.rd-editor-wrap');
    if (!wrap) { alert('ERR: wrap nenalezen'); return; }
    var editor = wrap.querySelector('.rd-editor-body');
    if (!editor) { alert('ERR: editor nenalezen'); return; }
    var isBlue = color === 'blue';
    var chip = document.createElement('div');
    chip.className = isBlue ? 'rd-info-chip rd-chip-blue' : 'rd-info-chip rd-chip-red';
    chip.style.cssText = isBlue
      ? 'display:block;background:rgba(96,165,250,.12);border-left:3px solid #60a5fa;border-radius:6px;padding:10px 14px;margin:8px 0;color:#93c5fd;font-size:.88rem;line-height:1.5;min-height:1.5em'
      : 'display:block;background:rgba(239,68,68,.12);border-left:3px solid #f87171;border-radius:6px;padding:10px 14px;margin:8px 0;color:#fca5a5;font-size:.88rem;line-height:1.5;min-height:1.5em';
    chip.setAttribute('contenteditable', 'true');
    chip.textContent = isBlue ? 'Informace...' : 'Upozornění...';

    // Tlačítko "za box" pro pokračování v textu
    var exitBtn = document.createElement('button');
    var btnWrap = document.createElement('div');
    btnWrap.setAttribute('contenteditable', 'false');
    btnWrap.style.cssText = 'display:flex;gap:6px;margin-top:6px';
    exitBtn.type = 'button';
    exitBtn.setAttribute('contenteditable', 'false');
    exitBtn.textContent = '↵ Pokračovat v textu';
    exitBtn.style.cssText = 'background:none;border:1px dashed currentColor;border-radius:4px;padding:2px 8px;font-size:.72rem;cursor:pointer;opacity:.6;color:inherit';
    exitBtn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      var p = document.createElement('p');
      p.innerHTML = '<br>';
      chip.parentNode.insertBefore(p, chip.nextSibling);
      // Přesunout kurzor do nového odstavce
      var r = document.createRange();
      r.setStart(p, 0);
      r.collapse(true);
      var s = window.getSelection();
      s.removeAllRanges();
      s.addRange(r);
      editor.focus();
    });
    var delBtn2 = document.createElement('button');
    delBtn2.type = 'button';
    delBtn2.setAttribute('contenteditable', 'false');
    delBtn2.textContent = '✕ Odstranit pole';
    delBtn2.style.cssText = 'background:none;border:1px dashed currentColor;border-radius:4px;padding:2px 8px;font-size:.72rem;cursor:pointer;opacity:.6;color:inherit';
    delBtn2.addEventListener('click', function(e) {
      e.preventDefault(); e.stopPropagation();
      chip.remove();
      editor.focus();
    });
    btnWrap.appendChild(exitBtn);
    btnWrap.appendChild(delBtn2);
    chip.appendChild(btnWrap);

    editor.appendChild(chip);
    // Označit placeholder text pro snadné přepsání
    chip.focus();
    if (document.createRange) {
      var r = document.createRange();
      r.setStart(chip.firstChild, 0);
      r.setEnd(chip.firstChild, chip.firstChild.length);
      var s = window.getSelection();
      s.removeAllRanges();
      s.addRange(r);
    }
  }



  // Inicializovat existující chipy v editoru (načtené z DB)
  function rdInitChips(editor) {
    editor.querySelectorAll('.rd-info-chip').forEach(function(chip) {
      if (chip.dataset.chipeditinit) return;
      chip.dataset.chipeditinit = '1';
      var isBlue = chip.classList.contains('rd-chip-blue');
      chip.setAttribute('contenteditable', 'true');
      chip.style.cssText = isBlue
        ? 'display:block;background:rgba(96,165,250,.12);border-left:3px solid #60a5fa;border-radius:6px;padding:10px 14px;margin:8px 0;color:#93c5fd;font-size:.88rem;line-height:1.5;min-height:1.5em'
        : 'display:block;background:rgba(239,68,68,.12);border-left:3px solid #f87171;border-radius:6px;padding:10px 14px;margin:8px 0;color:#fca5a5;font-size:.88rem;line-height:1.5;min-height:1.5em';
      // Přidat tlačítko pokračovat
      var exitBtn = document.createElement('button');
      var btnWrap = document.createElement('div');
      btnWrap.setAttribute('contenteditable', 'false');
      btnWrap.style.cssText = 'display:flex;gap:6px;margin-top:6px';
      exitBtn.type = 'button';
      exitBtn.setAttribute('contenteditable', 'false');
      exitBtn.textContent = '↵ Pokračovat v textu';
      exitBtn.style.cssText = 'background:none;border:1px dashed currentColor;border-radius:4px;padding:2px 8px;font-size:.72rem;cursor:pointer;opacity:.6;color:inherit';
      exitBtn.addEventListener('click', function(e) {
        e.preventDefault(); e.stopPropagation();
        var p = document.createElement('p');
        p.innerHTML = '<br>';
        chip.parentNode.insertBefore(p, chip.nextSibling);
        var r = document.createRange();
        r.setStart(p, 0); r.collapse(true);
        var s = window.getSelection();
        s.removeAllRanges(); s.addRange(r);
        chip.closest('.rd-editor-body').focus();
      });
      var delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.setAttribute('contenteditable', 'false');
      delBtn.textContent = '✕ Odstranit pole';
      delBtn.style.cssText = 'background:none;border:1px dashed currentColor;border-radius:4px;padding:2px 8px;font-size:.72rem;cursor:pointer;opacity:.6;color:inherit';
      delBtn.addEventListener('click', function(e) {
        e.preventDefault(); e.stopPropagation();
        var editor = chip.closest('.rd-editor-body');
        chip.remove();
        if (editor) editor.focus();
      });
      btnWrap.appendChild(exitBtn);
      btnWrap.appendChild(delBtn);
      chip.appendChild(btnWrap);
    });
  }

  // Spustit jako globální funkce dostupná z DOMContentLoaded
  window.rdInitAllChips = function() {
    document.querySelectorAll('.rd-editor-body').forEach(function(editor) {
      rdInitChips(editor);
    });
  };
  // Spustit hned i s prodlevou jako záloha
  rdInitAllChips();
  setTimeout(rdInitAllChips, 100);
  setTimeout(rdInitAllChips, 500);

  // Simple WYSIWYG editor
  window.rdEdFmt = function(btn, cmd, val) {
    var wrap = btn.closest('.rd-editor-wrap');
    var editor = wrap.querySelector('.rd-editor-body');
    editor.focus();
    document.execCommand(cmd, false, val || null);
  }

  // Sync editor content to hidden textarea before submit
  function syncEditors() {
    document.querySelectorAll('.rd-editor-body').forEach(function(div) {
      var ta = div.closest('.rd-editor-wrap').querySelector('.rd-f-obsah');
      if (!ta) return;
      // Klonovat a vyčistit contenteditable atributy z chipů před uložením
      var clone = div.cloneNode(true);
      clone.querySelectorAll('.rd-info-chip').forEach(function(chip) {
        chip.removeAttribute('contenteditable');
        chip.removeAttribute('style');
        // Odebrat pomocné buttony a jejich wrapper div
        chip.querySelectorAll('button').forEach(function(b) { b.remove(); });
        chip.querySelectorAll('div[contenteditable="false"]').forEach(function(d) { d.remove(); });
      });
      ta.value = clone.innerHTML;
    });
  }

  // Override form submit to sync editors
  var lf2 = document.getElementById('rd-lekce-form');
  if (lf2) lf2.addEventListener('submit', function() { syncEditors(); }, true);

  // Slider labels - set default 180 if 0
  document.querySelectorAll('.rd-f-cas').forEach(function(s) {
    if (parseInt(s.value) === 0) {
      s.value = 180;
      var label = s.closest('.rd-lektor-item') && s.closest('.rd-lektor-item').querySelector('.rd-cas-val');
      if (label) label.textContent = '3 min';
    }
    s.addEventListener('input', function() {
      s.closest('.rd-lektor-item').querySelector('.rd-cas-val').textContent = Math.round(s.value/60) + ' min';
    });
  });

  // Collect lekce
  function collectLekce() {
    return Array.from(document.querySelectorAll('#rd-lekce-list .rd-lektor-item')).map(function(item) {
      var obrEl = item.querySelector('.rd-f-obrazek');
      return {
        nazev: item.querySelector('.rd-f-nazev').value,
        popis: item.querySelector('.rd-f-popis').value,
        cas:   item.querySelector('.rd-f-cas').value,
        obsah: item.querySelector('.rd-f-obsah').value,
        obrazek: obrEl ? obrEl.value : '',
      };
    });
  }

  function rdObrIkonaNahrat() {
    return '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>Nahrát obrázek';
  }
  function rdObrIkonaOdstranit() {
    return '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>Odstranit obrázek';
  }

  window.rdUploadObr = function(btn) {
    var wrap = btn.closest('.rd-f-obrazek-wrap');
    var inp  = wrap.querySelector('.rd-f-obrazek');
    var img  = wrap.querySelector('.rd-obr-nahled');

    // Pokud už je obrázek → tlačítko funguje jako Odstranit
    if (inp.value.trim()) {
      if (!confirm('Odstranit obrázek lekce?')) return;
      var staryUrl = inp.value.trim();
      var orig = btn.innerHTML;
      btn.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="animation:rd-spin 0.7s linear infinite"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>Odstraňuji…';
      btn.disabled = true;
      var fd = new FormData();
      fd.append('action', 'rd_upload_lekce_obrazek');
      fd.append('rezim', 'odstranit');
      fd.append('stary_url', staryUrl);
      fetch('<?php echo admin_url("admin-ajax.php"); ?>', {method:'POST', credentials:'include', body:fd})
        .then(function(r){ return r.json(); })
        .then(function(){
          inp.value = '';
          img.src = '';
          img.style.display = 'none';
          btn.innerHTML = rdObrIkonaNahrat();
          btn.disabled = false;
        })
        .catch(function(){ btn.innerHTML = orig; btn.disabled = false; alert('Chyba sítě.'); });
      return;
    }

    // Jinak → nahrát nový
    var file = document.createElement('input');
    file.type = 'file';
    file.accept = 'image/jpeg,image/png,image/webp,image/gif';
    file.onchange = function() {
      if (!file.files || !file.files[0]) return;
      var orig = btn.innerHTML;
      btn.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="animation:rd-spin 0.7s linear infinite"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>Nahrávám…';
      btn.disabled = true;
      var fd = new FormData();
      fd.append('action', 'rd_upload_lekce_obrazek');
      fd.append('obrazek', file.files[0]);
      fd.append('stary_url', inp.value.trim());
      fetch('<?php echo admin_url("admin-ajax.php"); ?>', {method:'POST', credentials:'include', body:fd})
        .then(function(r){ return r.json(); })
        .then(function(res){
          btn.disabled = false;
          if (res && res.success) {
            inp.value = res.data.url;
            img.src = res.data.url;
            img.style.display = 'block';
            btn.innerHTML = rdObrIkonaOdstranit();
          } else {
            btn.innerHTML = orig;
            alert('Chyba: ' + (res && res.data ? res.data : 'nahrávání selhalo'));
          }
        })
        .catch(function(){ btn.innerHTML = orig; btn.disabled = false; alert('Chyba sítě.'); });
    };
    file.click();
  };

  // Collect otazky
  function collectOtazky() {
    return Array.from(document.querySelectorAll('#rd-otazky-list .rd-lektor-item')).map(function(item) {
      var spravna = item.querySelector('.rd-f-spravna:checked');
      var moznosti = {};
      item.querySelectorAll('.rd-f-moz').forEach(function(m) { moznosti[m.dataset.pis] = m.value; });
      return {
        otazka: item.querySelector('.rd-f-otazka').value,
        a: moznosti['A'], b: moznosti['B'], c: moznosti['C'], d: moznosti['D'],
        spravna: spravna ? spravna.value : 'A',
      };
    });
  }

  // Collect novinky
  function collectNovinky() {
    return Array.from(document.querySelectorAll('#rd-novinky-list .rd-lektor-item')).map(function(item) {
      return {
        tag:   item.querySelector('.rd-f-tag').value,
        nazev: item.querySelector('.rd-f-nazev').value,
        obsah: item.querySelector('.rd-f-obsah') ? item.querySelector('.rd-f-obsah').value : '',
      };
    });
  }

  // Form submits
  var lf = document.getElementById('rd-lekce-form');
  if (lf) lf.addEventListener('submit', function() {
    syncEditors();
    document.getElementById('lekce_json').value = JSON.stringify(collectLekce());
  });
  var tf = document.getElementById('rd-test-form');
  if (tf) tf.addEventListener('submit', function() { document.getElementById('otazky_json').value = JSON.stringify(collectOtazky()); });
  var nf = document.getElementById('rd-novinky-form');
  if (nf) nf.addEventListener('submit', function() {
    syncEditors();
    document.getElementById('novinky_json').value = JSON.stringify(collectNovinky());
  });

  // Add lekce
  var addLekce = document.getElementById('rd-add-lekce');
  if (addLekce) addLekce.addEventListener('click', function() {
    var list = document.getElementById('rd-lekce-list');
    var idx = list.children.length;
    var div = document.createElement('div');
    div.className = 'rd-lektor-item';
