  // Helper: parsovat CSV řádek se správným zacházením s uvozovkami
  function rdParseCsvLine(line) {
    var result = [], cur = '', inQ = false;
    for (var i = 0; i < line.length; i++) {
      var c = line[i];
      if (c === '"') {
        if (inQ && line[i+1] === '"') { cur += '"'; i++; } // escaped quote
        else inQ = !inQ;
      } else if (c === ';' && !inQ) { result.push(cur.trim()); cur = ''; }
      else cur += c;
    }
    result.push(cur.trim());
    return result;
  }
  function rdParseCsv(text) {
    // Odstranit BOM
    text = text.replace(/^\uFEFF/, '');
    var lines = text.split(/\r?\n/).filter(function(l) { return l.trim(); });
    // Přeskočit záhlaví pokud začíná textem (ne daty)
    var start = 0;
    if (lines.length > 0) {
      var first = rdParseCsvLine(lines[0]);
      if (isNaN(parseFloat(first[0])) && lines.length > 1) {
        // Zkontroluj jestli první řádek vypadá jako záhlaví
        var lower = first.join('').toLowerCase();
        if (lower.indexOf('název') !== -1 || lower.indexOf('otázka') !== -1 || lower.indexOf('štítek') !== -1) start = 1;
      }
    }
    return lines.slice(start).map(rdParseCsvLine);
  }

  // Helper: validovat BBcode značky - kontrola párování
  function rdValidateBb(text, cols_label) {
    var tags = ['b', 'i', 'v', 'o'];
    var errors = [];
    tags.forEach(function(t) {
      var opens  = (text.match(new RegExp('\\[' + t + '\\]', 'g')) || []).length;
      var closes = (text.match(new RegExp('\\[\\/' + t + '\\]', 'g')) || []).length;
      if (opens !== closes) {
        errors.push('[' + t + '] — otevřeno: ' + opens + ', zavřeno: ' + closes);
      }
    });
    // Kontrola neznámých značek
    var unknown = text.match(/\[[a-z]{1,10}\]/g) || [];
    unknown.forEach(function(tag) {
      var t = tag.slice(1,-1);
      if (tags.indexOf(t) === -1) errors.push('Neznámá značka: ' + tag);
    });
    return errors;
  }

  // CSV import lekce
  var csvLekce = document.getElementById('rd-import-lekce');
  if (csvLekce) csvLekce.addEventListener('click', function() {
    var file = document.getElementById('rd-csv-lekce').files[0];
    if (!file) return alert('Vyberte CSV soubor');
    var reader = new FileReader();
    reader.onload = function(e) {
      var rows = rdParseCsv(e.target.result);
      var errors = [];
      rows.forEach(function(cols, idx) {
        if (cols.length < 4) { errors.push('Řádek ' + (idx+1) + ': málo sloupců (' + cols.length + ', očekáváno 4)'); return; }
        var bbErrors = rdValidateBb(cols[3], 'Text lekce');
        if (bbErrors.length) errors.push('Řádek ' + (idx+1) + ' "' + cols[0].slice(0,20) + '": ' + bbErrors.join(', '));
        var cas = parseInt(cols[2]);
        if (isNaN(cas) || cas < 0) errors.push('Řádek ' + (idx+1) + ': Čas musí být číslo v sekundách (sloupec 3), nalezeno: "' + cols[2] + '"');
      });
      if (errors.length) {
        alert('❌ Chyby v CSV souboru:\n\n' + errors.join('\n') + '\n\nImport byl zastaven. Opravte soubor a zkuste znovu.');
        return;
      }
      var list = document.getElementById('rd-lekce-list');
      list.innerHTML = '';
      rows.forEach(function(cols, idx) {
        if (cols.length < 4) return;
        var div = document.createElement('div');
        div.className = 'rd-lektor-item';
        var cas = parseInt(cols[2]) || 180;
        var obsah = rdBbToHtml(cols[3] || '');
        div.innerHTML = '<div class="rd-lektor-item-head"><span class="rd-lektor-num">'+(idx+1)+'</span><button type="button" class="rd-btn-icon rd-del-lekce">✕</button></div><div class="rd-lektor-fields"><input type="text" class="rd-input rd-f-nazev" value="'+cols[0].replace(/"/g,'&quot;')+'"><input type="text" class="rd-input rd-f-popis" value="'+cols[1].replace(/"/g,'&quot;')+'"><label class="rd-lektor-label">Čas studia: <strong class="rd-cas-val">'+Math.round(cas/60)+' min</strong><input type="range" class="rd-f-cas" min="60" max="600" step="30" value="'+cas+'"></label><div class="rd-editor-body rd-f-obsah-div" contenteditable="true">'+obsah+'</div><textarea class="rd-input rd-f-obsah" style="display:none">'+cols[3]+'</textarea></div>';
        list.appendChild(div);
        div.querySelector('.rd-f-cas').addEventListener('input', function(ev) { div.querySelector('.rd-cas-val').textContent = Math.round(ev.target.value/60)+' min'; });
        div.querySelector('.rd-del-lekce').addEventListener('click', function() { div.remove(); });
      });
      alert('Importováno '+rows.length+' lekcí. Klikněte Uložit.');
    };
    reader.readAsText(file, 'UTF-8');
  });

