  // Helper: převést HTML na čitelný text s BBcode značkami pro CSV export
  function rdStripHtml(html) {
    var tmp = document.createElement('div');
    tmp.innerHTML = html;

    // Odstranit ovládací prvky chipů (contenteditable=false)
    tmp.querySelectorAll('[contenteditable="false"]').forEach(function(el) { el.remove(); });
    // Odstranit toolbar tlačítka
    tmp.querySelectorAll('button, .rd-editor-toolbar').forEach(function(el) { el.remove(); });

    // Rekurzivní převod DOM → text s BBcode
    function convert(node) {
      if (node.nodeType === 3) return node.textContent; // text node
      var tag = node.tagName ? node.tagName.toLowerCase() : '';
      var inner = Array.from(node.childNodes).map(convert).join('');
      if (node.classList && node.classList.contains('rd-info-chip')) {
        if (node.classList.contains('rd-chip-blue'))  return '[i]' + inner.trim() + '[/i] ';
        if (node.classList.contains('rd-chip-red'))   return '[v]' + inner.trim() + '[/v] ';
      }
      if (tag === 'strong' || tag === 'b') return '[b]' + inner + '[/b]';
      if (tag === 'li') return '[o]' + inner.trim() + '[/o] ';
      if (tag === 'ul' || tag === 'ol') return inner;
      if (tag === 'br') return ' ';
      if (tag === 'h4') return inner.trim() + ' ';
      if (tag === 'p' || tag === 'div') return inner.trim() + ' ';
      return inner;
    }

    return convert(tmp).replace(/\s+/g, ' ').trim();
  }

  // Helper: převést BBcode zpět na HTML pro import
  function rdBbToHtml(text) {
    return text
      .replace(/\[b\]([\s\S]*?)\[\/b\]/g, '<strong>$1</strong>')
      .replace(/\[i\]([\s\S]*?)\[\/i\]/g, '<div class="rd-info-chip rd-chip-blue" style="display:block;background:rgba(96,165,250,.12);border-left:3px solid #60a5fa;border-radius:6px;padding:10px 14px;margin:8px 0;color:#93c5fd;font-size:.88rem">$1</div>')
      .replace(/\[v\]([\s\S]*?)\[\/v\]/g, '<div class="rd-info-chip rd-chip-red" style="display:block;background:rgba(239,68,68,.12);border-left:3px solid #f87171;border-radius:6px;padding:10px 14px;margin:8px 0;color:#fca5a5;font-size:.88rem">$1</div>')
      .replace(/\[o\]([\s\S]*?)\[\/o\]/g, '<li>$1</li>')
      .replace(/(<li>[\s\S]*?<\/li>)/g, '<ul>$1</ul>');
  }

  // CSV export lekce
  var expLekce = document.getElementById('rd-export-lekce');
