  // Helper: stáhnout CSV
  function rdDownloadCsv(rows, filename) {
    var bom = '\uFEFF';
    var csv = bom + rows.map(function(r) {
      return r.map(function(v) { return '"' + String(v).replace(/"/g,'""') + '"'; }).join(';');
    }).join('\r\n');
    var blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    a.click();
  }
  function rdDatum() {
    return new Date().toISOString().slice(0,10);
  }

  // ── Legislativa ──
  function collectZakony() {
    var result = [];
    document.querySelectorAll('#rd-zakony-list .rd-zakon-item').forEach(function(item) {
      result.push({ sekce:'proc_povinne', zkratka:item.querySelector('.rd-f-zkratka').value, nazev:item.querySelector('.rd-f-nazev').value, podtitulek:item.querySelector('.rd-f-podtitulek').value, obsah:item.querySelector('.rd-f-obsah').value });
    });
    document.querySelectorAll('#rd-postihy-list .rd-zakon-item').forEach(function(item) {
      result.push({ sekce:'postihy', zkratka:item.querySelector('.rd-f-zkratka').value, nazev:item.querySelector('.rd-f-nazev').value, podtitulek:item.querySelector('.rd-f-podtitulek').value, obsah:item.querySelector('.rd-f-obsah').value });
    });
    return result;
  }
  function collectKroky() {
    return Array.from(document.querySelectorAll('#rd-kroky-list .rd-krok-item')).map(function(item) {
      return { sekce:'obsah', nadpis:item.querySelector('.rd-f-nadpis').value, text:item.querySelector('.rd-f-text').value };
    });
  }
  var lf3 = document.getElementById('rd-leg-form');
  if (lf3) lf3.addEventListener('submit', function() {
    document.getElementById('zakony_json').value = JSON.stringify(collectZakony());
    document.getElementById('kroky_json').value = JSON.stringify(collectKroky());
  });
  function makeZakonItem(sekce, listId) {
    var list = document.getElementById(listId);
    var div = document.createElement('div');
    div.className = 'rd-lektor-item rd-zakon-item'; div.style.position = 'relative';
    div.dataset.sekce = sekce;
    div.innerHTML = '<div class="rd-lektor-item-head"><span class="rd-lektor-num">'+(list.children.length+1)+'</span></div><button type="button" class="rd-btn-icon rd-del-zakon" style="position:absolute;top:12px;right:12px;background:none;border:none;cursor:pointer;color:var(--au-text-3,#6b7280);font-size:14px;line-height:1;padding:2px 6px;border-radius:4px">✕</button><div class="rd-lektor-fields"><input type="text" class="rd-input rd-f-zkratka" placeholder="Zkratka" style="max-width:120px"><input type="text" class="rd-input rd-f-nazev" placeholder="Název"><input type="text" class="rd-input rd-f-podtitulek" placeholder="Podtitulek"><textarea class="rd-input rd-f-obsah" rows="3" placeholder="Obsah"></textarea></div>';
    list.appendChild(div);
    div.querySelector('.rd-del-zakon').addEventListener('click', function() { div.remove(); });
  }
  var addZakon = document.getElementById('rd-add-zakon');
  if (addZakon) addZakon.addEventListener('click', function() { makeZakonItem('proc_povinne','rd-zakony-list'); });
  var addPostih = document.getElementById('rd-add-postih');
  if (addPostih) addPostih.addEventListener('click', function() { makeZakonItem('postihy','rd-postihy-list'); });
  document.querySelectorAll('.rd-del-zakon').forEach(function(btn) { btn.addEventListener('click', function() { btn.closest('.rd-lektor-item').remove(); }); });
  var addKrok = document.getElementById('rd-add-krok');
