    var list = document.getElementById('rd-kroky-list');
    var div = document.createElement('div');
    div.className = 'rd-lektor-item rd-krok-item'; div.style.position = 'relative';
    div.innerHTML = '<div class="rd-lektor-item-head"><span class="rd-lektor-num">'+(list.children.length+1)+'</span></div><button type="button" class="rd-btn-icon rd-del-krok" style="position:absolute;top:12px;right:12px;background:none;border:none;cursor:pointer;color:var(--au-text-3,#6b7280);font-size:14px;line-height:1;padding:2px 6px;border-radius:4px">✕</button><div class="rd-lektor-fields"><input type="text" class="rd-input rd-f-nadpis" placeholder="Nadpis kroku"><textarea class="rd-input rd-f-text" rows="3" placeholder="Text"></textarea></div>';
    list.appendChild(div);
    div.querySelector('.rd-del-krok').addEventListener('click', function() { div.remove(); });
  });
  document.querySelectorAll('.rd-del-krok').forEach(function(btn) { btn.addEventListener('click', function() { btn.closest('.rd-lektor-item').remove(); }); });

})();
