/* ---- PŘIHLÁŠENÍ ---- */
function rd_sc_prihlaseni() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();

    // Admin preview — přihlásit pod tokenem bez hesla (jen pro přihlášené WP adminy/autoskola_admin)
    if (!empty($_GET['admin_preview_token']) && is_user_logged_in() && (current_user_can('manage_options') || rd_je_autoskola_admin())) {
        global $wpdb;
        $token = sanitize_text_field($_GET['admin_preview_token']);
        $k = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE token=%s LIMIT 1", $token));
        if ($k) {
            $_SESSION['rd_kod']   = $k->kod;
            $_SESSION['rd_jmeno'] = 'Admin preview';
            $_SESSION['rd_token'] = $k->token;
            wp_redirect(home_url('/kurz/'));
            exit;
        }
    }

    if (isset($_SESSION['rd_kod'])) {
        global $wpdb;
        // Zkontrolovat v DB jestli student splnil kurz
        $splnil = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1",
            $_SESSION['rd_kod']
        ));
        if ($splnil) {
            // Doplnit cert session z DB
            $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
            $_SESSION['rd_cert_jmeno'] = $splnil->jmeno;
            $_SESSION['rd_cert_datum'] = date('d.m.Y', strtotime($splnil->datum_skoleni));
            $_SESSION['rd_cert_firma'] = $kr ? $kr->firma_nazev : '';
            $_SESSION['rd_cert_score'] = $splnil->score;
            $_SESSION['rd_cert_uuid']  = $splnil->cert_uuid;
            $_SESSION['rd_cert_kod']   = $_SESSION['rd_kod'];
            $_SESSION['rd_cert_token'] = $_SESSION['rd_token'] ?? '';
            wp_redirect(home_url('/certifikat/')); exit;
        }
        wp_redirect(home_url('/kurz/')); exit;
    }
    $err = '';
    if (isset($_POST['rd_login'])) {
        $kod   = strtoupper(sanitize_text_field($_POST['rd_kod']));
        $jmeno = sanitize_text_field($_POST['rd_jmeno']);
        if (!$kod || !$jmeno) { $err = 'Vyplňte kód i jméno.'; }
        else {
            // Bruteforce ochrana – max 5 neúspěšných pokusů za 15 minut per IP
            $ip_key   = 'rd_bf_' . md5(rd_get_ip());
            $pokusy   = (int)get_transient($ip_key);
            if ($pokusy >= 5) {
                $err = 'Příliš mnoho neúspěšných pokusů. Zkuste to znovu za 15 minut.';
            } else {
            global $wpdb;
            // Nejdřív zkontrolovat zda kód existuje vůbec
            $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
            if (!$r) {
                $err = 'Kód není platný. Kontaktujte zaměstnavatele.';
                set_transient($ip_key, $pokusy + 1, 15 * MINUTE_IN_SECONDS);
            } elseif ($r->expiruje && strtotime($r->expiruje) < strtotime('today')) {
                $err = 'Platnost tohoto kódu vypršela dne ' . date('d.m.Y', strtotime($r->expiruje)) . '. Kontaktujte svého zaměstnavatele pro nový kód.';
            } elseif (!$r->pouzit && !empty($r->zamestnanec_jmeno) && strtolower(trim($r->zamestnanec_jmeno)) !== strtolower(trim($jmeno))) {
                // Kód přiřazen konkrétnímu zaměstnanci — jiné jméno neprojde
                $err = 'Tento kód je přiřazen jinému zaměstnanci. Kontaktujte svého zaměstnavatele.';
                set_transient($ip_key, $pokusy + 1, 15 * MINUTE_IN_SECONDS);
            } elseif ($r->pouzit && $r->ridic_jmeno && strtolower(trim($r->ridic_jmeno)) !== strtolower(trim($jmeno))) {
                // Kód použit jiným jménem
                $err = 'Kód byl již použit jiným řidičem.';
            } elseif ($r->pouzit) {
                // Stejné jméno, kód již použit - zkontrolovat stav kurzu
                $absolvoval = $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1",
                    $kod
                ));
                if ($absolvoval) {
                    // Přihlásit a zobrazit stránku s certifikátem
                    $_SESSION['rd_kod']         = $kod;
                    $_SESSION['rd_jmeno']       = $r->ridic_jmeno;
                    $_SESSION['rd_firma_email'] = $r->firma_email;
                    $_SESSION['rd_firma_nazev'] = $r->firma_nazev;
                    $_SESSION['rd_token']       = $r->token;
                    $_SESSION['rd_cert_jmeno']  = $absolvoval->jmeno;
                    $_SESSION['rd_cert_datum']  = date('d.m.Y', strtotime($absolvoval->datum_skoleni));
                    $_SESSION['rd_cert_firma']  = $absolvoval->firma_nazev;
                    $_SESSION['rd_cert_score']  = $absolvoval->score;
                    $_SESSION['rd_cert_uuid']   = $absolvoval->cert_uuid;
                    $_SESSION['rd_cert_kod']    = $kod;
                    $_SESSION['rd_cert_token']  = $r->token;
                    setcookie('rd_ridic', $kod, time()+86400*30, '/', '', is_ssl(), true);
                    wp_redirect(home_url('/certifikat/')); exit;
                } else {
                    // Vrátit řidiče do rozdělaného kurzu
                    $_SESSION['rd_kod']         = $kod;
                    $_SESSION['rd_jmeno']       = $r->ridic_jmeno;
                    $_SESSION['rd_firma_email'] = $r->firma_email;
                    $_SESSION['rd_firma_nazev'] = $r->firma_nazev;
                    $_SESSION['rd_token']       = $r->token;
                    setcookie('rd_ridic', $kod, time()+86400*30, '/', '', is_ssl(), true);
                    wp_redirect(home_url('/kurz/?token=' . $r->token)); exit;
                }
            } else {
                // Nový kód - první přihlášení
                $token = bin2hex(random_bytes(24));
                $wpdb->update(RD_TABLE_KODY, ['pouzit' => 1, 'ridic_jmeno' => $jmeno, 'datum_pouziti' => current_time('mysql'), 'token' => $token], ['kod' => $kod]);
                $_SESSION['rd_kod']         = $kod;
                $_SESSION['rd_jmeno']       = $jmeno;
                $_SESSION['rd_firma_email'] = $r->firma_email;
                $_SESSION['rd_firma_nazev'] = $r->firma_nazev;
                $_SESSION['rd_token']       = $token;
                // v6.0.0 — nastavit autoškolu do session
                if (!empty($r->autoskola_id)) {
                    $_SESSION['rd_autoskola_id'] = $r->autoskola_id;
                }
                // v6.0.0 — varování pokud kód expiruje do 30 dní
                if ($r->expiruje) {
                    $dni_do_exp = (int)round((strtotime($r->expiruje) - strtotime('today')) / 86400);
                    if ($dni_do_exp <= 30 && $dni_do_exp > 0) {
                        $_SESSION['rd_expiry_warning'] = 'Váš přístupový kód vyprší za <strong>' . $dni_do_exp . ' dní</strong> (' . date('d.m.Y', strtotime($r->expiruje)) . '). Dokončete školení včas.';
                    }
                }
                setcookie('rd_ridic', $kod, time()+86400*30, '/', '', is_ssl(), true);
                wp_redirect(home_url('/kurz/?token=' . $token)); exit;
            }
            } // end else bruteforce
        }
    }
    ob_start(); ?>
