        <button class="rd-btn rd-btn-green rd-btn-done" data-lekce="<?php echo $n; ?>" id="rdbtn<?php echo $n; ?>" disabled><svg style="width:16px;height:16px;vertical-align:middle;margin-right:6px" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 22h14M5 2h14M17 22v-4.172a2 2 0 00-.586-1.414L12 12M7 22v-4.172a2 2 0 01.586-1.414L12 12m0 0L7 6.172A2 2 0 016.586 4.758V2h10.828A2 2 0 0119 4.172v.586a2 2 0 01-.586 1.414L12 12z"/></svg>Probíhá studium</button>
      </div>
    </div>
    <?php endforeach; ?>
  </div>
  <div class="rd-kurz-complete" id="rd-kurz-complete">
    <div class="rd-complete-icon"><div class="rd-fi-aurora rd-ty-svg"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg></div></div>
    <h3 class="rd-complete-title">Všechny lekce hotové!</h3>
    <?php if (!empty($_SESSION['rd_lektor_preview'])): ?>
    <p>Náhled kurzu byl úspěšně dokončen. Obsah všech lekcí byl zkontrolován.</p>
    <a href="<?php echo esc_url(home_url('/?rd_nahled_konec=1')); ?>" class="rd-btn rd-btn-ghost" style="margin-top:8px">← Zpět do portálu lektora</a>
    <?php else: ?>
    <p>Pokračujte k závěrečnému testu — potřebujete alespoň <strong>80 %</strong> správných odpovědí.</p>
    <a href="<?php echo home_url('/zaverecny-test/?token=' . ($_SESSION['rd_token'] ?? '')); ?>" class="rd-btn rd-btn-primary">Spustit závěrečný test <svg style="display:inline;vertical-align:middle;margin-left:4px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></a>
    <?php endif; ?>
  </div>
</div>
    <?php return ob_get_clean();
}

/* ---- KVÍZ ---- */
function rd_sc_kviz() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    $tok = isset($_GET['token']) ? sanitize_text_field($_GET['token']) : (isset($_POST['_tok']) ? sanitize_text_field($_POST['_tok']) : '');
    if (!isset($_SESSION['rd_kod']) && $tok) {
        global $wpdb;
        $r = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE token=%s", $tok));
        if ($r) { $_SESSION['rd_kod']=$r->kod; $_SESSION['rd_jmeno']=$r->ridic_jmeno; $_SESSION['rd_firma_email']=$r->firma_email; $_SESSION['rd_firma_nazev']=$r->firma_nazev; $_SESSION['rd_token']=$tok; }
    }
    if (!isset($_SESSION['rd_kod'])) {
        // Zkontrolovat jestli má platný certifikát
        if (isset($_SESSION['rd_cert_jmeno']) && isset($_SESSION['rd_cert_token']) && isset($_SESSION['rd_token']) && $_SESSION['rd_cert_token'] === $_SESSION['rd_token']) {
            wp_redirect(home_url('/certifikat/')); exit;
        }
        wp_redirect(home_url('/prihlaseni/')); exit;
    }
    // LEGISLATIVNÍ OCHRANA: ověřit že řidič dokončil všechny lekce na serveru
    // Výjimka: zkušební test lektora přeskočí kontrolu
    global $wpdb;
    $je_zkusebni = !empty($_SESSION['rd_lektor_zkusebni']);
    if (!$je_zkusebni) {
        $kod_row_check = $wpdb->get_row($wpdb->prepare("SELECT lekce_done FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
        $lekce_done_check = $kod_row_check && $kod_row_check->lekce_done ? json_decode($kod_row_check->lekce_done, true) : [];
        $celkem_lekci = count(rd_lekce_source());
        $done_unique = array_unique(array_map('intval', (array)$lekce_done_check));
        $max_done = !empty($done_unique) ? max($done_unique) : 0;
        $vse_splneno = (count($done_unique) >= $celkem_lekci)
                    || ($max_done >= $celkem_lekci)
                    || (!empty($_SESSION['rd_kurz_done']) && $_SESSION['rd_kurz_done'] === $_SESSION['rd_kod']);
        if (!$vse_splneno) {
            return '<div class="rd-page rd-center" style="padding-top:60px"><div class="rd-login-card" style="text-align:center">
                <div class="rd-fi-aurora rd-ty-svg" style="margin:0 auto 20px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg></div>
                <h2 style="margin-bottom:12px">Test ještě není dostupný</h2>
                <p style="color:var(--au-text-2);margin-bottom:24px">Pro přístup k závěrečnému testu musíte nejprve dokončit všechny lekce kurzu.<br>Dokončeno: <strong>' . count(array_unique($lekce_done_check)) . '/' . $celkem_lekci . '</strong></p>
                <a href="' . home_url('/kurz/') . '" class="rd-btn rd-btn-primary">Zpět do kurzu <svg style="display:inline;vertical-align:middle;margin-left:4px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></a>
            </div></div>';
        }
    }

        // Pokud řidič již splnil test v DB, ukázat výsledek
    $jiz_splnil = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1",
        $_SESSION['rd_kod']
    ));
    if ($jiz_splnil) {
        // Obnovit session z DB pokud chybí
        if (!isset($_SESSION['rd_cert_jmeno'])) {
            $r2 = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $_SESSION['rd_kod']));
            if ($r2) {
                $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s", $_SESSION['rd_kod']));
                $_SESSION['rd_cert_jmeno'] = $r2->jmeno;
                $_SESSION['rd_cert_datum'] = $r2->datum_skoleni;
                $_SESSION['rd_cert_firma'] = $kr ? $kr->firma_nazev : '';
                $_SESSION['rd_cert_score'] = $r2->score;
                $_SESSION['rd_cert_token'] = $_SESSION['rd_token'] ?? '';
            }
        }
        wp_redirect(home_url('/certifikat/')); exit;
    }
    if (isset($_POST['odeslat_test'])) {
        global $wpdb;
        // Náhledový režim lektora — nevyhodnocovat, nezapisovat, jen info
        if (!empty($_SESSION['rd_lektor_preview'])) {
            // Zkušební test lektora — vyhodnotit bez zápisu do DB
            if (!empty($_SESSION['rd_lektor_zkusebni'])) {
                // Vyhodnotit stejně jako ostrý test
                $otazky_tok = isset($_POST['_otazky_tok']) ? sanitize_text_field(wp_unslash($_POST['_otazky_tok'])) : '';
                $tok_parts = explode('.', $otazky_tok, 2);
                $spravne_klic = null;
                if (count($tok_parts) === 2) {
                    [$payload, $sig] = $tok_parts;
                    $expected_sig = hash_hmac('sha256', $payload, wp_salt('auth'));
                    if (hash_equals($expected_sig, $sig)) {
                        $decoded = json_decode(base64_decode($payload), true);
                        if (is_array($decoded)) $spravne_klic = $decoded;
                    }
                }
                if ($spravne_klic === null) {
                    return '<div class="rd-page"><div class="rd-info-chip rd-chip-red">Chyba: nepodařilo se načíst otázky. Zkuste spustit test znovu.</div></div>';
                }
                $celkem = count($spravne_klic);
                $spravne = 0;
                $odpovedi = [];
                foreach ($spravne_klic as $idx => $spravna) {
                    $zvolena = isset($_POST['q'.$idx]) ? sanitize_text_field($_POST['q'.$idx]) : null;
                    $ok = ($zvolena === $spravna);
                    if ($ok) $spravne++;
                    $odpovedi[$idx] = ['zvolena' => $zvolena, 'spravna' => $spravna, 'ok' => $ok];
                }
                $procent = $celkem > 0 ? round($spravne / $celkem * 100) : 0;
                $uspech = $procent >= 80;
                // Načíst texty otázek z tokenu (payload obsahuje jen správné odpovědi, texty z $_POST['qt'])
                $qt = isset($_POST['qt']) ? (array)$_POST['qt'] : [];
                $qm = isset($_POST['qm']) ? (array)$_POST['qm'] : [];
                ob_start();
                ?>
                <div class="rd-page">
                  <div style="background:#fffbeb;border:1px solid #fbbf24;border-left:4px solid #f59e0b;border-radius:10px;padding:10px 16px;margin-bottom:20px;margin-top:20px;font-size:13px;display:flex;align-items:center;gap:8px">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                    <span style="color:#92400e"><strong style="color:#92400e">Zkušební test lektora</strong> — výsledky se neukládají</span>
                  </div>
                  <div style="<?php echo $uspech ? 'background:#dcfce7;border:1px solid #86efac' : 'background:#fee2e2;border:1px solid #fca5a5'; ?>;border-radius:12px;padding:24px;text-align:center;margin-bottom:24px">
                    <div style="font-size:2.5rem;font-weight:900;color:<?php echo $uspech ? '#166534' : '#991b1b'; ?>"><?php echo $spravne; ?> / <?php echo $celkem; ?></div>
                    <div style="font-size:1rem;color:<?php echo $uspech ? '#166534' : '#991b1b'; ?>;margin-top:4px"><?php echo $procent; ?> % správně — <?php echo $uspech ? '✓ Splněno (min. 80 %)' : '✗ Nesplněno (min. 80 %)'; ?></div>
                  </div>
                  <?php foreach ($odpovedi as $idx => $ans): ?>
                  <?php $bc = $ans['ok'] ? '#22c55e' : '#ef4444'; ?>
                  <div style="margin-bottom:10px;padding:14px;border-radius:10px;border:1px solid <?php echo $bc; ?>33;background:<?php echo $bc; ?>0d">
                    <div style="font-size:.85rem;font-weight:600;margin-bottom:8px;color:var(--au-text-1,#111)"><?php echo ($idx+1) . '. ' . esc_html($qt[$idx] ?? '—'); ?></div>
                    <?php foreach (['A','B','C','D'] as $p): ?>
                    <?php
                      $isSpravna = ($p === $ans['spravna']);
                      $isZvolena = ($p === $ans['zvolena']);
                      $bg = $isSpravna ? 'background:#dcfce7;color:#166534;font-weight:600' : ($isZvolena && !$ans['ok'] ? 'background:#fee2e2;color:#991b1b' : 'color:var(--au-text-2,#6b7280)');
                      $ico = $isSpravna ? '✓ ' : ($isZvolena && !$ans['ok'] ? '✗ ' : '');
                      $moznost_text = esc_html($qm[$idx][$p] ?? '');
                    ?>
                    <div style="font-size:.8rem;padding:4px 8px;border-radius:6px;margin-bottom:2px;<?php echo $bg; ?>"><?php echo $ico; ?><strong><?php echo $p; ?>.</strong> <?php echo $moznost_text; ?></div>
                    <?php endforeach; ?>
                    <?php if (!$ans['zvolena']): ?><div style="font-size:.75rem;color:#92400e;margin-top:4px">⚠ Nezodpovězeno</div><?php endif; ?>
                  </div>
                  <?php endforeach; ?>
                  <div style="margin-top:32px;text-align:center">
                    <a href="<?php echo esc_url(home_url('/?rd_nahled_konec=1')); ?>" class="rd-btn rd-btn-ghost">← Zpět do portálu lektora</a>
                  </div>
                </div>
                <?php
                return ob_get_clean();
            }
            // Běžný náhled kurzu — jen info
            return '<div class="rd-page" style="text-align:center;padding:60px 20px"><div style="background:var(--rd-grad,linear-gradient(135deg,#7c3aed,#db2777));color:#fff;border-radius:14px;padding:30px;max-width:500px;margin:0 auto"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="margin-bottom:12px"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg><h2 style="margin:0 0 8px">Náhledový režim</h2><p style="opacity:.9;margin:0">V náhledu se test nevyhodnocuje ani neukládá. Takto ho uvidí vaši studenti.</p></div></div>';
        }
        // zobrazeny ve formuláři. Klíč správných odpovědí je přenášen v
        // podepsaném skrytém poli (ne v PHP session — ta se mezi GET a POST
        // u tohoto formuláře ukázala nespolehlivá), takže nelze losovat
        // novou sadu a porovnávat proti ní staré odpovědi.
        $otazky_tok = isset($_POST['_otazky_tok']) ? sanitize_text_field(wp_unslash($_POST['_otazky_tok'])) : '';
        $tok_parts = explode('.', $otazky_tok, 2);
        $spravne_klic = null;
        if (count($tok_parts) === 2) {
            [$payload, $sig] = $tok_parts;
            $expected_sig = hash_hmac('sha256', $payload, wp_salt('auth'));
            if (hash_equals($expected_sig, $sig)) {
                $decoded = json_decode(base64_decode($payload), true);
                if (is_array($decoded)) $spravne_klic = $decoded;
            }
        }
        if ($spravne_klic === null) {
            wp_redirect(home_url('/zaverecny-test/')); exit;
        }
        $celkem = count($spravne_klic); $spravne=0;
        foreach ($spravne_klic as $i=>$sp) { $odp=isset($_POST['q'.$i])?sanitize_text_field($_POST['q'.$i]):''; if($odp===$sp)$spravne++; }
        $score=$uspech=0; $score=round($spravne/$celkem*100); $uspech=$score>=80;
        $jmeno=$_SESSION['rd_jmeno']; $kod=$_SESSION['rd_kod']; $datum=date('d.m.Y');
        // Načíst email a název firmy přímo z DB - spolehlivější než session
        $kod_row = $wpdb->get_row($wpdb->prepare("SELECT firma_email, firma_nazev, datum_pouziti, aktivni_cas_sec FROM " . RD_TABLE_KODY . " WHERE kod=%s", $kod));
        $femail = $kod_row ? $kod_row->firma_email : ($_SESSION['rd_firma_email'] ?? '');
        $fnazev = $kod_row ? $kod_row->firma_nazev : ($_SESSION['rd_firma_nazev'] ?? '');
        // Výpočet doby trvání kurzu
        $trvani = '';
        if ($kod_row && $kod_row->datum_pouziti) {
            $diff = round((time() - strtotime($kod_row->datum_pouziti)) / 60);
            $trvani = $diff > 0 ? $diff . ' min' : '';
        }
        $cert_uuid = $uspech ? wp_generate_uuid4() : null;
        // Délka školení = celkový aktivní čas (lekce + test), kumulovaný
        // periodickým ukládáním ze všech stránek kurzu (aktivni_cas_sec).
        // _aktivni_cas z formuláře (jen čas na této stránce) je fallback,
        // wall-clock rozdíl je poslední záchrana.
        if ($kod_row && (int)$kod_row->aktivni_cas_sec > 0) {
            $trvani_min = max(1, round((int)$kod_row->aktivni_cas_sec / 60));
        } elseif (isset($_POST['_aktivni_cas']) && intval($_POST['_aktivni_cas']) > 0) {
            $trvani_min = intval($_POST['_aktivni_cas']);
        } else {
            $trvani_min = ($kod_row && $kod_row->datum_pouziti) ? max(0, round((time() - strtotime($kod_row->datum_pouziti)) / 60)) : 0;
        }
        // v6.0.0 — přidat autoskola_id
        $ridici_data = ['kod'=>$kod,'firma_nazev'=>$fnazev,'firma_email'=>$femail,'jmeno'=>$jmeno,'score'=>$score,'uspech'=>$uspech?1:0,'cert_uuid'=>$cert_uuid,'trvani_min'=>$trvani_min];
        if (!empty($kod_row->autoskola_id)) $ridici_data['autoskola_id'] = $kod_row->autoskola_id;
        // IDEMPOTENCE: refresh/opětovné odeslání téhož formuláře (stejný kód +
        // stejný podepsaný klíč otázek) by jinak vytvořilo duplicitní záznam
        // a u úspěchu znovu odeslalo e-mail. Pokud už existuje záznam se
        // stejným kódem a stejným skórem za posledních 60 sekund, jde o
        // duplicitní odeslání — znovu nevkládat ani neodesílat e-mail.
        $existujici = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND score=%d AND datum_skoleni >= DATE_SUB(NOW(), INTERVAL 60 SECOND) ORDER BY id DESC LIMIT 1",
            $kod, $score
        ));
        if ($existujici) {
            $cert_uuid = $existujici->cert_uuid;
            $uspech = (bool)$existujici->uspech;
        } else {
        $wpdb->insert(RD_TABLE_RIDICI, $ridici_data);
        if ($uspech) {
            $wpdb->update(RD_TABLE_KODY,['pouzit'=>1],['kod'=>$kod]);
            $_SESSION['rd_cert_jmeno']=$jmeno; $_SESSION['rd_cert_datum']=$datum; $_SESSION['rd_cert_firma']=$fnazev; $_SESSION['rd_cert_score']=$score;
            $_SESSION['rd_cert_token'] = isset($_SESSION['rd_token']) ? $_SESSION['rd_token'] : uniqid();
            $_SESSION['rd_cert_kod'] = $_SESSION['rd_kod'] ?? ''; // Uložit před unset
            // Zajistit cert_uuid
            if (empty($_SESSION['rd_cert_uuid'])) {
                global $wpdb;
                $r_uuid = $wpdb->get_row($wpdb->prepare("SELECT id, cert_uuid FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $kod));
                if ($r_uuid) {
                    if (empty($r_uuid->cert_uuid)) { $nu = wp_generate_uuid4(); $wpdb->update(RD_TABLE_RIDICI, ['cert_uuid'=>$nu], ['id'=>$r_uuid->id]); $_SESSION['rd_cert_uuid'] = $nu; }
                    else { $_SESSION['rd_cert_uuid'] = $r_uuid->cert_uuid; }
                }
            }
            $_SESSION['rd_cert_uuid'] = $cert_uuid;
            $_SESSION['rd_cert_uuid'] = $cert_uuid;
            rd_odeslat_email($jmeno,$femail,$fnazev,$score,$datum,$kod,$trvani);
            // Email zaměstnavateli – automatické potvrzení o absolvování
            if ($femail) {
                $cert_url = home_url('/certifikat/?uuid=' . $cert_uuid);
                $subj_f = 'Zaměstnanec absolvoval školení řidičů – ' . $jmeno;
                $body_f  = rd_email_wrap(
                    $subj_f,
                    '<p>Dobrý den,</p>'
                    . '<p>informujeme vás, že váš zaměstnanec/ka <strong>' . esc_html($jmeno) . '</strong> úspěšně absolvoval/a školení referentských řidičů.</p>'
                    . '<table style="width:100%;border-collapse:collapse;font-size:13px;margin:16px 0">'
                    . '<tr><td style="padding:6px 0;color:#6b7280;width:140px">Jméno</td><td style="padding:6px 0;font-weight:600">' . esc_html($jmeno) . '</td></tr>'
                    . '<tr><td style="padding:6px 0;color:#6b7280">Výsledek testu</td><td style="padding:6px 0;font-weight:600;color:#16a34a">' . $score . ' %</td></tr>'
                    . '<tr><td style="padding:6px 0;color:#6b7280">Datum absolvování</td><td style="padding:6px 0">' . $datum . '</td></tr>'
                    . '<tr><td style="padding:6px 0;color:#6b7280">Přístupový kód</td><td style="padding:6px 0"><code>' . esc_html($kod) . '</code></td></tr>'
                    . '</table>'
                    . rd_email_btn('Zobrazit certifikát →', $cert_url)
                    . '<p style="font-size:12px;color:#9ca3af;margin-top:16px">Certifikát a ověření pravosti jsou dostupné po přihlášení do firemního portálu.</p>'
                );
                wp_mail($femail, $subj_f, $body_f, ['Content-Type: text/html; charset=UTF-8']);
            }
            unset($_SESSION['rd_kod'],$_SESSION['rd_firma_email'],$_SESSION['rd_firma_nazev']);
        }
        } // konec idempotence else (nový záznam)
        ob_start(); ?>
<div class="rd-page rd-center">
  <div class="rd-vysledek <?php echo $uspech?'rd-uspech':'rd-neuspech'; ?>">
    <div class="rd-vys-icon"><?php echo $uspech?'<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="url(#tg)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="tg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient></defs><path d="M6 9H4.5a2.5 2.5 0 010-5H6"/><path d="M18 9h1.5a2.5 2.5 0 000-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0012 0V2z"/></svg>':'<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="url(#sg)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="sg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient></defs><circle cx="12" cy="12" r="10"/><path d="M16 16s-1.5-2-4-2-4 2-4 2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>'; ?></div>
    <h2 class="rd-vys-title"><?php echo $uspech?'Školení úspěšně splněno!':'Test se nepodařilo splnit'; ?></h2>
    <div class="rd-score-ring">
      <svg class="<?php echo $uspech?'rd-score-ok':'rd-score-err'; ?>" viewBox="0 0 100 100" width="130" height="130">
