    $otazky_sig = hash_hmac('sha256', $otazky_payload, wp_salt('auth'));
    $otazky_token = $otazky_payload . '.' . $otazky_sig;
    $tok2=isset($_SESSION['rd_token'])?$_SESSION['rd_token']:'';
