/* ---- CERTIFIKÁT ---- */
function rd_sc_certifikat() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    global $wpdb;

    // Zjistit kód — ze session, cookie nebo URL parametru (pro admin/autoškolu)
    $cert_kod = $_SESSION['rd_cert_kod'] ?? $_SESSION['rd_kod'] ?? '';
    if (empty($cert_kod) && !empty($_COOKIE['rd_ridic'])) {
        $cert_kod = sanitize_text_field($_COOKIE['rd_ridic']);
    }
    // URL parametr ?kod= — pro přihlášené WP uživatele nebo firmu ze session
    if (empty($cert_kod) && !empty($_GET['kod'])) {
        $req_kod = sanitize_text_field($_GET['kod']);
        $je_wp_admin = is_user_logged_in() && (current_user_can('manage_options') || current_user_can('refdrive_access'));
        // Firma — ověřit že kód patří této firmě
        $je_firma = !empty($_SESSION['rd_firma_id']);
        if ($je_firma) {
            $firma_owns = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE kod=%s AND firma_email=(SELECT email FROM {$wpdb->prefix}rd_firmy WHERE id=%d LIMIT 1)",
                $req_kod, intval($_SESSION['rd_firma_id'])
            ));
            if ($firma_owns) $cert_kod = $req_kod;
        } elseif ($je_wp_admin) {
            $cert_kod = $req_kod;
        }
    }

    if (empty($cert_kod)) {
        wp_redirect(home_url('/')); exit;
    }

    // Načíst data přímo z DB — nezávisle na session
    $kr = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_KODY . " WHERE kod=%s LIMIT 1", $cert_kod));
    $splnil = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1 ORDER BY datum_skoleni DESC LIMIT 1", $cert_kod
    ));

    if (!$kr || !$splnil) {
        wp_redirect(home_url('/')); exit;
    }

    // Zajistit cert_uuid
    if (empty($splnil->cert_uuid)) {
        $nu = wp_generate_uuid4();
        $wpdb->update(RD_TABLE_RIDICI, ['cert_uuid' => $nu], ['id' => $splnil->id]);
        $splnil->cert_uuid = $nu;
    }

    $j = $splnil->jmeno;
    $f = $kr->firma_nazev ?? '';
    $s = intval($splnil->score);
    $datum_cas = date('d.m.Y H:i', strtotime($splnil->datum_skoleni));
    $cert_token = $kr->token ?? '';
    // Vygenerovat jednorázový přístupový token s expirací 1 hodiny
    $access_key = bin2hex(random_bytes(16));
    set_transient('rd_cert_access_' . $access_key, $cert_kod, HOUR_IN_SECONDS);
    $cert_url_sc = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($cert_kod) . '&access=' . $access_key;
    $score_dash = round($s * 2.765);
    ob_start(); ?>
<div class="rd-page rd-center">
  <div class="rd-vysledek rd-uspech">
    <div class="rd-vys-icon"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="url(#tg)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="tg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient></defs><path d="M6 9H4.5a2.5 2.5 0 010-5H6"/><path d="M18 9h1.5a2.5 2.5 0 000-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0012 0V2z"/></svg></div>
    <h2 class="rd-vys-title">Školení úspěšně splněno!</h2>
    <div class="rd-score-ring">
      <svg viewBox="0 0 100 100" width="130" height="130">
        <circle cx="50" cy="50" r="44" fill="none" stroke="rgba(52,211,153,.15)" stroke-width="7"/>
        <circle cx="50" cy="50" r="44" fill="none" stroke="#34d399" stroke-width="7" stroke-dasharray="<?php echo $score_dash; ?> 276" stroke-linecap="round" transform="rotate(-90 50 50)"/>
        <text x="50" y="56" text-anchor="middle" font-size="20" font-weight="bold" fill="#34d399" font-family="Arial,sans-serif"><?php echo $s; ?>%</text>
      </svg>
    </div>
    <p class="rd-vys-jmeno"><strong><?php echo esc_html($j); ?></strong> &mdash; <?php echo esc_html($f); ?></p>
    <div class="rd-email-note">
      <span class="rd-email-note-icon"><svg style="display:inline;vertical-align:middle;margin-right:4px" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg></span>
      Absolvováno: <strong><?php echo esc_html($datum_cas); ?></strong>
    </div>
    <a href="<?php echo esc_url($cert_url_sc); ?>" target="_blank" class="rd-btn rd-btn-primary">
      Zobrazit certifikát
      <svg style="display:inline;vertical-align:middle;margin-left:4px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
    </a>
  </div>
</div>
<?php return ob_get_clean();
}


/* ---- OBJEDNÁVKA ---- */
function rd_sc_objednavka() {
    // Zakázat cachování této stránky — cena se musí vždy číst čerstvě z DB
    if (!headers_sent()) {
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
        header('Pragma: no-cache');
        header('Expires: Thu, 01 Jan 1970 00:00:00 GMT');
    }
    // Kompatibilita s WP Rocket, LiteSpeed Cache, W3TC, WP Super Cache
    if (!defined('DONOTCACHEPAGE')) define('DONOTCACHEPAGE', true);
    if (!defined('DONOTCACHEDB'))   define('DONOTCACHEDB',   true);

    global $wpdb;
    // PK se načte až po zjištění autoškoly — viz níže
    $pk = '';

    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();

    // Načíst autoškolu — ?ref= má absolutní prioritu, pak session
    $as_fresh = null;
    $ref = sanitize_key($_GET['ref'] ?? '');

    if ($ref && defined('RD_TABLE_AUTOSKOLY')) {
        // Přímo z URL parametru — nejspolehlivější
        $as_fresh = $wpdb->get_row($wpdb->prepare(
            "SELECT id, slug, nazev, cena_kus, oop_url, stripe_pk, stripe_sk, stripe_aktivni, stripe_overeno FROM " . RD_TABLE_AUTOSKOLY . " WHERE slug=%s AND stav='aktivni' LIMIT 1",
            $ref
        ));
        if ($as_fresh) $_SESSION['rd_autoskola_id'] = $as_fresh->id;
    }

    if (!$as_fresh && !empty($_SESSION['rd_autoskola_id']) && defined('RD_TABLE_AUTOSKOLY')) {
        // Fallback na session — vždy čerstvě z DB
        $as_fresh = $wpdb->get_row($wpdb->prepare(
            "SELECT id, slug, nazev, cena_kus, oop_url, stripe_pk, stripe_sk, stripe_aktivni, stripe_overeno FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1",
            intval($_SESSION['rd_autoskola_id'])
        ));
    }

    // Bez platné autoškoly (ref nebo session) — zobrazit výběr autoškoly
    if (!$as_fresh) {
        ob_start(); ?>
<div class="rd-page" style="max-width:480px;margin:0 auto;padding-top:60px;text-align:center">
    <div class="rd-hero-badge" style="margin-bottom:24px;display:inline-flex">Pro firmy</div>
    <h1 class="rd-hero-h1" style="font-size:1.8rem!important">Vyberte autoškolu</h1>
    <p class="rd-hero-sub">Pro objednání školení prosím vyberte autoškolu z naší sítě partnerů.</p>
    <a href="<?php echo esc_url(home_url('/#autoskoly')); ?>" class="rd-btn rd-btn-primary" style="margin-top:24px">Vybrat autoškolu →</a>
</div>
<?php return ob_get_clean();
    }

    // Nastavit PK — použít Stripe autoškoly pokud je aktivní a ověřený, jinak žádný
    $as_stripe_aktivni = !empty($as_fresh->stripe_aktivni) && !empty($as_fresh->stripe_overeno);
    if ($as_stripe_aktivni && !empty($as_fresh->stripe_pk)) {
        $pk = $as_fresh->stripe_pk;
    }

    $cena     = intval(get_option('rd_cena_kus', 99));
    $as_nazev = '';
    $cena_zmena = null;

    if ($as_fresh) {
        // Vždy načíst cenu čerstvě z DB (bez cache) — ignorovat lokální proměnnou $as_fresh->cena_kus
        // která mohla být načtena dříve. Přečíst znovu přímo z tabulky.
        $cena_db = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1",
            intval($as_fresh->id)
        ));
        if ($cena_db > 0) {
            $cena = $cena_db;
        }
        $as_nazev = $as_fresh->nazev;
        if (!empty($_SESSION['rd_firma_id'])) {
            // Načíst poslední nákupní cenu z objednávky
            $firma_email_box = $wpdb->get_var($wpdb->prepare(
                "SELECT email FROM {$wpdb->prefix}rd_firmy WHERE id=%d LIMIT 1",
                intval($_SESSION['rd_firma_id'])
            ));
            if ($firma_email_box) {
                $last_order_box = $wpdb->get_row($wpdb->prepare(
                    "SELECT data FROM " . RD_TABLE_OBJ . "
                     WHERE autoskola_id=%d AND firma_email=%s AND stav IN ('zaplaceno','hotovo','prevod_ok')
                     ORDER BY vytvoreno DESC LIMIT 1",
                    intval($as_fresh->id), $firma_email_box
                ));
                if ($last_order_box) {
                    $ld_box = json_decode($last_order_box->data ?? '{}', true);
                    $nakupni_box = intval($ld_box['cena'] ?? 0);
                    if ($nakupni_box && $nakupni_box !== intval($as_fresh->cena_kus)) {
                        // Vytvořit pseudo-objekt pro zobrazení boxu
                        $cena_zmena = (object)[
                            'stara_cena' => $nakupni_box,
                            'nova_cena'  => intval($as_fresh->cena_kus),
                            'stav'       => intval($as_fresh->cena_kus) > $nakupni_box ? 'drazsi' : 'levnejsi',
                        ];
                    }
                }
            }
        }
    }

    // --- FLOW: Zrušení čekání firmou ("Nechci čekat") ---
    if ($as_fresh && isset($_GET['rd_zrusit_poptavku']) && isset($_GET['_wpnonce'])) {
        $popt_id_zrusit = intval($_GET['rd_zrusit_poptavku']);
        if (wp_verify_nonce($_GET['_wpnonce'], 'rd_zrusit_popt_' . $popt_id_zrusit)) {
            $popt_zrusit = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$wpdb->prefix}rd_poptavky WHERE id=%d AND autoskola_id=%d AND stav='nova' LIMIT 1",
                $popt_id_zrusit, $as_fresh->id
            ));
            if ($popt_zrusit) {
                $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'zrusena_ceka'], ['id' => $popt_id_zrusit]);
                // Email autoškole se posílá až když firma skutečně objedná u jiné autoškoly
                // Přesměrovat na výběr alternativ
                wp_redirect(home_url('/objednavka/?rd_alternativy=1&ref=' . $as_fresh->slug));
                exit;
            }
        }
    }

    // Zobrazit výběr alternativ po zrušení čekání
    if ($as_fresh && isset($_GET['rd_alternativy'])) {
        global $wpdb;
        $alternativy = $wpdb->get_results($wpdb->prepare(
            "SELECT a.* FROM " . RD_TABLE_AUTOSKOLY . " a
             WHERE a.stav='aktivni' AND a.id != %d
               AND " . rd_sql_kapacita_podminka('a', 1) . "
             LIMIT 10",
            $as_fresh->id
        ));
        ob_start(); ?>
        <div class="rd-page" style="max-width:520px;margin:0 auto;padding-top:40px">
            <a href="<?php echo esc_url(home_url('/')); ?>" style="display:inline-flex;align-items:center;gap:6px;font-size:.85rem;color:var(--au-text-2);text-decoration:none;margin-bottom:20px">← Zpět</a>
            <h2 style="margin:0 0 8px">Vyberte alternativní autoškolu</h2>
            <p style="color:var(--au-text-2);margin:0 0 24px;line-height:1.6">Autoškola <strong><?php echo esc_html($as_fresh->nazev); ?></strong> momentálně nemá kapacitu. Níže jsou dostupné alternativy.</p>
            <?php if (!empty($alternativy)): ?>
            <div style="display:flex;flex-direction:column;gap:10px">
            <?php foreach ($alternativy as $alt): ?>
            <a href="<?php echo esc_url(add_query_arg('ref', $alt->slug, home_url('/objednavka/'))); ?>"
               style="display:flex;align-items:center;justify-content:space-between;gap:12px;background:var(--au-surface,#fff);border:1px solid var(--au-border,#e5e7eb);border-radius:10px;padding:14px 18px;text-decoration:none;color:inherit;transition:border-color .2s,box-shadow .2s"
               onmouseover="this.style.borderColor='#7c3aed';this.style.boxShadow='0 2px 8px rgba(124,58,237,.1)'"
               onmouseout="this.style.borderColor='';this.style.boxShadow=''">
                <div>
                    <strong style="font-size:14px"><?php echo esc_html($alt->nazev); ?></strong>
                    <?php if ($alt->mesto): ?><div style="font-size:12px;color:var(--au-text-2)"><?php echo esc_html($alt->mesto); ?></div><?php endif; ?>
                </div>
                <div style="text-align:right;flex-shrink:0">
                    <div style="font-size:13px;font-weight:700;color:#7c3aed"><?php echo intval($alt->cena_kus); ?> Kč<span style="font-size:11px;font-weight:400;color:var(--au-text-2)"> / řidič</span></div>
                    <div style="font-size:11px;color:#16a34a;margin-top:2px">✓ Kapacita dostupná</div>
                </div>
            </a>
            <?php endforeach; ?>
            </div>
            <?php else: ?>
            <div style="text-align:center;padding:32px;color:var(--au-text-2)">
                <p>Momentálně nejsou dostupné žádné alternativní autoškoly. Zkuste to prosím později.</p>
            </div>
            <?php endif; ?>
        </div>
        <?php return ob_get_clean();
    }

    // --- FLOW: Poptávka při vyčerpané kapacitě ---
    if ($as_fresh && isset($_GET['poptavka'])) {
        $kapacita = rd_autoskola_kapacita_stav($as_fresh);
        if ($kapacita === 'vycerpana') {

            // Zpracovat odeslání poptávky (POST na stejné URL s ?poptavka=1)
            if (!empty($_POST['rd_poptavka_submit'])) {
                $nonce_ok = isset($_POST['rd_poptavka_nonce_field'])
                    ? wp_verify_nonce($_POST['rd_poptavka_nonce_field'], 'rd_poptavka_' . $as_fresh->id)
                    : false;

                $p_nazev = sanitize_text_field($_POST['firma_nazev'] ?? '');
                $p_email = sanitize_email($_POST['firma_email'] ?? '');
                $p_pocet = max(1, intval($_POST['pocet'] ?? 1));
                $p_err   = '';

                if (!$nonce_ok)        $p_err = 'Chyba zabezpečení, zkuste prosím znovu.';
                elseif (!$p_nazev)     $p_err = 'Zadejte název firmy.';
                elseif (!is_email($p_email)) $p_err = 'Zadejte platný email.';

                if (!$p_err) {
                    // Načíst aktuální cenu autoškoly a porovnat s poslední nákupní cenou firmy
                    $cena_autoskoly = (int)$wpdb->get_var($wpdb->prepare(
                        "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_fresh->id
                    ));
                    $nakupni_cena_firmy = 0;
                    if (!empty($_SESSION['rd_firma_id'])) {
                        $nakupni_cena_firmy = (int)$wpdb->get_var($wpdb->prepare(
                            "SELECT nakupni_cena FROM " . RD_TABLE_FIRMA_AS . "
                             WHERE firma_id=%d AND autoskola_id=%d AND kmenova=1 LIMIT 1",
                            intval($_SESSION['rd_firma_id']), $as_fresh->id
                        ));
                    }
                    // Cena je ok (stejná nebo nižší) a firma už dříve objednávala = čekací lhůta
                    $cena_ok = ($nakupni_cena_firmy > 0 && $cena_autoskoly <= $nakupni_cena_firmy);

                    // Uložit poptávku do DB
                    $wpdb->insert("{$wpdb->prefix}rd_poptavky", [
                        'autoskola_id'      => $as_fresh->id,
                        'firma_nazev'       => $p_nazev,
                        'firma_email'       => $p_email,
                        'pocet'             => $p_pocet,
                        'stav'              => 'nova',
                        'cena_pri_poptavce' => $cena_autoskoly,
                        'vytvoreno'         => current_time('mysql'),
                    ]);
                    $popt_id = $wpdb->insert_id;

                    $from    = get_option('rd_smtp_from', get_option('admin_email'));
                    $fname   = get_option('rd_smtp_from_name', get_bloginfo('name'));
                    $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $fname . ' <' . $from . '>'];

                    // Najít alternativní autoškolu pro pozdější použití
                    $jina_as = $wpdb->get_row($wpdb->prepare(
                        "SELECT a.* FROM " . RD_TABLE_AUTOSKOLY . " a
                         WHERE a.stav='aktivni' AND a.id != %d
                           AND " . rd_sql_kapacita_podminka('a', 1) . "
                         LIMIT 1",
                        $as_fresh->id
                    ));
                    if ($jina_as) {
                        $wpdb->update("{$wpdb->prefix}rd_poptavky", ['jina_as_id' => $jina_as->id], ['id' => $popt_id]);
                    }

                    if ($cena_ok) {
                        // ── ČEKACÍ LHŮTA: cena ok, firma čeká max 12h ──────────────────────
                        $lhuta_12h = date('d.m.Y H:i', strtotime('+12 hours'));
                        $zrusit_url = add_query_arg([
                            'rd_zrusit_poptavku' => $popt_id,
                            '_wpnonce'           => wp_create_nonce('rd_zrusit_popt_' . $popt_id),
                        ], home_url('/objednavka/?ref=' . $as_fresh->slug));

                        // Email autoškole
                        $email_as = $wpdb->get_var($wpdb->prepare(
                            "SELECT email FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_fresh->id
                        ));
                        if ($email_as) {
                            rd_email_autoskola($email_as,
                                'RefDrive: Nová poptávka — kapacita vyčerpána',
                                rd_email_wrap('Nová poptávka při vyčerpané kapacitě',
                                    '<p>Firma <strong>' . esc_html($p_nazev) . '</strong> (' . esc_html($p_email) . ') má zájem o školení <strong>' . $p_pocet . ' řidičů</strong>, ale vaše měsíční kapacita je vyčerpána.</p>'
                                    . '<p>Firma čeká na obnovení kapacity do <strong>' . $lhuta_12h . '</strong>. Pokud do té doby navýšíte balíček, bude okamžitě informována a objedná přímo u vás.</p>'
                                    . rd_email_btn('Navýšit balíček →', admin_url('admin.php?page=refdrive-as-platba'))
                                    . '<p style="font-size:12px;color:#6b7280">Pokud kapacitu nenavýšíte, firma dostane po uplynutí lhůty výběr alternativních autoškol.</p>'
                                )
                            );
                        }

                        ob_start(); ?>
                        <div class="rd-page" style="max-width:520px;margin:0 auto;padding-top:60px;text-align:center">
                            <div style="width:64px;height:64px;background:rgba(124,58,237,.12);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px">
                                <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                            </div>
                            <h2 style="margin:0 0 12px">Poptávka odeslána</h2>
                            <p style="color:var(--au-text-2);line-height:1.7">Autoškola <strong><?php echo esc_html($as_fresh->nazev); ?></strong> byla informována. Pokud do <strong><?php echo $lhuta_12h; ?></strong> obnoví kapacitu, dostanete ihned email s odkazem pro objednávku.</p>
                            <p style="color:var(--au-text-2);font-size:13px;margin-top:12px">Pokud nechcete čekat, můžete si vybrat jinou autoškolu.</p>
                            <a href="<?php echo esc_url($zrusit_url); ?>" class="rd-btn rd-btn-ghost" style="margin-top:16px;display:inline-flex">Nechci čekat — vybrat jinou autoškolu</a>
                            <br><a href="<?php echo esc_url(home_url('/')); ?>" style="font-size:13px;color:var(--au-text-3);margin-top:12px;display:inline-block">Zpět na hlavní stránku</a>
                        </div>
                        <?php return ob_get_clean();

                    } else {
                        // ── BEZ ČEKACÍ LHŮTY: cena vyšší nebo první objednávka ─────────────
                        // Rovnou nabídnout alternativy
                        if ($jina_as) {
                            $jina_url = add_query_arg('ref', $jina_as->slug, home_url('/objednavka/'));
                            wp_mail($p_email,
                                'Vaše poptávka školení — alternativní autoškola',
                                rd_email_wrap('Alternativní autoškola k dispozici',
                                    '<p>Dobrý den, <strong>' . esc_html($p_nazev) . '</strong>,</p>'
                                    . '<p>autoškola <strong>' . esc_html($as_fresh->nazev) . '</strong> bohužel nemůže váš zájem obsloužit.</p>'
                                    . '<p>Dovolujeme si vám nabídnout alternativní autoškolu: <strong>' . esc_html($jina_as->nazev) . '</strong>'
                                    . ($jina_as->mesto ? ' (' . esc_html($jina_as->mesto) . ')' : '') . ', která má pro vás kapacitu.</p>'
                                    . rd_email_btn('Objednat u ' . esc_html($jina_as->nazev) . ' →', $jina_url)
                                ),
                                $headers
                            );
                            $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $popt_id]);
                            ob_start(); ?>
                            <div class="rd-page" style="max-width:520px;margin:0 auto;padding-top:60px;text-align:center">
                                <div style="width:64px;height:64px;background:rgba(124,58,237,.12);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px">
                                    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
                                </div>
                                <h2 style="margin:0 0 12px">Nabízíme alternativu</h2>
                                <p style="color:var(--au-text-2);line-height:1.7">Autoškola <strong><?php echo esc_html($as_fresh->nazev); ?></strong> nemá kapacitu. Zaslali jsme vám email s alternativní autoškolu.</p>
                                <a href="<?php echo esc_url($jina_url); ?>" class="rd-btn rd-btn-primary" style="margin-top:20px;display:inline-flex">Objednat u alternativní autoškoly →</a>
                                <br><a href="<?php echo esc_url(home_url('/')); ?>" style="font-size:13px;color:var(--au-text-3);margin-top:12px;display:inline-block">Zpět na hlavní stránku</a>
                            </div>
                            <?php return ob_get_clean();
                        } else {
                            wp_mail($p_email,
                                'Vaše poptávka školení — omlouváme se',
                                rd_email_wrap('Kapacity momentálně vyčerpány',
                                    '<p>Dobrý den, <strong>' . esc_html($p_nazev) . '</strong>,</p>'
                                    . '<p>autoškola <strong>' . esc_html($as_fresh->nazev) . '</strong> bohužel nemůže vaši poptávku obsloužit a v tuto chvíli nejsou k dispozici ani alternativní autoškoly s dostatečnou kapacitou pro <strong>' . intval($p_pocet) . ' řidičů</strong>.</p>'
                                    . '<p>Ozveme se vám, jakmile bude kapacita obnovena. V případě dotazů nás kontaktujte na <a href="mailto:' . esc_attr(get_option('rd_faktura_email', 'info@refdrive.pro')) . '" style="color:#7c3aed">' . esc_html(get_option('rd_faktura_email', 'info@refdrive.pro')) . '</a>.</p>'
                                ),
                                $headers
                            );
                            $wpdb->update("{$wpdb->prefix}rd_poptavky", ['stav' => 'odmitnuta'], ['id' => $popt_id]);
                            ob_start(); ?>
                            <div class="rd-page" style="max-width:520px;margin:0 auto;padding-top:60px;text-align:center">
                                <div style="width:64px;height:64px;background:rgba(220,38,38,.12);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px">
                                    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#dc2626" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                                </div>
                                <h2 style="margin:0 0 12px">Kapacity jsou vyčerpány</h2>
                                <p style="color:var(--au-text-2);line-height:1.7">Autoškola <strong><?php echo esc_html($as_fresh->nazev); ?></strong> nemá kapacitu a momentálně nejsou k dispozici alternativy. Ozveme se vám jakmile to bude možné.</p>
                                <a href="<?php echo esc_url(home_url('/')); ?>" class="rd-btn rd-btn-ghost" style="margin-top:24px;display:inline-flex">← Zpět na hlavní stránku</a>
                            </div>
                            <?php return ob_get_clean();
                        } // konec else (if $jina_as)
                    } // konec else (if $cena_ok)
                }
                // Chyba validace - zobrazit formulář znovu s chybou
            }

            // Zobrazit poptávkový formulář
            $p_err = $p_err ?? '';
            // Bod 2: Předvyplnění z přihlášení firmy
            $pf_nazev = $_POST['firma_nazev'] ?? $_SESSION['rd_firma_nazev'] ?? '';
            $pf_email = $_POST['firma_email'] ?? $_SESSION['rd_firma_email'] ?? '';
            $pf_pocet = intval($_POST['pocet'] ?? $_GET['pocet'] ?? 5);
            $pf_prihlasen = !empty($_SESSION['rd_firma_id']);
            ob_start(); ?>
            <div class="rd-page rd-center" style="padding-top:40px">
              <div style="max-width:480px;margin:0 auto;text-align:center">

                <!-- Ikona -->
                <div style="width:88px;height:88px;border-radius:50%;background:linear-gradient(135deg,rgba(251,146,60,.18),rgba(239,68,68,.18));border:1.5px solid rgba(251,146,60,.35);display:flex;align-items:center;justify-content:center;margin:0 auto 24px">
                  <svg width="42" height="42" viewBox="0 0 24 24" fill="none" stroke="url(#warn-grad)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
                    <defs><linearGradient id="warn-grad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#fb923c"/><stop offset="100%" stop-color="#f43f5e"/></linearGradient></defs>
                    <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
                  </svg>
                </div>

                <!-- Nadpis -->
                <div style="display:inline-block;background:rgba(251,146,60,.12);border:1px solid rgba(251,146,60,.3);border-radius:20px;padding:4px 14px;font-size:.78rem;font-weight:600;color:#fb923c;letter-spacing:.04em;text-transform:uppercase;margin-bottom:14px">Kapacita vyčerpána</div>
