                    <?php if ($pf_prihlasen): ?>
                    <div style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:14px 18px;margin-bottom:24px;font-size:13px">
                        <div style="font-size:.75rem;color:var(--au-text-2);margin-bottom:6px">Přihlášeni jako:</div>
                        <strong><?php echo esc_html($pf_nazev); ?></strong> &middot; <?php echo esc_html($pf_email); ?>
                    </div>
                    <input type="hidden" name="firma_nazev" value="<?php echo esc_attr($pf_nazev); ?>">
