                          <input type="number" id="popt-pocet" name="pocet" min="1" value="<?php echo $pf_pocet; ?>" required style="flex:1;border:none;background:none;text-align:center;font-size:1rem;font-weight:600;color:var(--au-text,#e6edf3);width:100%;outline:none;-moz-appearance:textfield;appearance:textfield">
                          <button type="button" onclick="var i=document.getElementById('popt-pocet');var v=Math.min(500,parseInt(i.value||1)+1);i.value=v;" style="width:44px;height:44px;border:none;background:none;color:var(--au-text,#e6edf3);font-size:1.3rem;cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-left:1px solid rgba(255,255,255,.08)">+</button>
