<script>
(function(){
var CENA=<?php echo intval($cena); ?>;
var AS_SLUG=<?php echo json_encode($as_fresh->slug ?? ''); ?>;
var platbaTyp='karta';
var stripe=null,els=null,card=null,expiry=null,cvc=null;
try{
<?php if($pk): ?>stripe=Stripe('<?php echo esc_js($pk); ?>');
els=stripe.elements({appearance:{theme:'night',variables:{colorPrimary:'#2563eb',colorBackground:'#21262d',colorText:'#e6edf3',colorTextSecondary:'#8b949e',colorTextPlaceholder:'#484f58',borderRadius:'8px',fontSizeBase:'16px',fontFamily:'Inter, system-ui, sans-serif'}},loader:'never'});
card=els.create('cardNumber');expiry=els.create('cardExpiry');cvc=els.create('cardCvc');
card.mount('#rds-card');expiry.mount('#rds-expiry');cvc.mount('#rds-cvc');
<?php endif; ?>
}catch(e){console.warn('Stripe init error:',e);}
function rdsPlatba(typ){
    platbaTyp=typ;
    var sw=document.getElementById('rds-stripe-wrap');
    if(sw){if(typ==='karta'){sw.style.cssText='margin-top:20px';}else{sw.style.cssText='visibility:hidden;height:0;overflow:hidden;margin:0;padding:0;position:absolute';}}
    var pw=document.getElementById('rds-prevod-wrap');
    if(pw) pw.style.display=typ==='prevod'?'block':'none';
    document.querySelectorAll('.rd-platba-opt').forEach(function(o){o.classList.remove('rd-platba-sel');});
    var optEl=document.getElementById('rds-opt-'+typ);
    if(optEl) optEl.classList.add('rd-platba-sel');
    var p=parseInt(document.getElementById('rds-pocet').value)||1;
    var s=p*CENA;
    var btn=document.getElementById('rds-submit');
    btn.innerHTML=typ==='karta'?'Zaplatit <span id="rds-btn-cena">'+s+'</span> Kč →':'Objednat a vystavit fakturu →';
}
window.rdsPlatba=rdsPlatba;
<?php if (get_option('rd_karta_disabled') === '1' || !$pk || !$as_stripe_aktivni): ?>
rdsPlatba('prevod');
<?php endif; ?>
document.getElementById('rds-form').addEventListener('submit',async function(e){
    e.preventDefault();
    var btn=document.getElementById('rds-submit');
    var err=document.getElementById('rds-err');
    var nazev=document.getElementById('rds-nazev').value.trim();
    var email=document.getElementById('rds-email').value.trim();
    var pocetEl=document.getElementById('rds-pocet');
    var pocet=parseInt(pocetEl ? pocetEl.value : 1)||1;
    var hiddenPocet=document.getElementById('rds-inp-pocet');
    if(hiddenPocet) hiddenPocet.value=pocet;
    err.style.display='none';
    if(!nazev||!email){err.textContent='Vyplňte název firmy a email.';err.style.display='block';return;}
    var oopCheck=document.getElementById('rds-oop-souhlas');
    if(oopCheck&&!oopCheck.checked){
      err.textContent='Musíte souhlasit s obchodními podmínkami autoškoly.';
      err.style.display='block';err.style.maxHeight='200px';err.style.padding='12px 16px';
      oopCheck.scrollIntoView({behavior:'smooth',block:'center'});
      return;
    }
    btn.disabled=true;btn.textContent='Zpracovávám...';
    function rdGetVal(id, hiddenId) {
        var hidden = hiddenId ? document.getElementById(hiddenId) : null;
        var el = document.getElementById(id);
        if (hidden && hidden.value) return hidden.value;
        return el ? el.value : '';
    }
    var data={
        pocet:pocet,
        firma_nazev: rdGetVal('rds-nazev','rds-hidden-nazev') || nazev,
        firma_email: rdGetVal('rds-email','rds-hidden-email') || email,
        ico:     rdGetVal('rds-ico',    'rds-hidden-ico'),
        telefon: rdGetVal('rds-tel',    'rds-hidden-telefon'),
        ulice:   rdGetVal('rds-ulice',  'rds-hidden-ulice'),
        mesto:   rdGetVal('rds-mesto',  'rds-hidden-mesto'),
        psc:     rdGetVal('rds-psc',    'rds-hidden-psc'),
        autoskola_id: <?php echo intval($_SESSION['rd_autoskola_id'] ?? 0); ?>
    };
    if(platbaTyp==='karta' && stripe){
        var res=await fetch('<?php echo esc_url(rest_url("refdrive/v1/create-payment")); ?>',{method:'POST',headers:{'Content-Type':'application/json','X-WP-Nonce':'<?php echo wp_create_nonce("wp_rest"); ?>'},body:JSON.stringify(data)});
        var json=await res.json();
        if(json.error){err.textContent=json.error;err.style.display='block';btn.disabled=false;btn.innerHTML='Zaplatit <span id="rds-btn-cena">'+pocet*CENA+'</span> Kč →';return;}
        var result=await stripe.confirmCardPayment(json.client_secret,{payment_method:{card:card}});
        if(result.error){var ce=document.getElementById('rds-card-err');ce.textContent=result.error.message;ce.style.display='block';ce.style.maxHeight='200px';ce.style.padding='12px 16px';btn.disabled=false;btn.innerHTML='Zaplatit <span id="rds-btn-cena">'+pocet*CENA+'</span> Kč →';}
        else{window.location.href='<?php echo home_url("/dekujeme/"); ?>?pi='+result.paymentIntent.id+'&email='+encodeURIComponent(email);}
    }else{
        var fd=new FormData();
        fd.append('action','rd_objednavka_prevod');
        fd.append('data',JSON.stringify(data));
        var res=await fetch('<?php echo admin_url("admin-ajax.php"); ?>',{method:'POST',credentials:'include',body:fd});
        var json=await res.json();
        if(json.success){window.location.href='<?php echo home_url("/dekujeme/"); ?>?typ=prevod&email='+encodeURIComponent(email);}
        else{
            var errMsg=json.data||'Chyba. Zkuste znovu.';
            if(AS_SLUG && errMsg.indexOf('kapacit')!==-1){
                window.location.href='<?php echo home_url("/objednavka/"); ?>?ref='+encodeURIComponent(AS_SLUG)+'&poptavka=1&pocet='+encodeURIComponent(pocet);
            } else {
                err.textContent=errMsg;err.style.display='block';err.style.maxHeight='200px';err.style.padding='12px 16px';btn.disabled=false;btn.textContent='Objednat a vystavit fakturu →';
            }
        }
    }
});
})();
</script>
    <?php return ob_get_clean();
}

/* ---- DĚKUJEME ---- */
function rd_sc_dekujeme() {
    $typ=$_GET['typ']??'karta'; $email=sanitize_email($_GET['email']??''); $pi=sanitize_text_field($_GET['pi']??'');
    if ($pi && $typ!=='prevod') {
        $res=wp_remote_get('https://api.stripe.com/v1/payment_intents/'.urlencode($pi),['headers'=>['Authorization'=>'Bearer '.rd_stripe_sk()]]);
        if (!is_wp_error($res)) {
            $data=json_decode(wp_remote_retrieve_body($res),true);
            if(($data['status']??'')==='succeeded'){
                $nazev=$data['metadata']['firma_nazev']??''; $email=$data['metadata']['firma_email']??$email; $pocet=intval($data['metadata']['pocet_kodu']??0);
                global $wpdb;
                $stav=$wpdb->get_var($wpdb->prepare("SELECT stav FROM ".RD_TABLE_OBJ." WHERE pi_id=%s",$pi));
                if($stav==='ceka'){
                    // Atomicky změnit stav - zabránit dvojímu zpracování
                    $updated = $wpdb->query($wpdb->prepare(
                        "UPDATE ".RD_TABLE_OBJ." SET stav='zpracovava' WHERE pi_id=%s AND stav='ceka'", $pi
                    ));
                    if($updated > 0) {
                        $obj_data = json_decode($wpdb->get_var($wpdb->prepare("SELECT data FROM ".RD_TABLE_OBJ." WHERE pi_id=%s",$pi)), true) ?? [];
                        rd_vygenerovat_kody($nazev,$email,$pocet,$pi,$obj_data);
                        $wpdb->update(RD_TABLE_OBJ,['stav'=>'zaplaceno'],['pi_id'=>$pi]);
                        // Notifikovat původní autoškoly kde firma čekala (stav zrusena_ceka)
                        $as_id_obj = intval($obj_data['autoskola_id'] ?? 0);
                        if ($as_id_obj) rd_notifikovat_puvodni_autoskolu($email, $nazev, $as_id_obj);
                    }
                }
            }
        }
    }
    ob_start(); ?>
<div class="rd-page rd-center" style="padding-top:40px">
  <div class="rd-thankyou-card">
    <?php if ($typ==='prevod'): ?>
      <div class="rd-thankyou-icon rd-ty-blue"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="url(#bg)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient></defs><rect x="3" y="10" width="18" height="11" rx="1"/><polyline points="3 10 12 3 21 10"/><line x1="8" y1="14" x2="8" y2="21"/><line x1="12" y1="14" x2="12" y2="21"/><line x1="16" y1="14" x2="16" y2="21"/></svg></div>
      <h2 class="rd-thankyou-title">Objednávka přijata!</h2>
      <p class="rd-thankyou-sub">Na email <strong><?php echo esc_html($email); ?></strong> jsme odeslali proforma fakturu.</p>
      <p class="rd-thankyou-note">Kódy obdržíte do 24 hodin od přijetí platby.</p>
    <?php else: ?>
      <div class="rd-thankyou-icon rd-ty-green"><div class="rd-fi-aurora rd-ty-svg"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg></div></div>
      <h2 class="rd-thankyou-title">Platba proběhla úspěšně!</h2>
      <p class="rd-thankyou-sub">Přístupové kódy jsme odeslali na email <strong><?php echo esc_html($email); ?></strong>.</p>
      <p class="rd-thankyou-note">Zkontrolujte i složku spam, pokud email nedorazil.</p>
    <?php endif; ?>
    <a href="<?php echo home_url('/'); ?>" class="rd-btn rd-btn-primary rd-thankyou-btn"><svg style="display:inline;vertical-align:middle;margin-right:4px" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>Zpět na úvod</a>
  </div>
</div>
