add_action('rest_api_init', 'rd_rest_init');
function rd_rest_init() {
    register_rest_route('refdrive/v1', '/create-payment', ['methods'=>'POST','callback'=>'rd_rest_platba','permission_callback'=>'__return_true']);
    register_rest_route('refdrive/v1', '/create-invoice', ['methods'=>'POST','callback'=>'rd_rest_faktura','permission_callback'=>'__return_true']);
    register_rest_route('refdrive/v1', '/webhook',        ['methods'=>'POST','callback'=>'rd_rest_webhook','permission_callback'=>'__return_true']);
    register_rest_route('refdrive/v1', '/faktura/(?P<id>\d+)', ['methods'=>'GET','callback'=>'rd_rest_faktura_html','permission_callback'=>'__return_true']);
}

function rd_faktura_token($platba_id, $as_id) {
    return substr(hash_hmac('sha256', $platba_id . ':' . $as_id, wp_salt('auth')), 0, 32);
}

function rd_faktura_url($platba_id, $as_id) {
    return rest_url('refdrive/v1/faktura/' . intval($platba_id)) . '?token=' . rd_faktura_token($platba_id, $as_id);
}

