function rd_rest_faktura_html(WP_REST_Request $req) {
    global $wpdb;
    $platba_id = intval($req->get_param('id'));
    $token     = sanitize_text_field($req->get_param('token'));
    $platba    = $wpdb->get_row($wpdb->prepare(
        "SELECT p.*, t.nazev, t.limit_kodu, t.popis FROM " . RD_TABLE_AS_PLATBY . " p LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id WHERE p.id=%d LIMIT 1",
        $platba_id
    ));
    if (!$platba) wp_die('Faktura nenalezena.', 404);
    $as = $wpdb->get_row($wpdb->prepare("SELECT * FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $platba->autoskola_id));
    if (!$as) wp_die('Autoškola nenalezena.', 404);
    if (!hash_equals(rd_faktura_token($platba_id, $as->id), $token)) wp_die('Neplatný přístupový token.', 403);
    header('Content-Type: text/html; charset=UTF-8');
    echo rd_faktura_html_obsah($platba, $as, (object)['nazev'=>$platba->nazev,'limit_kodu'=>$platba->limit_kodu,'popis'=>$platba->popis]);
    exit;
}



function rd_rest_platba(WP_REST_Request $req) {
    if (!wp_verify_nonce($req->get_header('X-WP-Nonce'), 'wp_rest')) {
        return new WP_REST_Response(['error' => 'Neplatný bezpečnostní token.'], 403);
    }
    $d     = $req->get_json_params();
    $pocet = intval($d['pocet'] ?? 1);
    $email = sanitize_email($d['firma_email'] ?? '');
    $nazev = sanitize_text_field($d['firma_nazev'] ?? '');

    // v6.1.0 — načíst cenu z autoškoly pokud je předána
    $cena = intval(get_option('rd_cena_kus', 99));
    $as_id = intval($d['autoskola_id'] ?? 0);
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        global $wpdb;
        $as_cena = $wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1",
            $as_id
        ));
        if ($as_cena > 0) $cena = intval($as_cena);
    }

    if ($pocet < 1 || !$email || !$nazev) return new WP_REST_Response(['error' => 'Neplatná data'], 400);

    // Kontrola limitu kódů autoškoly
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        $zbyvajici = rd_autoskola_zbyvajici_kapacita($as_id);
        if ($zbyvajici !== null && $pocet > $zbyvajici) {
            return new WP_REST_Response(['error' => 'Autoškola nemá dostatek kapacity. Zbývá ' . $zbyvajici . ' kódů z měsíčního limitu.'], 400);
        }
    }

    // Použít Stripe SK autoškoly pokud má aktivní a ověřené Stripe
    $sk_pouzit = rd_stripe_sk(); // fallback na globální
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        global $wpdb;
        $as_stripe_row = $wpdb->get_row($wpdb->prepare(
            "SELECT stripe_sk, stripe_aktivni, stripe_overeno FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1",
            $as_id
        ));
        if ($as_stripe_row && $as_stripe_row->stripe_aktivni && $as_stripe_row->stripe_overeno && !empty($as_stripe_row->stripe_sk)) {
            $sk_pouzit = $as_stripe_row->stripe_sk;
        }
    }

    $res=wp_remote_post('https://api.stripe.com/v1/payment_intents',['headers'=>['Authorization'=>'Bearer '.$sk_pouzit,'Content-Type'=>'application/x-www-form-urlencoded'],'body'=>http_build_query(['amount'=>$pocet*$cena*100,'currency'=>'czk','metadata[firma_nazev]'=>$nazev,'metadata[firma_email]'=>$email,'metadata[pocet_kodu]'=>$pocet,'receipt_email'=>$email,'description'=>"Školení řidičů – $pocet kódů – $nazev"])]);
    if(is_wp_error($res))return new WP_REST_Response(['error'=>'Chyba spojení'],500);
    $body=json_decode(wp_remote_retrieve_body($res),true);
    if(isset($body['error']))return new WP_REST_Response(['error'=>$body['error']['message']],400);
    $as_id_ins = intval($d['autoskola_id'] ?? 0);
    $d['cena'] = $cena; // Uložit cenu do JSON
    $oop_snap = '';
    if ($as_id_ins) {
        global $wpdb;
        $oop_snap = (string)$wpdb->get_var($wpdb->prepare("SELECT oop_url FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id_ins));
    $oop_verze_snap_ins = (string)$wpdb->get_var($wpdb->prepare("SELECT oop_verze FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id_ins));
    }
    global $wpdb; $wpdb->insert(RD_TABLE_OBJ,['pi_id'=>$body['id'],'firma_nazev'=>$nazev,'firma_email'=>$email,'pocet'=>$pocet,'stav'=>'ceka','autoskola_id'=>$as_id_ins?:null,'data'=>json_encode($d),'oop_url_snapshot'=>$oop_snap,'oop_verze_snapshot'=>$oop_verze_snap_ins,'oop_souhlas_datum'=>current_time('mysql'),'oop_souhlas_ip'=>rd_get_ip()]);

    return new WP_REST_Response(['client_secret'=>$body['client_secret']],200);
}

function rd_rest_faktura(WP_REST_Request $req) {
    if (!wp_verify_nonce($req->get_header('X-WP-Nonce'), 'wp_rest')) {
        return new WP_REST_Response(['error' => 'Neplatný bezpečnostní token.'], 403);
    }
    $d     = $req->get_json_params();
    $pocet = intval($d['pocet'] ?? 1);
    $email = sanitize_email($d['firma_email'] ?? '');
    $nazev = sanitize_text_field($d['firma_nazev'] ?? '');

    // v6.1.0 — načíst cenu z autoškoly pokud je předána
    $cena  = intval(get_option('rd_cena_kus', 99));
    $as_id = intval($d['autoskola_id'] ?? 0);
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        global $wpdb;
        $as_cena = $wpdb->get_var($wpdb->prepare(
            "SELECT cena_kus FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1",
            $as_id
        ));
        if ($as_cena > 0) $cena = intval($as_cena);
    }
    if($pocet<1||!$email||!$nazev)return new WP_REST_Response(['error'=>'Neplatná data'],400);

    // Kontrola limitu kódů autoškoly
    if ($as_id && defined('RD_TABLE_AUTOSKOLY')) {
        $zbyvajici = rd_autoskola_zbyvajici_kapacita($as_id);
        if ($zbyvajici !== null && $pocet > $zbyvajici) {
            return new WP_REST_Response(['error' => 'Autoškola nemá dostatek kapacity. Zbývá ' . $zbyvajici . ' kódů z měsíčního limitu.'], 400);
        }
    }

    $castka=$pocet*$cena; $castka_dph=round($castka*1.21);
    $d['cena'] = $cena; // Uložit cenu do JSON pro zobrazení v přehledu objednávek
    $as_id_ins2 = intval($d['autoskola_id'] ?? 0);
    $oop_snap2 = $as_id_ins2 ? (string)$wpdb->get_var($wpdb->prepare("SELECT oop_url FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id_ins2)) : '';
    $oop_verze_snap2 = $as_id_ins2 ? (string)$wpdb->get_var($wpdb->prepare("SELECT oop_verze FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id_ins2)) : '';
    // Nejdřív uložit s dočasným pi_id, pak přegenerovat VS z ID objednávky
    global $wpdb; $wpdb->insert(RD_TABLE_OBJ,['pi_id'=>'PREVOD-TMP-'.time(),'firma_nazev'=>$nazev,'firma_email'=>$email,'pocet'=>$pocet,'stav'=>'prevod_ceka','autoskola_id'=>$as_id_ins2?:null,'data'=>json_encode($d),'oop_url_snapshot'=>$oop_snap2,'oop_verze_snapshot'=>$oop_verze_snap2,'oop_souhlas_datum'=>current_time('mysql'),'oop_souhlas_ip'=>rd_get_ip()]);
    $obj_id = $wpdb->insert_id;
    // VS = ID autoškoly (3 číslice) + ID objednávky (7 číslic) = max 10 číslic
    $vs = str_pad($as_id_ins2, 3, '0', STR_PAD_LEFT) . str_pad($obj_id, 7, '0', STR_PAD_LEFT);
    $wpdb->update(RD_TABLE_OBJ, ['pi_id' => 'PREVOD-' . $vs], ['id' => $obj_id]);

    // Platební a fakturační údaje: autoškola má přednost, fallback na globální nastavení
    $dodavatel_nazev = '';
    $dodavatel_ico   = '';
    $dodavatel_adresa = '';
    if ($as_id) {
        $as_row = $wpdb->get_row($wpdb->prepare(
            "SELECT nazev, ico, ulice, mesto, psc, faktura_nazev, faktura_ico, faktura_ulice, faktura_mesto, faktura_psc,
                    cislo_uctu, iban, bic, banka, splatnost, faktura_pozn
             FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d LIMIT 1", $as_id
        ));
    }
    if (!empty($as_row)) {
        $cislo_uctu   = esc_html($as_row->cislo_uctu ?: get_option('rd_cislo_uctu', '—'));
        $iban         = esc_html(rd_get_iban($as_row->cislo_uctu ?: get_option('rd_cislo_uctu', ''), $as_row->iban ?: get_option('rd_iban', '')));
        $bic          = esc_html($as_row->bic         ?: get_option('rd_bic', ''));
        $banka        = esc_html($as_row->banka        ?: get_option('rd_banka', ''));
        $splatnost    = intval($as_row->splatnost ?: get_option('rd_splatnost', 14));
        $faktura_pozn = esc_html($as_row->faktura_pozn ?: get_option('rd_faktura_pozn', ''));
        $dodavatel_nazev  = esc_html($as_row->faktura_nazev ?: $as_row->nazev);
        $dodavatel_ico    = esc_html($as_row->faktura_ico   ?: $as_row->ico);
        $dodavatel_adresa = esc_html(trim(($as_row->faktura_ulice ?: $as_row->ulice) . ', ' . ($as_row->faktura_psc ?: $as_row->psc) . ' ' . ($as_row->faktura_mesto ?: $as_row->mesto), ', '));
    } else {
        $cislo_uctu   = esc_html(get_option('rd_cislo_uctu', '—'));
        $iban         = esc_html(get_option('rd_iban', ''));
        $bic          = esc_html(get_option('rd_bic', ''));
        $banka        = esc_html(get_option('rd_banka', ''));
        $splatnost    = intval(get_option('rd_splatnost', 14));
        $faktura_pozn = esc_html(get_option('rd_faktura_pozn', ''));
        $dodavatel_nazev  = esc_html(get_option('rd_faktura_nazev', get_bloginfo('name')));
