        $spd = 'SPD*1.0*ACC:' . $iban_clean . '*AM:' . $castka_qr . '*CC:CZK*MSG:Skoleni+ridicku*X-VS:' . $vs;
        $qr_url = 'https://api.qrserver.com/v1/create-qr-code/?size=160x160&ecc=M&data=' . rawurlencode($spd);
