        $telo .= '<p style="font-size:11px;color:#9ca3af;margin:6px 0 0">Naskenujte QR kód v mobilní aplikaci své banky</p>';
        $telo .= '</div>';
    }
    $telo .= '</div>';
    $telo .= '</div><div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb"><p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">Automaticky odesláno systémem <strong>refdrive.pro</strong></p></div></div></div></body></html>';
    $_from  = get_option('rd_smtp_from', get_option('admin_email'));
    $_fname = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $_fname . ' <' . $_from . '>'];
    wp_mail($email, 'Objednávka přijata – ' . $nazev, $telo, $headers);
    // Notifikace adminovi
    $notif = get_option('rd_notif_email', get_option('admin_email'));
    $admin_telo = rd_email_admin_prevod($nazev, $email, $pocet, $castka_dph, $vs);
    wp_mail($notif, 'Nová objednávka převodem – ' . $nazev, $admin_telo, $headers);
    return new WP_REST_Response(['success'=>true],200);
}

function rd_rest_webhook(WP_REST_Request $req) {
    $payload   = $req->get_body();
    $sig       = $req->get_header('Stripe-Signature');
    $wh_secret = get_option('rd_stripe_wh', '');

    if ($wh_secret && $sig) {
        // Ověření Stripe podpisu (HMAC-SHA256)
        $parts     = [];
        foreach (explode(',', $sig) as $part) {
            [$k, $v] = array_pad(explode('=', $part, 2), 2, '');
            $parts[$k][] = $v;
        }
        $timestamp = $parts['t'][0] ?? 0;
        $expected  = hash_hmac('sha256', $timestamp . '.' . $payload, $wh_secret);
        $received  = $parts['v1'][0] ?? '';
        if (!hash_equals($expected, $received)) {
            return new WP_REST_Response(['error' => 'Neplatný podpis webhooku.'], 403);
        }
        // Zamítni události starší než 5 minut
        if (abs(time() - intval($timestamp)) > 300) {
            return new WP_REST_Response(['error' => 'Webhook je příliš starý.'], 403);
        }
    }

    $event=json_decode($payload, true);
    if(($event['type']??'')==='payment_intent.succeeded'){
        $pi=$event['data']['object']; $nazev=$pi['metadata']['firma_nazev']??''; $email=$pi['metadata']['firma_email']??''; $pocet=intval($pi['metadata']['pocet_kodu']??0);
        if($email&&$pocet>0){
            global $wpdb;
            $stav=$wpdb->get_var($wpdb->prepare("SELECT stav FROM ".RD_TABLE_OBJ." WHERE pi_id=%s",$pi['id']));
            if($stav==='ceka'){
                $updated = $wpdb->query($wpdb->prepare(
                    "UPDATE ".RD_TABLE_OBJ." SET stav='zpracovava' WHERE pi_id=%s AND stav='ceka'", $pi['id']
                ));
                if($updated > 0) {
                    rd_vygenerovat_kody($nazev,$email,$pocet,$pi['id']);
                    $wpdb->update(RD_TABLE_OBJ,['stav'=>'zaplaceno'],['pi_id'=>$pi['id']]);
                }
            }
        }
    }
    return new WP_REST_Response(['ok'=>true],200);
}

