   POMOCNÉ FUNKCE
   ============================================================ */
function rd_gen_kod() {
    global $wpdb;
    do { $k=strtoupper(substr(str_shuffle('ABCDEFGHJKLMNPQRSTUVWXYZ'),0,3)).'-'.str_pad(random_int(1000,99999),5,'0',STR_PAD_LEFT); $e=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".RD_TABLE_KODY." WHERE kod=%s",$k)); } while($e>0);
    return $k;
}

function rd_vygenerovat_kody($firma_nazev, $firma_email, $pocet, $pi_id, $data=[]) {
    global $wpdb;
    // Uložit firmu do portálu
    $firma_row = rd_ulozit_firmu(array_merge(['firma_nazev'=>$firma_nazev,'firma_email'=>$firma_email], $data));
    $pocet = intval($pocet);
    if ($pocet < 1) { return; }

    // Zjistit autoškolu — priorita: $data > session > kmenová autoškola firmy
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) @session_start();
    $autoskola_id = null;
    if (!empty($data['autoskola_id'])) {
        $autoskola_id = intval($data['autoskola_id']);
    } elseif (!empty($_SESSION['rd_autoskola_id'])) {
        $autoskola_id = intval($_SESSION['rd_autoskola_id']);
    } elseif ($firma_row && is_numeric($firma_row)) {
        $kmenovaAS = rd_get_firma_autoskola($firma_row);
        if ($kmenovaAS) $autoskola_id = $kmenovaAS->id;
    }

    // Expirace kódů
    $expirace_dni = intval(get_option('rd_kod_expirace_dni', 365));
    $expiruje = date('Y-m-d', strtotime('+' . $expirace_dni . ' days'));

    $kody=[];
    for($i=0;$i<$pocet;$i++){
        $k = rd_gen_kod();
        $insert_data = ['firma_nazev'=>$firma_nazev,'firma_email'=>$firma_email,'kod'=>$k,'expiruje'=>$expiruje];
        if ($autoskola_id) $insert_data['autoskola_id'] = $autoskola_id;
        $wpdb->insert(RD_TABLE_KODY, $insert_data);
        $kody[]=$k;
    }

    // v6.0.0 — aktualizovat čítač kódů autoškoly
    if ($autoskola_id) {
        rd_autoskola_pridat_kody($autoskola_id, $pocet);
    }

    $kody_html=implode('<br>',array_map('esc_html',$kody));
    $prihl_url = home_url('/prihlaseni/');
    $portal_url = home_url('/firma-portal/');
    // Datum expirace do emailu
    $expir_text = date('d.m.Y', strtotime($expiruje));
    $telo  = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>@media(prefers-color-scheme:dark){.em-bg{background:#0d0d14!important}.em-card{background:#1a1728!important;border-color:#2d2a3e!important}.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}.em-muted{color:#9ca3af!important}.em-row td{border-bottom-color:#2d2a3e!important}.em-surface{background:#251f38!important;border-color:#2d2a3e!important}.em-footer{border-top-color:#2d2a3e!important}}</style></head><body style="margin:0;padding:0;font-family:Arial,sans-serif"><div class="em-bg" style="background:#f5f5f7;padding:32px 16px"><div class="em-card" style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;border:1px solid #e5e7eb;overflow:hidden"><div style="height:4px;background:linear-gradient(90deg,#7c3aed,#db2777)"></div><div style="padding:28px 32px 24px">';
    $telo .= '<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px"><tr><td>';
    $telo .= '<span style="font-family:Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:-0.5px"><span style="color:#7c3aed">ref</span><span style="color:#db2777">drive</span><span style="color:#7c3aed">.pro</span></span>';
    $telo .= '<div style="font-size:11px;color:#9ca3af;margin-top:2px">Online školení referentských řidičů</div>';
    $telo .= '</td></tr></table>';
    $telo .= '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 8px">Přístupové kódy ke školení</h2>';
    $telo .= '<p class="em-muted" style="font-size:14px;color:#6b7280;margin:0 0 24px;line-height:1.6">Platba byla přijata. Níže najdete přístupové kódy pro vaše zaměstnance.</p>';
    $telo .= '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-bottom:20px">';
    $telo .= '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Firma</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . esc_html($firma_nazev) . '</td></tr>';
    $telo .= '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb" class="em-muted">Počet kódů</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb" class="em-text">' . count($kody) . ' ks</td></tr>';
    $telo .= '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280" class="em-muted">Kódy platí do</td><td style="padding:7px 0;font-size:13px;font-weight:700;text-align:right;color:#dc2626">' . esc_html($expir_text) . '</td></tr>';
    $telo .= '</table>';
    $telo .= '<div style="background:#fef9c3;border:1px solid #fde68a;border-radius:8px;padding:12px 16px;margin-bottom:20px;font-size:12px;color:#92400e">⚠️ Kódy je nutné využít do <strong>' . esc_html($expir_text) . '</strong>. Po tomto datu kódy expirují a školení nebude možné absolvovat.</div>';
    $telo .= '<div class="em-surface" style="background:#f9f8ff;border:1px solid #e5e7eb;border-radius:8px;padding:16px 20px;margin-bottom:20px">';
    $telo .= '<p style="font-size:11px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px" class="em-label">Přístupové kódy</p>';
    $telo .= '<pre style="margin:0;font-family:monospace;font-size:13px;line-height:2;color:#111827;background:none;border:none;padding:0" class="em-text">' . implode("\n", array_map('esc_html', $kody)) . '</pre>';
    $telo .= '</div>';
    $telo .= '<p class="em-muted" style="font-size:13px;color:#6b7280;line-height:1.6;margin:0">Každý kód je jednorázový. Řidič ho zadá na <a href="' . home_url('/prihlaseni/') . '" style="color:#7c3aed">refdrive.pro/prihlaseni</a>.</p>';
    $telo .= '</div><div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb"><p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">Automaticky odesláno systémem <strong>refdrive.pro</strong></p></div></div></div></body></html>';
    $_from  = get_option('rd_smtp_from', get_option('admin_email'));
    $_fname = get_option('rd_smtp_from_name', get_bloginfo('name'));
    wp_mail($firma_email, 'Přístupové kódy ke školení – ' . $firma_nazev, $telo, ['Content-Type: text/html; charset=UTF-8', 'From: ' . $_fname . ' <' . $_from . '>']);

    // Notifikace autoškole — nová objednávka od firmy
    if ($autoskola_id) {
        $as_row = $wpdb->get_row($wpdb->prepare(
            "SELECT nazev, email FROM " . RD_TABLE_AUTOSKOLY . " WHERE id=%d AND stav='aktivni' LIMIT 1",
            $autoskola_id
        ));
        if ($as_row && $as_row->email) {
            $as_telo = rd_email_wrap(
                'Nová objednávka školení',
                '<p>Firma <strong>' . esc_html($firma_nazev) . '</strong> (' . esc_html($firma_email) . ') právě objednala školení přes váš odkaz.</p>'
                . '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:16px 0">'
                . '<tr><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Počet kódů</td><td style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb">' . intval($pocet) . ' ks</td></tr>'
                . '</table>'
                . rd_email_btn('Zobrazit v administraci →', admin_url('admin.php?page=refdrive-as-' . $autoskola_id))
            );
            rd_email_autoskola($as_row->email, 'RefDrive: Nová objednávka — ' . $firma_nazev, $as_telo);
        }
    }
}

