        . $logo
        . '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 8px">Školení bylo úspěšně dokončeno</h2>'
        . '<p class="em-muted" style="font-size:14px;color:#6b7280;margin:0 0 24px;line-height:1.6">' . $j . ' absolvoval školení referentských řidičů a úspěšně prošel závěrečným testem.</p>'
        . '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-bottom:24px">'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Řidič</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb;color:#111827">' . $j . '</td></tr>'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Firma</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb;color:#111827">' . $f . '</td></tr>'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Výsledek testu</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb;color:#111827">' . $s . ' %</td></tr>'
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280;border-bottom:1px solid #e5e7eb">Datum</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;border-bottom:1px solid #e5e7eb;color:#111827">' . $d . '</td></tr>'
        . $tr
        . '<tr class="em-row"><td style="padding:7px 0;font-size:13px;color:#6b7280">Kód</td><td class="em-text" style="padding:7px 0;font-size:13px;font-weight:500;text-align:right;color:#111827">' . $k . '</td></tr>'
        . '</table>'
        . '<a href="' . esc_url($portal_url) . '" style="' . $btn_style . '">Zobrazit přehled v portálu</a>'
        . '</div>'
        . '<div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb"><p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">Automaticky odesláno systémem <strong>refdrive.pro</strong></p></div>'
        . '</div></div></body></html>';
}



function rd_odeslat_email($jmeno, $email, $firma, $score, $datum, $kod, $trvani = '') {
    $predmet   = 'Školení dokončeno – ' . $jmeno . ' (' . $firma . ')';
    $telo      = rd_sestavit_email($jmeno, $email, $firma, $score, $datum, $kod, $trvani);
    $from      = get_option('rd_smtp_from', get_option('admin_email'));
    $from_name = get_option('rd_smtp_from_name', get_bloginfo('name'));
    $headers   = ['Content-Type: text/html; charset=UTF-8', 'From: ' . $from_name . ' <' . $from . '>'];
    $result    = wp_mail($email, $predmet, $telo, $headers);
    return $result;
}

/* ============================================================
   Zjistí, kdo provedl akci "Obnovit výchozí" — rozliší lektorský kontext
   (přihlášení přes $_SESSION['rd_lektor']) od admin kontextu (přihlášený WP
   uživatel v administraci). Vrací pole se jménem a typem pro účely logování.
   ============================================================ */
function rd_kdo_resetoval() {
    global $wpdb;
    if (!empty($_SESSION['rd_lektor'])) {
        $jmeno = (string) $wpdb->get_var($wpdb->prepare(
            "SELECT jmeno FROM {$wpdb->prefix}rd_lektor WHERE id=%d", $_SESSION['rd_lektor']
        ));
        return ['jmeno' => $jmeno ?: 'Lektor', 'typ' => 'lektor'];
    }
    $u = wp_get_current_user();
    return ['jmeno' => $u && $u->display_name ? $u->display_name : 'Admin', 'typ' => 'admin'];
}

