/* ---- FIREMNÍ PORTÁL ---- */
function rd_sc_firma_portal() {
    if (!session_id() && !rd_is_rest() && !(defined("DOING_CRON") && DOING_CRON)) session_start();
    // Přihlášený řidič sem nesmí
    if (isset($_SESSION['rd_kod'])) {
        global $wpdb;
        $abs = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE kod=%s AND uspech=1", $_SESSION['rd_kod']));
        if ($abs || isset($_SESSION['rd_cert_jmeno'])) { wp_redirect(home_url('/certifikat/')); exit; }
        wp_redirect(home_url('/kurz/')); exit;
    }
    global $wpdb;
    $tbl_firmy = $wpdb->prefix . 'rd_firmy';
    $zprava = '';
    $faze = 'login'; // login, kod, portal

    // Odhlášení
    if (isset($_GET['odhlasit_firmu'])) {
        global $wpdb;
        $wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_rd_cert_access_%' OR option_name LIKE '_transient_timeout_rd_cert_access_%'");
        unset($_SESSION['rd_firma_id'], $_SESSION['rd_firma_email'], $_SESSION['rd_firma_nazev'], $_SESSION['rd_login_email']);
        setcookie('rd_firma_login', '', time() - 3600, '/', '', is_ssl(), false);
        wp_redirect(home_url('/firma-portal/')); exit;
    }

    // Pokud již přihlášena
    if (isset($_SESSION['rd_firma_id'])) {
        $faze = 'portal';
    } else {
        // Smazat rozpracované přihlášení pokud přicházíme přes GET (ne POST)
        if (!isset($_POST['rd_firma_login']) && !isset($_POST['rd_firma_kod'])) {
            unset($_SESSION['rd_login_email']);
        }
    }

    // Odeslání emailu s kódem
    if (isset($_POST['rd_firma_login']) && $faze === 'login') {
        $email = sanitize_email($_POST['firma_email'] ?? '');
        if (!$email) {
            $zprava = '<div class="rd-alert rd-alert-err">Zadejte platný email.</div>';
        } else {
            $firma = $wpdb->get_row($wpdb->prepare("SELECT * FROM $tbl_firmy WHERE email=%s", $email));
            if (!$firma) {
                $zprava = '<div style="background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.25);border-radius:10px;padding:16px;text-align:center;margin-bottom:0">'
                    . '<div class="rd-expired-date" style="display:flex;align-items:center;justify-content:center;gap:8px;font-size:14px;font-weight:600;margin-bottom:10px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px;flex-shrink:0"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>Email nenalezen.</div>'
                    . '<a href="' . home_url('/#autoskoly') . '" class="rd-portal-action-link" style="display:inline-flex;align-items:center;gap:6px;background:rgba(52,211,153,.15);border:1px solid rgba(52,211,153,.3);padding:8px 16px;border-radius:8px;font-size:13px;font-weight:600;text-decoration:none">Vyberte autoškolu a objednejte →</a>'
                    . '</div>';
            } else {
                // Vygenerovat token
                $token = str_pad(random_int(100000, 999999), 6, '0', STR_PAD_LEFT);
                $expiry = gmdate('Y-m-d H:i:s', time() + 15 * 60);
                $wpdb->update($tbl_firmy, ['login_token' => $token, 'token_expiry' => $expiry], ['email' => $email]);
                // Odeslat email
                $telo  = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>@media(prefers-color-scheme:dark){.em-bg{background:#0d0d14!important}.em-card{background:#1a1728!important;border-color:#2d2a3e!important}.em-text{color:#f1f0fb!important}.em-label{color:#ffffff!important}.em-muted{color:#9ca3af!important}.em-surface{background:#251f38!important;border-color:#2d2a3e!important}.em-footer{border-top-color:#2d2a3e!important}}</style></head><body style="margin:0;padding:0;font-family:Arial,sans-serif"><div class="em-bg" style="background:#f5f5f7;padding:32px 16px"><div class="em-card" style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;border:1px solid #e5e7eb;overflow:hidden"><div style="height:4px;background:linear-gradient(90deg,#7c3aed,#db2777)"></div><div style="padding:28px 32px 24px">';
                $telo .= '<a href="https://refdrive.pro" style="text-decoration:none;display:block;margin-bottom:20px"><span style="font-family:Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:-0.5px"><span style="color:#7c3aed">ref</span><span style="color:#db2777">drive</span><span style="color:#7c3aed">.pro</span></span><div style="font-size:11px;color:#9ca3af;margin-top:2px">Online školení referentských řidičů</div></a>';
                $telo .= '<h2 class="em-text" style="font-size:18px;font-weight:500;color:#111827;margin:0 0 8px">Přihlašovací kód</h2>';
                $telo .= '<p class="em-muted" style="font-size:14px;color:#6b7280;margin:0 0 24px;line-height:1.6">Váš jednorázový přihlašovací kód do Firemního přístupu. Platí 15 minut.</p>';
                $telo .= '<div class="em-surface" style="background:#f9f8ff;border:1px solid #e5e7eb;border-radius:8px;padding:28px;text-align:center;margin-bottom:20px">';
                $telo .= '<div style="font-size:2rem;font-weight:900;letter-spacing:10px;color:#111827;font-family:monospace" class="em-text">' . $token . '</div>';
                $telo .= '</div>';
                $telo .= '<p class="em-muted" style="font-size:13px;color:#6b7280;margin:0">Pokud jste přihlášení nepožadovali, ignorujte tento email.</p>';
                $telo .= '</div><div class="em-footer" style="padding:14px 32px;border-top:1px solid #e5e7eb"><p class="em-muted" style="font-size:11px;color:#9ca3af;margin:0">Automaticky odesláno systémem <strong>refdrive.pro</strong></p></div></div></div></body></html>';
                $_from4 = get_option('rd_smtp_from', get_option('admin_email'));
                $_fname4 = get_option('rd_smtp_from_name', get_bloginfo('name'));
                wp_mail($email, 'Přihlašovací kód – refdrive.pro', $telo, ['Content-Type: text/html; charset=UTF-8', 'From: ' . $_fname4 . ' <' . $_from4 . '>']);
                $_SESSION['rd_login_email'] = $email;
                $faze = 'kod';
                $zprava = '<div class="rd-alert rd-alert-ok" style="flex-direction:column;align-items:center;text-align:center;gap:6px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:24px;height:24px;flex-shrink:0;display:block;margin:0 auto 2px"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg><span>Kód byl odeslán na <strong>' . esc_html($email) . '</strong>.<br>Zkontrolujte email.</span></div>';
            }
        }
    }

    // Ověření kódu
    if (isset($_POST['rd_firma_kod'])) {
        $email = $_SESSION['rd_login_email'] ?? sanitize_email($_POST['login_email'] ?? '');
        $kod   = sanitize_text_field($_POST['login_kod'] ?? '');
        // Bruteforce ochrana OTP – max 10 pokusů za 15 minut per IP
        $fb_key = 'rd_fb_' . md5(rd_get_ip());
        $fb_cnt = (int)get_transient($fb_key);
        if ($fb_cnt >= 10) {
            $faze = 'kod';
            $zprava = '<div class="rd-alert rd-alert-err">Příliš mnoho neúspěšných pokusů. Zkuste to znovu za 15 minut.</div>';
        } else {
        $firma = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $tbl_firmy WHERE email=%s AND login_token=%s", $email, $kod
        ));
        if (!$firma) {
            set_transient($fb_key, $fb_cnt + 1, 15 * MINUTE_IN_SECONDS);
            $faze = 'kod';
            $zprava = '<div class="rd-alert rd-alert-err" style="flex-direction:column;align-items:center;text-align:center;gap:6px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:24px;height:24px;flex-shrink:0;display:block;margin:0 auto 2px"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><span>Neplatný nebo vypršelý kód.</span></div>';
        } else {
            delete_transient($fb_key);
            unset($_SESSION['rd_lektor'], $_SESSION['rd_kod'], $_SESSION['rd_token']);
            $_SESSION['rd_firma_id']    = $firma->id;
            $_SESSION['rd_firma_email'] = $firma->email;
            $_SESSION['rd_firma_nazev'] = $firma->nazev;
            unset($_SESSION['rd_login_email']);
            setcookie('rd_firma_login', base64_encode($firma->id), time() + 86400, '/', '', is_ssl(), true);
            $wpdb->update($tbl_firmy, ['login_token' => null, 'token_expiry' => null], ['id' => $firma->id]);
            // Redirect — cookie zajistí obnovení session, header se vykreslí správně
            wp_redirect(home_url('/firma-portal/')); exit;
        }
        } // end bruteforce else
    }

    // Pokud byl email zadán ale čekáme na kód
    if ($faze === 'login' && isset($_SESSION['rd_login_email']) && !isset($_POST['rd_firma_login'])) {
        $faze = 'kod';
    }

    ob_start();

    /* --- PŘIHLÁŠENÍ --- */
    if ($faze === 'login'): ?>
<div class="rd-page rd-center">
  <div class="rd-login-card">
    <div class="rd-login-icon-wrap">
      <div class="rd-login-icon">
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="3" y="3" width="18" height="18" rx="2" stroke="url(#bld-g)" stroke-width="1.8" fill="url(#bld-g2)" opacity="1"/>
          <rect x="3" y="3" width="18" height="18" rx="2" stroke="url(#bld-g)" stroke-width="1.8"/>
          <path d="M9 21V12h6v9" stroke="url(#bld-g)" stroke-width="1.8" stroke-linecap="round"/>
          <rect x="7" y="6" width="3" height="3" rx=".5" fill="url(#bld-g)"/>
          <rect x="14" y="6" width="3" height="3" rx=".5" fill="url(#bld-g)"/>
          <defs>
            <linearGradient id="bld-g" x1="3" y1="3" x2="21" y2="21"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient>
            <linearGradient id="bld-g2" x1="3" y1="3" x2="21" y2="21"><stop offset="0%" stop-color="#a78bfa" stop-opacity=".1"/><stop offset="100%" stop-color="#f472b6" stop-opacity=".08"/></linearGradient>
          </defs>
        </svg>
      </div>
    </div>
    <h2>Firemní přístup</h2>
    <p class="rd-login-sub">Zadejte email, který jste použili při první objednávce.</p>
    <?php echo $zprava; ?>
    <form method="post" class="rd-form">
      <div class="rd-field" style="margin-top:20px"><label>Firemní email</label><input type="email" name="firma_email" required placeholder="hr@vase-firma.cz" autofocus></div>
      <button type="submit" name="rd_firma_login" class="rd-btn rd-btn-primary rd-btn-full">Odeslat přihlašovací kód →</button>
    </form>
    <p class="rd-login-help">Jste zde poprvé? <a href="<?php echo home_url('/#autoskoly'); ?>" style="white-space:nowrap">Objednejte školení</a> u vybrané autoškoly a účet se vytvoří automaticky.</p>
  </div>
</div>

    <?php elseif ($faze === 'kod'): ?>
<div class="rd-page rd-center">
  <div class="rd-login-card">
    <div class="rd-login-icon-wrap">
      <div class="rd-login-icon">
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="5" width="20" height="14" rx="2" stroke="url(#mail-g)" stroke-width="1.8" fill="url(#mail-g2)"/>
          <path d="M2 8l10 7 10-7" stroke="url(#mail-g)" stroke-width="1.8" stroke-linecap="round"/>
          <defs>
            <linearGradient id="mail-g" x1="2" y1="5" x2="22" y2="19"><stop offset="0%" stop-color="#a78bfa"/><stop offset="100%" stop-color="#f472b6"/></linearGradient>
            <linearGradient id="mail-g2" x1="2" y1="5" x2="22" y2="19"><stop offset="0%" stop-color="#a78bfa" stop-opacity=".1"/><stop offset="100%" stop-color="#f472b6" stop-opacity=".08"/></linearGradient>
          </defs>
        </svg>
      </div>
    </div>
    <h2>Zadejte přihlašovací kód</h2>
    <?php echo $zprava; ?>
    <form method="post" class="rd-form">
      <div class="rd-field">
        <label>6místný kód</label>
        <input type="text" name="login_kod" required placeholder="123456" maxlength="6" pattern="[0-9]{6}" autofocus style="text-align:center;font-size:1.5rem;letter-spacing:8px;font-family:monospace">
      </div>
      <input type="hidden" name="login_email" value="<?php echo esc_attr($_SESSION['rd_login_email'] ?? ''); ?>">
      <button type="submit" name="rd_firma_kod" class="rd-btn rd-btn-primary rd-btn-full">Přihlásit se →</button>
    </form>
    <p class="rd-login-help"><a href="<?php echo home_url('/firma-portal/'); ?>">← Zadat jiný email</a></p>
  </div>
</div>

    <?php elseif ($faze === 'portal'):
        $firma_email = $_SESSION['rd_firma_email'];
        $firma_nazev = $_SESSION['rd_firma_nazev'];
        $firma_data  = $wpdb->get_row($wpdb->prepare("SELECT * FROM $tbl_firmy WHERE email=%s", $firma_email));

        // Kmenová autoškola
        $kmenova_as = $wpdb->get_row($wpdb->prepare(
            "SELECT a.id, a.slug, a.nazev, a.cena_kus FROM " . RD_TABLE_AUTOSKOLY . " a
             INNER JOIN " . RD_TABLE_FIRMA_AS . " fa ON fa.autoskola_id=a.id
             WHERE fa.firma_id=%d AND fa.kmenova=1 LIMIT 1",
            intval($firma_data->id ?? 0)
        ));

        // Zjistit nákupní cenu z poslední objednávky
        $portal_nakupni_cena = 0;
        $portal_cena_smer = null;
        if ($kmenova_as) {
            $last_obj_portal = $wpdb->get_row($wpdb->prepare(
                "SELECT data FROM " . RD_TABLE_OBJ . "
                 WHERE autoskola_id=%d AND firma_email=%s AND stav IN ('zaplaceno','hotovo','prevod_ok')
                 ORDER BY vytvoreno DESC LIMIT 1",
                $kmenova_as->id, $firma_email
            ));
            if ($last_obj_portal) {
                $ld_portal = json_decode($last_obj_portal->data ?? '{}', true);
                $portal_nakupni_cena = intval($ld_portal['cena'] ?? 0);
            }
            if ($portal_nakupni_cena) {
                if (intval($kmenova_as->cena_kus) > $portal_nakupni_cena) $portal_cena_smer = 'drazsi';
                elseif (intval($kmenova_as->cena_kus) < $portal_nakupni_cena) $portal_cena_smer = 'levnejsi';
            }
        }

        // URL tlačítka objednávky – při zdražení výběr autoškol, při zlevnění přímá objednávka
        $objednavka_url = $kmenova_as
            ? ($portal_cena_smer === 'drazsi'
                ? home_url('/#autoskoly')
                : home_url('/objednavka/?ref=' . $kmenova_as->slug))
            : home_url('/#autoskoly');

        // Statistiky
        $celkem  = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s", $firma_email));
        $pouzito = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE firma_email=%s AND pouzit=1", $firma_email));
        $splnilo = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " WHERE firma_email=%s AND uspech=1", $firma_email));
        $kody    = $wpdb->get_results($wpdb->prepare("SELECT k.*, COALESCE(k.ridic_jmeno,r.jmeno) as jmeno_ridice, r.score, r.uspech, r.cert_uuid, r.datum_skoleni, a.nazev as autoskola_nazev FROM " . RD_TABLE_KODY . " k LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod = k.kod ORDER BY uspech DESC, id DESC LIMIT 1) LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=k.autoskola_id WHERE k.firma_email=%s ORDER BY k.vytvoreno DESC LIMIT 100", $firma_email));

        // Nevyužité kódy expirující do 30 dní
        $expirujici_kody = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_KODY . "
             WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL
             AND expiruje BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY)", $firma_email));
        $expirujici_prirazene = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_KODY . "
             WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL
             AND expiruje BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY)
             AND zamestnanec_email IS NOT NULL AND zamestnanec_email != ''", $firma_email));
        $expirovane_kody = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_KODY . "
             WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL AND expiruje < CURDATE()", $firma_email));
        $expirovane_prirazene = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_KODY . "
             WHERE firma_email=%s AND pouzit=0 AND expiruje IS NOT NULL AND expiruje < CURDATE()
             AND zamestnanec_email IS NOT NULL AND zamestnanec_email != ''", $firma_email));
    ?>
<div class="rd-page">
  <!-- Header portálu -->
  <div class="rd-portal-header">
    <div class="rd-portal-brand">
      <div class="rd-hero-badge"><svg style="display:inline;vertical-align:middle;margin-right:5px" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0H5m14 0h2M5 21H3m4-10h2m4 0h2M9 7h2m4 0h2"/></svg>Firemní přístup</div>
      <h1 class="rd-portal-company"><?php echo esc_html($firma_nazev); ?></h1>
      <p class="rd-portal-email"><?php echo esc_html($firma_email); ?></p>
    </div>
  </div>

  <!-- Statistiky — kompaktní řádek, klikatelné filtry -->
  <div id="rd-stat-filters" style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0">
    <div class="rd-stat-card" data-filter="vse" style="cursor:pointer;background:rgba(124,58,237,.12);border:1px solid rgba(124,58,237,.2);border-radius:10px;padding:12px 8px;text-align:center;transition:box-shadow .15s">
      <div class="rd-stat-num rd-stat-num-violet" style="font-size:22px;font-weight:800;color:#a78bfa;line-height:1"><?php echo $celkem; ?></div>
      <div class="rd-stat-label" style="font-size:10px;color:#9ca3af;margin-top:4px;text-transform:uppercase;letter-spacing:.04em">Celkem</div>
    </div>
    <div class="rd-stat-card" data-filter="splnil" style="cursor:pointer;background:rgba(52,211,153,.1);border:1px solid rgba(52,211,153,.2);border-radius:10px;padding:12px 8px;text-align:center;transition:box-shadow .15s">
      <div class="rd-stat-num rd-stat-num-green" style="font-size:22px;font-weight:800;color:#34d399;line-height:1"><?php echo $splnilo; ?></div>
      <div class="rd-stat-label" style="font-size:10px;color:#9ca3af;margin-top:4px;text-transform:uppercase;letter-spacing:.04em">Splnilo</div>
    </div>
    <div class="rd-stat-card" data-filter="probiha" style="cursor:pointer;background:rgba(251,191,36,.1);border:1px solid rgba(251,191,36,.2);border-radius:10px;padding:12px 8px;text-align:center;transition:box-shadow .15s">
      <div class="rd-stat-num rd-stat-num-amber" style="font-size:22px;font-weight:800;color:#fbbf24;line-height:1"><?php echo $pouzito - $splnilo; ?></div>
      <div class="rd-stat-label" style="font-size:10px;color:#9ca3af;margin-top:4px;text-transform:uppercase;letter-spacing:.04em">Probíhá</div>
    </div>
    <div class="rd-stat-card" data-filter="volny" style="cursor:pointer;background:rgba(167,139,250,.08);border:1px solid rgba(167,139,250,.15);border-radius:10px;padding:12px 8px;text-align:center;transition:box-shadow .15s">
      <div class="rd-stat-num rd-stat-num-violet2" style="font-size:22px;font-weight:800;color:#c4b5fd;line-height:1"><?php echo $celkem - $pouzito; ?></div>
      <div class="rd-stat-label" style="font-size:10px;color:#9ca3af;margin-top:4px;text-transform:uppercase;letter-spacing:.04em">Volných</div>
      <?php
        $pocet_prirazene = count(array_filter($kody, fn($k) => !$k->pouzit && !empty($k->zamestnanec_email)));
        if ($pocet_prirazene > 0):
      ?>
      <div style="font-size:10px;color:#a78bfa;margin-top:3px"><?php echo $pocet_prirazene; ?> odesláno</div>
      <?php endif; ?>
    </div>
  </div>

  <!-- Upozornění na expiraci kódů -->
  <?php if ($expirovane_kody > 0): ?>
  <div class="rd-info-chip rd-chip-red" style="margin-bottom:16px">
