    <tbody>
    <?php foreach ($kody as $k):
      if ($k->pouzit && $k->uspech) $rd_stav = 'splnil';
      elseif ($k->pouzit && $k->uspech === '0') $rd_stav = 'nesplnil';
      elseif ($k->jmeno_ridice) $rd_stav = 'probiha';
      elseif (!empty($k->zamestnanec_email)) $rd_stav = 'prirazen';
      else $rd_stav = 'volny';
    ?>
    <tr data-stav="<?php echo esc_attr($rd_stav); ?>">
      <td><code class="rd-code"><?php echo esc_html($k->kod); ?></code></td>
      <td class="rd-td-name"><?php
        if ($k->jmeno_ridice) {
          echo esc_html($k->jmeno_ridice);
        } elseif (!empty($k->zamestnanec_jmeno)) {
          echo esc_html($k->zamestnanec_jmeno);
          echo '<br><span style="font-size:11px;opacity:.6">' . esc_html($k->zamestnanec_email) . '</span>';
          if (!empty($k->kod_odeslan_at)) echo '<br><span style="font-size:11px;opacity:.5">Odesláno ' . date('d.m. H:i', strtotime($k->kod_odeslan_at)) . '</span>';
        } else {
          echo '<span class="rd-empty">—</span>';
        }
      ?></td>
      <td><?php echo $k->autoskola_nazev ? '<span style="font-size:.8rem">' . esc_html($k->autoskola_nazev) . '</span>' : '<span class="rd-empty">—</span>'; ?></td>
      <td><?php
        if ($rd_stav === 'splnil') echo '<span class="rd-badge rd-badge-green"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display:inline;vertical-align:middle;margin-right:3px"><polyline points="20 6 9 17 4 12"/></svg>Splnil</span>';
        elseif ($rd_stav === 'nesplnil') echo '<span class="rd-badge rd-badge-red"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display:inline;vertical-align:middle;margin-right:3px"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>Nesplnil</span>';
        elseif ($rd_stav === 'probiha') echo '<span class="rd-badge rd-badge-blue"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display:inline;vertical-align:middle;margin-right:3px"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>Probíhá</span>';
        elseif ($rd_stav === 'prirazen') echo '<span class="rd-badge rd-badge-violet" style="background:rgba(124,58,237,.12);color:#7c3aed;border:1px solid rgba(124,58,237,.25)"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display:inline;vertical-align:middle;margin-right:3px"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>Odesláno</span>';
        else echo '<span class="rd-badge rd-badge-amber"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display:inline;vertical-align:middle;margin-right:3px"><circle cx="12" cy="12" r="9"/></svg>Volný</span>';
      ?></td>
      <td class="rd-td-score"><?php echo $k->score !== null && $k->pouzit ? $k->score . '%' : '<span class="rd-empty">—</span>'; ?></td>
      <td class="rd-td-date"><?php echo $k->datum_skoleni ? date('d.m.Y', strtotime($k->datum_skoleni)) : ($k->datum_pouziti ? date('d.m.Y', strtotime($k->datum_pouziti)) : '<span class="rd-empty">—</span>'); ?></td>
      <td class="rd-td-date"><?php echo $k->vytvoreno ? date('d.m.Y', strtotime($k->vytvoreno)) : '<span class="rd-empty">—</span>'; ?></td>
      <td class="rd-td-date"><?php
        if (!$k->expiruje) {
          echo '<span class="rd-empty">—</span>';
        } else {
          $rd_exp_ts = strtotime($k->expiruje);
          $rd_exp_str = date('d.m.Y', $rd_exp_ts);
          if (!$k->pouzit && $rd_exp_ts <= time()) {
            echo '<span class="rd-expired-date">' . $rd_exp_str . '</span>';
          } else {
            echo $rd_exp_str;
          }
        }
      ?></td>
      <td><?php if ($k->pouzit && $k->uspech):
        $access_key_sc = bin2hex(random_bytes(16));
