        $cert_url = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($k->kod) . '&access=' . $access_key_sc;
        echo '<a href="' . esc_url($cert_url) . '" target="_blank" data-tooltip="Zobrazit certifikát" class="rd-icon-btn" style="display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:52px;padding:5px 6px;border-radius:6px;border:1px solid rgba(34,197,94,.25);color:#22c55e;background:rgba(34,197,94,.08);text-decoration:none"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="6"/><path d="M15.477 12.89L17 22l-5-3-5 3 1.523-9.11"/></svg><span style="font-size:9px;line-height:1;font-weight:500">Certifikát</span></a>';
