  <script>
  (function(){
    function rdInitFiltry(){
    var cards = document.querySelectorAll('#rd-stat-filters .rd-stat-card');
    var rows  = document.querySelectorAll('#rd-ridici-table tbody tr');
    var active = 'vse';
    function applyFilter(f) {
      active = f;
      cards.forEach(function(c){
        c.classList.toggle('rd-stat-active', c.dataset.filter === f);
      });
      rows.forEach(function(r){
        var stav = r.dataset.stav;
        var show = (f === 'vse')
          || (f === stav)
          || (f === 'probiha' && stav === 'nesplnil')
          || (f === 'volny' && stav === 'prirazen');
        r.style.display = show ? '' : 'none';
      });
    }
    cards.forEach(function(c){
      c.addEventListener('click', function(){
        applyFilter(c.dataset.filter === active && active !== 'vse' ? 'vse' : c.dataset.filter);
      });
    });
    applyFilter('vse');

    // Řazení tabulky kliknutím na hlavičku
    var rdSortCol = -1, rdSortAsc = true;
    document.querySelectorAll('#rd-ridici-table .rd-th-sort').forEach(function(th) {
      th.addEventListener('click', function() {
        var col = parseInt(th.dataset.col);
        if (rdSortCol === col) { rdSortAsc = !rdSortAsc; }
        else { rdSortCol = col; rdSortAsc = true; }
        document.querySelectorAll('.rd-th-sort .rd-sort-icon').forEach(function(i){ i.textContent = '⇅'; i.style.opacity = '.4'; });
        th.querySelector('.rd-sort-icon').textContent = rdSortAsc ? '↑' : '↓';
        th.querySelector('.rd-sort-icon').style.opacity = '1';
        var tbody = document.querySelector('#rd-ridici-table tbody');
        var rows = Array.from(tbody.querySelectorAll('tr'));
        rows.sort(function(a, b) {
          var ac = a.cells[col] ? a.cells[col].textContent.trim() : '';
          var bc = b.cells[col] ? b.cells[col].textContent.trim() : '';
          var an = parseFloat(ac), bn = parseFloat(bc);
          if (!isNaN(an) && !isNaN(bn)) return rdSortAsc ? an - bn : bn - an;
          return rdSortAsc ? ac.localeCompare(bc, 'cs') : bc.localeCompare(ac, 'cs');
        });
        rows.forEach(function(r){ tbody.appendChild(r); });
      });
    });
    } // konec rdInitFiltry
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', rdInitFiltry);
    } else {
      rdInitFiltry();
    }
  })();
  </script>
  <?php endif; ?>

