// Export handlers — firma portál (CSV absolventů, ZIP certifikátů)
add_action('init', function() {
    if (empty($_GET['rd_firma_export'])) return;
    if (!session_id() && !rd_is_rest()) session_start();
    $firma_email = $_SESSION['rd_firma_email'] ?? '';
    if (!$firma_email) return;
    $nonce = sanitize_text_field($_GET['nonce'] ?? '');
    if (!wp_verify_nonce($nonce, 'rd_firma_export_' . $firma_email)) wp_die('Neplatný požadavek.');
    global $wpdb;
    $typ = sanitize_key($_GET['rd_firma_export']);

    $kody = $wpdb->get_results($wpdb->prepare(
        "SELECT k.kod, COALESCE(k.ridic_jmeno,r.jmeno) as jmeno, r.score, r.datum_skoleni, r.cert_uuid, a.nazev as autoskola
         FROM " . RD_TABLE_KODY . " k
         LEFT JOIN " . RD_TABLE_RIDICI . " r ON r.id = (SELECT id FROM " . RD_TABLE_RIDICI . " r2 WHERE r2.kod=k.kod ORDER BY uspech DESC, id DESC LIMIT 1)
         LEFT JOIN " . RD_TABLE_AUTOSKOLY . " a ON a.id=k.autoskola_id
         WHERE k.firma_email=%s AND k.pouzit=1 AND r.uspech=1
         ORDER BY r.datum_skoleni DESC",
        $firma_email
    ));

    if ($typ === 'csv') {
        // CSV absolventů
        $bom = "\xEF\xBB\xBF";
        $rows = [['Jméno řidiče', 'Kód', 'Autoškola', 'Datum absolvování', 'Score (%)', 'Certifikát URL']];
        foreach ($kody as $k) {
            $cert_url = '';
            if ($k->cert_uuid) {
                $token = bin2hex(random_bytes(16));
                set_transient('rd_cert_access_' . $token, $k->kod, HOUR_IN_SECONDS);
                $cert_url = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($k->kod) . '&access=' . $token;
            }
            $rows[] = [
                $k->jmeno ?? '',
                $k->kod,
                $k->autoskola ?? '',
                $k->datum_skoleni ? date('d.m.Y', strtotime($k->datum_skoleni)) : '',
                $k->score ?? '',
                $cert_url,
            ];
        }
        $csv = $bom . implode("\n", array_map(function($r) {
            return implode(';', array_map(fn($v) => '"' . str_replace('"', '""', $v) . '"', $r));
        }, $rows));
        nocache_headers();
        header('Content-Type: text/csv; charset=UTF-8');
        header('Content-Disposition: attachment; filename="absolventi-' . date('Y-m-d') . '.csv"');
        echo $csv; exit;

    } elseif ($typ === 'zip') {
        // ZIP certifikátů
        if (!class_exists('ZipArchive')) wp_die('ZIP není dostupný na serveru.');
        $tmpfile = tempnam(sys_get_temp_dir(), 'rdzip_');
        $zip = new ZipArchive();
        $zip->open($tmpfile, ZipArchive::OVERWRITE);
        foreach ($kody as $k) {
            if (!$k->cert_uuid) continue;
            $token = bin2hex(random_bytes(16));
            set_transient('rd_cert_access_' . $token, $k->kod, HOUR_IN_SECONDS);
            $cert_url = plugin_dir_url(__FILE__) . 'rd-cert.php?kod=' . urlencode($k->kod) . '&access=' . $token;
            $cert_data = wp_remote_get($cert_url, ['timeout' => 15, 'sslverify' => false]);
            if (!is_wp_error($cert_data) && wp_remote_retrieve_response_code($cert_data) === 200) {
                $jmeno_safe = remove_accents($k->jmeno ?? $k->kod);
                $jmeno_safe = preg_replace('/[^a-zA-Z0-9_\-]/', '_', $jmeno_safe);
                $jmeno_safe = preg_replace('/_+/', '_', $jmeno_safe); // sloučit opakovaná podtržítka
                $jmeno_safe = trim($jmeno_safe, '_');
                $zip->addFromString('certifikaty/' . $jmeno_safe . '_' . $k->kod . '.html', wp_remote_retrieve_body($cert_data));
            }
        }
        $zip->close();
        nocache_headers();
        header('Content-Type: application/zip');
        header('Content-Disposition: attachment; filename="certifikaty-' . date('Y-m-d') . '.zip"');
        header('Content-Length: ' . filesize($tmpfile));
        readfile($tmpfile);
        unlink($tmpfile);
        exit;
    }
}, 5);

// Uložit firmu při první objednávce (hook po úspěšné platbě)
function rd_ulozit_firmu($data) {
    global $wpdb;
    $tbl = $wpdb->prefix . 'rd_firmy';
    $email = sanitize_email($data['firma_email'] ?? '');
    $nazev = sanitize_text_field($data['firma_nazev'] ?? '');
    if (!$email || !$nazev) return;
    // Uložit pokud neexistuje, jinak aktualizovat údaje
    $existing = $wpdb->get_var($wpdb->prepare("SELECT id FROM $tbl WHERE email=%s", $email));
    if ($existing) {
        $wpdb->update($tbl, [
            'nazev'   => $nazev,
            'ico'     => sanitize_text_field($data['ico'] ?? ''),
            'ulice'   => sanitize_text_field($data['ulice'] ?? ''),
            'mesto'   => sanitize_text_field($data['mesto'] ?? ''),
            'psc'     => sanitize_text_field($data['psc'] ?? ''),
            'telefon' => sanitize_text_field($data['telefon'] ?? ''),
        ], ['id' => $existing]);
    } else {
        $wpdb->insert($tbl, [
            'email'   => $email,
            'nazev'   => $nazev,
            'ico'     => sanitize_text_field($data['ico'] ?? ''),
            'ulice'   => sanitize_text_field($data['ulice'] ?? ''),
            'mesto'   => sanitize_text_field($data['mesto'] ?? ''),
            'psc'     => sanitize_text_field($data['psc'] ?? ''),
            'telefon' => sanitize_text_field($data['telefon'] ?? ''),
        ]);
    }
}

function rd_lekce_source() {
    global $wpdb;
    $rows = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}rd_lekce ORDER BY poradi ASC", ARRAY_A);
    $default_cas = intval(get_option('rd_lekce_default_cas', 180));
    if (!empty($rows) && count($rows) >= 5) {
        return array_map(function($r) use ($default_cas) {
            return ['nazev'=>$r['nazev'],'popis'=>$r['popis'],'cas'=>((int)$r['cas'] > 0 ? (int)$r['cas'] : $default_cas),'obsah'=>$r['obsah'],'obrazek'=>$r['obrazek'] ?? null,'id'=>$r['id']];
        }, $rows);
    }
    // DB prázdná — použít hardcoded lekce s výchozím časem z nastavení
    $lekce = rd_get_lekce();
    return array_map(function($l) use ($default_cas) {
        $l['cas'] = $default_cas;
        return $l;
    }, $lekce);
}

function rd_otazky_source($count = 10) {
    global $wpdb;
    $rows = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}rd_otazky ORDER BY poradi ASC", ARRAY_A);
    if (!empty($rows) && count($rows) >= 20) {
        $all = array_map(function($r) {
            return ['otazka'=>$r['otazka'],'moznosti'=>['A'=>$r['moznost_a'],'B'=>$r['moznost_b'],'C'=>$r['moznost_c'],'D'=>$r['moznost_d']],'spravna'=>$r['spravna'],'id'=>$r['id']];
        }, $rows);
    } else {
        $all = rd_get_otazky();
    }
    if (count($all) <= $count) return $all;
    $keys = array_rand($all, $count);
    if (!is_array($keys)) $keys = [$keys];
    $selected = [];
    foreach ($keys as $k) $selected[] = $all[$k];
    return $selected;
}

function rd_novinky_source() {
    global $wpdb;
    $rows = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}rd_novinky ORDER BY poradi ASC", ARRAY_A);
    if (!empty($rows)) {
        return array_map(function($r) {
            return ['tag'=>$r['tag'],'nazev'=>$r['nazev'],'obsah'=>$r['obsah'],'id'=>$r['id']];
        }, $rows);
    }
    // Fallback - default novinky
    return [
        ['tag'=>'Aktuálně 2025/2026','nazev'=>'Digitální záznam o nehodě','obsah'=>'Záznam o dopravní nehodě lze od roku 2025 vyplnit digitálně přes aplikaci ČKP. Platí pro nehody bez zraněných se škodou do 200 000 Kč. <strong>Pojišťovny digitální záznam plně akceptují.</strong>'],
        ['tag'=>'Platné od 2026','nazev'=>'Řidičský průkaz v mobilu stačí','obsah'=>'Fyzická kartička <strong>není nutná</strong> — policista ověřuje platnost oprávnění online přes registr řidičů. Aplikace eDoklady rovněž funguje, ale <strong>není podmínkou</strong>.'],
        ['tag'=>'Od 1. 7. 2025','nazev'=>'Nový limit pro přivolání policie: 200 000 Kč','obsah'=>'Limit pro povinné přivolání policie se zvýšil na <strong>200 000 Kč</strong>. Pod touto hranicí (bez zraněných) stačí vyplnit záznam o nehodě — nově i digitálně přes aplikaci ČKP.'],
        ['tag'=>'Pro firmy s mladými zaměstnanci','nazev'=>'L17 a přísnější bodový postih','obsah'=>'Začínající řidiči jsou v přísnějším bodovém režimu. Dbejte na <strong>důsledné proškolení mladých referentů.</strong>'],
        ['tag'=>'Od 1. 1. 2026','nazev'=>'Lékařské prohlídky seniorů: nová pravidla','obsah'=>'Povinné prohlídky: Od 1. 1. 2026 se první povinná prohlídka posouvá na <strong>70 let</strong>. Řidiči ve věku 65–69 let prohlídku <strong>nemusí absolvovat</strong>. Lékař výsledek zapisuje elektronicky — posudek není nutné vozit u sebe. Zdroj: Ministerstvo dopravy ČR.'],
    ];
}


