// Načíst kroky "Jak to funguje" z options (JSON)
function rd_get_kroky() {
    $default = [
        ['h' => 'Vyberte autoškolu',      'p' => 'Níže najdete seznam partnerských autoškol. Vyberte tu s dostupnou kapacitou a objednejte kódy pro své zaměstnance.'],
        ['h' => 'Rozešlete kódy řidičům', 'p' => 'Každý zaměstnanec dostane unikátní přístupový kód. Kódy jsou platné 1 rok od vygenerování.'],
        ['h' => 'Absolvujte e-learning',  'p' => 'Kurz trvá cca 30–45 minut a obsahuje 10 lekcí. Závěrečný test má 15 otázek, minimální úspěšnost je 80 %.'],
        ['h' => 'Certifikát ihned',        'p' => 'Po úspěšném absolvování si každý řidič stáhne certifikát. Zaměstnavatel dostane automatické potvrzení.'],
    ];
    $saved = get_option('rd_txt_kroky', '');
    if ($saved) {
        $parsed = json_decode($saved, true);
        if (is_array($parsed) && count($parsed) > 0) return $parsed;
    }
    return $default;
}

// Vytvořit DB tabulky pro legislativu (pokud neexistují)
function rd_vytvorit_tabulky_leg() {
    global $wpdb;
    $cs = $wpdb->get_charset_collate();
    $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_leg_zakony (
        id INT AUTO_INCREMENT PRIMARY KEY,
        sekce VARCHAR(100) DEFAULT 'proc_povinne',
        zkratka VARCHAR(20) DEFAULT '§',
        nazev VARCHAR(300) NOT NULL,
        podtitulek VARCHAR(200) DEFAULT '',
        obsah TEXT,
        poradi INT DEFAULT 0
    ) {$cs}");
    $wpdb->query("CREATE TABLE IF NOT EXISTS {$wpdb->prefix}rd_leg_kroky (
        id INT AUTO_INCREMENT PRIMARY KEY,
        sekce VARCHAR(100) DEFAULT 'obsah',
        nadpis VARCHAR(200) NOT NULL,
        text TEXT,
        poradi INT DEFAULT 0
    ) {$cs}");
}

// Načíst zákonné záznamy z DB (s fallbackem)
function rd_leg_zakony_source($sekce = 'proc_povinne') {
    global $wpdb;
    $table = $wpdb->prefix . 'rd_leg_zakony';
    if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") !== $table) {
        rd_vytvorit_tabulky_leg();
    }
    $rows = $wpdb->get_results(
        $wpdb->prepare("SELECT * FROM {$table} WHERE sekce=%s ORDER BY poradi ASC", $sekce),
        ARRAY_A
    );
    if (!empty($rows)) return $rows;
    // Fallback výchozí hodnoty
    $defaults = [
        'proc_povinne' => [
            ['id'=>0,'zkratka'=>'§','nazev'=>'Zákoník práce — zákon č. 262/2006 Sb.','podtitulek'=>'Základní povinnost zaměstnavatele','obsah'=>'§ 103 odst. 2 zákoníku práce ukládá zaměstnavateli povinnost zajistit zaměstnancům školení o právních předpisech k zajištění bezpečnosti a ochrany zdraví při práci, které se vztahují k jejich práci — tedy i k řízení motorových vozidel.

Školení musí proběhnout při nástupu do práce, při změně pracovního zařazení a při změně pracovních postupů. Obsah, četnost a způsob provedení školení si zaměstnavatel stanoví sám — zákon formu školení nepředepisuje. <strong>E-learning je tedy přípustnou formou.</strong>','poradi'=>1],
            ['id'=>0,'zkratka'=>'§','nazev'=>'Zákoník práce — zákon č. 262/2006 Sb.','podtitulek'=>'Dokumentace školení','obsah'=>'§ 103 odst. 3 zákoníku práce ukládá zaměstnavateli povinnost vést dokumentaci o provedeném školení.

Tato dokumentace je klíčová při kontrole inspektorátu práce. <strong>Osvědčení z RefDrive spolu s výpisem z firemního portálu tuto povinnost splňuje.</strong>','poradi'=>2],
            ['id'=>0,'zkratka'=>'NV','nazev'=>'NV č. 168/2002 Sb.','podtitulek'=>'Organizace práce při provozování dopravy','obsah'=>'Nařízení vlády č. 168/2002 Sb. stanoví způsob organizace práce při provozování dopravy. Vztahuje se na všechny zaměstnavatele provozující dopravu — tedy i na firmy s referentskými řidiči.','poradi'=>3],
            ['id'=>0,'zkratka'=>'§','nazev'=>'Zákoník práce — zákon č. 262/2006 Sb.','podtitulek'=>'Odpovědnost zaměstnance za škodu','obsah'=>'Zaměstnanec odpovídá za škodu způsobenou zaměstnavateli z nedbalosti do výše <strong>4,5násobku průměrného měsíčního výdělku</strong>. Při úmyslném jednání je odpovědnost neomezená.','poradi'=>4],
            ['id'=>0,'zkratka'=>'§','nazev'=>'Zákon č. 361/2000 Sb.','podtitulek'=>'Pravidla silničního provozu','obsah'=>'Zákon o provozu na pozemních komunikacích upravuje pravidla silničního provozu, povinnosti účastníků nehody, nulovou toleranci alkoholu a bodový systém.

Od 1. 7. 2025 platí nový limit pro povinné přivolání policie k nehodě: <strong>škoda přesahující 200 000 Kč</strong> nebo přítomnost zraněných osob.','poradi'=>5],
        ],
        'postihy' => [
            ['id'=>0,'zkratka'=>'!','nazev'=>'Pokuta inspektorátu práce','podtitulek'=>'§ 17 zákona č. 251/2005 Sb.','obsah'=>'Za porušení povinností v oblasti BOZP, včetně neprovádění školení řidičů, může oblastní inspektorát práce uložit pokutu až do <strong>2 000 000 Kč</strong>.','poradi'=>1],
            ['id'=>0,'zkratka'=>'!','nazev'=>'Odpovědnost za škodu při nehodě','podtitulek'=>'Občanský zákoník a zákoník práce','obsah'=>'Pokud neproškolený řidič způsobí nehodu a zaměstnavatel neprokáže, že školení bylo provedeno, může nést zvýšenou odpovědnost za způsobenou škodu. Pojišťovna může uplatnit regresní nárok.','poradi'=>2],
            ['id'=>0,'zkratka'=>'!','nazev'=>'Chybějící dokumentace','podtitulek'=>'Povinnost vést evidenci','obsah'=>'Zaměstnavatel musí být schopen při kontrole doložit, že školení proběhlo — kdo, kdy a co bylo obsahem. RefDrive automaticky generuje certifikát a evidenci výsledků dostupnou ve firemním portálu.','poradi'=>3],
        ],
    ];
    return $defaults[$sekce] ?? [];
}

// Načíst kroky obsahu školení z DB (s fallbackem)
function rd_leg_kroky_source($sekce = 'obsah') {
    global $wpdb;
    $table = $wpdb->prefix . 'rd_leg_kroky';
    if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") !== $table) {
        rd_vytvorit_tabulky_leg();
    }
    $rows = $wpdb->get_results(
        $wpdb->prepare("SELECT * FROM {$table} WHERE sekce=%s ORDER BY poradi ASC", $sekce),
        ARRAY_A
    );
    if (!empty($rows)) return $rows;
    $defaults = [
        'obsah' => [
            ['id'=>0,'nadpis'=>'Dopravní předpisy','text'=>'Pravidla silničního provozu, značky, povinnosti řidiče a chodce, alkohol a drogy za volantem.','poradi'=>1],
            ['id'=>0,'nadpis'=>'Bezpečnost a BOZP','text'=>'Kontrola vozidla před jízdou, bezpečnostní přestávky, povinná výbava, práce s vozidlem.','poradi'=>2],
            ['id'=>0,'nadpis'=>'Dopravní nehoda','text'=>'Povinnosti při nehodě, přivolání záchranky a policie, záznam o nehodě, první pomoc.','poradi'=>3],
            ['id'=>0,'nadpis'=>'Odpovědnost','text'=>'Odpovědnost zaměstnance za škodu, regresní nárok pojišťovny, trestněprávní odpovědnost.','poradi'=>4],
        ],
    ];
    return $defaults[$sekce] ?? [];
}

/* ============================================================
   TEXTY WEBU – admin stránka
   ============================================================ */

// Globální helper - musí být mimo funkci, jinak PHP fatal při každém dalším načtení
function rd_texty_field($label, $name, $val, $rows = 0, $default = '') {
    $s = 'width:100%;font-size:13px;padding:8px 10px;border:1px solid #e5e7eb;border-radius:6px;box-sizing:border-box';
    // Zobrazit výchozí hodnotu pokud je uložená hodnota prázdná
    $display_val = ($val !== '' && $val !== false && $val !== null) ? $val : $default;
    echo '<div style="margin-bottom:10px">';
    echo '<label style="font-size:12px;font-weight:600;color:#6b7280;display:block;margin-bottom:4px">' . esc_html($label) . '</label>';
    if ($rows > 0) {
        echo '<textarea name="' . esc_attr($name) . '" rows="' . intval($rows) . '" style="' . $s . ';resize:vertical">' . esc_textarea($display_val) . '</textarea>';
    } else {
        echo '<input type="text" name="' . esc_attr($name) . '" value="' . esc_attr($display_val) . '" style="' . $s . '">';
    }
    echo '</div>';
}


function rd_portal_render($page) {
    global $wpdb;
    $as = rd_get_my_autoskola();
    if (!$as) wp_die('Autoškola nenalezena.');

    $id = (int)$as->id;

    // --- Data pro dashboard ---
    $celkem_kodu     = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d", $id));
    $pouzito_kodu    = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d AND pouzit=1", $id));
    $absolventi      = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT r.id) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1", $id, $id));
    $firem           = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT firma_email) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d AND firma_email!=''", $id));
    $avg_score       = (int)$wpdb->get_var($wpdb->prepare("SELECT AVG(r.score) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1", $id, $id));

    // Čekající objednávky (bankovní převody)
    $cekajici_obj = $wpdb->get_results($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_OBJ . " WHERE autoskola_id=%d AND stav='prevod_ceka' ORDER BY vytvoreno ASC",
        $id
    ));

    // Čekající platba balíčku
    $ceka_balicek = $wpdb->get_row($wpdb->prepare(
        "SELECT p.*, t.nazev as tier_nazev FROM " . RD_TABLE_AS_PLATBY . " p LEFT JOIN " . RD_TABLE_AS_TIERY . " t ON t.id=p.tier_id WHERE p.autoskola_id=%d AND p.stav='ceka_potvrzeni' ORDER BY p.id DESC LIMIT 1",
        $id
    ));

    // Aktivní balíčky
    $aktivni_platby  = rd_autoskola_aktivni_platby($id);
    $celkem_zbyvaji  = rd_autoskola_zbyvajici_kapacita($id);

    // Poslední objednávky
    $posledni_obj = $wpdb->get_results($wpdb->prepare(
        "SELECT * FROM " . RD_TABLE_OBJ . " WHERE autoskola_id=%d ORDER BY vytvoreno DESC LIMIT 5",
        $id
    ));

    // Top firmy podle absolventů
    $top_firmy = $wpdb->get_results($wpdb->prepare(
        "SELECT k.firma_nazev, k.firma_email, COUNT(DISTINCT r.id) as abs_count
         FROM " . RD_TABLE_KODY . " k
         INNER JOIN " . RD_TABLE_RIDICI . " r ON r.kod=k.kod
         WHERE k.autoskola_id=%d AND r.uspech=1
         GROUP BY k.firma_email
         ORDER BY abs_count DESC LIMIT 6",
        $id
    ));
    $top_max = !empty($top_firmy) ? max(array_column((array)$top_firmy, 'abs_count')) : 1;

    // Měsíční statistiky (posledních 6 měsíců)
    $mesice_labels = [];
    $mesice_abs    = [];
    $mesice_kody   = [];
    for ($m = 5; $m >= 0; $m--) {
        $ts    = strtotime("-$m months");
        $mesice_labels[] = strftime('%b', $ts) ?: date('M', $ts);
        $rok   = date('Y', $ts);
        $mes   = date('m', $ts);
        $mesice_abs[]  = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_RIDICI . " r LEFT JOIN " . RD_TABLE_KODY . " k ON k.kod=r.kod WHERE (r.autoskola_id=%d OR k.autoskola_id=%d) AND r.uspech=1 AND YEAR(r.datum_skoleni)=%s AND MONTH(r.datum_skoleni)=%s",
            $id, $id, $rok, $mes
        ));
        $mesice_kody[] = (int)$wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM " . RD_TABLE_KODY . " WHERE autoskola_id=%d AND YEAR(vytvoreno)=%s AND MONTH(vytvoreno)=%s",
            $id, $rok, $mes
        ));
    }

    // Počet čekajících akcí pro badge v menu
    $akce_count = count($cekajici_obj) + ($ceka_balicek ? 1 : 0);

    $portal_url = home_url('/portal/');

    // Aktuální měsíc v češtině
    $mesice_cs = ['','ledna','února','března','dubna','května','června','července','srpna','září','října','listopadu','prosince'];
    $dnes_text = date('j') . '. ' . ($mesice_cs[(int)date('m')] ?? date('F')) . ' ' . date('Y');

    // Stav objednávek labels
    $stav_label = ['ceka'=>'Čeká','zaplaceno'=>'Zaplaceno','hotovo'=>'Hotovo','prevod_ceka'=>'Čeká na platbu','prevod_ok'=>'Zaplaceno','storno'=>'Storno'];

    ?>
<!DOCTYPE html>
<html lang="cs">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>RefDrive.pro — Portál autoškoly</title>
<meta name="robots" content="noindex,nofollow">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@latest/tabler-icons.min.css">
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"></script>
<style>
*{box-sizing:border-box;margin:0;padding:0}
:root{
  --ink:#18181b;--ink2:#52525b;--ink3:#a1a1aa;
  --line:#e4e4e7;--line2:#f4f4f5;
  --bg:#f7f7f8;--white:#fff;
  --v:#4f46e5;--vl:#eef2ff;--vd:#3730a3;
  --gr:#059669;--grl:#ecfdf5;
  --am:#b45309;--aml:#fffbeb;
  --rd:#dc2626;--rdl:#fef2f2;
  --radius:10px;
  --sb-w:52px;
}
html,body{height:100%;overflow:hidden}
body{font-family:'Inter',system-ui,sans-serif;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased;font-size:13px}

/* SHELL */
.shell{display:flex;height:100vh;overflow:hidden}

/* SIDEBAR */
.sb{width:var(--sb-w);background:var(--white);border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;padding:14px 0 10px;transition:width .22s cubic-bezier(.4,0,.2,1);overflow:hidden;flex-shrink:0;z-index:100}
.sb:hover,.sb.open{width:210px}
.sb-logo{width:32px;height:32px;border-radius:9px;background:var(--v);display:grid;place-items:center;flex-shrink:0;margin-bottom:12px;transition:none}
.sb-logo i{font-size:16px;color:#fff}
.sb-wordmark{opacity:0;white-space:nowrap;font-size:13px;font-weight:700;color:var(--ink);letter-spacing:-.01em;transition:opacity .15s .06s;position:absolute;left:52px;top:21px;pointer-events:none}
.sb:hover .sb-wordmark,.sb.open .sb-wordmark{opacity:1}
.sb-sep{width:28px;height:1px;background:var(--line);margin:5px 0;flex-shrink:0;transition:width .22s}
.sb:hover .sb-sep,.sb.open .sb-sep{width:178px}
.ni{display:flex;align-items:center;width:36px;height:34px;border-radius:8px;cursor:pointer;transition:all .16s;overflow:hidden;flex-shrink:0;position:relative}
.sb:hover .ni,.sb.open .ni{width:186px;padding:0 10px;gap:10px}
.ni:hover{background:var(--bg)}
.ni.on{background:var(--vl)}
.ni i.ic{font-size:16px;width:36px;text-align:center;flex-shrink:0;color:var(--ink3);transition:color .13s;line-height:34px}
.sb:hover .ni i.ic,.sb.open .ni i.ic{width:auto}
.ni.on i.ic{color:var(--v)}
.ni .nl{font-size:12px;color:var(--ink2);white-space:nowrap;opacity:0;transition:opacity .13s .04s;flex:1}
.sb:hover .ni .nl,.sb.open .ni .nl{opacity:1}
.ni.on .nl{color:var(--v);font-weight:500}
.np{font-size:9px;font-weight:700;background:var(--rd);color:#fff;padding:2px 5px;border-radius:99px;white-space:nowrap;opacity:0;transition:opacity .13s .04s;flex-shrink:0}
.sb:hover .np,.sb.open .np{opacity:1}
.ndot{position:absolute;top:5px;right:5px;width:7px;height:7px;border-radius:50%;background:var(--am);border:2px solid var(--white);animation:dot-pulse 2s ease infinite}
.sb:hover .ndot,.sb.open .ndot{display:none}
@keyframes dot-pulse{0%,100%{opacity:1}50%{opacity:.3}}
.sb-foot{margin-top:auto;width:100%;padding:0 8px}
.sb-user{display:flex;align-items:center;gap:9px;padding:7px 9px;border-radius:8px;cursor:pointer;transition:background .13s;overflow:hidden}
.sb-user:hover{background:var(--bg)}
.sb-av{width:28px;height:28px;border-radius:50%;background:var(--vl);display:grid;place-items:center;font-size:10px;font-weight:700;color:var(--v);flex-shrink:0}
.sb-uname{font-size:12px;font-weight:500;color:var(--ink);white-space:nowrap;opacity:0;transition:opacity .13s .04s}
.sb:hover .sb-uname,.sb.open .sb-uname{opacity:1}

/* MAIN */
.main{flex:1;min-width:0;display:flex;flex-direction:column;overflow:hidden}

/* TOPBAR */
.tb{height:52px;background:var(--white);border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 22px;gap:10px;flex-shrink:0}
.tb-title{font-size:14px;font-weight:600;color:var(--ink);letter-spacing:-.01em;flex:1}
.tb-sub{font-size:11px;color:var(--ink3);font-weight:400}
.btn{display:inline-flex;align-items:center;gap:5px;padding:6px 13px;border-radius:8px;font-size:12px;font-weight:500;cursor:pointer;border:none;transition:all .13s;text-decoration:none;white-space:nowrap}
.btn:active{transform:scale(.97)}
.btn-s{background:transparent;color:var(--ink2);border:1px solid var(--line)}
.btn-s:hover{background:var(--bg)}
.btn-p{background:var(--v);color:#fff}
.btn-p:hover{background:var(--vd)}

/* CONTENT AREA */
.cnt{flex:1;overflow-y:auto;padding:18px 22px;display:flex;flex-direction:column;gap:14px}

/* ACTION ROWS */
.actions{display:flex;flex-direction:column;gap:5px}
.action-row{display:flex;align-items:center;gap:11px;background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:11px 14px;cursor:pointer;transition:all .14s;animation:ai .3s ease both}
.action-row:hover{border-color:#c4c4c7;box-shadow:0 2px 8px rgba(0,0,0,.05);transform:translateY(-1px)}
.action-row:active{transform:translateY(0)}
.action-row.urg{border-left:3px solid var(--rd)}
.action-row.wrn{border-left:3px solid var(--am)}
@keyframes ai{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
.apip{width:7px;height:7px;border-radius:50%;flex-shrink:0}
.apip.rd{background:var(--rd);box-shadow:0 0 0 3px #fee2e2;animation:pip 1.8s ease infinite}
.apip.am{background:var(--am);box-shadow:0 0 0 3px #fef3c7;animation:pip 2.2s ease infinite}
@keyframes pip{0%,100%{box-shadow:0 0 0 3px rgba(220,38,38,.22)}50%{box-shadow:0 0 0 5px rgba(220,38,38,.04)}}
.at{flex:1;min-width:0}
.at-t{font-size:12px;font-weight:600;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.at-s{font-size:11px;color:var(--ink3);margin-top:1px}
.a-ago{font-size:10px;color:var(--ink3);white-space:nowrap;flex-shrink:0}
.a-cta{font-size:11px;font-weight:600;padding:4px 10px;border-radius:7px;border:none;cursor:pointer;transition:all .12s;white-space:nowrap;flex-shrink:0}
.a-cta:active{transform:scale(.96)}
.a-cta.rd{background:var(--rdl);color:var(--rd)}
.a-cta.rd:hover{background:#fee2e2}
.a-cta.am{background:var(--aml);color:var(--am)}
.a-cta.am:hover{background:#fef3c7}
.a-cta.vl{background:var(--vl);color:var(--v)}
.a-cta.vl:hover{background:#e0e7ff}

/* KPI STRIP */
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border-radius:var(--radius);overflow:hidden;border:1px solid var(--line)}
.kpi{background:var(--white);padding:14px 16px;transition:background .13s;cursor:default;animation:ai .28s ease both}
.kpi:hover{background:#fafafa}
.kpi-l{font-size:10px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--ink3);margin-bottom:7px;display:flex;align-items:center;gap:4px}
.kpi-l i{font-size:13px}
.kpi-n{font-size:22px;font-weight:700;letter-spacing:-.02em;color:var(--ink);line-height:1}
.kpi-d{font-size:10px;margin-top:4px;display:flex;align-items:center;gap:2px}
.dg{color:var(--gr)}.dam{color:var(--am)}.dntr{color:var(--ink3)}

/* GRID */
.g2{display:grid;grid-template-columns:1fr 240px;gap:13px}
.g2b{display:grid;grid-template-columns:1fr 1fr;gap:13px}

/* PANEL */
.panel{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:16px;animation:ai .3s ease both}
.ph{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:12px}
.pt{font-size:13px;font-weight:600;color:var(--ink)}
.pl{font-size:11px;color:var(--v);cursor:pointer;text-decoration:none}
.pl:hover{text-decoration:underline}

/* CHART */
.ch-leg{display:flex;gap:12px;margin-bottom:9px}
.leg{display:flex;align-items:center;gap:4px;font-size:11px;color:var(--ink3)}
.leg-sq{width:8px;height:8px;border-radius:2px}
.ch-box{position:relative;height:150px}

/* TABLE */
.tbl{width:100%;border-collapse:collapse;font-size:12px}
.tbl th{text-align:left;padding:0 0 7px;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3);border-bottom:1px solid var(--line)}
.tbl td{padding:7px 0;border-bottom:1px solid var(--line2);color:var(--ink2);vertical-align:middle}
.tbl tr:last-child td{border-bottom:none}
.tbl td.b{color:var(--ink);font-weight:500}
.tbl tr{cursor:pointer;transition:background .1s}
.tbl tr:hover td{background:#f9f9f9}
.badge{display:inline-flex;align-items:center;gap:3px;font-size:10px;font-weight:700;padding:2px 7px;border-radius:99px;white-space:nowrap}
.b-ok{background:var(--grl);color:var(--gr)}
.b-am{background:var(--aml);color:var(--am)}
.b-vl{background:var(--vl);color:var(--v)}
.b-rd{background:var(--rdl);color:var(--rd)}
.b-nd{background:var(--line2);color:var(--ink3)}
.b-pulse i{font-size:8px;animation:dot-pulse 1.6s ease infinite}

/* TOP FIRMY */
.fr{display:flex;align-items:center;gap:8px;margin-bottom:7px}
.fr:last-child{margin-bottom:0}
.fr-nm{font-size:12px;color:var(--ink);flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.fr-bg{width:56px;height:4px;background:var(--line);border-radius:99px;flex-shrink:0;overflow:hidden}
.fr-fi{height:100%;border-radius:99px;background:var(--v);transition:width .7s cubic-bezier(.4,0,.2,1)}
.fr-n{font-size:11px;color:var(--ink3);min-width:20px;text-align:right}

/* KAPACITA */
.cap{margin-bottom:10px}
.cap:last-child{margin-bottom:0}
.cap-h{display:flex;justify-content:space-between;margin-bottom:4px}
.cap-n{font-size:12px;color:var(--ink2)}
.cap-v{font-size:12px;font-weight:600;color:var(--ink)}
.cap-tr{height:5px;background:var(--line);border-radius:99px;overflow:hidden}
.cap-fi{height:100%;border-radius:99px;transition:width .8s cubic-bezier(.4,0,.2,1)}
.cap-m{font-size:10px;color:var(--ink3);margin-top:3px}
.cap-alert{display:flex;align-items:center;justify-content:space-between;background:var(--vl);border-radius:7px;padding:8px 11px;margin-top:10px;gap:8px}
.ca-t{font-size:11px;font-weight:500;color:var(--v)}
.ca-btn{font-size:11px;font-weight:600;background:var(--white);color:var(--v);border:1px solid #c7c9f0;border-radius:6px;padding:3px 9px;cursor:pointer;transition:all .12s;text-decoration:none}
.ca-btn:hover{background:var(--vl)}

/* RESPONSIVE */
@media(max-width:860px){.g2{grid-template-columns:1fr}.g2b{grid-template-columns:1fr}}
@media(max-width:640px){.kpis{grid-template-columns:1fr 1fr}.cnt{padding:12px 14px}.tb{padding:0 14px}}
@media(max-width:400px){.kpis{grid-template-columns:1fr}}
</style>
