// Chart.js — dashboard graf
<?php if ($page === 'dashboard'): ?>
(function(){
  var ctx = document.getElementById('ch1');
  if(!ctx) return;
  new Chart(ctx.getContext('2d'),{
    type:'bar',
    data:{
      labels:<?php echo json_encode($mesice_labels); ?>,
      datasets:[
        {label:'Absolventi',data:<?php echo json_encode($mesice_abs); ?>,backgroundColor:'#4f46e5',borderRadius:4,barPercentage:.44,categoryPercentage:.72},
        {label:'Vydané kódy',data:<?php echo json_encode($mesice_kody); ?>,backgroundColor:'#e0e7ff',borderRadius:4,barPercentage:.44,categoryPercentage:.72}
      ]
    },
    options:{
      responsive:true,maintainAspectRatio:false,
      animation:{duration:800,easing:'easeOutQuart'},
      plugins:{legend:{display:false},tooltip:{backgroundColor:'#18181b',titleColor:'#fff',bodyColor:'#d4d4d8',padding:10,cornerRadius:7,boxPadding:4}},
      scales:{
        x:{grid:{display:false},border:{display:false},ticks:{font:{size:11},color:'#a1a1aa'}},
        y:{grid:{color:'#f4f4f5'},border:{display:false},ticks:{font:{size:11},color:'#a1a1aa',maxTicksLimit:4}}
      }
    }
  });
})();
